window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["21264215"]={"book":{"id":21264215,"title":"高绩效教练","author":"（英）约翰•惠特默","translator":"林菲/徐中","publisher":"机械工业出版社","pubdate":"2013-2","isbn":"9787111404828","tags":["管理","领导力","教练","教练技术","个人提升","个人修炼","绩效","培训"],"memCount":13},"np":1,"pb":[32],"idx":[{"i":19618,"t":"高级效教练GROW模型","l":"TF2-2","c":"倩倩57","g":1,"p":1},{"i":18116,"t":"《高绩效教练》","l":"TF2-1","c":"杰哥5113","g":1,"p":1},{"i":17735,"t":"教练型管理者沟通秘籍——GROW模型","l":"TF1-2","c":"吕红（乐予）","g":1,"p":1},{"i":17023,"t":"教练式反馈模型","l":"TF2-3","c":"璞玉","g":1,"p":1},{"i":17022,"t":"教练式反馈模型","l":"TF2-2","c":"璞玉","g":1,"p":1},{"i":16024,"t":"用 GROW 模型激发对方的动力","l":"TF1-1","c":"Hiou","g":1,"p":1},{"i":15403,"t":"倾听和提问","l":"TF2-4","c":"袁士欣","g":1,"p":1},{"i":13703,"t":"教练会谈的框架","l":"TF1-1","c":"高瑶","g":1,"p":1},{"i":12844,"t":"grow模型","l":"TF2-1","c":"season&蒋恺轩","g":1,"p":1},{"i":12294,"t":"教练的框架","l":"TF1-2","c":"读书和跑步","g":1,"p":1},{"i":11533,"t":"有效提问代替给建议","l":"TF3-3","c":"柳颂婷","g":1,"p":1},{"i":10230,"t":"人人都可以是教练","l":"TF2-4","c":"闲人","g":1,"p":1},{"i":10214,"t":"初学者如何用好GROW模型？ ","l":"TF2-4","c":"冀颖妍","g":1,"p":1},{"i":10213,"t":"初学者如何用好GROW模型？ ","l":"TF2-4","c":"冀颖妍","g":1,"p":1},{"i":10009,"t":"用积极倾听，提升沟通质量","l":"TF1-2","c":"余涛","g":1,"p":1},{"i":9269,"t":"教练的框架","l":"TF1-2","c":"阅良","g":1,"p":1},{"i":9074,"t":"Grow模型~","l":"TF1-2","c":"田蕾","g":1,"p":1},{"i":8466,"t":"高绩效教练","l":"TF1-1","c":"海适涛哥","g":1,"p":1},{"i":7842,"t":"提问的顺序","l":"TF1-2","c":"陈海红","g":1,"p":1},{"i":7129,"t":"正向引导","l":"TF3-3","c":"苏红","g":1,"p":1},{"i":6820,"t":"如何用GROW模型实现自我教练","l":"TF1-1","c":"莫念","g":1,"p":1},{"i":6763,"t":"教练式提问，分析现状定目标，做计划","l":"TF2-4","c":"唐云霞","g":1,"p":1},{"i":5614,"t":"教练式反馈","l":"TF3-2","c":"唐云霞","g":1,"p":1},{"i":5427,"t":"有效提问","l":"TF3-1","c":"唐云霞","g":1,"p":1},{"i":4811,"t":"教练目标","l":"TF2-4","c":"唐云霞","g":1,"p":1},{"i":4623,"t":"在辅导中有效的提问","l":"TF1-1","c":"闲人","g":1,"p":1},{"i":3638,"t":"教练式沟通 激发无限可能","l":"TF2-3","c":"追逐1","g":1,"p":1},{"i":3544,"t":"直击事件本质，找到一次性解决方案！","l":"TF3-1","c":"锅净_二毛","g":1,"p":1},{"i":1127,"t":"《高绩效教练》拆书","l":"TF3-1","c":"张然","g":1,"p":1},{"i":632,"t":"简单几招，提高工作中简单小事情的绩效","l":"TF1-1","c":"锅净_二毛","g":1,"p":1},{"i":486,"t":"封闭式提问与开放式提问","l":"TF1-2","c":"dova","g":1,"p":1},{"i":477,"t":"真正负责的感觉随选择而来","l":"TF1-1","c":"dova","g":1,"p":1}],"ms":[{"id":19618,"topic":"高级效教练GROW模型","learn_goal":"","remark":"高级效教练GROW模型","level":"TF2-2","duration":20,"status":10,"type":0,"chaishujia":{"username":"倩倩57","city":"贵阳市"},"club":{"name":"贵阳黔灵分舵","city":"贵阳"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>各位爱学习的小伙伴，大家好啊，我是吴倩，一名热爱阅读的人民教师，终身学习者，也是一名新手拆书家。\u003c/p>\u003cp>在开始我们的分享之前，我们先简单分一下小组。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>今天我们来聊聊《高绩效教练》这本书。\u003c/p>\u003cp>（F）说到“教练”，你脑海里是不是浮现出来赛场上呐喊的身影？不过我们今天分享的这本书里的“教练”，指的是成长导师——他不是告诉你该怎么做，通过提出一个个好问题，激发你的自信心和责任感，帮你把自己心里那些模糊的想法变得清晰，进而开启行动。\u003c/p>\u003cp>（A）在教练这个领域，这本书基本就是“必读经典”，被译为30种语言，畅销全球120多个国家。作者花了三十多年研究教练技术，把自己的心得都写进了这本书，但是内容非常实在。用非常通俗的语言告诉了我们：什么时候需要教练？怎么问问题才有效？不仅给了我们一套系统的方法论，拿来即用，还挖出了背后的心理学原理，有助于我们从新的视角看待人。\u003c/p>\u003cp>（B1）读了这本书，不一定能让你立刻变成专业教练，但绝对能帮你换个眼光看日常的沟通——不管是带团队、教学生，还是和孩子聊天。你会开始懂得：有时候，最好的帮助不是急着给答案，而是耐心地问出一个好问题。\u003c/p>\u003cp>（B2）今天我们分享的这个片段，是教练领域的最经典模型“GROW”模型。学了这个模型以后，我们在鼓励别人、带动别人时，将会有令人惊讶的收获。而且它讲的不仅是一种技术，更是一种看待人、相信人的方式。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp> 在跟随我完成本次RIA现场学习后，运用GROW模型，完成一次针对自己实际问题的自我教练或同伴对话练习。\u003c/p>","ratings_count":1,"texts":[{"id":24023,"quote":"\u003cp>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003c/p>\u003cp>·目标设定（Goal），包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003c/p>\u003cp>·现状分析（Reality），探索当前的状况。\u003c/p>\u003cp>·方案选择（Options），可供选择的策略或行动方案。\u003c/p>\u003cp>·该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will）。\u003c/p>\u003cp>这个顺序可以方便地形成助记符GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。请参见图9中每个阶段的关键问题列表。\u003c/p>\u003cp>这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。GROW模型如此有效的一个因素就是这个框架是灵活的。\u003c/p>","explains":"\u003cp>\u003cstrong>\u003cem>（what）\u003c/em>\u003c/strong>我们刚刚阅读的片段是对GROW模型的简单概括。GROW模型是教练领域最经典的框架之一，提供四个阶段的提问，帮助我们自己和他人激发潜能、积极行动。\u003c/p>\u003cp>\u003cstrong>\u003cem>（why）\u003c/em>\u003c/strong>[通常的做法]平时当我们决定要去做一件什么事情的时候，通常要么闷头去干，要么苦思冥想不得其法；跟别人沟通的时候也常有“好为人师”的毛病。[后果]这样的做法导致的后果是我们并没有清晰的目标，或者有了目标却采取的是错误的方案，导致了时间和精力的浪费。在人际沟通中也会变得“爹味”十足。\u003c/p>\u003cp>而GROW模型则提供了一套高质量对话和提问的方案，帮助我们设定目标、厘清困惑、开启行动，在人际沟通中也会更加受欢迎。\u003c/p>\u003cp>\u003cstrong>\u003cem>（how）\u003c/em>\u003c/strong>GROW模型由四个单词的首字母组成，分别是“Goal”目标， “Reality”现状，“Option”选项 ，“Wil”意愿。使用这个模型时需要按照顺序提出相应的问题：\u003c/p>\u003cp>第一步，“Goal”目标。在这个阶段我们需要提问的是我们究竟想要的是什么？我们采取行动所期待的结果是什么？ \u003c/p>\u003cp>第二步，“Reality”现状。这一步提供提问明确我们所处的现状。问题可以包括：目前的情况是怎样的？”你已经做了哪些尝试？效果如何？有哪些相关的人和资源？\u003c/p>\u003cp>第三步，“Option”选项。在这一步可以通过头脑风暴的方式想到尽量多的方案。可以提出的问题包括：你能想到哪些方法？还有吗？如果是你佩服的人，他会怎么建议你？\u003c/p>\u003cp>第四步，“Wil”意愿。你接下来要做什么？第一步是什么？什么时候开始？\u003c/p>\u003cp>\u003cem>【过渡】了解了GROW模型的适用方法，接下来我们来看一个案例。\u003c/em>\u003c/p>\u003cp>\u003cstrong>\u003cem>（举例）\u003c/em>\u003c/strong>作为班主任，经常要跟学生斗智斗勇。有一段时间，班上学习风气特别差，学生学习态度不好，于是我就想利用周五下午学生放学的时间整治一下班上的学习风气。冲动之下，周五下午就把学生留了下来。可是把学生留下来之后，由于并没有充分的备课时间，只是单纯延长了放学时间，学生的心根本静不下来，引导学生学会自主学习的目标也根本没有达到，我自己也产生了不太好的感受。\u003c/p>\u003cp>\u003cstrong>\u003cem>（案例反变正）\u003c/em>\u003c/strong>如果我当时能够使用GROW模型思考，就会发现我的目标是引导学生学会自主学习，充分营造一个热爱学习的班级氛围。那么我就需要充分调研，了解学生在学习上出现的困难和问题，思考解决这个难题有哪些方法，以及具体要怎么行动才能达到我的目的。这样我可能就不会浪费一个小时，也能更有效地达到我的目标了。\u003c/p>\u003cp>\u003cem>【过渡】\u003c/em>当然，任何模型都会有边界。我们来看看这个模型的适用边界。 \u003c/p>\u003cp> \u003cstrong>\u003cem>（where）\u003c/em>\u003c/strong>特别适用于个人目标规划与决策，也非常适用于辅导下属。但是以下情况这个模型不是特别适用：当事人情绪崩溃时，对方需要的是陪伴和情绪安慰；要解决的事情有标准化的流程或者标准答案时，这个模型也不适用。\u003c/p>\u003cp>\u003cstrong>\u003cem>（预防异议）\u003c/em>\u003c/strong>听了对这个模型的介绍和案例，可能会有朋友觉得：“这四步听起来很完美，但现实中的问题千头万绪，真有这么简单吗？”\u003c/p>\u003cp>其实，GROW模型的强大之处，恰恰在于它把复杂问题简单化和结构化了。它就像是串起一地散乱珍珠的那条线，帮助我们看到混乱中的秩序。有了这个模型，我们并不能解决所有的问题，但它可以帮助我们在复杂的现实中，有一个清晰的思考框架，避免被情绪和细节淹没。更重要的是，这是一个可重复、可练习的思维习惯。刚开始可能觉得刻意，用多了就会成为你面对任何挑战时的第一反应。 \u003c/p>\u003cp>【过渡】所以，GROW模型不是一个僵化的教条，而是一个经过验证的、强大的强大工具，更是一种。理解了这些，我们就能更自信地开始应用它。接下来就让我们一起来规划一下应用。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>刚好现在又到新的一年了，新的一年，你是否有一些想要实现的目标呢？这是一个很好的利用GROW模型进行自我教练的契机。\u003c/p>\u003cp>比如在身心健康（比如规律锻炼、作息习惯、正念冥想、饮食习惯）；个人成长（读书、新技能学习、完成某项课程等）；事业与财务（简历更新、副业创收、存款储蓄、时间管理）；人际与生活（旅行计划、爱好培养、减少拖延、家人陪伴等）。\u003c/p>\u003cp>请在便利贴上写下自己的使用情境，限时30秒。\u003c/p>\u003cp> 那接下来呢？呃，请大家根据我们今天提到的这个grow模型的四步针对自己的使用情境进行自我教练。那么大家应该拿到了一份小的表格，上面呢有关于grow模型使用的四个步骤。那写完以后我们就就近的话，师傅和木木一个小组，这两位小伙伴一个小组，我们组内相互分享一下。这些参考问题，大家选其中的一个来提问就可以了。不用全部都提问，它是类似近似的问题。\u003c/p>\u003cp> 好，各位小伙伴，我们还能给到大家三十秒的时间。\u003c/p>\u003cp> 好时间的关系，哪位小伙伴愿意来我们现场分享一下吗？\u003c/p>\u003cp> \u003cstrong>曾燕老师分享：\u003c/strong>我的目标是做一家中年学习技能，学习创收的书籍超市。卖线下活动，线上课程。如果实现了我的这个目标，这是我的理想。我感觉那个时候我会很有成就感。我已经采取了什么样的行动？呃，直播学习，经常反思，并且制定了初步的计划。这个推着我向目标前进的，是我的理想是我的信仰，是我的意志力。阻碍了我的是我实力不足，能力欠缺以及执行力差。\u003c/p>\u003cp> 有什么样的不同选择来实现我的目标？先去脚踏实地认真工作。从工作里面生发。去思考。然后去到书店学习怎么样去经营自媒体课程做起来，然后把自己之前学习的课程设计。练习制作成网课。没有写这个项目的主要优缺点。\u003c/p>\u003cp>我会选什么开始采取行动？我已经在采取行动。如果在采取行动方面给自己打分？我的承诺度是五分。做什么使它达到十分？第一是加强精力锻炼，第二是克服自己的拖延，第三是需要认真完成执行自己计划中的每一步。不要盲目相信自己的能力，而是脚踏实地做好此时此刻现实中的计划。\u003c/p>\u003cp>我不会给自己做承诺因为我觉得我已经做够多了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1767567442000,"updated_at":1767567455000,"ria":true},{"id":18116,"topic":"《高绩效教练》","learn_goal":"","remark":"《高绩效教练》 GROW 模型，助您提升自我管理能力。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"杰哥5113","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是杰哥，一个在财务领域从业18年的老人，也是一个刚刚加入拆书帮拆书活动2个月的新人。我的标签有阅读达人、运动达人、鸡娃达人等，但是最近我最在乎的还是拆书过级，希望能早日达成三级拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":22371,"quote":"\u003cp>大家知道吗？今天咱们举办拆书的场所，是借用一个教练机构—开疆来做的拆书活动，开疆是中国第一家教练培养与应用机构, 也是最具声誉的实效性咨询机构。今天我和大家分享的也是一个和教练技术有关的模型 - GROW 模型，当然这个模型不仅可以用于教练的场景，也可以用来解决大家生活中的问题。 希望大家在跟我完成本次学习后，知道怎样使用 GROW 模型来激发身边人的自驱力，发现沟通完后，这个事后续就不再需要你盯着了，他就能自己发挥主观能动性把这个事情做好。\u003c/p>\u003cp>【FAB法介绍书籍】\u003cbr>今天我选的拆页是来自于《高绩效教练》这本书。\u003cbr>\u003cbr>【F】它的作者叫约翰·惠特默，是职场教练应用的先驱，也是绩效咨询(国际)有限公司的联合创始人。该书以GROW教练模型 [ 目标（goal）, 现状（reality）, 选择（option）, 意愿（will）]为教练逻辑，引用职场及运动场上的例子，清晰阐述了教练的理念和技巧。\u003cbr>【A】《高绩效教练》是全球第一畅销的教练书籍，全球百万领导者的必备读物！豆瓣8.2分高赞！被翻译成30余种语言，畅销130多个国家。\u003cbr>【B】针对目前企业界开始运用的“教练型领导”，本书将会是最佳的范例，同时对于学校的教师和孩子的家长而言都十分有益，将教授你如何成为一个能激发对象觉察力和责任感的好教练。\u003cbr>\u003cbr>下面我们先来阅读一下拆页：\u003c/p>\u003cp>拆页来源于 《高绩效教练》第9章 GROW 模型。\u003cbr>\u003cbr>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003cbr>● 目标设定（Goal），包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003cbr>● 现状分析（Reality），探索当前的状况。\u003cbr>● 方案选择（Options），可供选择的策略或行动方案。\u003cbr>● 该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will）。\u003cbr>这个顺序可以方便地形成助记符GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。请参见图9中每个阶段的关键问题列表。\u003cbr>\u003c/p>","explains":"\u003cp>【what】\u003cbr>这个片段讲述了什么呢？讲述了一个我们如何在对话中帮助我们的对象，来帮助其做出一个主动的行动计划，核心是通过询问目标，分析现状，寻找可选的全部方案，最后由对方自己在分析利弊之后做出行动的选择。在我们工作和生活中常常遇到一些需要对方发挥主观能动性的场景，这个时候GROW模型可以很有效地发挥作用。\u003cbr>【why】\u003cbr>为什么GROW模型有用？因为人是意义驱动的动物。而GROW模型首先切入的就是行动的意义，通过帮对方厘清目标，唤醒他们内生的意义感，从而形成内在的动力，当然仅有意义感还不够，所以GROW模型后面还依次帮对方厘清现状也就是行动的起点，以及梳理可选方案也就是选项，和可执行的时间和具体措施等等，通过【为什么要做】-【从哪里开始】-【可以如何做】-【何时开始做】这整一套流程，完成一个心理动员的完整闭环，就好比让对方在心中上紧了发条，接下来就可以奔向自己的目标了。\u003cbr>【why-not】\u003cbr>在我们的日常生活工作过程中，往往会碰到不使用 GROW 模型的情形，为了追求沟通的效率，快速决策，直接发出指令，要求对方完成某项任务，这样的做法往往会使得对方缺乏认同感，在后续具体操作中死板的按部就班，做到哪算哪，反正也不是自己做出的选择，有锅就让领导去背。\u003cbr>\u003cbr>我来举两个反面的例子：\u003cbr>\u003cbr>第一个是生活中的，在辅导我女儿学习的过程中，我属于领导的角色，我每次都会按照我的想法，从来不问我女儿的看法，给我女儿布置一大堆的家庭作业，然后也安排了好多补课，每天我女儿是应接不暇，疲于奔命，怨声载道，关键效果也很不好，这几年下来钱没少花，课没少上，但是成绩却始终上不去。\u003cbr>\u003cbr>另外，有的时候我们以为自己是按照 GROW 模型在走，但是因为缺失了GROW的精髓也就是唤醒意义感，所以变成了形似神不似的“伪GROW模型”，这样往往也起不了作用，例如：我有个前任领导，就是最近被罚了4点几个亿的那个审计公司，他性子特别急，有一次年中的时候因为整个审计小组的审计业务有点少，大老板说每个BU需要各自去拓展下审计业务，于是他使用一个伪 GROW 模型，他是这么说的：因为上面领导的要求，我们下半年的新审计客户的目标是1000万 (G)，目前我们有10个高级经理(R)，所以每个人下半年必须获得100万的新增审计业务的单子(O&amp;W)，如果完不成，绩效就差评，降工资，结束。其实我们听完之后，都挺生气的，觉得就是个拍脑袋的KPI, 大家也就爱理不理的，年底也没什么人完成100万的指标。\u003cbr>\u003cbr>【how】【提前准备台卡，把GROW模型的通俗解释写在上面】\u003cbr>那么，如果说上面的例子是一个使用 伪GROW 模型的案例，那什么才是正确的 GROW 模型打开方式呢？我认为需要执行下面的四个步骤：\u003cbr>1、首先需要和沟通对象确认一个目标，但是这个目标必须是由对方说出来的，而不是你给他设定的，比方说通过问“你想达到什么样的成果？”。\u003cbr>2、其次需要厘清现状，和对方一起来看看达成这个目标的现状如何，主要有哪些困难和制约因素的，比方说问：“你现在到哪里了？”。\u003cbr>3、让对方穷尽自己的想象，尽可能把所有的方案选择都罗列出来，不要担心太荒谬，或者不可实现，只有方案有足够的胆子去想，才能出来一些创新性的天才点子。比如问：“你能做什么？”。\u003cbr>4、让对方自己选择哪个具体的行动方案，该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will），比如问“你将要做什么？”\u003cbr>【where】\u003cbr>这个方法，特别适用于那些需要激发对象自驱力才能做好的事情，比方说员工的创造的有挑战性工作，孩子的学习等。\u003cbr>\u003cbr>\u003cstrong>【反面案例加工成正面的案例】\u003c/strong> \u003cbr>使用正确的 GROW 模型的方法，如果我作为那个前任领导，面对上述工作中的例子，会进行如下的改变：\u003cbr>\u003cbr>1、我会先讲述下目前公司碰到的困境，由于收入的连年下降，导致公司目前已经处于亏损的边缘，如果下半年不能再拓展足够多的业务，则公司可能要被迫面临裁员和降薪的困境，如果想避免被裁员和降薪（Goal），对于这样的困境，作为公司骨干的各位高级经理有什么建议的？\u003cbr>2、既然大家也都提到了需要尽力去拓展新业务这个方法，那我们看看这件事情目前主要存在哪些障碍的（Reality)？让大家来讲比方说时间安排上，因为大家平常的审计工作就挺繁重的，那什么时候去做这个拓展工作，还有就是渠道上，新的审计业务也不会自己主动上门来，我们去哪里找这些有需求的客户的？\u003cbr>3、针对上述提到的一些困难点，大家有什么好的办法可以去解决这些问题的，引发大家自己提出解决的各种方法(Option)。\u003cbr>4、那最后，总结下今天的讨论，请大家回去之后，按照今天讨论的结果，自己给自己设定一个新业务的拓展计划(Will)，然后发给我来看一下，我们每周都定期来讨论下这个计划的执行情况。\u003c/p>","interaction":"\u003cp>那么现在我请大家一起花2分钟的时间想想，你有没有碰到过类似的情况，你感觉你的领导给的指令让你无法忍受，完全没有考虑你的想法，都是他自己在拍脑袋，或者是在生活中有没有遇到过努力想劝说对方一件事儿，但是却没办法激起共鸣，对方却只是应付了事。大家想好了，看我一下。【可以考虑分下组，这样大家才能讨论起来，然后每组选个人来说下，不过需要控制下时间，还有A1+的分享需要时间】\u003cbr>学习者经验分享：\u003cbr>\u003cbr>锋哥: 我孩子一直很喜欢玩手机，他妈妈跟他说你不要玩了，可是没啥用，他还是继续玩，觉得他妈妈太烦了。\u003c/p>\u003cp>谢谢，大家分享的案例非常好，接下来我们花2分钟的时间，请大家想想如果以后再碰到类似的情况，结合我们今天新学的 GROW 模型，具体会怎么做的，大家想好了看我一下。【A1找的谁分享，A1+也需要找这个人来分享】\u003cbr>学习者经验分享：\u003cbr> \u003cbr>锋哥：我就想可以拉着他妈妈一起跟他聊了一次，先问他你的目标是什么？他说想以后考上好的大学。再问他那你现在的情况是怎么样的？他说好像还有点差距。然后问他有什么办法的？他说需要花更多的时间投入到学习中去。最后问他打算怎么处理学习和玩手机这两件事情？他说以后每天就玩半小时手机，这样也能够不影响学习。\u003c/p>\u003cp>时间过得很快，今天我们通过这二十分钟时间的练习，大概学会了 GROW 模型这个经典的教练模型，以后再遇到需要激发对方主观能动性的场景，切记要使用GROW的四步法，放弃说教和命令，通过激发对象的觉察和责任性，让对方觉得这事做的有意思，从而让他们发挥自己的主观能动性，更好的把事情做好。\u003cbr>\u003cbr>谢谢大家，今天的分享就到这里结束了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1727259921000,"updated_at":1730714312000,"ria":true},{"id":17735,"topic":"教练型管理者沟通秘籍——GROW模型","learn_goal":"","remark":"有效提问代替直接给建议。通过教练四问法（Grow模型），教你正确引导式问问题，有效引导对方思索，从而找到答案。","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"吕红（乐予）","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>各位好！我是爱读书、爱分享、爱喝茶的吕红，我的昵称是“乐予”，拼音： l+ü ，吕。 \u003c/p>\u003cp>三个标签介绍我自己：\u003c/p>\u003cp>一、【我是持续学习者】；\u003c/p>\u003cp>二、【我是温柔且有力量的企业高管】；\u003c/p>\u003cp>三、【我是创业者】目前是新晋企培人。\u003c/p>\u003cp>今天我要进行TF1-2的升级打怪，跟大家分享的书是《高绩效教练》，作者是【英】约翰.惠特默(John Whitmore)，他是教练领域的先行者，本书是全球销量排名第一的教练书籍，被誉为教练领域的“圣经”。\u003c/p>\u003cp>今天的要拆的主题是：有效提问代替直接给建议，通过教练四问法（Grow模型），可以有效引导对方思索，从而找到答案。\u003c/p>","ratings_count":1,"texts":[{"id":21955,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>接下来请大家花1-2分钟阅读一下这个片段，阅读完的小伙伴请扣1示意我一下。\u003c/p>\u003cp>《高绩效教练》【英】约翰.惠特默(John Whitmore) \u003c/p>\u003cp>\u003cstrong>教练的框架\u003c/strong>\u003c/p>\u003cp>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003c/p>\u003cp>● 目标设定（Goal），包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003c/p>\u003cp>● 现状分析（Reality），探索当前的状况。\u003c/p>\u003cp>● 方案选择（Options），可供选择的策略或行动方案。\u003c/p>\u003cp>● 该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will）。\u003c/p>\u003cp>这个顺序可以方便地形成助记符GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。请参见图9中每个阶段的关键问题列表。\u003c/p>\u003cp> 这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。GROW模型如此有效的一个因素就是这个框架是灵活的。\u003c/p>","explains":"\u003cp>刚才大家已经阅读完了拆页，相信对内容有了一些理解。\u003c/p>\u003cp>在我们的生活与工作中，常常会遇到这样的一些场景，比如你的孩子、朋友、下属等碰到问题兴致勃勃地向你请教时，你直接上来就一顿输出自己的想法，但对方听完你的建议后，直接来句你是站着说活不腰疼，而你也很受伤，我的好心被你当成驴肝肺了，结果双方不欢而散，以后他们碰到困难再也不来找你了，现在我们可以通过教练四问法（Grow模型）引导提问者自己寻找答案，并制定行动方案，来解决这个问题。\u003c/p>\u003cp>What:\u003c/p>\u003cp>GROW模型是一个包含四个步骤的框架：设定目标（Goal）、了解现实（Reality）、探索选择（Options）和决定行动（Will）。\u003c/p>\u003cp>Why:\u003c/p>\u003cp>GROW模型对于提升个人或团队的表现至关重要，因为它提供了一个清晰、结构化的方法来设定目标并实现这些目标。\u003c/p>\u003cp> 它帮助人们识别和克服障碍，找到最有效的解决方案，并增强实现目标的动力和承诺。\u003c/p>\u003cp>How:\u003c/p>\u003cp>使用GROW模型时，\u003c/p>\u003cp>\u003cstrong>第一步：问目标（Goal）\u003c/strong>，你可以这样说：你的目标是什么？什么时候实现？实现目标的标志是什么？怎么量化这个目标? 通过提问，设定具体、可衡量、可实现、相关性强、时限性的目标。\u003c/p>\u003cp>\u003cstrong>第二步：问现状（Reality\u003c/strong>），你可以这样说：目前的状况怎样？有哪些差距？\u003c/p>\u003cp>\u003cstrong>第三步：问方案（Options）\u003c/strong>，你可以这样说：为改变目前的状况，你能做什么？可供选择的方案有哪些？你见过别人怎么做？哪一种选择你认为是最有可能成功的？ \u003c/p>\u003cp>\u003cstrong>第四步：问行动（Will）\u003c/strong>，你可以这样说：下一步是什么？什么时候动？可能会碰到哪些问题？你需要什么支持？谁能帮助你？确定行动计划，设定时间表和里程碑。\u003c/p>\u003cp>通过以上四问法，可以迫使对方深入思考，从而自己找到答案，但步骤不是一成不变的，可以根据情况予以调整。\u003c/p>\u003cp>Where:\u003c/p>\u003cp>教练模型不仅适用于工作场景，如绩效沟通；还适用于生活中朋友、家人面临困境需要帮助的情形，但它只有在具有觉察和责任感的背景下才有效。\u003c/p>\u003cp> 案例：\u003c/p>\u003cp>接下来，我分享一个上周五我同事问我是否参与投标的案例:\u003c/p>\u003cp>\u003cstrong>**时间**：\u003c/strong>上周五\u003c/p>\u003cp>\u003cstrong>**地点**：\u003c/strong>办公室\u003c/p>\u003cp>\u003cstrong>**人物**：\u003c/strong>同事和我\u003c/p>\u003cp>\u003cstrong>**起因**：\u003c/strong>我们培训公司成立不久，接到一家医院的培训需求咨询，通过多次沟通后也提交了方案和报价，对方提出要走招投标流程。\u003c/p>\u003cp> \u003cstrong>**经过** ：\u003c/strong>医院需要我们在两周内确定是否参与投标并完成标书制作。我听完他的汇报后，直接就建议说，投啊，医院这种单位肯定是要走招投标流程的，别想那么多了，下周五前把标书做好就行了。\u003c/p>\u003cp>\u003cstrong>**结果** ：\u003c/strong> 同事到现在还没有完成标书的制作。\u003c/p>\u003cp>\u003cstrong>**反思** ：\u003c/strong> 为什么我的建议同事没有接纳呢？\u003c/p>\u003cp>反思我错误的地方是即没有问目标，也没有问现状，就直接就给建议了，我应该怎样引导才能让同事接受我的建议呢？如果重新再来一次，我会通过运用 GROW 模型进行提问：\u003c/p>\u003cp>第一步：问目标，你认为做这个事我们要实现的目标是什么？通过问目标，让同事思考做这件事给我们带来的价值和意义。\u003c/p>\u003cp>第二步：问现状，现在我们的情况怎么样？ 困难在哪里？找到差距，然后再第三步问方案、第四步问行动引导对方自己做出下一步行动。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1：激活经验】指令清晰。学习者在小组内分享了自已的经验，并有一个代表分享了本组的一个经验，现场给学习者分组。\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>希望以上案例也能引发各位小伙伴们关联起自己的一些过往的经历，现在我想请各位小伙伴回顾一下：\u003c/p>\u003cp>您有没有在生活中或职场上遇到过类似的不愉快的情景呢？比如，您作为一名管理者，与下属制订绩效考核指标时，他面无表情地说：领导，要不你直接给我下任务就好了；或者，你的好朋友想减肥向你征求意见时，你费尽心思，掏心掏肺地给他出主意，对方却不以为然，让你感到非常不愉快；再有，孩子中考报名向你征求意见，你巴拉巴拉一顿输出，孩子却说，算了，别说了，你根本不懂他… …\u003c/p>\u003cp>请大家思考一下类似的情形，一会儿我们进行分组，在小组内轮流进行分享，小组分享完后，我会邀请一位代表分享本组的一个经历，提醒一下，我们要把时间、地点、人物、起因、经过、结果都要说清楚哦，时间4分钟！\u003c/p>\u003cp>现在我们分一下组，今天共8位学习者，分为两组，4人一组，现在开始。\u003c/p>\u003cp>好，时间到，请大家回来，现在请一位小伙伴来分享一下他的经历，有哪位小伙伴愿意用1分钟的时间分享一下 ？\u003c/p>\u003cp>\u003cstrong>【学习者双琴案例记录】 \u003c/strong>\u003c/p>\u003cp>时间： 早上\u003c/p>\u003cp>地点： 家里\u003c/p>\u003cp>人物： 母子\u003c/p>\u003cp>起因： 中考前，妈妈希望儿子作息规律一点\u003c/p>\u003cp>经过： 妈妈认为儿子休息不够，营养也跟不上，于是直接要求孩子按她安排好的饮食和作息来做。\u003c/p>\u003cp>结果： 与儿子产生冲突，孩子很抗拒。\u003c/p>\u003cp>\u003cstrong>【A2：催化应用】指令清晰，每个学习者都写下了一个包含具体做法、有明确时限和只衡量或可观测预期结果的便签。\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp> 为了促进各位小伙伴更好地应用GROW这个模型，接下来我们用2-3分钟时间，请大家思考一下，你打算在未来的一周或一个月里怎么用GROW模型呢？\u003c/p>\u003cp>比如，您在工作或生活中，就某个事情，您打算运用这个工具来帮助对方达成目标或解决难题等等。您的计划里，一定要有明确的期限，具体的做法，及可衡量或可观测的预期结果。强调一下，这个时间，不是过去时间，是你未来想要做的事情。\u003c/p>\u003cp>好，现在我请一位小伙伴来分享一下他的计划，有哪位小伙伴愿意用1分钟的时间分享一下 ？\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者冰冰分享：\u003c/strong>\u003c/p>\u003cp> **明确的期限**：我计划在明后天与朋友沟通孩子的英语启蒙的安排。\u003c/p>\u003cp> **可衡量的结果**：让朋友理解英语启蒙的顺序是听说读写。\u003c/p>\u003cp> **行动计划**：我将运用GROW 模型进行提问：\u003c/p>\u003cp>\u003cstrong> 第一步：问目标。\u003c/strong>\u003c/p>\u003cp> 问：2岁孩子英语启蒙，你的目标是什么？\u003c/p>\u003cp>\u003cstrong> 第二步：问现状。\u003c/strong>\u003c/p>\u003cp> 问：孩子对英语有兴趣吗？ \u003c/p>\u003cp> 问：孩子现在在用什么工具学习英语？\u003c/p>\u003cp>\u003cstrong> 第三步：问方案。\u003c/strong>\u003c/p>\u003cp> 问：你是否认可我的教学理念和方案？\u003c/p>\u003cp>\u003cstrong> 第四步：问行动。\u003c/strong>\u003c/p>\u003cp> 问：孩子什么时候开始学习？\u003c/p>\u003cp>总结：\u003c/p>\u003cp> 感谢大家的参与，我也希望，当你真正遇到相似的情境时，可以按照自己今天的规划认真践行一遍。\u003c/p>\u003cp> 因为当你在现实场景中，真正运用过教练技术，你就能感受到这种方法论的独特魅力。\u003c/p>\u003cp> 好，今天的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1718361146000,"updated_at":1726143043000,"ria":true},{"id":17023,"topic":"教练式反馈模型","learn_goal":"","remark":"日常中我们经常会遇到给下属，孩子或和我们交流的人给反馈及建议，反馈无处不在，我们总会热情‘积极’真诚的给建议，希望帮到对方。但效果怎么样呢，对方因为我们的反馈更有能动性了，还是听的频频点头，做的时候往往如如不动。教练式反馈是只发问，不给建议！还能激发被教练者的能动性。高明之极！学会受益匪浅！","level":"TF2-3","duration":22,"status":30,"type":0,"chaishujia":{"username":"璞玉","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp> 大家好，欢迎大家来到我们拆书帮的讲座，我们在讲座开始前，我们先分一下组，一会会有大家分组学习和分享。来我们2人一组\u003c/p>\u003cp>一，自我介绍，图书介绍 2分钟\u003c/p>\u003cp>自我介绍：大家好，我叫曹瑜，我的一名家庭教育指导师，如果大家有家庭教育方面的问题，我们可以一起交流。\u003c/p>\u003cp>分享主题：教练式反馈模型，拆书家第二级tf2-3过级分享，用时23分\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>在跟随我完成本次学习后，学习者能够在日常和下属沟通或孩子交流时，使用grow五步反馈法，而不是评判和给建议。通过精准的发问，让对方主动探索解决方案。\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>这个主题选自《高绩效教练》，作者约翰•惠特默（John Whitmore)\u003c/p>\u003cp>F ：如果大家在日常中，管理下属，激励孩子时，发现很难真正调动对方责任感，\u003c/p>\u003cp>A: 实战，权威。\u003c/p>\u003cp>约翰•惠特默爵士以其在教练领域的杰出工作获得了国际教练联合会授予的总裁奖。有大量的实战经验，本书已经升级到第五版，销量超过50万册，业内关于教练书籍他是鼻祖，权威最高的一本。\u003c/p>\u003cp>作者书中大量的教练案例对话，并有发问工具包，让我们学以致用，\u003c/p>\u003cp>B；\u003c/p>\u003cp>如果你想激发团队能动性，调动责任感。激发孩子或自我潜能，或增强自信，提升员工责任感。这本书会帮助到你。真正去调动对方责任感。\u003c/p>\u003cp>同时，教练模型思维下，让你成为一个发问高手，思维和沟通都上一个高段位。 \u003c/p>","ratings_count":2,"texts":[{"id":21164,"quote":"\u003cp>我们先来看看常用的五个反馈层次。下面按照从最没用的A情境到最有效的E情境来排列，只有一个是能够大量促进学习和提升绩效的。其他4个中最好的情况可能在短期内带来一点改善，最糟的情况会导致业绩和自尊继续下滑。A到D被广泛应用在企业中，乍看起来似乎都是合理的，却禁不起仔细推敲。\u003c/p>\u003cp>A.教练感叹：“你真没用。”\u003c/p>\u003cp>这是一种伤害自尊心和自信心的人身攻击，摧毁了自尊和自信，必将使教练对象未来的表现更加糟糕。这没有任何帮助。\u003c/p>\u003cp>B.教练感叹：“这份报告没有用。”\u003c/p>\u003cp>这个针对报告而非针对该人的评判性评论，同样伤害了教练对象的自尊，尽管没那么严重，但它仍然没有提供任何有用的信息来帮助教练对象采取行动来完善和提升。\u003c/p>\u003cp>C.教练的反馈是：“你的报告内容清晰而简洁，但版面设计和演示的内容对目标读者来说太低端了。”\u003c/p>\u003cp>这个反馈避免了批评，向教练对象提供了一些信息帮助他采取行动，但没有足够的细节影响对方产生自主权。\u003c/p>\u003cp>D.教练的反馈是：“你觉得这份报告怎么样？”\u003c/p>\u003cp>现在教练对象拥有自主权，但可能会给出诸如“好”之类的回复，或这“很棒”或“糟糕”等价值性的判断，而不是更加有用的描述。\u003c/p>\u003cp>E.教练的反馈是：“你最喜欢什么？”“如果再做一次，你会做些什么不同的事？”“你学到了什么？”\u003c/p>\u003cp>为了回应这一系列用非评判方式提出来的问题，教练对象对报告和报告背后的思路进行了详细描述。\u003c/p>\u003cp>为什么E情境中列示的反馈形式会大大加速学习并提高绩效？因为只有E情境中教练满足了最佳教练的所有标准。为了回答E情境中教练提出的问题，教练对象不得不开动脑筋，参与进来。他们要想准确表达自己的想法，就必须仔细回忆并梳理思路，这就是觉察。它帮助教练对象学会评估自己的工作，从而变得更加自觉独立。通过这种方式，他们“拥有”产生业绩和自我评估的自主权，这就是担责。当这两个因素得到优化时，学习就发生了。相反，如果教练只是给出自己的意见，那么，教练对象大脑的实际参与度可能是最小的；没有自主权，教练就没有办法准确了解对方吸收到了什么。\u003c/p>\u003cp>使用描述性而不是主观判断性的话语，无论是E情境中的教练，还是C情境中的教练，都避免了激起教练对象的自我保护倾向。自我保护倾向必须要避免的原因在于当它存在时，真相和现状就会被不正确的借口和理由所掩盖，教练和教练对象都会相信这些借口和理由，改善绩效也就没有了基础。然而，在情境C中，如同在情境A和B中一样，教练保有了评估和纠正的所有权，教练对象与教练的关系是一种依赖型的关系，致使未来的学习成效会相应地最小化。情景A～情景D的方式都不够理想，然而它们在商业应用中最为常见。\u003c/p>\u003cp>GROW反馈框架\u003c/p>\u003cp>我已经介绍了使用GROW模型来构建一个教练对话。反馈本身实际上就是一个教练对话。因此，包括激发意愿在内，我正在分享的是一个成功反馈对话的路线图，我把它称为GROW反馈框架。为了把反馈变成一次学习的机会，需要问的关键问题如下：\u003c/p>\u003cp>·发生了什么？\u003c/p>\u003cp>·你从中学到了什么？\u003c/p>\u003cp>·未来你将怎样应用它？\u003c/p>\u003cp>让我们在GROW模型的框架下看看以下这些问题（见图13），看看当使用教练方式来加速学习和提高绩效时，整个反馈对话会怎样。图13　GROW反馈框架\u003c/p>","explains":"\u003cp>【why】我们日常中给反馈往往容易有评判，总觉得指出对方做的不好的，去帮助对方，但这样对方听了，往往会有情绪，或被打击，无法自我负责。让对方真正从问题跳脱出来，调动对方自我负责。\u003c/p>\u003cp>「what】拆页部分介绍用grow模型做为反馈框架，通过grow反馈模型的发问，做的好的部分，还有从中学到什么，并激发下一步行动的意愿和动力。这样对方是通过自我的觉察和反馈中获得信心和反思。不去评判和给建议。\u003c/p>\u003cp>how(细化步骤）\u003c/p>\u003cp>第一步：夯实目标。让对方明确他真正想要的目标是啥。\u003c/p>\u003cp>发问“发生了什么”“你真正想要达到的意图和目标是？执行中容易发生行为与目标偏差。\u003c/p>\u003cp>第二步：发现做的好的地方，提振信心。\u003c/p>\u003cp>“哪些方面进展良好?”叠加：“我喜欢，我欣赏你做的……”\u003c/p>\u003cp>●即使绩效水平比较低，这一步仍然至关重要。认可他做得好的方面。即使任务没有完全达标，也要认可对方的努力。\u003c/p>\u003cp>●不带评判是创建一个能激发创造力并带来投入的安全学习环境的\u003c/p>\u003cp>关键\u003c/p>\u003cp>第三步：探讨能改进和提升的部分\u003c/p>\u003cp>“可以做些什么不一样的呢?”叠  加：“如果这么做……会怎样?”激发对方探索更多可能性。\u003c/p>\u003cp>●在给教练对象任何自己的建议之前，留出时间让他反思想要做什么样的改变，能够建立自觉独立和担责\u003c/p>\u003cp>第四步，启发学习到什么？\u003c/p>\u003cp>●启发对方学习收获及将未来会做什么不同的行为，能增强信心，让他从问题中有所学习。\u003c/p>\u003cp>第五步，明晰以后或下一步行动计划\u003c/p>\u003cp>●将学习与整体的发展目标相联系\u003c/p>\u003cp>●赞同具体的行动。确认你们都已经清楚行动计划\u003c/p>\u003cp>每一步的黄金法则是先让教练对象分享，然后教练给出自己的看法。\u003c/p>\u003cp>我细化完步骤，我给大家举例：爱丽和上司闹别扭，请假，来找我诉苦，指责领导，决定辞职。\u003c/p>\u003cp>我问，第一步，你当初那么多公司中为什么选了这个公司啊？这就是从问题中跳脱出来重新夯实目标。\u003c/p>\u003cp>爱丽：这个公司在行业中是 龙头地位，我能学到东西，积累很多客户资源，为我两年后创业积累人脉。\u003c/p>\u003cp>我问：哦，那这个公司看来是实现你创业目标最适合的公司，为你创业做积累的啊。爱丽，是的。\u003c/p>\u003cp>我问，那你在这个公司获得你想要的这些部分来吗？或这个公司让你满意的有哪些？你付出和做了哪些第二步，发现好的部分\u003c/p>\u003cp>爱丽：这个公司，我积累了多少客户，学到了很多技能，积累了很多经验，我在公司里也很努力，做了很多工作。哎，美中不足就是这个新来上司和我脾气不对。\u003c/p>\u003cp>我问；对，说说，你那些不满意的，还有你觉得离实现你的目标，还需要改进和提升的部分。这是第三步探讨改进部分。\u003c/p>\u003cp>爱丽：我改改我这脾气，其实也不会有多大问题。对我的目标影响真不大。\u003c/p>\u003cp>我问：看来有所启发哦？启发和学习到什么呢？如果不改脾气，这对你的目标影响程度呢，学习到什么？\u003c/p>\u003cp>爱丽：我这脾气也真的改改，。。。。要不然以后自己创业也会有这些人际摩擦。我要为我以后创业领导团队积累经验，磨练心性\u003c/p>\u003cp>我问：那你下一步准备怎么做呢？\u003c/p>\u003cp>爱丽：和领导好好教练一次，道歉。第二，找个对标的榜样，遇到问题时，找他请教。不冲动。第三，我去学习一下领导力和情商课程，提升自己。\u003c/p>\u003cp>我问：具体规划可以列出来，每月评估反馈。\u003c/p>\u003cp>【where】反馈模型的使用边界，不要居高临下，直接给建议或批评。是教练要真正的信任对方，相信对方的潜能，不会越俎代庖\u003c/p>","interaction":"\u003cp>A3环节 演练，用时15分钟（6分钟+3分钟）\u003c/p>\u003cp>技能3，场景设计：可讨论，可分析，可演练的场景\u003c/p>\u003cp>我们来设想一个具体场景，你家孩子在学校看到两个同学在楼道走廊打闹，他过去劝阻，拉扯中，老师过来，不由分说，三人都被罚跑了2000米，孩子回家很气愤，回家骂骂咧咧说老师就是个傻蛋。爸爸听后，立即指责孩子，怎么能这么说老师呢，越大越退步了！孩子一听说，你们大人都很自以为是，摔门而去。现在需要智慧的妈妈出面来和孩子聊一聊，用我们今天的grow反馈模型，怎么来沟通。\u003c/p>\u003cp>现场讨论，精准控场，目标是技能应用，而非沉溺于解决问题。\u003c/p>\u003cp>——大家对场景设计清晰了吗？我们2人一组，\u003c/p>\u003cp> 第一环节：一个扮演孩子，一个扮演妈妈。妈妈是教练角色。孩子是被教练者。然后再互换角色演练。目标不是定在解决孩子这个问题上，而是应用今天的这四步反馈方法。注意，教练要以发问为主。每人3分钟。然后互换角色。 总用时共6分钟。\u003c/p>\u003cp>第二环节：\u003c/p>\u003cp>我们选出一组同学，来现场给大家演练一次。（3分钟）\u003c/p>\u003cp>「学员分享】\u003c/p>\u003cp>妈妈：今天在学校发生了什么？\u003c/p>\u003cp>孩子；去拉架，别误解。委屈。\u003c/p>\u003cp>妈妈：那你很勇敢啊，被委屈了，你觉得你要怎么做，你想要的是什么？——一夯实目标，二确认了做的部分\u003c/p>\u003cp>孩子，我不应该被批评，冤枉。\u003c/p>\u003cp>妈妈：那你觉得如果下次遇到这样的情况，你会怎么做。 ——三探讨改进和提升部分\u003c/p>\u003cp>孩子：我会和老师解释清楚。我应该去找找老师\u003c/p>\u003cp>妈妈：那你从中学习到了什么啊？ ——四启发学习\u003c/p>\u003cp>孩子：抱怨没有用，还会有更大麻烦。我被冤枉了，就要去澄清这个事。\u003c/p>\u003cp>妈妈：非常好，有思考。那你下一步准备怎么做 ——五明晰下一步行动计划。\u003c/p>\u003cp>孩子：我要和老师说清楚。\u003c/p>\u003cp>总结，补充，妈妈可以问孩子需要我陪你去吗？给孩子支持和力量。\u003c/p>\u003cp>——总结：反馈好的部分，清晰每一步的重点。都应用到。而且是发问形式。没有直接给建议。\u003c/p>\u003cp>倡导学以致用，以后群里多反馈！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1702270544000,"updated_at":1703466483000,"ria":true},{"id":17022,"topic":"教练式反馈模型","learn_goal":"","remark":"日常中我们经常会遇到给下属，孩子或和我们交流的人给反馈及建议，反馈无处不在，我们总会热情‘积极’真诚的给建议，希望帮到对方。但效果怎么样呢，对方因为我们的反馈更有能动性了，还是听的频频点头，做的时候往往如如不动。教练式反馈是只发问，不给建议！还能激发被教练者的能动性。高明之极！学会受益匪浅！","level":"TF2-2","duration":18,"status":30,"type":0,"chaishujia":{"username":"璞玉","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>分组，为了我们更好的学习，会分组分享，我们先分一下组，2人一组。\u003c/p>\u003cp> 自我介绍：大家好，我叫曹瑜，我是一名家庭教育指导师，三个标签是热爱生活，兴趣广泛，（比如喜欢音乐，舞蹈，旅行摄影）还有终身成长（最近在研究chatgpt的应用）\u003c/p>\u003cp>分享主题：教练式沟通\u003c/p>\u003cp>拆书家第二级tf2-2过级分享\u003c/p>\u003cp>用时18分\u003c/p>\u003cp>学习目标：大家今天学习完grow模型后，\u003c/p>\u003cp>能够在沟通中应用教练式grow模型提问，而不是只给别人建议或讲道理。让对方明晰自己目标，知道自己的现状，启发他想到更多方案，促发行动。自我解决问题。\u003c/p>\u003cp> 图书介绍：\u003c/p>\u003cp> F：如果大家在团队管理，教育孩子，自我激励上，给建议，对方总是防御，对方无法自我负责。没有责任感，高绩效教这本书，会通过练式沟通，从四个纬度，通过发问来解决这个问题。教练式的管理也让一个企业绩效大幅提升。\u003c/p>\u003cp>A:  \u003c/p>\u003cp>约翰•惠特默爵士以其在教练领域的杰出工作获得了国际教练联合会授予的总裁奖，有大量的实战经验。本书已经升级到第五版，销量超过50万册，他是市面上关于教练式管理的鼻祖，最权威的一本。\u003c/p>\u003cp>业内关于教练书籍相对权威和实用性较高，更实用，全面。\u003c/p>\u003cp>B:\u003c/p>\u003cp>如果你的下属，工作缺乏责任感，工作积极感不高，孩子每天再为父母而学习，不催不动。或自我比较迷茫时，这个grow教练模型，都可以帮到你，通过教练式沟通让对方自我负责，调动内驱力。\u003c/p>\u003cp>同时，在教练模型思维下，让你成为一个发问高手，思维和沟通都上一个高段位。\u003c/p>\u003cp> 今天的拆页学完，你会学会一些发问的技巧，用grow模型沟通解决对方困扰问题。\u003c/p>","ratings_count":2,"texts":[{"id":21163,"quote":"\u003cp>【大家用2分钟阅读原文，阅读完后抬头示意我】\u003c/p>\u003cp>GROW模型的关键点\u003c/p>\u003cp>成功使用GROW模型的关键是首先要花费足够的时间来探索“G”目标，直到教练对象能够设定一个既能够激励他们，又能帮助其向前发展的目标，然后凭你的直觉灵活选择其他几个环节的顺序，包括必要时重新审视目标。\u003c/p>\u003cp>第1步：你的目标是什么\u003c/p>\u003cp>·理解每种不同的目标类型：终极目标、绩效目标和过程目标。\u003c/p>\u003cp>·理解不同目标类型的主要目的和期望。\u003c/p>\u003cp>·明确此轮教练对话所期望的结果。\u003c/p>\u003cp>第2步：现状是什么\u003c/p>\u003cp>·就目前采取的行动评估当前的状况。\u003c/p>\u003cp>·明确之前采取的行动的结果和影响。\u003c/p>\u003cp>·就阻碍或限制当前进展的内部障碍和阻挠进行\u003c/p>\u003cp>第3步：你有什么选择\u003c/p>\u003cp>·确定可能性和备选方案。\u003c/p>\u003cp>·将可能采取的方案策略列出一个详细的提纲。\u003c/p>\u003cp>第4步：你将要做什么\u003c/p>\u003cp>·帮助梳理学习收获，并探讨如何改变以实现最初设定的目标。\u003c/p>\u003cp>·针对已确定步骤的实施情况进行一个总结，并创建相应的行动计划。\u003c/p>\u003cp>·明确未来可能遇到的障碍。\u003c/p>\u003cp>·考虑在后续的目标实现过程中，可能需要的支持和发展。\u003c/p>\u003cp>·评估约定行动的准确执行情况。\u003c/p>\u003cp>·重点强调如何保证责任担当以及目标的实现。\u003c/p>","explains":"\u003cp>[why]我们日常中有没有遇到这样情况，员工或朋友来向我们求助，我们热情给建议，往往对方说，说这不行，那没用。你的建议换来的往往是对方的防御和理由，而且关键是责任还背你身上了。这就是我们没用激发对方做为解决问题的主体。\u003c/p>\u003cp>[what]教练grow模型就很好的解决了这个问题。教练从对教练对象的目标，到现状，到选择，和意愿行动。这四个纬度的层层递进式发问，来激发教练对象的责任感和行动力。\u003c/p>\u003cp>[how]如何应用grow模型：\u003c/p>\u003cp>第一步：明晰目标。发问对方目标是什么，想要达成的意愿是什么，通过发问让对方从问题困境中去看清自己的目标。从大目标再切到中短期小目标。\u003c/p>\u003cp>第二步，评估现状。发问对方的现状如何，让对方评估现状，明晰障碍。\u003c/p>\u003cp>第三步，启发选择。发问对方，还有那些选择，还有那些资源，启发对方实现目标的更多可能性。\u003c/p>\u003cp>第四步，促动行为。发问对方，未来将要怎么做及夯实意愿度，调动对方的责任感！启发，对方自我负责，执行计划。\u003c/p>\u003cp>我给大家举个例子：比如一个15岁的孩子天天不学习，天天打扮追星，成绩一塌糊涂，家长苦口婆心，给报了很多补习班压根也不去。和家长对抗很严重。家长来找我咨询，我给家长指导，学习grow模型之后，家长应用找个grow 模型和孩子沟通后，孩子主动报了补习班去学习一年后考上大学了。\u003c/p>\u003cp>第一步，目标，爸爸问孩子，你的理想是什么啊，孩子：我的理想是当电影明星。爸爸：哦，你想当什么样的电影明星啊，孩子，象黄晓明那样的，哦，黄晓明是那样的明星，又有实力派又是偶像派。哦，第一步目标清楚了，继续发问，那怎么样才能成为黄晓明那样的电影明星呢，孩子，他们都是电影学院毕业的。我要是也能考上电影学院，那就离我的理想更近了。哦，是的。很多明星都是电影学院毕业的。对，爸爸，你给我报个表演班，哦，好的，表演班之外就差不多？嗯，我查一下电影学院的每年的录取成绩，我现在的英语比较差一点，其他成绩我再努力一年，应该问题不大，爸，我再报个英语补习班，今年我努力学习一年，应该没问题。（爸爸通过发问孩子分析了现状，差距，探讨更多的选择，最后孩子自我催发出未来行动，调动了孩子的责任感，）孩子开始为自己学，一年后孩子考上了。第四步，基本是孩子自己催发出来的。\u003c/p>\u003cp>【预防异议】我们可能也会有疑问，那孩子，员工遇到问题就靠发问就行吗？我们这么多宝贵经验不告诉他。我们日常中习惯性给孩子苦口婆心讲道理，给建议，会觉得给建议应该是最快的。我们从上面案例及结构看grow 模型，一步步激发了对方的责任感和内驱力。我们直接给建议，对方总会找出我做不到等。实际上发问才能真正激发对方的责任感和内驱力。发问貌似放弃了这份掌控，放弃了我要给你解决问题，我要为你负责，而把问题的解决完全交给对方，这是一种看似比较慢，但是真正从根本上激发个体责任心和潜能而解决问题。\u003c/p>\u003cp>【where】这个模型我认为5岁的孩子也可以用它来发问，沟通。成人更没问题 。边界就是对方也真的想解决问题。而不只是发泄一下情绪。那就用不着这个grow模型来给对方分析。\u003c/p>","interaction":"\u003cp>大家是不是迫不及待的想在未来应用起来呢？\u003c/p>\u003cp>A1\u003c/p>\u003cp>我们来设想我们在管理团队，激励下属或教养子女，或亲朋好友来求助，问你她是该先生孩子还是先提职称，等等大家想象一个你未来可以就此教练模型的应用场景（分组）\u003c/p>\u003cp>——分享什么场景下（或时间，地点）和谁，就某个问题，用grow模型来教练一下。这一步只分享场景，不分享如何使用方法\u003c/p>\u003cp>——每人1分钟，用时 2分钟。\u003c/p>\u003cp>——找一位同学分享，1分钟\u003c/p>\u003cp>【学员分享】：我的一位朋友，大龄单身青年，总为找对象发愁，经常找我聊这个问题。我认为下次我可以用这个教练式沟通模型来和她沟通，更好解决这个问题，。\u003c/p>\u003cp>A2再请大家设想一下，如何在刚才分享的那个场景下去应用今天所学的grow 教练模型。重点在于你的立场，心态，你会做那些发问，还有你会不做那些行为。如何用grow模型层层递进，最终启发对方积极行动去解决问题。\u003c/p>\u003cp>——再2人一组，相互分享。每人2分钟。用时4分\u003c/p>\u003cp>——请一位给大家分享，用时2分\u003c/p>\u003cp>【学员分享】\u003c/p>\u003cp> 30岁单身女青年，找对象，想尽快结婚很焦虑，我看她很痛苦，我想用这个grow模型来和她沟通帮助她\u003c/p>\u003cp>我问：第一步明晰目标，你这么焦虑，你身边有没有合适的男青年啊，那你想多长时间解决这个问题？给自己定个目标呗？\u003c/p>\u003cp>朋友：一年的时间，解决，一年找到可以结婚的对象。谈恋爱，到结婚。\u003c/p>\u003cp>我问；第二步评估现状，现在什么状态啊？\u003c/p>\u003cp>朋友：现在工作比较忙，社交紧紧限于公司同事。障碍比较多，机会比较少。\u003c/p>\u003cp>我问：第三步，现在还有那些选择呢，除了公司外面还有哪些更广阔天地啊？\u003c/p>\u003cp>朋友：我现在可以参加一些社群活动。现在这些社区男士比较少，女士不多，\u003c/p>\u003cp>我问：那你有没有找过一些男士比较多的社群呢？\u003c/p>\u003cp>朋友；对啊，我可以参加无人机，摄影社区，这些男士比较多，机会更多。\u003c/p>\u003cp>我问：那你准备具体怎么做呢，列个小计划，这就到了第四步，促进行为。\u003c/p>\u003cp>朋友；目前，正好有个跑步社团，我立即加入可以参加行动起来。列出了参加的几个社团的计划。\u003c/p>\u003cp>总结：各个步骤要点都有，清晰明了，大家实践中，问的会更内容丰满些，今天掌握了基本框架，我们拆书帮到宗旨就是学以致用！\u003c/p>\u003cp>请大家grow 起来，\u003c/p>\u003cp> 发问起来\u003c/p>\u003cp> 学以致用\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1702266800000,"updated_at":1703466496000,"ria":true},{"id":16024,"topic":"用 GROW 模型激发对方的动力","learn_goal":"","remark":"当你给别人提建议的时候，在对方听来可能会变成一种谴责，或者无论你给什么样的建议，对方都会立刻下意识的告诉你说不行，因为人们天生的有一种自我保护的意识，当别人告诉你该怎么做的时候，你往往会找出特别多的理由。 也许你也给过孩子或你的员工很多的建议，到最后慢慢地都变得不了了之，或者没什么用了，是为什么？ 《高绩效教练》是一本非常重要的改善我们和他人之间沟通，激发他人梦想和力量的一个里程碑式的著作。本书重点介绍了如何通过GROW模型来激发他人行为和心态的转变。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Hiou","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>亲爱的伙伴们，大家晚上好，欢迎大家来参加今天晚上的拆书活动，我是今天的第一位拆书家，我叫熊艳丽。\u003c/p>\u003cp>用三个标签介绍一下我自己：\u003c/p>\u003cp>第一个标签是家庭教育行业从业者，目前在一家家庭教育公司做课程，从事家庭教育行业是因为我希望能够帮助更多需要帮助的父母和家庭收获家庭的成长和幸福。\u003c/p>\u003cp>第二个标签是心理学爱好者,喜欢探寻和思考看不见的人的心理，同时也是在不断地学习心理学知识来帮助自己内在的成长。\u003c/p>\u003cp>第三个标签是新手上路的拆书家，两年前第一次参加拆书帮的线下活动，就很喜欢这种每个人都可以参与的学习形式，今天我终于正式开启了拆书的升级打怪之路。\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>第一次参加我们拆书帮活动的朋友，可能会好奇什么是拆书,还有拆书帮又是个什么样的组织。\u003c/p>\u003cp>\u003cstrong>拆书\u003c/strong>，是一种成人学习的方法论。区别于以知识为中心的学习，拆书法是以学习者为中心，帮助我们单纯的从书本中学习知识上升到提升能力和解决实际问题的应用。那重点是在于提升能力和解决实际问题，而不仅仅是获得知识。\u003c/p>\u003cp>那拆书法是如何帮我们提升能力和解决实际问题的呢，那就要介绍一下\u003cstrong>RIA便签法\u003c/strong>了。\u003c/p>\u003cp>\u003cstrong>RIA便签法\u003c/strong>有两种具体的应用，一种是你自己看书学习时用，你可以用3张便签来记录，另一种是现场的学习应用，就像我们现在这样。RIA分别是什么呢，R是阅读,就是看书中的原文，在现场，R就是阅读拆书家发给大家的拆页。I是理解，就是你看了书之后，对书中知识的理解，在自己看书时，可以把你刚刚看的内容是什么，为什么，怎么做记在便签上。那在现场I就是拆书家对原文拆页的讲解引导。A是拆为己用，就是结合书中的知识联想你过去的经验，以及如何运用书中的知识来解决问题的具体规划。所以RIA就是阅读原文，然后转化为自己的理解，最后再拆为自己的应用。\u003c/p>\u003cp>\u003cstrong>拆书帮\u003c/strong>是以拆书法为学习方法论的学习爱好者社群，表现为各地的“拆书帮分舵”。拆书帮分舵是非营利性“青年自组织”，使命是“释放学习促进者的能量”，帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":20101,"quote":"\u003cp>今天我要拆解的是《高绩效教练》中的选段，主题是用GROW模型激发对方的动力,邀请大家现在用两分钟的时间阅读一下我刚刚发给大家的拆页，阅读完的伙伴可以抬头示意一下我。\u003c/p>\u003cp>\u003cstrong>【R：阅读原文拆页】\u003c/strong>\u003c/p>\u003cp>原文拆页内容：《高绩效教练》（第4版） P47-48\u003c/p>\u003cp>\u003cstrong>主题：用GROW模型激发对方的动力\u003c/strong>\u003c/p>\u003cp>一对一的教练发生在同级之间，经理和下属之间，以往的老师和学生之间，教练和执行者之间，咨询师和求助者之间。一对一的教练甚至可能会被用于一名员工对其老板的向上管理，虽然这通常是隐蔽的。毕竟，没有人能以告知的方式很大程度地影响他的上司如何去做，因而向上教练有更高的成功率。\u003c/p>\u003cp>\u003cstrong>GROW模型\u003c/strong>\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四步骤：\u003c/p>\u003cp>l 目标设定（goal），本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>l 现状分析（reality），探索当前的情况。\u003c/p>\u003cp>l 方案选择（options），可供选择的策略或行动方案。\u003c/p>\u003cp>l 该做什么（what），何时（when），谁做（who），意愿（will）。\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>\u003cp>看到伙伴们都已经看完了。\u003c/p>","explains":"\u003cp>\u003cstrong>【I重述知识点】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>不知道大家有没有这样的经历：比如，一个朋友和我们说，他现在问遇到了一个问题不知道怎么办，我们很积极的帮他出谋划策，给了很多的建议。可是我们自认为很走心的建议，对方的回应却是：你说的道理我都懂，就是做不到，或者他会说：你说得倒是轻巧，你又不是我，你根本就不懂我。好像不管你怎么给他建议，他就是觉得有无数个理由不去做它，甚至有时候还觉得我们是在给他讲道理，最后搞得双方都不舒服。\u003c/p>\u003cp>那今天要给大家分享的就是通过GROW模型的辅导提问，帮助他人把责任回归到他自己，并看到他自己的潜能，从而促使他行为和心态的转变。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>\u003c/p>\u003cp>什么是GROW模型？我们把一次帮助他人解决问题的谈话看成是一次辅导，辅导可以通过一些提问来进行，而GROW模型就是辅导提问的一个框架步骤，GROW的4个字母分别对应它的4个步骤。用这4个步骤来进行提问能帮助对方实现自我责任，认清自我的现状，获得一个清晰的解决方案，也能够增强他的行动意愿。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>4个步骤分别是什么？GROW的4个字母是G、R、O、W。\u003c/p>\u003cp>\u003cstrong>G是goal,就是目标，所以用GROW模型来进行辅导提问的第一步就是确定目标。\u003c/strong>就是当别人来问你该怎么办的时候，你要先问他这样的问题：你的目标是什么？你希望变成什么样子？你希望实现什么？等等。如果他是有目标的，你要帮他理清目标。如果他没有目标，你要激发他确立一个相对清晰的目标。\u003c/p>\u003cp>\u003cstrong>R是reality，就是现状，第二步就是分析现状\u003c/strong>，要和对方一起分析当前的情况是怎么样的，和目标之间有哪些差距。比如说，你可以问他，那么现状是什么？影响你达成这个目标的因素都有哪些？都有谁与此相关？你都做过哪些努力？效果如何？等等。在分析现状时我们要用提问帮对方弄清楚客观事实，了解他所处的现状。\u003c/p>\u003cp>\u003cstrong>O是options，就是各种选择，第三步就是探讨选择方案。\u003c/strong>这里不是要和对方确定一个选择方案，而是和他一起探讨出更多的想要达成目标的可能性的方案。比如你可以问他：你可以做哪些不同的事来达到目标？还有吗？我们再多想一个办法看看？要像头脑风暴一样，用开放性思维探讨很多的解决方案，哪怕看起来很愚蠢可笑的，也要先记下来。\u003c/p>\u003cp>\u003cstrong>第四步是W，W是will意愿。就是将要怎么做，最后的行动方案是什么。\u003c/strong>其实它是包含了4个W，分别是what、when、who和will。你可以问他：你准备怎么做？你打算什么时候做？这个事情还需要谁的支持和帮助？你行动的意愿程度怎么样？给你的行动意愿程度打分，1-10分你打几分？是什么阻碍了你打10分？所以，第四步是确认行动，是将讨论转入决策的阶段。\u003c/p>\u003cp>因为没有把自己的想法强加给对方，而是激发他的意愿，他自始至终都掌握着主动权，所以用GROW模型来进行辅导，可以更好的激发他人自身的潜能和改变的动力。\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>\u003c/p>\u003cp>GROW模型只有在具有觉察和责任感的背景中才有效，就是用GROW模型来进行辅导提问是要对方是有意愿解决问题的，否则也是帮不了他的，就比如老板单方面的用这个步骤来给员工制定目标和方案是行不通的。\u003c/p>\u003cp>使用GROW模型最重要的一点就是你要时刻记住解决问题的责任在对方，你不要给建议，也不要对他有评价，如果你说：你这个想法不好，你应该这样，你不应该那样。这样的话责任很容易又回到我们身上，而没办法激发他的自我责任感和动力了。一个好的辅导过程的关键就是帮助对方提升觉察力和建立好的责任感。\u003c/p>\u003cp>这个就是关于GROW模型的介绍。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1联系具体经验】\u003c/strong>\u003c/p>\u003cp>我在学习到GROW模型的时候，脑海里出现了一句话：你说的这些道理我都懂。这是前两周一个周六晚上一个朋友给我打电话时对我说的一句话。她打电话给我是向我倾诉说她现在很纠结，不知道要不要把孩子送回老家。我当时并没有倾听完全部的前因后果，就开始表达我的观点，站在家庭教育的专业角度，给了很多我自认为十分中肯的建议，我以为会让她豁然开朗，结果电话结束她还是很不开心，好像并没有解决她的问题。\u003c/p>\u003cp>学习完GROW模型之后我就在\u003cstrong>反思\u003c/strong>：\u003c/p>\u003cp>为什么我自认为给了朋友很好的建议，她却告诉我：你说的道理我都懂呢。原因就是在我没有意识到解决问题的责任在对方，也没有去帮助她看到她自己有解决问题的潜力。而是去积极的给意见了，一旦我们轻易的给对方建议，对方就会立刻把责任推到了我们身上，形成依赖，或者他会下意识的说：这也不行，那也不行，因为人天生就有自我价值保护的意识。\u003c/p>\u003cp>以后我再遇到有人找我问“怎么办”的时候，就可以尝试用GROW模型，通过辅导提问来帮助他看见自己的潜能和解决问题的能力，还可以激发他行动的动力。\u003c/p>\u003cp>\u003cstrong>【A2规划具体应用】\u003c/strong>\u003c/p>\u003cp>（目标：）\u003c/p>\u003cp>下周星期天，我打算用GROW模型帮助一个朋友梳理他目前遇到的职业选择的问题，目标是帮助他能有一个更清晰的解决方案，并有信心和动力开始他的行动。\u003c/p>\u003cp>（行动：）\u003c/p>\u003cp>为了让下周日的沟通辅导更顺利，我打算下周五之前把GROW模型的每个步骤再次深入了解，多理解几个书中的应用案例，然后周六上午把GROW模型的步骤包含的问题罗列出来，准备好我将会怎么提问，提哪些问题，第三个就是要提前预设和分析辅导中可能会遇到的障碍，并想好对应的解决方案。第四个是我自己在周六做一次提前演练，确认熟悉步骤。周日见面按照准备的来行动。\u003c/p>\u003cp>以上就是今天我的分享——用GROW模型激发对方的动力的全部内容，谢谢大家。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1686567075000,"updated_at":1686625594000,"ria":true},{"id":15403,"topic":"倾听和提问","learn_goal":"","remark":"倾听和提问","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"袁士欣","city":""},"club":{"name":"烟台八仙过海分舵","city":"烟台"},"prologue":"\u003cp>学习目标：\u003c/p>\u003cp>在完成本次拆书学习之后，能够学会倾听的基本技巧。\u003c/p>\u003cp>自我介绍：\u003c/p>\u003cp>我是袁士欣，一个坚持跑马拉松的财顾小哥哥。同时我也是个保险经纪人。对于我来讲，卖保险这件事情是我这个属于工作上面在做的事情，那同时我更享受的事情是来去传播财商的教育。因为我看到了在拆书是一个非常好的学习知识的一个工具，所以我也就来到了拆书帮去学习拆书，成为一个拆书家啊，这是我加入到拆书帮的原因。\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>F：《高绩效教练》的作者是约翰·惠特默。这本书主要讲了如何用教练的方法提升员工绩效。书里讲到的GROW模型是经典的教练式沟通的模型。\u003c/p>\u003cp>A：这本书的豆瓣评分达到了8.1分，在教练类书籍里，这本书在全球销量榜榜首，被翻译成20多种语言出版。作者首次把教练的概念引入到企业管理中，也因此获得了国际教练联合会授予的总裁奖。\u003c/p>\u003cp>B1：通过学习这本书，你可以掌握教练式沟通技巧，这种技巧在你培训、带人、管理团队中，帮助你最大限度地激发教练对象的潜能。\u003c/p>\u003cp>B2：今天拆解的片段是教练式沟通中的2个技能，倾听和提问。学习倾听的技巧，可以让你的教练对象感受到安全感，可以让她感受到被看见、被共情。学习提问的技巧，可以激发教练对象发生更多的思考。\u003c/p>","ratings_count":1,"texts":[{"id":19459,"quote":"\u003cp>真正地被“倾听”，并被真正地“听到”是很奢侈的。大多数人都不擅倾听；大家在学校被告知要倾听，却没有被训练或被指导如何倾听。通常当人们表现出似乎在倾听时，他们只是在等待他们发言的时机，一旦时机到了，他们就会按照自己的日程行事。他们可能会谈论一些完全不相关的事情，或者想要分享他们自己的经验、想法和观点，或者给出一些建议。花一分钟的时间，回忆一下最近一次当别人用这种方式“听”你时你的感受。\u003c/p>\u003cp>对回答保持关注\u003c/p>\u003cp>教练意味着要充分关注教练对象对问题的回答——包括关注其表达的内容和传递的感受。如果这种关注不发生，信任就会消失，教练也就不会知道接下来的好问题是什么。提问必须是一个自然的过程。如果教练提问事先准备好的问题将会破坏交谈的流畅性，不能跟随教练对象的兴趣以及他们自己的议程。如果你的教练对象讲话时你在想下一个该问什么问题，教练对象就会觉察到你没有在倾听。最好先仔细听对方把话讲完，如果需要的话停顿一下，等待下一个合适的问题自然浮现出来。如果你真的是在倾听，那么你的直觉将会是你最好的向导。\u003c/p>\u003cp>你的注意力在哪里\u003c/p>\u003cp>倾听是一种技巧，需要全神贯注和加以练习。但奇怪的是很少有人在听新闻或听一个好的广播剧时存在困难。兴趣有助于保持注意力。也许你需要学会对他人感兴趣，让自己保有好奇心。当你真正倾听某人，或是当某人真正倾听你的时候，那是多么难能可贵呀！当你倾听时，你真的听到了吗？当你观看时，你真的看见了吗？我的意思是要跟对方进行目光交流。人们喜欢沉浸于自己的想法、观点和想要谈的事情上，特别是被安排为提供建议的角色之时。有人说，既然我们有两只耳朵和一张嘴，那么我们的听说之比就应该是2∶1。也许教练要学会的最难的事就是闭嘴。\u003c/p>\u003cp>——《高绩效教练》第8章\u003c/p>","explains":"\u003cp>What：\u003c/p>\u003cp>这个片段讲了能让教练对象感受真正被“听到”的2个技巧。\u003c/p>\u003cp>Where：\u003c/p>\u003cp>这两个技巧可以使用的场景：\u003c/p>\u003cp>1. 教练式沟通。\u003c/p>\u003cp>2. 家人朋友不开心向自己倾诉。\u003c/p>\u003cp>3. 客户、下属的投诉和抱怨。\u003c/p>\u003cp>Why：\u003c/p>\u003cp>为什么我们要用这样的方法倾听呢？当我们说的话被“听到”，我们才有继续说下去的欲望。所以，当我们的角色变成倾听者时，我们要做一些事情，让对方感受到我们在认真地听。我们听得越认真，我们就能听到越多有用的信息。\u003c/p>\u003cp>【强调不那么做的坏处】\u003c/p>\u003cp>如果我们没有认真听对方说的话，我们的内心变化是会从眼神、表情里表现出来，对方会因此产生不信任，这种不信任会让对方不愿意跟我们倾诉更多。\u003c/p>\u003cp>去年，有一次我和一个同行一起喝茶交流。在交流过程中，我非常想说说我对行业的理解。但我发现，我刚起一个话头，他就把话接了过去，继续表达他的想法。来回几次之后，我放弃了，对这次谈话没有了任何兴趣。本来他是有招募我的想法的，但最后他连我的需求都没机会了解。\u003c/p>\u003cp>对他来说，更好的交流方式是，减少自己的发言，多听我说，他才有机会了解我的想法、我的需求。\u003c/p>\u003cp>How：\u003c/p>\u003cp>【细化步骤】\u003c/p>\u003cp>如何倾听：\u003c/p>\u003cp>1. 沟通前不要预设问题\u003c/p>\u003cp>2. 关注对方的每一句话\u003c/p>\u003cp>3. 适当回应，尽量少说话\u003c/p>\u003cp>4. 等待下一个问题自然浮现\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>在倾听过程中，你可能会遇到一些问题，比如，对方说的太多怎么办？\u003c/p>\u003cp>如果我们倾听的目的是为了帮对方疏解情绪，对方说的多，说明对方的情绪积压真的很重，我们要允许她多说，有利于她把情绪都释放出来。\u003c/p>\u003cp>如果我们倾听的目的是为了给予教练式沟通，说得多说明思考得多，我们获得的信息越多，越有利于我们了解他的想法。在回应中，我们跟上适当的问题，就能把控谈话，这是另一个技能。\u003c/p>\u003cp>如果对方说得太少怎么办？\u003c/p>\u003cp>这考验的是我们提问的能力，在下一个拆页中，有相应的解决方案。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>回想一下，过去一年你有没有这样的经历：教别人做一件事情，指导下属工作，倾听家人诉苦，处理客户投诉。想一想你在这个过程中是如何倾听的，倾听结果如何，与大家做一下分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员：在家里，老公跟自己念叨工作上、职场上、和朋友之间的事，我也不感兴趣，我很少静下心来去听。\u003c/p>\u003cp>回应：你这么做之后，你老公是什么表现？\u003c/p>\u003cp>学员：下次不说了。\u003c/p>\u003cp>回应：你是什么感觉？\u003c/p>\u003cp>学员：感觉不正常。\u003c/p>\u003cp>回应：好的，这是我们不倾听给我们带来的结果。\u003c/p>\u003cp>A1+:\u003c/p>\u003cp>【遇到同等情形如何做】\u003c/p>\u003cp>如果再遇到同样的情形，你打算在哪些方面做改变？请说明你最想改变的一点。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员：我先把不耐烦控制住。听他说的时候，我先把手机放下来。也不会走开去做别的事情。过程中我会一直保持关注，比方他问我是什么问题，我都及时去回复。\u003c/p>\u003cp>【关联到原文知识点的回应和反馈】\u003c/p>\u003cp>回应：好的。我们下一次沟通的时候能够做一点改变就好，我们能看到，你做到了一点是保持对对方的关注。我相信通过你的这一点改变，你和你老公的沟通一定会变得更好。\u003c/p>\u003cp>过渡：\u003c/p>\u003cp>【体现两段拆页关系】\u003c/p>\u003cp>第一段内容我们学习的是如何倾听。倾听是在对方有表达欲的时候使用的技巧，如果对方不知道说什么，你可以使用的技巧是提问。倾听和提问是在教练式沟通中全程都要使用的两个技能。\u003c/p>\u003cp>下一个片段学习目标是：在完成本次拆书学习之后，会使用提出好问题的方式引导沟通对象思考。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":19460,"quote":"\u003cp>开放式问题\u003c/p>\u003cp>开放式问题要求描述性的答案，从而提升觉察，而封闭式问题则是要求绝对准确的回答，这“是”与“否”的答案关闭了进一步探索细节的大门。它们甚至不能推动人们大脑的运转。在教练过程中，开放式问题可以更加有效地产生觉察和责任感。\u003c/p>\u003cp>以下问题都是开放式问题。\u003c/p>\u003cp>·你想要完成什么？\u003c/p>\u003cp>·此刻发生了什么？\u003c/p>\u003cp>·你想要怎样？\u003c/p>\u003cp>·什么东西能阻止你？什么能帮助你？\u003c/p>\u003cp>·可能会有什么问题？\u003c/p>\u003cp>·你能做什么？\u003c/p>\u003cp>·谁能帮助你？\u003c/p>\u003cp>·你可以在哪里获得更多？\u003c/p>\u003cp>·你将会怎么做？\u003c/p>\u003cp>疑问词\u003c/p>\u003cp>创建觉察和责任感最有效的问题应以寻求量化或收集事实的词语开始，比如“什么”“何时”“谁”“多少”。不建议使用“为什么”，因为它经常意味着批评并会引发防御心理。使用“为什么”和“如何”时，不合适的问题会引发分析性思考，这可能会适得其反。分析（思考）和觉察（观察）是不同的心智模式，几乎不可能同时应用并充分发挥效用。如果需要对事实准确地报告，对其出处和意义的分析最好暂时停止。如果你确实需要询问有关“为什么”的问题，最好表达成“是什么原因……”，而有关“如何”的问题可以用“做这件事情的步骤是……”来替代。这更能引发具体和真实的回答。\u003c/p>\u003cp>专注细节\u003c/p>\u003cp>开始的提问应该宽泛，然后逐渐聚焦于细节。这种对细节的关注可以让教练对象专心致志、保持兴趣。这一点可以用查看1平方英尺\u003c/p>\u003cp>地毯的例子来说明。在观察完纹理、颜色、图案，可能还有一个斑点或是污点后，观察者就不会再对那块地毯给予更多的关注和兴趣了，他的注意力会开始转移到更有意思的事情上。但给他一个放大镜，他会在失去兴趣前更深入地、长时间地再看一遍。一个放大镜会将那一小片地毯变为一个充满形状、质地、颜色、微生物甚至活生生的昆虫的迷人世界，足以让观察者长时间地目瞪口呆。\u003c/p>\u003cp>这同样适用于教练。教练需要更加深入地探索细节，并让教练对象意识到那些比较模糊的因素可能非常重要。\u003c/p>\u003cp>通过加入个别词语可以更加聚焦开放式问题的焦点。比如：\u003c/p>\u003cp>·你还想要些什么？\u003c/p>\u003cp>·你真正想要的是什么？\u003c/p>\u003cp>·到底什么正在发生？\u003c/p>\u003cp>·你还能做些什么？\u003c/p>\u003cp>·确切地说，你将会做些什么？\u003c/p>\u003cp>你的问题不需要套用这些例句，只需融这些原则并基于你的情境选择令你舒服的用词。不经意的提问“然后呢？”就可以替代正式的提问“确切地说，你将会做些什么”。一个最强有力的教练式问题就是简单的问题“还有呢”。\u003c/p>\u003cp>——《高绩效教练》第7章\u003c/p>","explains":"\u003cp>What：\u003c/p>\u003cp>这段拆页告诉我们如何提出一个好问题，引导沟通对象做进一步的思考。\u003c/p>\u003cp>Where：\u003c/p>\u003cp>这种方法的使用场景：\u003c/p>\u003cp>1. 教练式沟通。\u003c/p>\u003cp>2. 指导下属工作。\u003c/p>\u003cp>3. 引导式培训。\u003c/p>\u003cp>4. 拆书会。\u003c/p>\u003cp>5. 头脑风暴会。\u003c/p>\u003cp>Why：\u003c/p>\u003cp>为什么我们要学习这种提问方法呢？这种沟通方法有利于我们获取对方更多的信息，知道对方是怎么想的，我们才更容易帮对方解决问题。\u003c/p>\u003cp>【强调不那么做的坏处】\u003c/p>\u003cp>不这样做会怎么样？\u003c/p>\u003cp>在不用这些方法的时候，我们要么会把对方的思路逼入死胡同，要么启动对方大脑的防御机制，这都不利于引导对方发散思考。\u003c/p>\u003cp>在公司开会的时候，领导经常会问这样的问题：为什么这个月没有完成目标？在听到这句话时，我的第一反应是领导在责备我，我的第一反应是找借口。我一点没有要找改进方法的想法。\u003c/p>\u003cp>如果这句话改成“你这个月没完成目标是什么原因？”我的感受就会好一些。\u003c/p>\u003cp>How：\u003c/p>\u003cp>引导提问的步骤：\u003c/p>\u003cp>1. 设计一个开放式的问题。\u003c/p>\u003cp>2. 用其他词代替“为什么 ”“如何”这样的疑问词。\u003c/p>\u003cp>3. 先提出宽泛性问题。\u003c/p>\u003cp>4. 逐步提出更细节的问题。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>驾校教练是我们接触最多的教练，他会时刻提醒我们看清前方路况。\u003c/p>\u003cp>你的驾校教练有在教你上道的时候问你问题吗？有没有这么问题的：你看清楚前方路况了吗？\u003c/p>\u003cp>你听到这个问题是什么感觉？是不是还有点抵触？或者变得更紧张了？\u003c/p>\u003cp>“你为什么不看清楚前方路况？”你教练这么问过你没？你是什么感觉？是不是更加抵触，或者习惯性辩解：“我看清楚了。”“我不知道。”或者你会直接跟教练说：“让你说的我更紧张了。”\u003c/p>\u003cp>这些问题都不能激发学员。但请想想，如果问题换成这样是什么效果。\u003c/p>\u003cp>1.当你开到这条道上的时候，你看到了什么？\u003c/p>\u003cp>2.距离前面的路口有多远？\u003c/p>\u003cp>3.通过这个路口时，你对车速有什么感受？\u003c/p>\u003cp>4.你觉得距离这个路口多远就应该开始踩刹车了？\u003c/p>\u003cp>与之前的问题相比，这4个问题会带来4个影响：\u003c/p>\u003cp>1.你要回答看到了什么，一定会真的看清前方路况。\u003c/p>\u003cp>2.回答前面路口有多远，你会集中注意力做估算。\u003c/p>\u003cp>3.问对车速的感受，是描述性的，而非批判性的，不存在伤害自尊的风向。\u003c/p>\u003cp>4.问距离多远踩刹车，可以通过验证答案的准确性，来了解学员是否聚精会神。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>我已经看出了问题所在，能不能直接告诉他？\u003c/p>\u003cp>过往我们都是采取这种方式与别人沟通的，想一想我们告诉孩子改正的事情，我们指出的下属的错误，有多少真的被改正了？\u003c/p>\u003cp>这是因为每个人的认知不同，面临的情况不同。通过问的方式，能让对方把更多你不知道的信息告诉你，你才有机会了解他的卡点在哪。\u003c/p>\u003cp>如果他自己能得出你想要的结论，那他就真的想通了。\u003c/p>\u003cp>如果对方得出的结论跟自己不一样怎么办？\u003c/p>\u003cp>场景不同，处理的方法也不同。\u003c/p>\u003cp>比如面对孩子，我们要想，我们的引导过程中有没有让他抵触，他故意给了一个你不喜欢的答案。如果没有抵触，说明孩子的认知还没到位，我们要给孩子成长的空间，尊重孩子的选择，后面可以带他做复盘，孩子其实比我们想象的优秀。\u003c/p>\u003cp>如果面对的是下属，我们也可以给他成长空间。同时，我们应该把这种情况反馈到招聘上，下次招人要确认应聘者的关键认知是否具备。\u003c/p>","interaction":"\u003cp>A3:\u003c/p>\u003cp>场景设计：\u003c/p>\u003cp>分舵目前只有10个会员，我们的舵主发愁下一步该如何发展。你是分舵的教练，现在你要跟舵主做一次教练式沟通。引导舵主对下一步发展做思考。你会提出的第一个引发他思考的问题是什么？\u003c/p>\u003cp>小组讨论：\u003c/p>\u003cp>今天我们只分一个小组。我们一起讨论出一个好的答案。\u003c/p>\u003cp>角色扮演：\u003c/p>\u003cp>现在我们需要2个小伙伴做角色扮演。一个人扮演舵主，另一个人扮演教练。教练除了提出刚刚讨论的问题外，还可以应用今天拆的两个拆页的内容，与舵主做3分钟的即兴沟通。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>【组内角色扮演】\u003c/p>\u003cp>教练：你理想中的分舵应该是什么样？\u003c/p>\u003cp>舵主：几方面吧，就比如说。会员人数持续增多啊！就是不是猛然间增多一个月增多了十个人，然后后边几个月没有的那种是持续的，就证明咱们的影响力在持续扩散。然后另一方面是已经入会的会员，我们持续的去有一部分持续的去晋级。然后另一部分是体现过，就是活动一直在定时开展，这证明我们是一个向上的一个阶段。然后这样的分座应该是一个就是。就是向上的这么一个状态吧，我理想中的分舵应该就是这样啊。\u003c/p>\u003cp>教练：我听说你，我们会员持续增多。那就是目前我们身做会员的进展如何，或者你有什么好的方法能让这个会员会持续增多呢？\u003c/p>\u003cp>舵主：目前应该从1月份到现在也就是录了一个吧？还是个没有交会费的？嗯，进展比较缓慢，在这一块儿拓新方面，我感觉我们其实需要。嗯，有一个持续性的。一个活动来吸引他们吧啊，一个持续性的活动啊，你觉你认为我们会举办什么样的活动会更好更吸引会员呢？首先一个是就是。先说大面就是不管是什么活动。先持续，然后再一个是能吸引新会员的应该。嗯，应该是，也就是用那种。拆书法的那种魅力去吸引他们，而不是那种积极活动。然后持续的去输出一些影响，或者是输出一个片段对他的影响，然后这样的话就是慢慢的不会打影响力才会吸引来会员。就是用拆书法的影响去影响。\u003c/p>\u003cp>回应：采访一下两位，这样问完了之后感受如何？\u003c/p>\u003cp>舵主扮演者：愿意主动思考，愿意积极主动地去改变。\u003c/p>\u003cp>教练扮演者：我不用动脑，顺着对方的思路问问题就好。对方会充分思考，答案超出我的预期。\u003c/p>\u003cp>回应：感谢两位的反馈。刚刚教练提的问题比较符合我们今天学习的好问题的要求。我们以后在与人沟通的时候，也要做到这样。\u003c/p>\u003cp>A2:【A2包含情景或场景】\u003c/p>\u003cp>指导学员、指导下属、拆书、培训、头脑风暴会，以上这些场景，哪些是你在未来一个月能用到的场景，请选一个描述一下。\u003c/p>\u003cp>在这个场景中，你将如何练习今天学到的提问技巧，请写下你认为最重要的一点。然后我们每个人分享一下自己的答案。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员：下周一晚上开始，用提问的方式引导孩子去提醒孩子，我会问：咱们接下来要干什么？咱们今晚还要做什么事？\u003c/p>\u003cp>回应：期待你沟通的改变能够带来不错的效果。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>通过今天的拆解，相信你一定可以在倾听和提问上给别人更多的赋能。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1679469652000,"updated_at":1680182493000,"ria":true},{"id":13703,"topic":"教练会谈的框架","learn_goal":"","remark":"你有没有发现和90后、00后工作沟通时“胡萝卜+大棒”的领导风格已经不奏效？\n\n你有没有发现TA来问你怎么办，你给明明给出的是“建议”，TA听到的是“指责”？\n\n你有没有发现沟通工作目标后，常常TA在执行过程中都会打折扣？\n\n\n\n90后、00后需要的是能帮助他们树立自信、激发潜能的的“教练型领导风格”，“教练会谈”应该遵循什么样的框架？来听高瑶拆解图书《高绩效教练》","level":"TF1-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"高瑶","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是高瑶，用拆书帮的3个标签法介绍一下自己：\u003c/p>\u003cp>² 培训管理工作者：10年以上培训管理工作经验\u003c/p>\u003cp>² 持续收入倡导者：过去的生活经历让我看懂手停口停的工作，无法应对生活中必然会发生的“意外”！不惑之年开始创业，是看懂持续收入的美好，也希望帮助更多人获得持续收入，获得富足人生！\u003c/p>\u003cp>² 终身成长践行者：不论是本职、创业和生活，在选择上我都会看重一点，带给我的成长！\u003c/p>\u003cp>希望和大家一起在拆书的路上和个人成长的路上，彼此照亮，升级人生！\u003c/p>\u003cp>【拆书&amp;拆书帮介绍】\u003c/p>\u003cp>拆书是一种成人化的方法论，拆书既不是把书拆掉，也≠划重点，重点在于和学习者产生“联结”，可以说学习者在应用拆书法学习时，最重要的把书里的知识和自身过往经验相连接，并且思考怎么应用到以后的生活工作中去。拆书法有两个应用场景：\u003c/p>\u003cp>1.个人学习，学习者用RIA便签读书法，达到参加一场培训的效果\u003c/p>\u003cp>2. 组织学习，拆书家将一本书、或者同一主题书籍的不同片段加工成一场现场培训，引导一群人将某一主题内容拆为己用\u003c/p>\u003cp>而拆书帮则是一群使用拆书法学习的伙伴的社群，在各地有分舵，帮助更多的学习爱好者个人成长，打怪升级，成为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":17729,"quote":"\u003cp>《高绩效教练》P85\u003c/p>\u003cp>教练的框架\u003c/p>\u003cp>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003c/p>\u003cp> 目标设定(Goal) 含本次教练对话的目标，以及设定教练的短期目标和长期目标\u003c/p>\u003cp> 现状分析(Reality) 探索当前的状况。\u003c/p>\u003cp> 方案选择(Option), 可供选择的策略或行动方案。\u003c/p>\u003cp> 该做什么(What) ,何时(When), 谁做(Who), 以及这样做的意愿(Will)。\u003c/p>\u003cp>这个顺序可以方便的形成助记符Grow, 我会不断的提到它。因为选择和自我激励对成功至关重要。所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。\u003c/p>\u003cp>这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>","explains":"\u003cp>【I：便签】\u003c/p>\u003cp>What：（关键词：目标、现状、方案、意愿）\u003c/p>\u003cp>大家刚才阅读的片段来自于约翰·惠特默爵士《高绩效教练》，这本书被誉为教练领域的《圣经》，大家刚才看到的就正是整本书里最核心的Grow教练模型的基本框架,包含了目标、现状、方案和意愿四个部分。\u003c/p>\u003cp>Why:\u003c/p>\u003cp>很有意思的是这个模型来自于意外发现：这位爵士的体育俱乐部由于网球教练人手不够，请滑雪教练来救场，但是发现经过一学期的训练，滑雪教练居然可以培养出网球高手！\u003c/p>\u003cp>想象网球场里，运动员打出一个球后，如果是网球教练指导，他会说：你的手臂应该怎样，你的腰应该怎样，运动员会去做但不会去想，所以进步缓慢。而如果是滑雪教练从旁指导，那画风恐怕会大不一样，因为他们不会打网球，所以TA会问：“你觉得刚才那个球打的怎么样？什（R现状）？”，“我感觉好像发球角度有点偏。”“那你觉得应该怎么调整下呢？（O选择）”，“我觉得需要调整一下握拍的角度”。\u003c/p>\u003cp>你看正是因为他们不会打网球，他们就不会一上来就建议，而是提问，让运动员自己琢磨自己的现状，再自己琢磨怎么去调整达到掌握打球技巧。这样的教练方式帮助运动员找到了状态，并且自己主动承担改变的责任。\u003c/p>\u003cp>在生活和工作中，当会有人问你这事怎么办，我们常常会根据自己的经验给出答案或者建议，中国人好为人师啊，但是给出建议后常会有2种情况，要么他当场说你这方法我试过了，因为……原因行不通，要么对方说“我试试看”却没有下文，究其原因就是因为这个建议是“你”给出的，大部分人在问问题时并不是不知道答案，只是不想去承担这个责任，因为谁给出了答案自然就应当负责！那么GROW教练模型就可以很好的解决这个问题，通过不断提问的方式引导对方承担责任、主动思考，使目标清晰，寻找达到目标的方法并且激发对方想把事情做好的动力。一般来说，教练模型需要遵循四个步骤：\u003c/p>\u003cp>HOW\u003c/p>\u003cp>问目标。工作生活中出现问题，常常是不清楚自己真正想要什么，也就是“想去哪”。通过提问，可以厘清目标，具体到这次对话的目标，也可以厘清短期和长期目标。\u003c/p>\u003cp>问现状。目标明确后，我们需要明确“我在哪”——通过提问，可以客观了解我们的现状，之前做过什么，有哪些阻碍前进的因素等等\u003c/p>\u003cp>问方案。目的地-所在地的距离，我们有哪些方案可以选择？是飞机、高铁还是自驾或者拼车？\u003c/p>\u003cp>问行动。方案确定后，就该决定好谁去（who）？什么时候（when）动身？需要准备带些什么（what）？还有最需要确认的却最容易被忽略的一点是：真要出发吗？（will）\u003c/p>\u003cp>WHERE：这个模型可以应用在工作辅导，培训，老师带学生，家长辅导孩子，开导朋友等场景。\u003c/p>","interaction":"\u003cp>【A1:激活经验】\u003c/p>\u003cp> 我有一个合伙人，在兼职创业的过程中，常常会因为思路不清晰和主业的时间冲突等原因，造成兼职创业工作没有头绪，过去她跟我说不知道该怎么做时，我常常会直接告诉她答案，但是我发现她常常是做了没两天就停下来了。于是前几天她又来找我沟通没有忙到点子上时，我就使用了这个GROW模型跟她沟通：\u003c/p>\u003cp> 因为月初与她沟通过目标，所以我通过【问目标】问让她回顾一下月初的计划，是要开好20人的本店，此时再次通过提问，得知她目前已经有8个会员，这样就能引导她自己说出和目标的差距，和可以进行的行动计划。当然我知道在执行的过程中不会一帆风顺，所以我在【问现状】的时候会问她会有什么阻碍她自己刚刚说出的推荐计划。当她能坦诚说出“不想动脑子”时，我想这是很多人在别人建议时的真实心理，潜意识就是我不但不想动脑子，而且我还不想承担完不成的责任。于是我加入“如果做到了对你有什么好处”，引导她思考完成本月的目标对于她的事业的影响。然后再【问方案】为了达成目标需要做什么？并且通过“还有吗？”这个提问，让她意识到除了推荐计划，还有学习计划 和跟进计划需要去做。通过“提问”+“鼓励”的方式，我的这位合伙人厘清了工作思路，觉得自己“脑子清晰，也不混沌了，人也精神了”，变得开心，于是我继续最后一击【问行动】，她立刻有了非常具体的行动计划。\u003c/p>\u003cp>【反思】这个对话是我看了GROW教练框架之后有意识的一次应用，教练沟通的核心是激发被教练者的潜能，而不是让一个有丰富经验的人去传授经验，所以按照目标-现状-方案-意愿的提问顺序提问，让被教练者按照教练框架自己想出达成目标的方法和行动计划是才是重点，教练者要尽量控制自己不说答案，避免成为背锅侠。\u003c/p>\u003cp>【A2:目标与行动】\u003c/p>\u003cp>准备明天和女儿用GROW模型进行一次谈话\u003c/p>\u003cp>1） 问问女儿，对于马上要进行的分班考目标是什么？\u003c/p>\u003cp>2） 想达到她的目标，在有限的时间内，目前的学习科目中需要着重关注的是哪一科，她需要获得什么帮助\u003c/p>\u003cp>3） 把达成目标的策略做成每日计划贴在墙上。\u003c/p>\u003cp>4） 每天按照完成情况打√\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1656837526000,"updated_at":1658067773000,"ria":true},{"id":12844,"topic":"grow模型","learn_goal":"","remark":"当员工带着某个问题来找你帮忙的时候，通常你会怎么做？\n大多数人的第一反应就是“我觉得吧，你应该……”又或者是“我建议你……”结果就是什么事都落到你头上，揽的一身活，结果还不尽如人意，员工也得不到成长；再看一种情况就是有些员工浑水摸鱼、偷懒，你想到的对策就是胡萝卜加大棒，但是结果如何呢？该混日子的还是混日子，对嘛？\n如果你想改变这种现状，提升你的管理效率，成为一个能够帮助他人、令人尊敬而不是烦人的管理者，可以看一下这本书。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"season&蒋恺轩","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>大家好，我叫蒋恺轩，大家可以称呼我恺轩。今天由我来陪伴大家一起进行本次的RIA现场拆书学习。我今天分享的内容来源于约翰·惠特莫爵士的代表作《高绩效教练》。\u003c/p>\u003cp>F:约翰·惠特默爵士是商业教练的先驱，绩效咨询（国际）有限公司的联合创始人。他成功地把教练技术从体育行业迁移到了商业领域，为企业高管提供一对一的服务，被授予教练领域的“终身成就奖”。\u003c/p>\u003cp>这本书的核心内容有两个方面：\u003c/p>\u003cp>1、教练型管理如何区别于传统型管理，从而有效提升员工的绩效表现？\u003c/p>\u003cp>2、教练型管理者该怎么跟员工对话，有什么操作要点？\u003c/p>\u003cp>A:这本书介绍的是一种全新的教练型的管理风格，强调由内而外地释放员工的潜能，让员工在高效完成工作的同时，实现自我成长和蜕变。提供了非常实用的模型和方法，便于我们进行模仿和操作。\u003c/p>\u003cp>B:想想看，当员工带着某个问题来找你帮忙的时候，通常你会怎么做？大多数人的第一反应就是“我觉得吧，你应该……”又或者是“我建议你……”结果就是什么事都落到你头上，揽的一身活，结果还不尽如人意，员工也得不到成长；再看一种情况就是有些员工浑水摸鱼、偷懒，你想到的对策就是胡萝卜加大棒，但是结果如何呢？该混日子的还是混日子，对嘛？\u003c/p>\u003cp>如果你想改变这种现状，提升你的管理效率，成为一个能够帮助他人、令人尊敬而不是烦人的管理者，可以看一下这本书。\u003c/p>","ratings_count":1,"texts":[{"id":16805,"quote":"\u003cp>教练的框架：\u003c/p>\u003cp>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003c/p>\u003cp>●目标设定（Goal），包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003c/p>\u003cp>●现状分析（Reality），探索当前的状况。\u003c/p>\u003cp>●方案选择（Options），可供选择的策略或行动方案。\u003c/p>\u003cp>●该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will）。\u003c/p>\u003cp>这个顺序可以方便地形成助记符GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。请参见图9中每个阶段的关键问题列表。\u003c/p>\u003cp>这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。GROW模型如此有效的一个因素就是这个框架是灵活的。\u003c/p>","explains":"\u003cp>在跟随我完成本次RIA现场学习之后，学习者能够在进行员工辅导时减少使用“命令+告知”模式的频率，而是能够主动去运用GROW的模型和员工进行对话。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>\u003c/p>\u003cp>教练型管理教给我们要对员工充分的信任，相信员工本身拥有解决问题的资源和能力，通过高质量的提问和对话，提升员工的能力和动机，帮助他们排除干扰，让他们的潜能得到释放，高效完成工作的同时实现自我探索和蜕变。\u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>\u003c/p>\u003cp>通常情况下，大家对员工管理属于“控制型管理”，在沟通方面，喜欢用“命令+告知”的方式，不论是发号施令还是提出建议或者员工提方案，我们拿主意都属于这种类型，这种方式导致员工就只会把工作当做是你的责任，而和他没有关系，本身的责任感不强；另一方面在激励上，采用“胡萝卜加大棒”的方式，好好干我给你奖励，不好好干，我后面就有规章制度惩罚你，最终的结果如何呢？显而易见不怎么样，大家可以看看企业内有多少仍然在混日子的员工就知道了。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>举一个我自己的亲身经历，在2019年5月的时候，我和团队内的一个伙伴沟通工作内容，我大概是这样的表述了一下，在年底我们需要完成1300的客户新增量，100场社区活动，目前和供应商的对接上出现了很严重的问题，按照我们之前的沟通，你要设计一个进度表，里面包含了“时间、地点、方式、参与人员、人员信息、时候报告等等等”，最后就是我给她布置了一大堆的内容，包含了后面遇到的种种可能的困难都说了，各种情况的解决方案也都想好了一一告诉他，照着做就行，并且还说了OKR的达成和他的年终奖有关，最后虽然达成了OKR，但是全年都是我在推着他做。第二年做另一个项目的时候也没有太多的成长，还是只会听我说的做，自己也觉得没多少意思，后来离职了。他的离职，我认为自己是背负了一定的责任。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>那到底如何才能做到高质量的提问和对话，从而提升员工的能力和动机呢？绝不是靠即兴发挥和毫无章法的闲聊，而是有一套完整的方案，叫做GROW模型，具体分为四步，我也称之为四个明确：\u003c/p>\u003cp>第一步，明确目标。\u003c/p>\u003cp>发展目标、绩效目标、谈话目标。\u003c/p>\u003cp>和员工谈关于个人的未来发展目标和满足当下工作需求的绩效目标。先让员工有明确的方向感，起到自我激励作用，再谈支撑未来发展的绩效目标，比如“为了赢得晋升的机会，近半年最应该实现的是哪个部分呢？”接下来就是更加具体的目标了，主要围绕如何达成绩效目标，以及就这次谈话的目的和范围达成共识。\u003c/p>\u003cp>第二步，明确现状。\u003c/p>\u003cp>引导员工客观地描述当下事件的事实情况，梳理现状。先听再问，了解了对方所描述的具体内容再停顿片刻思考仔细想如何提问。同时需要请员工思考维持现状的后果是什么，“如果什么都不做，最坏的局面会发展成什么样？”从而唤起员工愿意改变的勇气。\u003c/p>\u003cp>第三步，明确选择。\u003c/p>\u003cp>帮助员工罗列出尽可能多的方案选项。重数量而不是质量，避免“负面假设”，比如“这不太可能”“我们不具备XX条件”等预设问题，用“如果我们现在有能力清除任何障碍，你会怎么做？”的句式。在提出了足够多的方案之后，记得补充一句“还有其他的么？”。如果我们想要发表一些个人观点，需要有一个请求许可的环节，“我有一些想法，不知道会不会帮助到你，你想听听看么？”目的在于维护员工的责任感，明确这是他自己的工作。\u003c/p>\u003cp>第四步，明确行动。\u003c/p>\u003cp>夯实员工的意愿，把对话的成果转换成行动计划（承诺）。首先把刚才的谈话内容转化成可执行的计划，从刚才方案中选择落地；其次是评估执行这个计划的意愿，“如果范围是1-10分，你会对执行计划的坚定程度打几分？”当员工回答低于8分时，我们可以直接说明“根据以往经验，那些打分低于8分的人很少能坚持下来。”从而我们可以就计划进行微调，比如减少任务量，延期等方式，或者保持原样，激发本人的斗志。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>再来回看我2019年的失败经历，其实当时情况下，我找他沟通也是为了提效，完成工作任务。按照四个确定可以做：\u003c/p>\u003cp>1、明确目标。年终奖想拿到双薪甚至更多，首先需要完成对应的OKR，“客户新增量”和“场次”就是我们本年度项目要达成的目标之一，今天我们就如何达成这个目标来达成一个一致的实施计划。\u003c/p>\u003cp>2、明确现状。先听她谈一下现在我们的状况如何，她是如何看待我们的现状。尝试问她，“如果我们按照现在的进度进展，结果会如何。”\u003c/p>\u003cp>3、明确选择。先听她会提出哪些建议，或许是和供应商合作的规范性、或者会跳脱出供应商之外的其他选项，当时在和供应商合作的时候，她总会说“他们不按照要求，我们定什么要求都没用”，其实当时可以尝试问“如果我们有能力要求供应商，我们可以怎么做”，尽可能多地帮助她想到更多的选择，而不是去打压她的创新或者其他想法。\u003c/p>\u003cp>4、明确行动。就刚才的各种选择，和她一起评估可实施性，由她把选择展开成具体实施的方案，最后和她确认如果按照我们今天沟通的结果开始做，后续她有多少信心完成，给自己打一个分数。\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>\u003c/p>\u003cp>运用GROW模型帮助我们更容易更规范地进行提问和倾听，目的是通过提升员工的能力和意愿从而最终提升员工绩效。当员工缺乏的是某种操作技能，那么就有可能不太适合通过提问来帮助其提升能力，更多的是要指导和演示以及练习来提升能力。\u003c/p>","interaction":"\u003cp>\u003cstrong>【显像提问】\u003c/strong>\u003c/p>\u003cp>现在，让我们回想一下，有没有那种我们在和员工/孩子/合作伙伴沟通怎么做，告诉了第一步第二步第三步，还要告诉第一步怎样可以怎样不可以，有任何一点小问题都要来问你，你成了脑子，他成了不会思考的手；又或者是明明说了要这样做，结果过了几天什么也没做，等最后你去问他的时候，又告诉你他觉得这里或者那里有困难，不想这么做。\u003c/p>\u003cp>请大家按照刚才的分组，分享一下自己曾经遇到过的类似的情况是什么样的。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>慢慢，反面案例\u003c/p>\u003cp>之前有一位学员，想要学习怎么写便签，为了过级写便签，他需要教练给出每一步明确的要求，在数次要求后，教练就逼不得已给出了明确的步骤，学员最后就按照教练的要求，用找好的便签，固定好的步骤和要求，虽然便签的结果还可以，但是一到自己做就做不好，个人没有什么成长。\u003c/p>\u003cp>\u003cstrong>【A1+反思加工】\u003c/strong>\u003c/p>\u003cp>大家已经分享自己曾经不太好的记忆，有的伙伴分享了……，有的伙伴分享了……，那现在让我们来想一下，如果运用GROW模型的四步法，你们当时的沟通要如何进行会比较好？大家在思考这个问题的时候，我可以简单的提示一下大家，其实GROW模型的运用是建立在大量的练习和经验之上的，今天我们第一次接触GROW，不一定要完整的运用这里提到的每一步，只需回想一下，如果将这个模型运用在当时的场景，你会怎么怎么进行这个对话，请大家尝试一下吧。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>慢慢，反思加工的案例\u003c/p>\u003cp>自己作为训练营的教练，没做好的是，一开始没有帮助学员明晰自己的长期目标，拆书过级只是当前的一个短期目标，学会RIA的技能，长期是自己通过学习方法成长。结果学员就一味的追寻短期结果。如果重新再做的话，可以更多精力帮助学员明确个人的发展目标，从而在后续的学习中，针对这个长期目标和短期目标服务。\u003c/p>\u003cp>结束语：\u003c/p>\u003cp>那今天的分享就到此结束，大家在今后的生活和工作中，减少使用“命令+告知”模式的频率，能够主动去运用GROW的模型中的方法和“员工”对话，帮助成就他人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1640442888000,"updated_at":1645606311000,"ria":true},{"id":12294,"topic":"教练的框架","learn_goal":"","remark":"无论是在一个正式的教练会谈还是在一个非正式的教练对话中，建议提问的顺序都遵循四个阶段GROW模型的认识","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"读书和跑步","city":""},"club":{"name":"武汉古琴台分舵","city":"武汉"},"prologue":"\u003cp>大家好，我是陈东风，一个喜欢跑步和读书的餐饮人。今天进行拆书帮1-2的升级打怪，拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵，其使命是帮助更多学习爱好者成长为拆书家。今天我跟大家分享的书是《高绩效教练》，作者是约翰.惠特默，他是教练领域的先行者，获得了国际教练联合会授予的总裁奖，本书是全球销量排名第一的教练书籍，被誉为教练领域的“圣经”。你有没有过这样的经历，当别人请教你问题的时候，你直接给出了答案，但是往往执行效果不佳。你一片真心给出各种方案他们却无动于衷，没有任何行动。这本书可以教你如何解决这类问题。接下来请大家用1分钟时间阅读一下片段。\u003c/p>","ratings_count":1,"texts":[{"id":16219,"quote":"\u003cp>教练的框架\u003c/p>\u003cp>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003c/p>\u003cp>● 目标设定（Goal），包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003c/p>\u003cp>● 现状分析（Reality），探索当前的状况。\u003c/p>\u003cp>● 方案选择（Options），可供选择的策略或行动方案。\u003c/p>\u003cp>● 该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will）。\u003c/p>\u003cp>这个顺序可以方便地形成助记符GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。请参见图9中每个阶段的关键问题列表。\u003c/p>\u003cp>这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。GROW模型如此有效的一个因素就是这个框架是灵活的。\u003c/p>","explains":"\u003cp>1分钟到了，大家都读完了吧，大家在平常的工作生活总都会碰到同事，家人，朋友咨询你问题的情况，我们可能都会直接给出我们认为的答案，但是，结果往往不如意，没有让提问的人产生行动。这个教练的框架就是通过反问问题的方式，引导提问者自己寻找答案，并制定行动方案。当提问者向你提问一个问题的时候，你可以问他，你的目标是什么？你想解决什么问题？ 再问他现在的情况是什么样子的，引导让他自己说出现状。然后问他你现在有哪几种选择？你可以做什么？让他自己选择一个方案出来。最后问他有多大的意愿按他自己说的方案去做。\u003c/p>\u003cp>自我案例： \u003c/p>\u003cp>以前有个同事问我，我现在做得很不开心，工资低又没发展前途，我要不要辞职？我首先跟他确认目标：你问我这个问题是想我让我帮你解决问题还是只是吐槽一下。他说：我想让你帮我分析下我现在怎么解决比较好。于是我问他现状：那你目前的情况是怎么的呢？他说：现在这个工作做的不开心，工资低又没有发展前景，但是如果辞职我不知道我能做什么。我问他：那你现在有什么选择。他说：要么直接辞职，再找工作，但是又不知道要做啥，要么继续在这个公司上班，但是有没有发展前途，所以很困惑。我继续问他：还有别的选择吗？他想了一下，回答说：也可以先继续做着，然后边做边找，找好了再辞职。最后，我问他，你更愿意选择哪个方案。他说第三种。 就这样通过引导的方式，让提问者自己寻找答案。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>\u003c/p>\u003cp>现在我们阅读了这个拆页，大家回想一下，我们以前是否有遇到别人向你请教问题怎么解决的情况，你是如何回答他的。请大家每两个人来分成一组进行分享，并且由一位分享者代表整组的一个经验进行分享。\u003c/p>\u003cp>学员分享：小伙伴做人力资源的同事因为事务性工作较多，压力较大，所以想辞职，向小伙伴请教，小伙伴在向未学习GROW模型的情境下，也基本用到了ROW大部分知识。\u003c/p>\u003cp>\u003cstrong>A2:\u003c/strong>\u003c/p>\u003cp>那么在今天学习了教练的框架后，你如何运用到自身上去，想一下最近你朋友或家人问你的一个问题，你该如何回答呢？这里将给大家一分钟的时间将你的A2便签写下来，不要只是表决心，需要有明确的目标和具体的行动计划，最好符合SMART原则。同样我们将邀请一位伙伴和大家分享A2便签的内容。\u003c/p>\u003cp>学员分享：小伙伴分享了有同事问他职业发展没奔头的情况下怎么做。小伙伴将运用GROW进行引导，问他的目标是什么？并通过提问让他对自己的现状进行分析，然后引导他找出自己可能有的方案，并最终问题更有意愿选择哪个方案。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1630971292000,"updated_at":1632364085000,"ria":true},{"id":11533,"topic":"有效提问代替给建议","learn_goal":"","remark":"当给他人建议时，有时会被对方当做是一种谴责，他还可能想尽一切理由来告诉我们建议是行不通的，但是如果像教练一样相信对方自己已经有了答案或者具备潜力自己找到答案，那激发他觉察力和责任感的一连串有效问题比给建议来的更加可靠有有用。","level":"TF3-3","duration":76,"status":30,"type":0,"chaishujia":{"username":"柳颂婷","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，感谢大家来参与我的拆书过级，我叫柳颂婷，是一名正在过级的拆书家，今天是冲刺最后一关，3-3级。我今天拆解的内容来自这本《高绩效教练》，主题是：有效提问代替给建议。\u003c/p>\u003cp>学习的过程中有组内分享讨论的环节，所以我们先分一下组，邻近的两个人为一组。\u003c/p>\u003cp>好，下面正式进入内容的环节了。\u003c/p>\u003cp>我先用场景法来介绍一下我今天的拆解内容，让大家可以感受到它的用处，快速进入状态。\u003c/p>\u003cp>【场景法介绍】\u003c/p>\u003cp>\u003cstrong>【事件】\u003c/strong>我妹妹前几天电话问我：我是应该继续留在北京呢还是回长沙工作好？听完她的问题我就乐了，心想终于有机会策她回长沙了。于是我就从她在北京的状态分析到她回长沙的机会，告诉她回长沙更好。还本着负责的态度给她列出了她现在可以做哪些事情来应对，别裸辞给自己压力。还没等我说完，她就突然生气了：你说的这些我都知道，我都纠结了半年了，我说不回长沙吧，你和爸妈又念叨，我一说回来你又不让我裸辞，你们到底想要我怎样。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>大家在生活或者工作中有没有这样的经历？明明我们是替对方着想，满足他的需要绞尽脑汁地给建议，但是对方居然还生气了？难道给建议还是一种错？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>其实，当别人跑过来咨询我们的时候，大部分人的第一反应就是给帮助给建议，但是当我们不断地给别人建议你应该怎么做，你为什么不试试这样做的时候，这在对方听来可能是一种谴责，他会觉得我们好像站着说话不腰疼，面对我们给的建议，他可能会想尽一切理由来告诉我们这样不行滴。这样的给建议反而变成了给压力，沟通不仅没达到想要的结果，还被打上了好为人师的便签，人际关系堪忧。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>今天我拆解的这本《高绩效教练》，它提出来的像教练一样通过一连串的有效问题来代替给建议的方法，可以激发对方的觉察力，让他看见自己的目标、现状、以及可能的选择，最后做出完全由他自己愿意承担责任的行动计划。这本书虽然听起来是一本用于职场的管理书籍，但是当面对要给孩子、给学生做辅导、给朋友们做建议等场景时，我们也可以像教练一样通过不断的有效提问来帮助他建立责任与自信。\u003c/p>\u003cp>【学习目标】【可观察到的动作】\u003c/p>\u003cp>今天我的拆页一共有两个片段，在片段一的学习后，大家就能辨别（行为）什么叫做教练式的有效问题。完成片段二的学习后，就能理解并描述（行为）出解决一个完整问题的提问四步骤，之后用它来处理他人请求给建议、辅导同事、辅导孩子等等这样类似的问题（界定）。\u003c/p>\u003cp>下面进入第一个片段的学习，首先请大家1分钟的时间阅读手中的原文片段1——问题的功能。\u003c/p>","ratings_count":1,"texts":[{"id":15456,"quote":"\u003ch1>R1【原文片段】\u003c/h1>\u003cp>选自《高绩效教练》P39\u003c/p>\u003cp>\u003cstrong>问题的功能\u003c/strong>\u003c/p>\u003cp>\u003cstrong>问题的提出是为了获取信息。\u003c/strong>我可能需要信息来解决我自己的一个问题，或者利用它来给其他人提供建议或是解决方案。但如果我是一个教练，问题的答案就变得次要了。信息不是要为我所用，也没有必要是完整的。\u003cstrong>我只需要知道客户自己掌握了必要的信息。客户给出的答案经常可以提示教练下面要问什么问题\u003c/strong>，而与此同时能够让教练监控客户是否走在一条高效工作的路径上，或者是否符合目的或公司的目标。\u003c/p>","explains":"\u003ch1>I1【重述知识】\u003c/h1>\u003cp>好，我看大家都读完了。下面进入知识讲解，请大家打起精神哦。 \u003c/p>\u003cp>【具体内容】【核心概念的定义】【互动】\u003c/p>\u003cp>原文片段告诉我们问题的作用是什么呀？\u003c/p>\u003cp>（互动）获取信息。\u003c/p>\u003cp>对的，提问题的目的是为了获取信息。再问一下大家，是为了谁能获取信息呀？\u003c/p>\u003cp>（互动）为了他自己。\u003c/p>\u003cp>没错，给大家点赞！是为了对方给自己获取信息。这个片段是选择书中“有效的问题”这一章节，从问题的功能描述来看，咱们可以将这种\u003cstrong>能帮助他人思考去获取更多信息的问题称之为有效问题\u003c/strong>。那大家觉得是所有的问题都能达到这样的效果吗？\u003c/p>\u003cp>（互动）不是的。\u003c/p>\u003cp>对哈，并不是所有的问题都能达到这个效果，无法帮助对方获取更多信息的属于无效问题。下面我们通过两个案例来看看有效问题和无效问题的具体区别： \u003c/p>\u003cp>【正反例辨析】\u003c/p>\u003cp>（案例1）小明考试只得了60分，妈妈生气地问：“你上课认真听讲了吗？” “你考60分对得起我吗？”大家说，这是有效问题还是无效问题呢？（互动）无效问题。没错，无效问题，为什么呢？因为这个问题，小明基本只能回答：我听了，对不起这样的答案是吧，看似是提问，实际上答案锁定在了“是”和“否”，“对”或“错”上面，它关闭了探索更多信息的大门，属于封闭性问题，基本不可能让小明能获取到考不好的原因以及责任感。所以，有效问题不能是封闭式问题，而是对应的开放式问题！\u003c/p>\u003cp>（案例2）老板问小红：“你的报告为什么不按照模板做？”请问，这是一个有效的问题吗？（互动）不一定哈，是吧，看老板语气。这个问题的答案是开放的，没错，不过它很容易让人感觉到是在批评，从而引起防御心理，一旦有了这样的情绪，对方基本很难再专心致志、保持兴趣地去探索更多的信息了，而且这种问题存在明显的引导性——应该按模板做，不要创新。这也会关闭获取多方面信息的通道，这也属于无效问题。所以，有效的问题还应该在措辞、语气上让对方感受到安全与信任。像“为什么”这一类暗含批评和有着明显引导性的问题，最好不要使用，一定要用的话，可以表达成：“是什么原因你没有按照模板做？”，这更能引起具体和真实的回答。\u003c/p>\u003cp>从以上两个例子我们能看出提出有效问题的两个关键步骤了：\u003c/p>\u003cp>第一． \u003cstrong>用开放式的问题。\u003c/strong>也就是用能促使对方思考，能收集到量化信息或事实的疑问词来提问，比如“什么”“何时”“多少”“谁”。这一类的问题呢，它的答案就是不固定的，它会促使对方集中精神，运转大脑，否则可能根本无法回答出问题。比如：是哪些因素影响这个结果？\u003c/p>\u003cp>第二．\u003cstrong>不带情绪地表达。\u003c/strong>这里的不带情绪是指在措辞、语气上不要有明显的引导性、批评性。因为只有当对方感受到安全和信任的时候，他才不会被情绪主导，动用大脑思考。为了控制好情绪，大家要注意慎用“为什么”这个词，像是：“你到底为什么要这样做”这样的问题可以改为：“是什么原因你选择这样做？”\u003c/p>\u003cp>以上就是我总结的提出有效问题的两个步骤。下面我把小明考试60分的案例加工一下，让大家加深一下理解：\u003c/p>\u003cp>1、看到小明只考了60分，妈妈很生气，她想要通过有效的问题来让小明意识到是因为他上课没有听讲所以只考了这么多分，于是把“你上课听讲了吗？”这样的封闭问题改为：“这试卷上的内容有哪些是老师上课没有讲过的？”小明可能会回答：123题老师讲过但我还是不会，第4题我没有听到老师讲。\u003c/p>\u003cp>2、听过这个，妈妈想告诉小明听不懂的要再问老师才行，于是把口头上的“为什么不问老师”这样带批评性的问题改为：“不会的知识，是什么原因你没有向老师再请教呢？”小明可能回答：我不敢、我没有想过等等。妈妈可以再问：“那还有其他办法能把知识弄懂吗？”“如果改变什么情况，你就敢去请教老师呢？”\u003c/p>\u003cp>大家感受到了吗，原来无效的问题通过加工成有效问题后，已经可以激发小明看到自己的不足，还能开动大脑去思考解决办法，妈妈什么建议和说教都没有说就基本达到了让小明意识到不足以及怎么改进的目的。这就是有效问题的魅力。\u003c/p>\u003cp>【预防异议+讲解】\u003c/p>\u003cp>听到这里，可能有学习者会说，我顺着情绪告诉对方我希望的做法，对方基本也能听话，我为什么要这么麻烦地去调整为有效问题呢？因为有效问题的提出可以激发人们的潜力与责任感！想想看，没有获得世界冠军的教练为什么可以培养出世界冠军来，因为教练把人看做是一颗本身就能成长为参天大树的种子，而不是任人浇灌的空容器，他们的重点是帮助人们学习而不是给他授课。而提有效问题的这个方式，就能达到激发对方去思考探索，从而提升学习力的方式。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>有效提问特别适用于需要对方深入思考，需要对方承担责任这样的沟通场景。生活中一些很简单的随便问问就没有必要这么刻意和麻烦，比如：你吃饭了吗？要不要去吃饭？\u003c/p>","interaction":"\u003ch1>A2【我的应用】 \u003c/h1>\u003cp>为了加深大家对“有效提问两步骤”的理解，下面我们进入应用阶段，首先请大家想象一下，在接下来的一周里，自己可能遇到的能用上有效提问去帮助他人获取更多信息的场景，比如指导同事的工作改进、帮助朋友做他纠结的选择、培养孩子对事物的观察力等等。请先在纸上写下这个场景及发生的时间。注意还不需要去设计问题解决它，只是写下场景和时间就好。时间1分钟，待会我会请伙伴来分享一下。\u003c/p>\u003cp>【伙伴分享场景】\u003c/p>\u003cp>分享场景1：告诉新来的老师应该多关注一下家长的反馈和建议；\u003c/p>\u003cp>回应：感谢小丽的分享，小丽觉得告诉新老师要注意加深和家长的沟通场景可以用到有效提问。还有其他伙伴想分享一下的吗？\u003c/p>\u003cp>分享场景2：我孩子很粘我，但是向我今天要来参加学习两小时，他就会闹一下，我想和小孩沟通，想让他思考当妈妈不在的时候怎么愉快的度过。\u003c/p>\u003cp>回应：感谢海萝的分享，海萝想运用有效提问腊和孩子沟通，希望他自己提出如何度过妈妈不在的两个小时。\u003c/p>\u003cp>【布置特定的任务】\u003c/p>\u003cp>好的，下面进入解决问题环节。请小组内先确定解决你们刚写下的哪个场景，然后角色扮演，一人扮演提问者，一人扮演回答者，进行一个小剧本的编辑。注意提问者需要运用我们刚才的“有效提问两步骤”的知识点。时间为5分钟。\u003c/p>\u003cp>【伙伴分享解决方案】\u003c/p>\u003cp>分享剧本：\u003c/p>\u003cp>场景：小易马上要去面试了，她很担心通不过，也担心通过了要不要去，希望朋友小王能给一些建议。\u003c/p>\u003cp>小易：我后天准备去应聘一个高校的职位，我很担心不会通过。\u003c/p>\u003cp>小王：嗯，那你现在害怕什么？\u003c/p>\u003cp>小易：我害怕我的准备不够。\u003c/p>\u003cp>小王：那你现在准备了一些什么？\u003c/p>\u003cp>小易：我不清楚是要看对方的指定内容还是自己准备一个。\u003c/p>\u003cp>小王：有个师姐说像这种面试，一般是自己准备一个擅长的内容准备就好了。\u003c/p>\u003cp>小易：这样的话，那我可以挑一个我擅长的准备，比如我擅长对空巢老人的护理。\u003c/p>\u003cp>小王：嗯嗯，这就非常好呀。\u003c/p>\u003cp>【给出反馈】\u003c/p>\u003cp>感谢易老师和王老师的分享，在你们的对话中，小王刚开始用了两个问题来帮助小易去看到自己到底害怕什么以及做哪些准备比较好，而不是直接告诉她有什么好怕了的，你准备准备就好了。帮助对方想到更多的信息从而思考到可以选择的行动，这就是有效问题的魅力。\u003c/p>\u003cp>【点出两个片段的关系】\u003c/p>\u003cp>以上就是我们第一个片段的学习，通过学习，大家知道并理解了什么叫做有效问题，也能通过简单两步提出有效问题。下面呢，进入我们的第二个片段学习，它是一个解决完整问题的提问四步骤，也是《高绩效教练》这本书的核心内容，与刚刚第一个知识点是递进关系。\u003c/p>\u003ch1>\u003c/h1>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":15457,"quote":"\u003ch1>A1：【反思过去】\u003c/h1>\u003cp>在开始之前，我给大家设计了一个自测题，来看看大家在面对他人询问建议时通常的做法是怎样的，5个题目请按照1-6分的标准给自己打分，1代表完全不符合，6代表完全符合，然后把总分统计一下。\u003c/p>\u003cp>【自测表】\u003c/p>\u003cp>【自测表解释】\u003c/p>\u003cp>好，我看大家都已经测完了。\u003c/p>\u003cp>来，请问有没有得分10分以下的伙伴？这个得分意味着面对他人需要给建议的场景时，你是可以控得住自己情绪，把沟通主场交给对方，那今天的学习内容就是给你添加一对翅膀，通过四个阶段的提问你能帮助对方更好地找到目标与行动方向。待会的知识相信你应该能没有太多障碍的应用出去。期待你们的成功。\u003c/p>\u003cp>10-20分的伙伴请举一下手。这个得分的伙伴说明上述的5种情况大部分都是有些符合你们的状态的，这说明你们想要帮助他人做决策，偶尔也能控制自己的表达欲给对方空间。好好学习，有今天知识的加持，你们一定能两个目的都达到！\u003c/p>\u003cp>20分以上的伙伴在哪里~？你们是今天的幸运儿。这个得分说明你们有着一颗强烈的想要帮助对方的心，往往在他人需求帮助的时候，倾尽自己所能给建议，生怕对方做出错误的选择。好好学习今天的内容，以后用提问题来代替给建议，它更让你们更好地达到帮助他人的目的。\u003c/p>\u003cp>好，下面请大家花1分钟的时间阅读手中的原文片段——GROW模型。\u003c/p>\u003ch1>R2【原文片段】\u003c/h1>\u003cp>选自《高绩效教练》P47-48\u003c/p>\u003cp>\u003cstrong>GROW模型\u003c/strong>\u003c/p>\u003cp>我建议提问的顺序遵循以下四个步骤：\u003c/p>\u003cp>l 目标设定（goal），本次教练对话的目标，已经教练的短期目标和长期目标。\u003c/p>\u003cp>l 现状分析（reality），探索当前的情况。\u003c/p>\u003cp>l 方案选择（options），可供选择的策略或行动方案。\u003c/p>\u003cp>l 该做什么（what），何时（when），谁做（who），意愿（will）。\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推理或者处理。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>\u003cp>在现状分析之前就开始设定目标可能看起来有些奇怪。表面的逻辑正好相反，因为我们当然需要在我们设定目标之前了解现状，实际上并非如此，仅仅基于现状的目标容易倾向于负面，变成问题的应对，被过去的表现所局限，因简单的推断而缺少创新，只能实现小小的增长而不是本该有的成就，甚至影响生产力。短期的固定目标甚至会让我们远离长期的目标。我在团队培训课程中目标设定的经验是团队不可避免地基于过去的所作所为来设定目标，而不是未来可以做什么。在许多情况下他们不能规划什么是可能的。\u003c/p>\u003cp>确定理想的长期解决方案后决定实现该理想的现实步骤，这种方式形成的目标通常更令人鼓舞、更有创意和更激励人。让我用一个例子来说明这个要点。如果我们试图通过分析现状，解决一个在一条战略要道上的交通堵塞问题，我们很可能会仅仅基于缓解现有交通流量来设定目标，如拓宽道路。这实际上可能会与更有远见的长期目标相矛盾，后者通过明确该地区在未来某时间的理想交通模式来设定，然后看实现该目标所需的阶段步骤。因此我的建议是，在大多数情况下，使用上述建议的四个步骤。\u003c/p>\u003ch1>\u003c/h1>","explains":"\u003ch1>I2【知识讲解】\u003c/h1>\u003cp>好，基本都读完了，现在我对原文知识进行一下讲解。\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>请问一下大家，GROW模型是什么呀？\u003c/p>\u003cp>（互动）提问的四个顺序。\u003c/p>\u003cp>是的，GROW模型的四个字母分别代表了提问的四个顺序，哪四个顺序呢？\u003c/p>\u003cp>（互动）目标-现状-选择-行动。\u003c/p>\u003cp>对的，目标-现状-选择-行动。下面我们来一起学习下这四个步骤到底怎么应用。\u003c/p>\u003cp>【具体内容】【how】\u003c/p>\u003cp>\u003cstrong>1、 问目标。\u003c/strong>为什么需要把问目标放在第一步呢？因为如果对方能一开始就认识到这次沟通有着重要的目标目的后，他将会格外重视自己态度，全身心参与，从而让整个沟通高效。问目标的时候做好能问出对方的长期目标、短期目标，甚至这次沟通的目标。长期目标，比如保持健康、获得冠军、工作稳定等这种鼓舞人激动人的美好状态。短期目标则是对方努努力，自己就能控制并且能衡量的一个目标，比如一个月减肥3公斤、今年存下10万元等等。可以直接问：你的长期目标是什么？你短期内希望实现什么？这次谈话你希望获得什么？ \u003c/p>\u003cp>\u003cstrong>2、 问现状。\u003c/strong>在已经定义了各种目标之后，我们需要让对方尽量全面地了解当前的现状，有外部的现状，也有他自身的。关于现状最重要的一个标准是客观，问到对方描述事实说出感受就好，所以，我们可以这样问：你目前的状况是什么？和这件事相关的人有哪些？他们分别是什么态度？你做了哪些事情去实现目标？\u003c/p>\u003cp>\u003cstrong>3、 问选择。\u003c/strong>这个阶段还不是为了找到正确的答案，而是要列出尽可能多的可供选择的方案。比如：你现在有哪些选择？你见过或听过别人有哪些做法？注意，在这阶段，方案的数量比质量和可行度重要的得多，所以不妨多问几个“还有吗？”。\u003c/p>\u003cp>\u003cstrong>4、 问行动。\u003c/strong>最后一步就是抉择时刻了。需要通过问题来让对方确定下一步的行动方案。包括：打算什么时候去做？会遇到什么困难？需要什么资源支持？等等。\u003c/p>\u003cp>以上就是GROW模型的四步骤了，下面我用一个实例应用来让大家感受一下它的魅力。还是我妹妹的那个例子，来，我请我旁边的鸭鸭来角色扮演一下我妹妹，请你帮我读一下A的文字。\u003c/p>\u003cp>A：“你说我是继续留在北京工作呢，还是回长沙工作好？”\u003c/p>\u003cp>一、好，下面进入阶段1，问目标：\u003c/p>\u003cp>B：“你喜欢什么样的工作状态呢？”（问长期目标）\u003c/p>\u003cp>A：“我希望工作单位比较靠谱，比较稳定，也还好玩。” \u003c/p>\u003cp>B：“哦，所以你今天找我，是希望确定到底北京还是长沙可以更有利于你的目标实现吗？”（问本次沟通的目标）\u003c/p>\u003cp>A：“是的，其实我觉得还是长沙，但是我不能坚定辞职回长沙的决定。”\u003c/p>\u003cp>B：“那你觉得你需要在长沙确定一些什么，你会有更加坚定的感觉？”（问短期目标）\u003c/p>\u003cp>A：“我如果能确定做什么能让我在3年左右的时间考上教师编制的话，我会很坚定。”\u003c/p>\u003cp>（旁白）好，到这里已经对方已经确定了长期目标、本次谈话的目标、以及短期3年的目标。下面就是进行短期目标（3年考上教师编制）的探讨。\u003c/p>\u003cp>二、阶段2，问现状：\u003c/p>\u003cp>B：“为了能考上教师编制，你现在做了哪些准备？”（问个人现状）\u003c/p>\u003cp>A：“我在考教师资格证，这个是必须的，但是好像竞争力还不大，很普遍。”\u003c/p>\u003cp>B :“那你知道现在招聘中有什么样的条件能增加你的竞争力呢？”（问环境现状）\u003c/p>\u003cp>A :“这个我也还不是很清楚，但是我想实战经验多一些，学历上再升级一下肯定更好……我好像光在焦虑矛盾了，确实没有太去了解这些。”\u003c/p>\u003cp>（旁白）好，现状问到这里也可以了，她已经意识到自己焦虑的原因了。\u003c/p>\u003cp>三、阶段3，问选择了：\u003c/p>\u003cp>B:“那现在你觉得你可以做些什么？”\u003c/p>\u003cp>A :“我可以去教师招聘网上收集一些具体的条件和我自己对比一下，不满足的那些我去了解怎么能快速满足。”\u003c/p>\u003cp>B:“还有吗？”（探索更多的可能）\u003c/p>\u003cp>A :“我还可以先换个工作到要求不那么多的培训机构去攒一些教学经验。”\u003c/p>\u003cp>（旁白）这里还可以多问几个“还有吗？”，直到对方穷尽了选择。\u003c/p>\u003cp>四、阶段4，问行动：\u003c/p>\u003cp>B：“那你下一步的行动是什么？”\u003c/p>\u003cp>A：“去收集招聘要求。”\u003c/p>\u003cp>B：“这个过程可能会遇到的障碍是什么？”\u003c/p>\u003cp>A：“网上的信息与实际可能存在偏差。”\u003c/p>\u003cp>B：“那你需要什么支持呢？”\u003c/p>\u003cp>A：“最好能问一下身边当老师的朋友对比一下，这样更靠谱。”\u003c/p>\u003cp>B：“嗯，你打算什么时候做这件事情？”\u003c/p>\u003cp>A：“下周就做。”\u003c/p>\u003cp>好，谢谢鸭鸭，通过这样的一个实例讲解，大家对GROW模型的提问四步骤理解更深了吗？大家发现没有，整个过程我都没有提出任何建议，只是在不断提问而已。与“提建议”是分享自己的经验形成鲜明对比的是，“提问题”是把主场交给对方，通过问题来让他清晰自己的目标，来分析现状反思自己，然后去找可能的方案，最后再确定下一步行动。整个过程最大程度地激发了对方对信息的获取，以及提高他的责任感，进而确保了之后行动的执行力增强。\u003c/p>\u003cp>【预防异议+讲解】\u003c/p>\u003cp>可能有学习者会问，万一对方怎么都回答不到点子上，根本推不动怎么办呢？其实这个问题有很多原因可能导致，比如我们的提问水平还比较初级，那需要我们自己多加练习。另外还可以根据对方的水平能力来降低一些谈话的目标，分阶段的沟通，毕竟成长要慢慢来。还可能是我们给自己提的问题设置了一个答案，对方没有给出差不多的回复就很失望，这就要特别注意不要把这个提问方式变相成为引导对方一步步走入自己设置的坑的模式了，我们应该把关注力从对方回答是不是在点子上转移到对方是否动用了大脑在思考，是否觉察到了更多的信息，激起了自己的责任心上，如果是这样，那这个教练的提问过程就是有意义的。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>GROW模型特别适用于工作指导、亲子辅导、朋友询问建议等等场景，如果是在知识的交流等场合，他人询问我们建议时，那就要还是根据自己经验分享实实在在的建议了。 \u003c/p>\u003ch1>\u003c/h1>","interaction":"\u003ch1>A3【场景演练】 \u003c/h1>\u003cp>接下来，我们进入一个实战环节，叫做“微行动学习“，这是一个大家一起发挥智慧、应用今天所学知识来解决实际问题的环节。咱们今天学了教练式提问的四步骤GROW模型，大家可以想想，在操作步骤中，哪个部分对你来说最难、或是你生活中正好有什么类似的困扰，都可以提出来，我们一起在这里解决。\u003c/p>\u003cp>【伙伴提问】【提问式反馈与回应】 \u003c/p>\u003cp>（提前设想大家可能的问题）\u003c/p>\u003cp>操作上：实在忍不住提建议、被对方反问得哑口无言、对方回答不对、记不住提问流程、用词不当；（准备一个问题库来解决）\u003c/p>\u003cp>流程上：问目标最难（长期目标鼓舞人心，短期目标smart）、问现状难（客观、感官、情感；非评价判断）、问选择难（还有吗？换位思考）、问行动（追问执行度打分）\u003c/p>\u003cp>案例上：XX案例，探讨本质是什么？对抗？经验不足激活不来？等等、用问题库来尝试；\u003c/p>\u003cp>海萝：我主要遇到的问题就是和对方聊着聊着就被对方带偏了，忘记了本来要干嘛。\u003c/p>\u003cp>小丽：嗯，我也是，有时候是对方被我带偏了，最后他的问题还是没有解决。\u003c/p>\u003cp>拆书家回应：也就是说不能坚守一开始的目标，对吧。这个确实经常出现呢。\u003c/p>\u003cp>小丽：估计是沟通的目标也不那么重要，本来就是闲聊，哈哈。\u003c/p>\u003cp>文静：我有时候看到别人做的不好想给建议，但是对方不觉得自己做的不好，怎么办？\u003c/p>\u003cp>拆书家回应：哈哈，这是一个特别想帮助他人成长的伙伴哈，大家觉得这个障碍和今天的哪个知识点能关联呢？\u003c/p>\u003cp>其他人回应：这个好像没有关系，降低点对别人的要求。\u003c/p>\u003cp>拆书家：是否可以通过问他的目标来试试看，如果他有超出他现状的目标追求，可能就能进行了。\u003c/p>\u003cp>文静：有道理。\u003c/p>\u003cp>小龙：我主要就是觉得聊得很嗨很有效果，但就是不行动。\u003c/p>\u003cp>拆书家回应：嗯嗯，小龙是担心事后不行动，那这个和我们我今天的哪个知识点可以关联起来呢？\u003c/p>\u003cp>其他人回应：应该是行动吧，可能是行动问的还不够清晰。\u003c/p>\u003cp>小王：我的问题不是和别人聊，我是自己存在摇摆，这个工具可以解决吗？\u003c/p>\u003cp>拆书家&amp;其他人补充：这个提问模型也可以用来自己问自己的。\u003c/p>\u003cp>小王：哦哦，那我的问题就是，我现在想不出来自己的目标是什么，就是自己到底想要什么。\u003c/p>\u003cp>拆书家回应：小王表示她在问目标环节存在使用障碍，问题无法帮助自己想清晰自己的目标。\u003c/p>\u003cp>丝丝：我的问题是有没有什么工具可以来衡量一下这个沟通确实产生了效果。\u003c/p>\u003cp>其他伙伴回应：前面的自测表可以，如果对方找到了方向就是有效果了。\u003c/p>\u003cp>【伙伴确认】 \u003c/p>\u003cp>好的，现在现场的学习者们提出了5个问题，分别是：\u003c/p>\u003cp>1、沟通是聚焦不了话题，跑偏了。\u003c/p>\u003cp>2、想给意识不到自己能更好的他人建议。\u003c/p>\u003cp>3、沟通后不行动。\u003c/p>\u003cp>4、不清晰目标的时候，怎么办？\u003c/p>\u003cp>5、有没有工具能测量沟通效果？\u003c/p>\u003cp>时间问题，大家先挑选一个来运用微行动的方式尝试解决下，我们投票决定吧。\u003c/p>\u003cp>结果：问题1、2、5：分别1票，问题3：4票，问题4：6票。\u003c/p>\u003cp>好的，根据大家的选择，接下来我们确定来解决没有清晰目标的时候该怎么办这个问题。具体的问题才能确定具体的解决方案，下面先请我们的案主小王再详细描述下这个问题的具体情况，时间、地点、人物、过程等等。\u003c/p>\u003cp>伙伴小王分享：\u003c/p>\u003cp>我是学护理学的，就是我现在确定工作有3个选择：医药类公司、高校、医院，我现在在考虑到底去哪个，我不清晰。我朋友里因为工资高去了医药类公司、有朋友因为编制去了高校，还有去了医院做科研的。我不清晰编制有什么用，我不太喜欢去医院科研，去高校我好像是能接受的，但是我还是不坚定不清晰。\u003c/p>\u003cp>【引导分组讨论问题本质】 \u003c/p>\u003cp>好，谢谢小王，她的具体问题是：有三个选择摆在她面前，朋友们有各有选择，她现在虽然是偏重有编制的高校，但是她还是不清楚自己想要什么。这种情况很普遍哈，自己没有坚定的选择，可能听到别人说这个好就心动，那个好也心动。现在我们先来一起讨论面对选择摇摆不定这个问题背后的本质原因是什么？按照刚刚的分组，小组内一起讨论出问题的本质？注意多结合自己的经验。一会儿每个小组派一位代表来分享。\u003c/p>\u003cp>【明确问题本质】 \u003c/p>\u003cp>现在请各个组分享自己组讨论的结果，我们一起来听听。找出一个大家都认同的。大家的结果主要是这几个：\u003c/p>\u003cp>小组A：本质是她不清晰自己的价值观\u003c/p>\u003cp>小组B：不清楚自己要什么\u003c/p>\u003cp>小组C：对几个选择缺乏认知和经验\u003c/p>\u003cp>小组D：她想要的太多\u003c/p>\u003cp>案主，你更加认可哪一个？\u003c/p>\u003cp>案主小王：我觉得是我不清楚自己要什么，不清晰未来的目标，描述不出来这个场景。\u003c/p>\u003cp>【引导分组讨论解决方案】\u003c/p>\u003cp>好的，谢谢大家的讨论和分享，刚才案主小王已经确定了她在选择面前摇摆不定的本质原因是她不清楚自己未来的目标，也就是咱们A小组和B小组探讨出来的本质。现在我们再来发挥一下全员的智慧帮助她来探寻解决方案，请大家根据自己的经验及咱们刚学习的知识来讨论，我再明确一下咱们讨论对象是：如何通过有效问题的方式来帮助对方确定自己的未来目标与场景。待会我请伙伴来分享。\u003c/p>\u003cp>（备注过程：小组内讨论的时候开始陷入到为小王去分析几个选择的利弊，给出了像每个都去试试的行动建议，有的小组陷入“这个只能她自己去找，别人帮不了的”无奈状态。经舵主提醒：用今天的知识“提问代替给建议”去解决。）\u003c/p>\u003cp>感谢舵主，我看到我们陷入到不断在提建议的状态了，我提醒一下咱们需要想想今天学习到的内容：用提问题来代替给建议。现在将讨论的话题明确为：通过哪些有效的问题可以帮助对方来清晰她未来的目标，或者说想要的场景？\u003c/p>\u003cp>【小组讨论，给出解决方案】\u003c/p>\u003cp>小组A：你想要什么样的生活？然后通过她的回来来问她这几个工作选择哪些可以满足她想要的生活。你未来的美好场景你觉得是哪些组成的？\u003c/p>\u003cp>小组B：也可以想想过去的生活，哪些是你喜欢的，哪些是不喜欢的？\u003c/p>\u003cp>小组C：你看到或听到的，哪个人的状态你比较喜欢？你希望你未来工作的时间模式是怎样的？你想要2年后的收入水平如何？你希望和你周边的同事是什么样的状态？\u003c/p>\u003cp>小组D：我们都是无效的讨论了。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>哇，不错，大家讨论的特别热烈，非常热心地提出了很多有效的问题来帮助小王去解决问题。有通过提问她未来美好场景的组成的，有提问反思过去看看自己喜爱什么的，还有小组通过4个问题来将未来场景具体化，某个自己喜欢的人、工作时间模式、收入水平、同事相处。真的很棒~！也给了我很多的思路和启发，谢谢。小王，这几条都是大家根据自己的经验和认知给出的好建议，你可以根据自己的实际情况选择运用，其他的学习者也可以从中选择能用得上的方法，期待你们能运用出去解决问题。另外，彩蛋来了，我给大家准备了一份四阶段的问题清单（见附页），刚开始应用的时候，大家可以直接拿着这份题库去提问，等经验足够了之后，再自行优化。\u003c/p>\u003ch1>A2【应用作业】\u003c/h1>\u003cp>把知识拆成自己的能力是我们拆书法的目标，那只有不断地运用知识，知识才能变成我们的能力，通过今天的学习，相信大家已经掌握了怎么提有效的问题，以及提问题的四个步骤，用提提问来代替给建议。不过呢，从自己的经验出发给建议希望对方快速解决问题的行为模式已经很顺手了，要调整到完全的提问题模式还需要很多的练习，所以呢，这里还有一个叫做事后复盘的应用型的家庭作业留给到大家：\u003c/p>\u003cp>请大家回去一周内，刻意留意自己给别人建议的场景，把你们的对话记录下来，然后试着用今天的GROW模型提问四步法去修改你当时的建议。如果实在一周内没有发生这样的场景，也可以回想一下曾经你给别人建议的对话，或者记录别人给你建议的对话，把它作为复盘资料。这个作业还请大家分享给我一下哦。\u003c/p>\u003cp>苹谷分享课后作业：\u003c/p>\u003cp>老婆最近换工作拿到了一个比较心仪的offer，她问我的意见时，我直接告诉她距离太远她受不了的，不要考虑去了。虽然老婆也认可，但看得出来她还是有些失落，对接下来的找工作没有太大的热情了。如果我采用GROW模型的四步骤来和她对话，她心里应该会舒畅很多，例如：\u003c/p>\u003cp>1、 询目标：\u003c/p>\u003cp>我：长期来看，你对自己的工作和生活有什么期待呢？\u003c/p>\u003cp>老婆：我希望有自己的喜欢的事业，并有余力能教育好孩子。\u003c/p>\u003cp>我：那具体什么样的工作能满足你呢？\u003c/p>\u003cp>老婆：企业稳定，薪资保持在中上水平；加班不多，有自己的时间。\u003c/p>\u003cp>2、 问现状：\u003c/p>\u003cp>我：那你现在这个offer符合吗？\u003c/p>\u003cp>老婆：这个企业实力不错，我觉得挺稳定的，薪资也达到预期。不过通勤时间太久了，我每天上下班需要2个多小时，要做到有自己的时间来教育小孩有点难度。\u003c/p>\u003cp>3、 问选择：\u003c/p>\u003cp>我：那你现在还有其他的选择吗？\u003c/p>\u003cp>老婆：目前还有几个企业待面试，其中有一家各方面都还比较符合我的需求。我可以等这家企业面试结果出来后在做选择。\u003c/p>\u003cp>我：还有吗？\u003c/p>\u003cp>老婆：我再找找通勤时间符合我需求的地方投投简历，做一下备胎。\u003c/p>\u003cp>4、 问行动：\u003c/p>\u003cp>我：那个各方面都符合你需求的公司，你对面试通过的信心指数如何？\u003c/p>\u003cp>老婆：嗯，5-6分吧。\u003c/p>\u003cp>我：这个得分那还有点悬呀，还有什么方式可以提升一下信心指数吗？\u003c/p>\u003cp>老婆：我再去仔细研究一下他们的需求，然后把经验先组织几套逻辑话术来预备面试。\u003c/p>\u003cp>我：嗯嗯，很好，我帮你做做参谋。面试是什么时候？\u003c/p>\u003cp>老婆：下周一。\u003c/p>\u003cp>我：那还有4天，你打算哪天让我配合你练手？\u003c/p>\u003cp>老婆：后天！\u003c/p>\u003cp>我：得咧，我们来努力把信心指数提高到8分！\u003c/p>\u003ch1> \u003c/h1>\u003cp>【强有力的总结】\u003c/p>\u003cp>今天咱们学习了两个片段的知识，一个是有效的提问，它是不带着批评和引导性的，只是为了让对方获取更多信息，提升他觉察力和责任感的问题，片段二咱们学习了解决一个新问题完整的提问四步骤，叫做GROW模型：问目标-问现状-问选择-问行动。希望大家回去都用起来。\u003c/p>\u003cp>比尔盖茨说：每个人都需要一位教练。\u003c/p>\u003cp>通过教练式的有效提问，我们可以像照镜子一样感知到自己的行为和意识，从而激发内心的潜力与责任感，创造前所未有的奇迹。\u003c/p>\u003cp>以上就是我今天的拆书内容，感谢大家将近1个半小时的陪伴，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1620964175000,"updated_at":1621476697000,"ria":true},{"id":10230,"topic":"人人都可以是教练","learn_goal":"","remark":"《高绩效教练》作者约翰·惠特默爵士是教练领域的先行者，本书以GROW模型为教练逻辑，清晰阐述了教练的理念和技巧。本书是全球销量排名第一的教练书籍，长期被国际教练界誉为“教练领域的‘圣经’”和金牌标准，是全球数万教练和百万领导者的必备参考书。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"闲人","city":"长治市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>技能目标：两个拆页搭配，要求：有逻辑关系\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次现场学习后，学习者可以 可以使用GROW模型给自己或他人做一次教练式谈话。\u003c/p>\u003cp>\u003cstrong>目标：简单开场，分组\u003c/strong>\u003c/p>\u003cp>【开场】不破不能立，不拆不成器！拆书帮把知识拆成你的能力！欢迎大家参加拆书帮上党分舵线下拆书练级活动，我是今天的领拆人，RIA学习力导师、一级拆书家闲人。\u003c/p>\u003cp>【分组】为了方便学习过程中充分交流讨论，我们简单分个组。今天有*位书友到场，我们*人一组，这样分开。\u003c/p>\u003cp>谢谢！\u003c/p>\u003cp>\u003cstrong>目标：用FAB法介绍图书。要求：清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>【F核心是书，激发好奇心~讲什么】\u003c/p>\u003cp>《高绩效教练》作者约翰·惠特默爵士是教练领域的先行者，本书以GROW模型为教练逻辑，清晰阐述了教练的理念和技巧。\u003c/p>\u003cp>【A优势，作比较，突出权威性】\u003c/p>\u003cp>本书是全球销量排名第一的教练书籍，长期被国际教练界誉为“教练领域的‘圣经’”和金牌标准，是全球数万教练和百万领导者的必备参考书。\u003c/p>\u003cp>【B利益，可以带给学习者什么~解决什么问题】\u003c/p>\u003cp>你可能会说，自己又不想做教练，学这有什么用？\u003cstrong>【预防异议】\u003c/strong>你有没有给人提过建议？\u003cstrong>（停顿）\u003c/strong>其实，工作中，领导对员工，生活中，家长对孩子，甚至是同事之间、朋友之间、家人之间不经意间就会去教练他人或者被教练。\u003c/p>\u003cp>通常我们给完建议之后，自己觉得是肺腑之言、警世恒言，但很多时候对方却毫不领情，甚至还认为是一派胡言。问题出在哪里呢？就是方法不对，\u003cu>用高绩效教练的方法将你不仅不用担心对方能否听进去，还能让对方通过和你的对话自己找到答案，自身得到成长，并为自己的言行负责。\u003c/u>\u003c/p>\u003cp>【B2】\u003c/p>\u003cp>对教练有了新的认知后，今天就用书中的2个片段，\u003cu>带大家一起学习如何通过一场教练式对话，通过一系列问题帮助他人自己找到答案。\u003c/u>\u003c/p>","ratings_count":1,"texts":[{"id":14066,"quote":"\u003cp>\u003cstrong>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003c/strong>\u003c/p>\u003cp>在跟随我完成第一个RIA现场学习后，学习者可以在\u003cu>和员工谈绩效、给学生、孩子做辅导，或者给人提建议等正式非正式的教练场景下（界定）\u003c/u>，提出（行为）让对方更集中注意力专注细节（澄清）的问题。\u003c/p>\u003cp>\u003cstrong>目标：逻辑关系\u003c/strong>\u003c/p>\u003cp>【过渡语】首先我们先来学习教练的一项基本功——提问。\u003c/p>\u003cp>下面请用1分钟的时间快速阅读这个片段。重点看划线内容。\u003c/p>\u003cp>【R阅读原文】强有力的问题P70-71\u003c/p>\u003cp>提问远比指导或建议更能创建觉察或建立责任感。如果任何耳熟能详的问题都能够达到目的当然好，可惜现状不是这样。我们需要检验各类问题的有效性。为此，我会用体育运动中一个简单的类比来进行说明。如果问人们什么是在所有球类运动中使用最频繁的指令，他们会告诉你:“眼睛盯住球。”\u003c/p>\u003cp>在所有的球类运动中，盯住球当然非常重要，但“盯住球”的指令实际上会让你做得好吗?不会。如果会，那我们很多人都可以在运动场上表现得更出色。我们都知道，高尔夫球手在放松时击球会更直更远，但是“放松”这个命令会让高尔夫球手感觉更放松吗?不，这可能会让他们更加紧张。\u003c/p>\u003cp>\u003cu>如果命令一个人去做他需要做的事,反而不能产出我们所需要的结果,那么什么会让我们达到目的呢?让我们尝试问一个问题。\u003c/u>\u003c/p>\u003cp>\u003cem>\u003cu>•\u003cstrong>“你在看球吗?”\u003c/strong>我们会如何回答?也许我们会辩解,也可能会撒谎,就像我们在学校的时候老师问我们是不是注意听讲一样。\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•\u003cstrong>“你为什么不看着球?”\u003c/strong>我们会更加辩解,或者再加上一点儿分析。“我在看球。”“我不知道。”“因为我在想我的握杆动作。”或者更诚实的,“因为你让我分神并令我紧张。”\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cu>这些问题效果都不好,但请想想如下问题的效果。\u003c/u>\u003c/p>\u003cp>\u003cem>\u003cu>•那个球朝你飞过来的时候,是朝哪一边旋转的?\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•当球这次过网的时候,高度是多少?\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•这一次,或每一次它反弹起来的时候,它会旋转得更快还是更慢?\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•当你第一眼看到球旋转时,它离你的对手多远?\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cu>这些问题从完全不同的角度出发,它们创造出了其他问题或是命令不能实现的四个重要的效果。\u003c/u>\u003c/p>\u003cp>\u003cem>\u003cu>•这类问题促使球员观察球,否则他们无法回答此问题。\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•球员会比平常更加集中精神,才能正确回答这个问题,因此提供了更高质量的输入。\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•这些答案是描述性的而不是判断性的,因此没有自我批评或是伤害自尊的风险。\u003c/u>\u003c/em>\u003c/p>\u003cp>\u003cem>\u003cu>•我们的教练有一个意见反馈圈,他们有能力确认球员回答的正确性,因此了解球员是否聚精会神。\u003c/u>\u003c/em>\u003c/p>\u003cp>看完了请举手示意我一下，好，看到大部分都读完了，没读完的也没关系，接下来我会进一步讲解。\u003c/p>","explains":"\u003cp>\u003cstrong>技能要求：应用意译案例，不这么做的坏处，预防异议\u003c/strong>\u003c/p>\u003cp>【why】片段中的这个案例是不是似曾相识？学驾照的时候，教练是怎么训你的？辅导孩子作业时，你是怎么训孩子的？\u003cstrong>（通常做法）\u003c/strong>你有没有因为教练的训斥学得更快呢？孩子有没有被你训的进步了呢？相反，你可能因为紧张忘记动作，孩子因此而厌学。\u003cstrong>（坏处）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>我们就以学驾照为例，\u003c/p>\u003cp>一个教练黑着个脸坐着副驾上，一只手举起来随时准备打在你的胳膊上！\u003c/p>\u003cp>“看前面！”“打方向！”“回轮儿！”\u003c/p>\u003cp>“看哪里呢？”“往哪儿打？”\u003c/p>\u003cp>“低下个头看什么？”“为什么不踩离合？”\u003c/p>\u003cp>听到这些你怎么想？怎么回应？\u003c/p>\u003cp>开始还是紧张、怀疑自己，被这样问了以后开始抵触！\u003c/p>\u003cp>【what】这种命令、怀疑和指责的方式让对方把注意力集中在执行上，做到好坏都是在执行你的指令，把责任推给了教练，不仅不能得到我们想要的效果，还让对方产生了抵触情绪。\u003cstrong>（坏处）所以，\u003c/strong>一定要精心构思你的强有力但不责备的问题，使得思考问题的过程本身就是一种学习，并能通过这个过程学到东西。这才是教练的目的。\u003c/p>\u003cp>【how】那怎么就是强有力的问题了呢？要具备以下三个要素：\u003c/p>\u003cp>第一，要是开放式问题。相对应的就是封闭式问题，“你吃了吗？”这种用是或否就能直接回答的问题就是封闭式问题。“发生了什么？”“遇到什么问题？”这类开放性的问题要能得到描述性的答案，需要对方思考自己的行为。\u003c/p>\u003cp>第二，\u003cu>用“什么”“何时”“多少”“谁”等疑问词。\u003c/u>不建议用“为什么”。不是要多问几个“为什么”吗？这种探究行为值得肯定，但“为什么”经常会带有批评指责的意味，会引发防御心理，如果确实需要类似提问，可以换成“是什么原因……”。（是什么原因导致我们到了马路牙子上呢？）\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>第三，要专注细节。需要对方集中注意力在细节上才能回答。“目前这个速度，方向盘打一圈，车子会偏出去多少度？”\u003c/p>\u003cp>【预防异议】有人可能会说，直接告诉他怎么做不是更省时省力、直截了当吗？\u003c/p>\u003cp>是的，我们通常也是这样做的，那后果（坏处）是什么？可能当下做事的效率确实是提高了，但对方只是在简单的执行，自己没有思考，也没有责任，做的不好都是你让我这样做的！\u003c/p>\u003cp>【where】\u003c/p>\u003cp>当然，如果你只追求当下的效率，或者事态紧急，那你还是简单直接比较好。只要你希望对方能够有所成长，能够为自己的行为承担责任，那最后能用提问来激发对方的觉察——就是意识到自己在做什么！\u003c/p>","interaction":"\u003cp>\u003cstrong>A1要求：联系到过往具体经验\u003c/strong>\u003c/p>\u003cp>【提问设计】\u003c/p>\u003cp>现在请你想一下，在过去的一个月里，有没有类似这样的场景：给孩子辅导作业，教孩子骑车，或者和下属、爱人、同事，有人向你询问意见建议的情况。\u003c/p>\u003cp>回忆一下，当时你是怎么说的？结果怎么样？\u003c/p>\u003cp>想想当时发生了什么？你的建议是？结果呢？\u003c/p>\u003cp>每人一分钟，小组内分享。\u003c/p>\u003cp>谁来给大家分享一下？\u003c/p>\u003cp> \u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>付佳：孩子背诵毕业稿。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>要不断提示，让我很生气，一直不断提高分贝给提示。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果：让孩子的诵读越来越不顺，导致当天后面完全忘词。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>崔姐：辅导孩子写作业\u003c/strong>\u003c/p>\u003cp>\u003cstrong>写的特别慢，甚至写着写着就睡着了，直接开骂。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结果：我直接替他写了。\u003c/strong>\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>谢谢**！正如原文所讲，直接给建议好不好啊？（停顿）不好！对方不仅不会感激，还有了压迫感（20日现场演练）！（回到原文）\u003c/p>\u003cp>好，再次感谢**，掌声鼓励！（号召鼓掌）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>\u003cstrong>A1+要求：学习者加工出以后遇到同等情况如何做\u003c/strong>\u003c/p>\u003cp>OK，看来大家有已经觉察到或意识到提问的重要性，现在就给你一次穿越的机会，让你再回到当时的场景，你会怎么做？\u003c/p>\u003cp>你能提出什么的强有力的问题？\u003c/p>\u003cp>（互动）……\u003c/p>\u003cp>还有吗？\u003c/p>\u003cp>……\u003c/p>\u003cp> \u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>付佳：这几句有难度吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是哪里不好理解呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>崔姐：你写作业过程中发生什么了呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你遇到什么困难了？想不想跟我说一说？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>需要我做些什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是什么让你这么慢呢？想不想和我说一说？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有没有需要帮助的？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【现场反馈】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有没有需要帮助的？这个问题我只用回答有或者没有，这就是一个封闭性的问题。可以换成：哪些地方需要我的帮助？ \u003c/strong> \u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>是否符合“强有力问题”三个要素呢？\u003c/p>\u003cp>（互动）\u003c/p>\u003cp>哪里不符合？\u003c/p>\u003cp>非常好！我和你的看法一致！（点评）\u003c/p>\u003cp>谢谢，大家都提出了强有力的问题，为自己鼓掌！（号召鼓掌）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>以后再遇到被人求助等的情况是提建议呢？还是提问题呢？\u003c/p>\u003cp>（互动：提问题！）\u003c/p>\u003cp>目标：承上启下。要求：呼应、总结、简短\u003c/p>\u003cp>通过刚才的学习，看到大家已经具备了教练的一项基本能力——提问，那接下来，就给到大家教练的必备工具——GROW模型！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":14067,"quote":"\u003cp>\u003cstrong>目标：设定学习目标。要求：可观察/可测量的行为或动作\u003c/strong>\u003c/p>\u003cp>在跟随我完成第二个RIA现场学习后，学习者可以运用GROW模型的四个步骤（澄清），设计（行为）一次教练式（界定）对话。\u003c/p>\u003cp>\u003cstrong>目标：实用类图书、包含HOW的片段；内容不超过2页纸\u003c/strong>\u003c/p>\u003cp>请用1分钟时间快速阅读拆页二\u003c/p>","explains":"\u003cp>\u003cstrong>技能要求：应用细化步骤，不这么做的坏处，预防异议\u003c/strong>\u003c/p>\u003cp>【what】这就是本书最核心的教练框架，GROW模型：也就是一个完整教练过程4个阶段。\u003c/p>\u003cp>只要你稍微留意一下，工作和生活中，经常会遇到各种正式或非正式的教练场景，不论是对下属、对学生、对孩子，还是和同事朋友家人，甚至是对上级，都可以需要进行教练式的谈话。\u003c/p>\u003cp>【why】（举例子）比如上次我们拆倒推分解法，演练结束之后，我问肖琴什么感觉，她说有压迫感！还记得当时发生了什么吗？\u003c/p>\u003cp>（互动：请肖琴和付佳回忆）\u003c/p>\u003cp>（总结：因为时间有限，付佳扮演的老付直接给出一堆自认为合理的建议。）\u003c/p>\u003cp>通常情况，我们习惯于按照自己的理解给出意见建议，甚至会一遍遍苦口婆心的教训和指点，如果是下属或孩子，还会恨铁不成钢地劈头盖脑一顿指责！\u003cstrong>（通常做法）\u003c/strong>我们期望的是对方幡然悔悟、痛改前非、重新做人，但结果是一堆理由、满心委屈，落得个站着说话不腰疼。\u003cstrong>（坏处）\u003c/strong>\u003c/p>\u003cp>【how】\u003cstrong>（细化步骤）\u003c/strong>\u003c/p>\u003cp>正确的做法是运用教练模型的四个步骤来提问：\u003c/p>\u003cp>1、问目标。大多数人迷失的主要原因就是目标不清晰，不清楚自己真正想要什么。通过提问，可以明确目标。在这一步，你可以问：你的目标是什么？你想要什么?\u003c/p>\u003cp>2、问现状。目前是什么情况？对于完成目标有哪些有利和不利因素？通过这样的提问，可以帮助对方客观了解自己当前的现状。\u003c/p>\u003cp>3、问方案。面对目标与现状之间的差距，你有什么想法？有什么计划？有哪些选择？这一步最主要的是探索更多的可能性，以找出最优方案。\u003c/p>\u003cp>4、问行动。方案确定后，你第一步将做什么？什么时候开始行动？什么时候能完成？通过类似问题确定行动计划、时间表和观测机制。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有人可能会认为每次沟通都这样一步一步问，太费劲了！\u003c/p>\u003cp>这里有两点需要说明：第一，之前已经说过，再强调一次：只要是你希望对方能够有所成长，意识到自己需要为此负责，最好通过以上四步，可以迫使对方深入思考，从而自己找到答案；但步骤不是一成不变的，可以根据情况予以调整。\u003c/p>\u003cp>【where】第二，教练模型的适用场景就是各种正式非正式的、有意识地想让对方成长的教练场景，不适合紧急情况处置、闲聊或者有明显答案等情形。\u003c/p>","interaction":"\u003cp>\u003cstrong>要求：用知识点通过小组讨论形成方案，并角色扮演。\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>接下来，我们就来用今天学到的方法来设计一个模拟教练场景：人物还是小强和老付，背景是：小强对拆书法和拆书帮很感兴趣，刚参加了两期的线上训练营，现在想要加入我们分舵。老付要以舵主或长老的身份和小强进行一次教练式谈话。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>现在，请大家用8分钟时间，按照开场的分组，在小组内按照GROW模型的四个步骤，帮老付和小强设计一组对话。\u003c/p>\u003cp>开始。\u003c/p>\u003cp>（互动交流）可以提出哪些问题？对方可能说什么？针对性再怎么问？注意：一定要按照GROW模型的四个步骤来进行。\u003c/p>\u003cp>【角色扮演】（6分钟）\u003c/p>\u003cp>现在要请一人来扮演老付，一人演小强，谁来？\u003c/p>\u003cp>好，两位请选择一组对话。\u003c/p>\u003cp>请开始你们的表演！\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：恭喜你完成了两期的训练营学习！【问目标】你现在参加拆书帮目标是什么？有什么计划吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小强（肖琴）：我特别向往拆书家，想在年内成为三级拆书家。1月份到3-3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：【问现状】你现在的情况是什么样子？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小强（肖琴）：现在我刚刚参加完训练鞋，拜了师，拿到拆书家成长手册，浏览了官网\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：【问方案】那你接下来计划怎么做？有什么打算？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小强（肖琴）：年底会比价忙，现在还好可以抽出时间，我计划近期安排的紧凑一点，一周到两周一次，到后期难度大了可以一个月过一级。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：前面的级别想到比较简单，你可以适当调整一下节奏\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小强（肖琴）：那我9月份之前尽量安排紧凑一点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：那你下周准备做些什么？你可能会遇到哪些困哪或问题，需要我们帮助的？【问行动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小强（肖琴）：我计划下周先准备好1-1 的预备表，需要和教练沟通一下，还需要分舵的前辈给与一定的帮助。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：【问行动】那你明天要做些什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小强（肖琴）：我要开始写预备表\u003c/strong>\u003c/p>\u003cp>\u003cstrong>老付（崔姐）：接下来我们都会全力以赴帮助你的，欢迎你家人拆书帮上党分舵！\u003c/strong>\u003c/p>\u003cp>【设计反馈】\u003c/p>\u003cp>谢谢两位（鼓掌）！两组设计的问题都符合GROW模型的基本框架（真诚赞美），当然，在实际应用中可能会遇到各种情况，作者通过多年的实践总结，在本书的最后把他常用的教练问题工具包给到了我们，需要的朋友可以下去后找我哦！（超越拔高）\u003c/p>\u003cp>【现场反馈】\u003c/p>\u003cp>\u003cstrong>A2要求：包括情景或场景，学习者受启发联系到自己的具体应用场景\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>现在请想一下，未来一周，你可以对谁进行一次正式或非正式的教练式对话？孩子？合伙人？闺蜜？或者是自己？\u003c/p>\u003cp>（等待回答）\u003c/p>\u003cp>针对什么事情？写在便签上！\u003c/p>\u003cp>（学习者设计出场景）\u003c/p>\u003cp>【行动指令】\u003c/p>\u003cp>OK，现在就针对自己写出的场景，请按照GROW模型设计自己的提问清单。时间5分钟\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>付佳：和孩子沟通语言大赛的事情\u003c/strong>\u003c/p>\u003cp>\u003cstrong>崔姐：和孩子沟通考研的事情\u003c/strong>\u003c/p>\u003cp>\u003cstrong>肖琴：和老公沟通孩子教育的问题\u003c/strong>\u003c/p>\u003cp>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>【小组分享】\u003c/p>\u003cp>设计好了之后可以在小组内进行分享，另一名组员可以把自己当成教练对象，感受一下这些问题，并提出自己的意见建议。\u003c/p>\u003cp>（视现场时间，公开表达）\u003c/p>\u003cp>谁愿意给大家说说自己的问题清单设计。\u003c/p>\u003cp>……\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>肖琴：【问目标】你想要一个什么样的亲子关系？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【问现状】你和孩子目前是什么情况？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【问方案】你计划怎么改进和孩子的关系呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【问行动】你近期准备采取什么行动，以改进亲子关系？\u003c/strong>\u003c/p>\u003cp>【反馈设计】\u003c/p>\u003cp>非常好，对GROW教练模型已经达到满足日常基本应用的程度。（赞美）你计划什么时间执行这个计划呢？请在2周内完成，并把效果和遇到的问题发在我们分舵会员群，和大家交流讨论哦。\u003c/p>\u003cp>再次感谢！（掌声）\u003c/p>\u003cp>【现场反馈】掌声感谢肖琴的分享。\u003c/p>\u003cp>整个过程设计大体还是符合GROW模型的，其中也有一些问题属于封闭问题。\u003c/p>\u003cp>时间关系，其他人没有分享，希望大家在为了2周内，用你设计的这一组问题，和计划教练的对象开展一次教练式的对话，并把效果和遇到的问题发在我们分舵会员群，和大家交流讨论哦。\u003c/p>\u003cp>目标：强有力的结语，要求：简短，呼应\u003c/p>\u003cp>好，我们刚刚一起学习了高绩效教练的GROW模型，今后再遇到类似他人求助等正式非正式教练场景，请记住这四个步骤，我们一起回忆一下：\u003cstrong>（互动）\u003c/strong>一问G~目标，二问R~现状，三问O~选择，四问W~意愿（行动）。\u003c/p>\u003cp>还要注意强有力问题的三个要是：开放式问题，疑问词，和专注于细节。\u003c/p>\u003cp>YES！完美！\u003c/p>\u003cp>我今天的拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1596720436000,"updated_at":1597755766000,"ria":true},{"id":10214,"topic":"初学者如何用好GROW模型？ ","learn_goal":"","remark":"“教练技术”是一种心理学应用的专业技能。教练技术的核心是提问，在沟通中运用提问而不是建议来启发个体的自我潜能，学习对自己负责。 如果你将其运用在上级和下属之间，它就变成一种管理工具；如果你将其运用到朋友之间，它就是一种沟通技能；如果你将其运用在家长和孩子的对话之中，它就成为一种辅导方式。 因此，如果你是一位职场人士，想要锻炼自己的领导力；或者你很喜欢结交朋友，想提升自己的个人影响力；又或者你已经生了娃，想加强你与孩子之间的沟通关系……那么，教练技术都非常适合你。","level":"TF2-4","duration":40,"status":0,"type":0,"chaishujia":{"username":"冀颖妍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>贴错了，可删除。\u003c/p>\u003cp>【TF2-4 拆页二】\u003c/p>\u003cp>【学习目标2】\u003c/p>\u003cp>在跟随我完成第二个拆页的学习之后，学习者能够：在对方的目标明确时，运用教练技术中的ROW的提问方式，帮助他人分析现状、探索可选方案和明确行动意愿，并且能够保护他人的\u003cstrong>责任感\u003c/strong>。\u003c/p>","ratings_count":0,"texts":[{"id":14048,"quote":"\u003cp>接下来，我们开始学习第二个拆页——GROW模型具体指的是什么，以及后三个环节的提问方法论。\u003c/p>\u003cp>【学习目标2】\u003c/p>\u003cp>在学习这个拆页后，大家能够：在对方的目标明确时，运用教练技术中的ROW的提问方式，帮助他人分析现状、探索可选方案和明确行动意愿。\u003c/p>\u003cp>现在请各位小伙伴用1分钟的时间阅读以下片段。完成后麻烦举手示意。好，请开始。\u003c/p>\u003cp>【片段二】\u003c/p>\u003cp>\u003cstrong>GROW模型\u003c/strong>\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四步骤\u003c/p>\u003cp>* 目标设定(goal)，本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>* 现状分析( reality)，探索当前的情况。\u003c/p>\u003cp>* 方案选择( options)，可供选择的策略或行动方案。\u003c/p>\u003cp>* 该做什么(what)，何时(when)，谁做(who)，意愿(will)。\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个段开始或结束。\u003c/p>","explains":"\u003cp>【预防异议】\u003c/p>\u003cp>以上就是教练技术的GROW模型，作者用200字就对该模型做完了概述，于是你们可能会认为，学习GROW模型是一件非常简单的事情。\u003c/p>\u003cp>我曾经也是这么认为的。可是，当我尝试在现实生活中运用这套方法论时，我才知道这有多么的艰难。\u003c/p>\u003cp>[Why]【不这么做的坏处】\u003c/p>\u003cp>\u003cstrong>[难点1：要压制“提建议”的冲动]\u003c/strong>\u003c/p>\u003cp>各位都知道，GROW模型主要运用的现实场景是，当别人跑来咨询你时，你要用它来教练他人。可是，在现实生活当中，当别人过来咨询你时，你的第一反应是什么？\u003c/p>\u003cp>我现在假设一个场景，帮助大家回忆一下哈。\u003c/p>\u003cp>我知道，今天能来参加拆书线下活动的小伙伴们平时都是比较爱看书的。现在，假如有一位刚进职场的小学妹跑来问你：“师兄（师姐），你认为工作后，我们应该如何保持良好的阅读习惯呢？”\u003c/p>\u003cp>请问：你的第一反应是什么？\u003c/p>\u003cp>[反例]\u003c/p>\u003cp>你心里可能会想：“呀，这个问题我很熟悉呀，我能作答！”然后，就拉着学妹的双手，语重心长地说：\u003c/p>\u003cp>职场人的时间是很宝贵的，如果你想保持阅读习惯……\u003c/p>\u003cp>\u003cu>\u003cstrong>你应该 \u003c/strong>先解决自己的学习动力问题；\u003c/u>\u003c/p>\u003cp>\u003cu>\u003cstrong>你应该 \u003c/strong>优先阅读适合自己的致用类书籍；\u003c/u>\u003c/p>\u003cp>\u003cu>\u003cstrong>你应该 \u003c/strong>在余闲时间不玩手机、不刷抖音、不煲热剧，把全部碎片时间用于读书……\u003c/u>\u003c/p>\u003cp>这是你的第一反应，它叫做“\u003cstrong>提建议\u003c/strong>”。\u003c/p>\u003cp>为什么我们喜欢提建议呢？因为自我感觉良好呀！\u003c/p>\u003cp>你看，学妹很认真地记下了你的建议，看起来你已经拯救了学妹，你预期学妹的世界将因此而得到改变。所以，你的自我感觉当然良好。\u003c/p>\u003cp>可是，你有没有想过，学妹真的会践行你的建议吗？\u003c/p>\u003cp>很遗憾，基本不会。\u003c/p>\u003cp>说实话，以上场景也是本人经常遇到的，我也是很乐意给学妹提建议的。\u003c/p>\u003cp>但，通常一两个月后当我再次碰到她，问她读书计划开展得怎么样时……学妹通常一脸尴尬，说因为出现了各种各样的突发状况，无奈暂缓了……\u003c/p>\u003cp>如果只有一个学妹出了突发状况不执行我的建议，那我可能真信了。可是，我发现，许多学妹都是用类似理由搪塞我的……我就开始反思：是不是当初我所提的建议对她其实毫无意义？因为她们根本没有去践行。\u003c/p>\u003cp>后来，我静心一想，觉得学妹们做得也没错。因为“提建议”是从我的视角出发，我认为什么是对的，就会硬塞给对方，所以对方觉得“不适用、不去用”是相当正常的。\u003c/p>\u003cp>于是，教练技术的基础要求是，当别人咨询你时，你要以“\u003cstrong>提问\u003c/strong>”的方式去启发对方主动思考，也就是说，你得压制住自己想“提建议”的冲动。这就涉及到你的底层思维模式的艰难转换，这也是你想运用GROW模型时会碰到的第一个难点。\u003c/p>\u003cp>\u003cstrong>[难点2：提问过程不可控]\u003c/strong>\u003c/p>\u003cp>好了，现在我假设你已经下定决心选择“提问题”的反应模式，这时你又会碰上第二个操作难点——\u003cstrong>提问过程的不可控因素\u003c/strong>实在太多了。\u003c/p>\u003cp>提问属于即时互动的过程。如果你记不起GROW模型各个环节的问句，请问你要如何发问？如果对方的回答老是切不到重点，请问你要如何启发他继续深入思考？……\u003c/p>\u003cp>所以，在实践中你会惊讶地发现，提问过程其实是一个“幺蛾子满天飞”的过程。\u003c/p>\u003cp>怎么解决？\u003c/p>\u003cp>作者想到的办法是，在书中为GROW模型的每一个环节都准备了详细的问题清单，每个清单大约有十几、二十条，乘以四，大约共80个条目。\u003c/p>\u003cp>可是，当碰到现实问题时，作为教练技术初学者的我们可能一个清单中的问题都无法回想起来。\u003c/p>\u003cp>[What]\u003c/p>\u003cp>于是，为了方便大家理解和记忆，今天我特意把GROW模型转化为一幅记忆图，帮助大家记住环节之间的逻辑关联，以及每个环节的基础问句。\u003c/p>\u003cp>各位请看，记忆图中的\u003cstrong>B点\u003c/strong>表示你未来想要到达的目的地，这代表着第一个环节\u003cstrong>设定总体目标（G）\u003c/strong>。\u003c/p>\u003cp>然后，图中\u003cstrong>A点\u003c/strong>表示你现在所处的位置，代表着第二个环节\u003cstrong>分析现状（R）\u003c/strong>。\u003c/p>\u003cp>接着，你可以启发对方思考\u003cstrong>如何从A点到达B点\u003c/strong>，触发对方思考第三个环节——\u003cstrong>探讨可选方案（O）\u003c/strong>。\u003c/p>\u003cp>最后，在你选定最优方案后，可以细化行动计划，确定某些小目标，明确第一步、第二步、第三步……自己应该做些什么。这就代表着模型中的第四个环节\u003cstrong>明确行动计划（W）\u003c/strong>。\u003c/p>\u003cp>根据上述逻辑，我为四个环节提炼出相应的基础问句，它们分别是：\u003c/p>\u003cp>第一句：\u003cstrong>你想要什么？\u003c/strong>（G环节）\u003c/p>\u003cp>第二句：\u003cstrong>你现在的情况是怎么样的？\u003c/strong> （R环节）\u003c/p>\u003cp>第三句：\u003cstrong>你能做些什么？\u003c/strong>（O环节）\u003c/p>\u003cp>第四句：\u003cstrong>你会怎么做？\u003c/strong>（W环节）\u003c/p>\u003cp>因此，通过“一张图和四个问句”，现在我们更加容易地把GROW模型印在自己的心中了。\u003c/p>\u003cp>与此同时，鉴于大部分咨询者一开始是不太习惯回答问题的，通常而言，我们不可能就以一个问题就能问到有用答案。所以，我们要懂得围绕各环节的基础问句稍作延伸，变成四组小问题，达成启发对方深度思考的效果。\u003c/p>\u003cp>[How]\u003c/p>\u003cp>对于设定目标的G环节，我们的延伸问题已经通过上一个拆页学习到了，包括界定问题、最终目标和绩效目标三个子问题。\u003c/p>\u003cp>接下来，我们着重提炼后三个环节ROW的问题集。事实上，它们的形态可以灵活多变，不过为了让大家加速入门，我将自己常用的问题集作为模板，供大家参考：\u003c/p>\u003cp>【\u003cstrong>ROW问题集\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>R环节（现状分析）\u003c/strong>\u003c/p>\u003cp>基础问句：你现在的情况是怎么样的？ \u003c/p>\u003cp>延伸问句：你目前遇到了什么困难吗？\u003c/p>\u003cp>能否描述一个与你现状相关的具体场景？\u003c/p>\u003cp>\u003cstrong>O环节（方案选择）\u003c/strong>\u003c/p>\u003cp>基础问句：你能做些什么？ \u003c/p>\u003cp>延伸问句：方案一、方案二、方案三分别有哪些？\u003c/p>\u003cp> 还有吗？（最大化可选方案）\u003c/p>\u003cp>\u003cstrong>W环节（行动计划）\u003c/strong>\u003c/p>\u003cp>基础问句：你会怎么做？\u003c/p>\u003cp>延伸问句：第一步、第二步、第三步分别是什么？\u003c/p>\u003cp> 你需要什么资源来支持，提高可行性？ \u003c/p>\u003cp>【案例】\u003c/p>\u003cp>接下来，我举自己的实战例子，以便大家理解如何运用“ROW问题集”。\u003c/p>\u003cp>[反例转正例]\u003c/p>\u003cp>前几天，又有一位学妹来问我与坚持读书相关的问题——\u003cu>在今年年初初她制定了一个读书计划，截至今年年底，她想要读完50本书\u003c/u>。但试运行了半年，现在她觉得好难坚持下去，于是跑来问我怎么办。\u003c/p>\u003cp>鉴于学妹的目标已经比较明确，所以我从分析现状等环节开始提问。\u003c/p>\u003cp>\u003cstrong>1、现状分析（R）\u003c/strong>\u003c/p>\u003cp>我：\u003cstrong>你现在的情况是怎么样的？\u003c/strong>是遇到什么困难了吗？\u003c/p>\u003cp>学妹：工作后，我总感觉自己的时间不够用。\u003c/p>\u003cp>我：\u003cstrong>能否描述一下你现在典型的一天是什么样子的呢？\u003c/strong>\u003c/p>\u003cp>学妹：因为公司离家远，我每天6:30起床，然后坐2小时地铁到单位；8:30-18:30是我的上班时间；然后我20:30回到家，一直忙家里的事，直到22:30才能上床睡觉。\u003c/p>\u003cp>（旁白：至此，对方的现状分析已经描述得比较清晰了，所以我就可以进入下一环节的提问。）\u003c/p>\u003cp>\u003cstrong>2、方案选择（O）\u003c/strong>\u003c/p>\u003cp>我：那么，在没有时间这个问题上，结合你的典型日程，你觉得\u003cstrong>你能做些什么呢？\u003c/strong>\u003c/p>\u003cp>学妹：在家22:00哄完孩子睡着后，其实我可以爬起来先看1小时书再睡觉。\u003c/p>\u003cp>我：恩，这个想法很好。\u003cstrong>还有吗？\u003c/strong>比如，你有什么时间有可能复用呢？\u003c/p>\u003cp>学妹：哦，坐地铁上下班时，路途中有接近4小时，也许我可以带本书在地铁里看书。\u003c/p>\u003cp>我：恩，很好。\u003cstrong>还有其他吗？\u003c/strong> \u003c/p>\u003cp>学妹：没有了，实在想不出来。\u003c/p>\u003cp>（旁白：在方案选择环节有个小技巧，我们可以多问一两次“还有吗”，尝试引导对方思考出更多可选方案。）\u003c/p>\u003cp>\u003cstrong>3、行动计划（W）\u003c/strong>\u003c/p>\u003cp>我：那么接下来，\u003cstrong>你会怎么做呢？第一步、第二步、第三步分别是什么？\u003c/strong>\u003c/p>\u003cp>学妹：第一步，我会把下半年想看的书一次性买下来；然后按照能挤出来的时间去执行——充分利用上下班坐地铁的时间，以及小孩睡下后的时间去阅读；试行一周后，我再看看还能如何优化和调整。\u003c/p>\u003cp>（旁白：现在，整套行动计划都是学妹自己一个人想出来的，大家认为，学妹后续去执行的概率会不会变得更大？肯定会。）\u003c/p>\u003cp>所以，与“提建议”形成鲜明对比的是，“提问题”是站在对方角度，请他主动思考适合自己的方案和计划，能够最大程度地启发对方，提高了对方的\u003cstrong>责任感\u003c/strong>，进而提高了她的后续执行力。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>不过，有小伙伴的心中可能还有疑虑，在实战过程中，作为提问者的我们如何突然想不到问题、卡壳了，会不会很尴尬、很奇怪？\u003c/p>\u003cp>其实，教练技术是要结合你的\u003cstrong>认真倾听\u003c/strong>才能起到作用，在提问过程中，只要你认真听取他人的表达，仔细观察对方，并按照他的兴趣、明示或暗示继续问下去，你就不会被卡住。\u003c/p>\u003cp>你还可以加上一个小技巧——用一张纸把对方所回答的\u003cstrong>关键字记录\u003c/strong>下来。一方面会让对方感觉到你很重视他的答案，进而更加认真思考你提出的问题；另一方面在记录的过程中，你也为自己腾出了思考下一个问题的时间。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】角色扮演\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>为了让大家更好的理解和运用刚刚讲述的方法。我们来做一个小游戏。\u003c/p>\u003cp>\u003cu>小明是小红的同桌同事，他今年报名参加了中级经济师的考试，考试时间在11月初。考试通过后，他就能加薪，而且有助未来的职业发展。可是，现在他感觉自己工作太忙了，抽不出太多时间复习，准备放弃考试。如果你是小红，你会怎么劝小明继续积极备考呢？\u003c/u>\u003c/p>\u003cp>现在，请大家两两为一组，一位扮演小明，另一位扮演小红，请你使用“ROW问题集”帮助小明分析现状、探索可选方案、明确行动意愿。请大家在组内演练体验5分钟。待会我会让两位分角色扮演的小伙伴上来给我们进行现场演绎和分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>70后福哥扮演小红，90后Cindy扮演小明。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>既然你这么想拿到中级经济师的证，那么你想怎么样达到这个目标呢？你每天的时间是怎么利用的？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>我一般九点半开始上班，下班是晚上八点，晚上到家忙完生活上的事情就睡觉了。所以感觉很难找到时间复习，这是我的现状。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>时间挤挤还是有的，你觉得自己有哪些时间还有可能利用起来？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>我想到，公司中午有2个小时的休息时间，我觉得利用午休时间抽出1小时复习，应该是可以的；还有我上班时间比较晚，如果我早起复习，时间还是有的。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>还有吗？晚上时间有利用的可能吗？ \u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>晚上应该很难，我干完所有事情会头疼，所以必须早睡。只有中午和早起时间了。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>今年的复习计划你打算什么时候开始呢？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>距离考试时间还剩五六个月，考试内容包括12个章节，平均每月要完成两个章节。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>你回去之后打算怎么做，第一步、第二步等等分别要做什么？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>第一步是把相关书籍买齐全；第二步平均每个月完成2个章节内容；第三步看完书籍遇到问题我还要请教小红，因为你比较有经验。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>好的，没问题。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>（摘要点评）\u003c/p>\u003cp>感谢这两位小伙伴给我们带来的精彩演绎，让我们掌声送给他们。\u003c/p>\u003cp>刚才\u003cu>小红（福哥）\u003c/u>的提问基本遵循了“ROW问题集”的提问逻辑，每一个环节都有兼顾到。接着，\u003cu>小明（Cindy）\u003c/u>也很认真地作答。小明给自己梳理出来的现状是“她的工作时间很忙，大概晚上十点要睡觉”；在方案选择的时候，她给自己挑出两个时间段，一个是早起，另一个是中午时段用于复习，这时她的方案一和方案二；最后在讲到完善行动步骤时，她讲得特别好，她说“第一步要完善复习材料，第二步是按计划每月复习，第三步遇到不会就请教小红”等等，这是她的第一步、第二步、第三步。这证明大家对于这套方法论开始找到自己的感觉了。\u003c/p>\u003cp>【A2】催化应用（第一步）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>为了帮助大家将今天所学习的“ROW问题集”运用到现实生活当中，现在请大家想象一下，在未来的一到两周内，你会不会遇到别人请教你的情境？\u003c/p>\u003cp>\u003cu>如果你是个健身达人，疫情过后，同事们纷纷关注自己的身体健康，都想来请教你“如何坚持每周至少去一次健身房”；\u003c/u>\u003c/p>\u003cp>\u003cu>如果你的厨艺很好，春节期间，你在朋友圈稍稍露了几手，现在你的朋友都来问你“如何训练自己的厨艺，以便抓住老公的胃”……\u003c/u>\u003c/p>\u003cp>现在，请大家先花2分钟时间设想一下这个情境，包括时间、地点和人物以及对方已设定的目标等概要信息。\u003c/p>\u003cp>参考模板：\u003c/p>\u003cp>情境：在\u003cu>_____\u003c/u>（何时），\u003cu>_____\u003c/u>（求助者姓名）可能会来找我咨询\u003c/p>\u003cp>\u003cu>_________________________\u003c/u>（哪件事情）。\u003c/p>\u003cp>TA的目标是：\u003cu>___________________________________。\u003c/u>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[从事保险行业的柯伟娜]\u003c/strong>\u003c/p>\u003cp>情境：在\u003cu>下周一早上\u003c/u>，\u003cu>我的团队成员小陈\u003c/u>可能会来找我咨询\u003cu>如何提高自己的介绍保险产品的能力。\u003c/u>\u003c/p>\u003cp>TA的目标是：\u003cu>他希望介绍保险产品后，能够取得客户信任，提高下单量。\u003c/u>\u003c/p>\u003cp>【A2】催化应用（第二步）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>接下来，请大家思考一下，你会如何运用“ROW问题集”向求助者提问，帮助他理清现状、寻找可选方案和明确行动计划。\u003c/p>\u003cp>请大家思考3分钟，之后我念一位小伙伴的思考结果。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[从事保险行业的柯伟娜]\u003c/strong>\u003c/p>\u003cp>我们之间的对话可能如下：\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>你现在跟客户介绍产品后情况是怎么样的？会遇到什么困难吗？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会诉说，客户听他介绍后仍然心存疑虑、迟迟不肯下单等现实困难。）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>那么，你认为你能做些什么呢？比如，在准备阶段你能多做些什么？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会说说自己可以优化产品跟潜在客户之间的匹配度）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>到了跟客户面谈时，你还能做些什么呢？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会谈及自己跟客户见面时增加一些沟通技巧等）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>所以，你的方案一是XXX，方案二是XXX……（此处稍微帮他总结一下，如果他想到的办法不够多，我适当增加1-2个可选方案供他参考。）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>从这一周开始，在面见潜在客户之前，你会怎么做呢？第一步、第二步、第三步分别做些什么？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会梳理出自己的具体行动步骤）\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>好的，我看见大部分小伙伴都已经写出了自己的未来规划。这个未来场景是否真正出现，其实不太重要。真正重要的是，我们今天在现场强迫自己参照新学的方法论为这个情景做过详细规划，这有利于我们的内化和理解。在未来，当大家遇到类似场景，我希望大家可以真正做到学以致用。谢谢。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好了，以上就是今天我要带领大家学习的内容。现在我们来回顾一下。\u003c/p>\u003cp>今天我们学习了教练技术的GROW模型，在第一个拆页片段详细学习了第一环节G，通过“目标设定三步骤”可以帮助你或他人确定总体目标，\u003cstrong>提升自我觉察力\u003c/strong>。在第二个拆页片段里，我们着重学习了模型的后三步，通过“ROW问题集”，让大家理解了提问而不是提建议，会更有助于让对方明确自己的责任担当，\u003cstrong>拥有强烈的责任感\u003c/strong>。\u003c/p>\u003cp>在书中第49页，当作者给我们介绍了GROW模型后，他说到：“如果你能从本书中学到什么，最好是\u003cstrong>觉察力和责任感\u003c/strong>，它们远比GROW模型重要得多”。这也是我为大家精心挑选以上两个拆页的真正原因。\u003c/p>\u003cp>最后，我想邀请大家思考一下《高绩效教练》书名中的另一个关键词，什么才算得上是“\u003cstrong>高绩效\u003c/strong>”？\u003c/p>\u003cp>如果你只是按某人要求完成了某项任务，这算不算“高绩效”？我认为不算。只有当你以最高标准来要求自己，充分展现个人潜能，最终做成的事情超越了他人的预期——这才算得上是“高绩效”。\u003c/p>\u003cp>而，一个人要充分展现潜能达成高绩效，就需要他敢于承担自己的全部责任，并且拥有充分的自主选择权。所以，书中提到“\u003cstrong>你可以使一个人跑，但不能使他快跑\u003c/strong>”，除非你使用的是教练技术这套强有力的提问术。\u003c/p>\u003cp>非常感谢大家在这一个小时内的专注学习。现在，我要给大家留个小作业。刚才各位设想了未来一两周内别人有可能来请教你的情景，并写出了你的教练思路。我希望，当你真正遇到相似情境时，可以按照自己天的规划认真践行一遍。因为当你在现实场景中，真正运用过教练技术，你就能感受到这种方法论的独特魅力。\u003c/p>\u003cp>感谢大家的耐心聆听，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1596439137000,"updated_at":1597223291000,"ria":true},{"id":10213,"topic":"初学者如何用好GROW模型？ ","learn_goal":"","remark":"【拆书主题】初学者如何用好GROW模型？ \n【拆书价值】 “教练技术”是一种心理学应用的专业技能。教练技术的核心是提问，在沟通中运用提问而不是建议来启发个体的自我潜能，学习对自己负责。 如果你将其运用在上级和下属之间，它就变成一种管理工具；如果你将其运用到朋友之间，它就是一种沟通技能；如果你将其运用在家长和孩子的对话之中，它就成为一种辅导方式。 因此，如果你是一位职场人士，想要锻炼自己的领导力；或者你很喜欢结交朋友，想提升自己的个人影响力；又或者你已经生了娃，想加强你与孩子之间的沟通关系……那么，教练技术都非常适合你。 \n【拆解书籍】《高绩效教练》\n","level":"TF2-4","duration":40,"status":30,"type":0,"chaishujia":{"username":"冀颖妍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>各位亲爱的小伙伴们，大家晚上好，我叫冀颖妍。我现在一家大型传媒集团担任企业战略规划师，我也是一位爱学习、爱演讲和爱社交的鸡血型三好女青年。\u003c/p>\u003cp>【F】\u003c/p>\u003cp>今天我想给大家推荐的书籍叫做《高绩效教练》。第一次听到这书名的小伙伴们可能会觉得有点奇怪，我不打算学网球、又不打算练健身，为什么要学习一本\u003cstrong>教练\u003c/strong>书籍？\u003c/p>\u003cp>实际上，我们细看书名就发现，“教练”一词对应的英文是 “Coaching”，指的是“\u003cstrong>教练技术\u003c/strong>”，它是\u003cstrong>一种心理学应用的专业技能\u003c/strong>。教练技术的核心是运用\u003cstrong>提问\u003c/strong>的方式，\u003cstrong>启发个体的自我潜能\u003c/strong>。\u003c/p>\u003cp>【B1】\u003c/p>\u003cp>如果你将其运用在上级和下属之间，它就变成一种\u003cstrong>管理工具\u003c/strong>；如果你将其运用到朋友之间，它就是一种\u003cstrong>沟通技能\u003c/strong>；如果你将其运用在家长和孩子的对话之中，它就成为一种\u003cstrong>辅导方式\u003c/strong>。\u003c/p>\u003cp>因此，如果你是一位职场人士，想要锻炼自己的领导力；或者你很喜欢结交朋友，想提升自己的个人影响力；又或者你已经生了娃，想加强你与孩子之间的沟通关系……那么，教练技术都非常适合你。\u003c/p>\u003cp>【A】\u003c/p>\u003cp>《高绩效教练》这本书的豆瓣评分高达8.2，它成书在20年前，是教练技术领域的一本最经典之作。本书作者约翰.惠特默爵士是教练领域的先行者，他定义了教练技术的基本规则“GROW模型”，世人沿用至今。\u003c/p>\u003cp>GROW模型包括目标设定（G）、现状分析（R）、方案探索（O）和明确行动计划（W）四个环节。在面对某个全新事件时，如果你能针对这四个环节逐一提问，那么对方的思考过程就会比较全面。\u003c/p>\u003cp>【B2】\u003c/p>\u003cp>稍后，我会通过两个片段给大家详细讲解这个模型，让大家初步掌握教练技术，懂得用它帮助自己和他人解决生活中的一些常见问题，达到助人助己的效果。\u003c/p>","ratings_count":2,"texts":[{"id":14047,"quote":"\u003cp> [What]\u003c/p>\u003cp>今天我为大家挑选的第一个拆页是教练技术GROW模型的\u003cstrong>第一个环节G\u003c/strong>，关于设定目标的方法论。这一步是模型中最重要的一步。\u003c/p>\u003cp>【学习目标1】\u003c/p>\u003cp>在学习这个片段后，大家能够：学习到设定目标（G）的整体思路，帮助自己或者他人设定既能鼓舞人心又有可执行性的总体目标。\u003c/p>\u003cp>现在请各位小伙伴用2分钟的时间进行阅读，完成后麻烦举手示意。\u003c/p>\u003cp>好，请开始。 \u003c/p>\u003cp>【片段一】\u003c/p>\u003cp>\u003cstrong>目标设定\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一次教练对话的目标\u003c/strong>\u003c/p>\u003cp>我们在开始一场教练对话之时,一定会首先设定一个目标。如果客户选择了一个教练课,当然需要他来定义自己希望从中得到什么。即使是应教练或是经理的要求来\u003cstrong>解决一个他的具体问题\u003c/strong>,客户仍可以被问到他是否还想从中得到什么。 \u003c/p>\u003cp>比如: 你希望从此次教练中获得什么？我们这次有半个小时进行教练,你希望进展到哪里？这一次教练可能带给你最大的帮助是什么？\u003c/p>\u003cp>这样通常会引发如下的回答：\u003c/p>\u003cp>*我可以获得个人发展的计划\u003c/p>\u003cp>*清楚地知道下个行动步骤，并做出承诺\u003c/p>\u003cp>* 一个关乎于往何方的决定\u003c/p>\u003cp>* 理解最关键的问题是什么\u003c/p>\u003cp>* 一个达成一致的某个项目预算\u003c/p>\u003cp>\u003cstrong>问题的目标\u003c/strong>\u003c/p>\u003cp>现在我们要面对目标及目标相关的问题，这里我们需要区分最终目标和绩效目标。\u003c/p>\u003cp>\u003cstrong>最终目标\u003c/strong>。最终的目标，如成为市场的领跑者，被任命为市场总监，搞定一个重要大客户，赢得金牌——它们很少全然在你自己的控制中。你不可能知道或者掌握你的竞争对手的行为。\u003c/p>\u003cp>\u003cstrong>绩效目标\u003c/strong>。确定一个你有信心的绩效标准会让你有很大的机会实现你最终的目标。它基本在你的控制中，并且通常能够提供一个衡量进展的方法。绩效目标的例子可能是“95%的产品一次通过质量检查标准”，“我们下个月要卖出100套工具”，或是“9月底前，在4分10秒内跑完1600米”。重要的是，相较一个最终目标而言，让自己对一个有把握的绩效目标做出承诺和承担责任感要容易得多。一个最终目标应该能够被一个绩效目标所支持。最终目标可能带来了鼓舞，但绩效目标定义了具体内容。\u003c/p>","explains":"\u003cp>好的，我看见大部分小伙伴们已经看完原文片段了。\u003c/p>\u003cp>现在，我想请大家回忆一下，你通常是怎么给自己设定目标的？\u003c/p>\u003cp>我们很多人设目标是这样的：“\u003cstrong>今年我要减肥！！！\u003c/strong>” \u003c/p>\u003cp>然后呢？\u003c/p>\u003cp>然后就没有然后了。\u003c/p>\u003cp>所以，你可能只是表了个态而已，并不能称之为设定目标。\u003c/p>\u003cp>[How]【细化行动步骤】\u003c/p>\u003cp>那么，怎么才算是设定目标呢？\u003c/p>\u003cp>看了以上原文片段后，我们可以将目标设定提炼为以下三个步骤：\u003c/p>\u003cp>\u003cstrong>第一步，界定问题：\u003c/strong>\u003c/p>\u003cp>首先，我们要界定“\u003cstrong>你希望解决一个什么具体问题\u003c/strong>”。\u003c/p>\u003cp>因为现实生活中，我们很多人讨论问题是模糊的，或者是多个问题并行的。比如，夫妻之间的拌嘴，一开始妻子可能只是看不惯老公顾着玩手机不认真听自己讲话，但妻子说着说着可能就会把一切与老公有关的人和事都浮现在脑海中，这会使她更加生气，这样的沟通效果和解决问题的能力，可想而知。所以，当出现这种情况时，我们需要先确定一个具体的问题，一次只解决一个问题。\u003c/p>\u003cp>比如刚才的减肥话题，我其实希望自己解决的是\u003cu>长期身材管理\u003c/u>问题。\u003c/p>\u003cp>\u003cstrong>第二步，明确最终目标：\u003c/strong>\u003c/p>\u003cp>接着，我们要思考“\u003cstrong>长期来看，这对你有什么价值或好处\u003c/strong>”，这是你的最终目标，它能起到鼓舞人心、激励你不断前行的作用。\u003c/p>\u003cp>比如我想要减肥，\u003cu>是因为我想像Angelababy等明星一样，生完孩子身材完全不走样\u003c/u>。这是我的最终目标。\u003c/p>\u003cp>\u003cstrong>第三步，确定绩效目标：\u003c/strong>\u003c/p>\u003cp>最后，我们要明确一下“\u003cstrong>具体而言，你希望什么时候，达到什么效果\u003c/strong>”，也就是说，你的绩效目标至少要包含\u003cstrong>实现时间\u003c/strong>、\u003cstrong>衡量是否成功的标准\u003c/strong>，使之更加具备\u003cstrong>可实现性\u003c/strong>。\u003c/p>\u003cp>所以，我还可以为自己的减肥目标添上：\u003cu>在今年年底，我希望自己能成功减重5斤，而且核心肌肉要变得更扎实\u003c/u>。这是我的绩效目标。\u003c/p>\u003cp>因此“今年我要减肥”的这句表态，经过“目标设定三步骤”的梳理后，可以完整表述如下：\u003c/p>\u003cp>为了解决自己\u003cu>长期身材管理问题\u003c/u>（界定问题），我希望\u003cu>在今年年底前\u003c/u>为自己\u003cu>减重5斤，核心肌肉变扎实\u003c/u>（绩效目标），以便早日\u003cu>实现减肥目标，像明星一样，生完孩子身材完全不走样\u003c/u>（最终目标）。\u003c/p>\u003cp>[Why]\u003c/p>\u003cp>所以，这个方法论能够让我们针对某个\u003cstrong>具体问题\u003c/strong>，制定出一个既能\u003cstrong>鼓舞人心\u003c/strong>又有\u003cstrong>可操作性\u003c/strong>的完整目标。\u003c/p>\u003cp>【案例】\u003c/p>\u003cp>关于目标设定，除了减肥问题，大家可能还会关心脱单问题。\u003c/p>\u003cp>为了帮助大家学会运用“目标设定三步骤”，现在我想邀请大家讨论一下：如何设定你的脱单目标呢？\u003c/p>\u003cp>\u003cstrong>第一步，界定问题：\u003c/strong>对于不同的人而言，“脱单”需求所指向的本质问题可能都有所不用。比如，普通人想脱单可能主要想满足自己的情感需求；而，对于赌王儿子这一类特殊人群而言，脱单可能还涉及繁衍子嗣、争夺财产等问题。\u003c/p>\u003cp>\u003cstrong>第二步，明确最终目标：\u003c/strong>即使我们同为普通人，在不同年龄层，你想找女朋友的最终目标都是不同的。比如，你在20岁找女友，可能是为了感受青春萌动；在30岁找女友，可能是冲着结婚生子；40岁，可能你是为了找到事业伴侣；50-60岁，如果你还没找到女友……那么你可能就得往夕阳红的方向去努力了。（笑）\u003c/p>\u003cp>\u003cstrong>第三步，确定绩效目标：\u003c/strong>首先，你要确定理想女友的\u003cstrong>衡量标准\u003c/strong>。要知道，如果不确定标准就直接去行动，你可能永远实现不了最终目标。\u003c/p>\u003cp>比如，你想找贤良淑德的，你经常去泡吧，能否找得到？自答：很难找到，对吧？可能请亲戚给你推荐一位公务员会更加靠谱。但如果你想找时尚潮流的，那么去泡吧，就是个挺匹配的选择了。又比如，如果你想找个热爱学习的，你可以上哪里找呢？自答：很多小伙伴们可能已经想到了，多来参加像拆书帮这类线下活动嘛，这里天然聚集了热爱学习的小伙伴。\u003c/p>\u003cp>在确定衡量标准后，接下来，我们还要为绩效目标加上\u003cstrong>达成时间\u003c/strong>——比如你可能想在自己28岁之前确定一位稳定交往的对象等等。\u003c/p>\u003cp>最后，你的脱单目标可以完整表述如下：\u003c/p>\u003cp>为了\u003cu>满足情感需求\u003c/u>（界定问题），我希望自己\u003cu>争取在28岁前\u003c/u>找到一位\u003cu>热爱学习\u003c/u>的女朋友（绩效目标），以便早日\u003cu>实现脱单目标，找到适合的结婚对象\u003c/u>（最终目标）。\u003c/p>\u003cp>【适用范围】\u003c/p>\u003cp>最后，我还想请大家留意一下，“目标设定”的每一个步骤都对应着一个相应问题，也就是说，这套方法论不仅可以作为你梳理思路的有效工具，还可以以提问的方式引导他人主动思考，帮助他人设定完整的目标。\u003c/p>","interaction":"\u003cp>\u003cstrong>（A1显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>请各位回想一下，近年来你在工作或生活中有没有遇到过为自己设立目标，但最后没有完成的情况？\u003c/p>\u003cp>比如，\u003cu>你想换个地方租房子（旧目标）\u003c/u>，过了一个季度，突然发现自己什么资料都还没开始搜集……\u003c/p>\u003cp>又比如，\u003cu>你想健身减肥（旧目标）\u003c/u>，所以在年初狠心办理了一张健身卡，半年过去了，你突然发现自己只去过一次健身房，根本坚持不下来，于是赶紧把健身卡转手卖掉……\u003c/p>\u003cp>再比如，\u003cu>你想去加勒比海度假（旧目标）\u003c/u>，谁料眨眼到了年底，你才发现自己还没有攒够钱出发……\u003c/p>\u003cp>现在请各位小伙伴两两为一组，分组讨论。\u003c/p>\u003cp>你们有没有类似情形？回忆那些你曾经因为设立的目标太模糊、太宽泛，导致目标没有完成的情况。按照时间、地点、事件来表述。\u003c/p>\u003cp>待会我会请1位小伙伴起来跟我们分享一下自己的过往经历。\u003c/p>\u003cp>讨论时间2分钟，请开始。\u003c/p>\u003cp>\u003cstrong>学员案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[90后女生寻落]\u003c/strong>的旧目标：\u003c/p>\u003cp> \u003cu>现在太瘦了，我希望自己一年后体重可以增加一些\u003c/u> 。\u003c/p>\u003cp>\u003cstrong>（A1+经验激活）\u003c/strong>\u003c/p>\u003cp>大家设想一下，我们把时间轴放回到刚分享的情景中，如果再遇到这样的情况，你会如何运用今天学习的“目标设定三步骤”呢？那请大家想好以后写在纸上交给我，时间是1分钟。\u003c/p>\u003cp>参考模板：\u003c/p>\u003cp>1、你的旧目标： 。\u003c/p>\u003cp>2、按照“目标设定三步骤”重新思考：\u003c/p>\u003cp>\u003cstrong>第一步，界定问题：\u003c/strong>\u003c/p>\u003cp>Q：你希望解决一个什么具体问题？\u003c/p>\u003cp>A：我希望解决的问题是 。\u003c/p>\u003cp>\u003cstrong>第二步，明确最终目标：\u003c/strong>\u003c/p>\u003cp>Q：长期来看，这对你有什么价值或好处？\u003c/p>\u003cp>A：这件事能够让我获得 的好处。\u003c/p>\u003cp>\u003cstrong>第三步，确定绩效目标：\u003c/strong>\u003c/p>\u003cp>Q：具体而言，你希望什么时候，达到什么效果？\u003c/p>\u003cp>A：我希望在 （何年何月），达到 的效果（衡量标准）。\u003c/p>\u003cp>3、你修改后的目标: 。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[90后女生寻落]\u003c/strong> \u003c/p>\u003cp>1、你的旧目标：\u003cu>现在太瘦了，我希望自己一年后体重可以增加一些 \u003c/u>。\u003c/p>\u003cp>2、按照“目标设定三步骤”重新思考：\u003c/p>\u003cp>\u003cstrong>第一步，界定问题：\u003c/strong>\u003c/p>\u003cp>Q：你希望解决一个什么具体问题？\u003c/p>\u003cp>A：我希望解决的问题是\u003cu> 我希望在今年年底之前为自己增重10斤 \u003c/u>。\u003c/p>\u003cp>\u003cstrong>第二步，明确最终目标：\u003c/strong>\u003c/p>\u003cp>Q：长期来看，这对你有什么价值或好处？\u003c/p>\u003cp>A：这件事能够让我获得\u003cu> 体态均匀、气色更好、身体健康 \u003c/u>的好处。\u003c/p>\u003cp>\u003cstrong>第三步，确定绩效目标：\u003c/strong>\u003c/p>\u003cp>Q：具体而言，你希望什么时候，达到什么效果？\u003c/p>\u003cp>A：我希望在 \u003cu>今年每个月 \u003c/u>（何年何月），达到 \u003cu>增重1.5斤 \u003c/u>的效果（衡量标准）。\u003c/p>\u003cp>3、你修改后的目标: \u003cu>为了让自己身体健康、气色更好、体态均匀，我希望今年每个月都能增重1.5斤，以达到在今年年底之前为自己增重10斤的目标 \u003c/u>。\u003c/p>\u003cp>\u003cstrong>拆书家反馈： \u003c/strong>\u003c/p>\u003cp>好的，谢谢这位同学，我们掌声鼓励。刚才这位同学给我们做了一个很好的示范。她想解决的问题是希望自己身体变得更健康，她要达成的最终目标是希望一年增重10斤，最后她还为自己添加了一个很细致的绩效目标，即每月要增重1.5斤等等。谢谢她的分享。\u003c/p>\u003cp>以上就是《高绩效教练》中提及到的“目标设定三步骤”。不知大家有没有发现，在运用教练技术的思维模式时，我们需要比往常更加\u003cstrong>专注\u003c/strong>，在目标设定（G）这一环节你需要更加专注地思考“你想要什么”，在接下来的拆页中你也要更加专注地思考你的现状、选择和决心问题。于是，在使用教练技术的过程中，我们\u003cstrong>提升了自己的觉察力\u003c/strong>，能够更准确地认识个人的实际情况，让自己有机会取得更高绩效。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":14050,"quote":"\u003cp>接下来，我们开始学习第二个拆页——GROW模型具体指的是什么，以及后三个环节的提问方法论。\u003c/p>\u003cp>【学习目标2】\u003c/p>\u003cp>在学习这个拆页后，大家能够：在对方的目标明确时，运用教练技术中的ROW的提问方式，帮助他人分析现状、探索可选方案和明确行动意愿。\u003c/p>\u003cp>现在请各位小伙伴用1分钟的时间阅读以下片段。完成后麻烦举手示意。好，请开始。\u003c/p>\u003cp>【片段二】\u003c/p>\u003cp>\u003cstrong>GROW模型\u003c/strong>\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四步骤\u003c/p>\u003cp>* 目标设定(goal)，本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>* 现状分析( reality)，探索当前的情况。\u003c/p>\u003cp>* 方案选择( options)，可供选择的策略或行动方案。\u003c/p>\u003cp>* 该做什么(what)，何时(when)，谁做(who)，意愿(will)。\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个段开始或结束。\u003c/p>","explains":"\u003cp>【预防异议】\u003c/p>\u003cp>以上就是教练技术的GROW模型，作者用200字就对该模型做完了概述，于是你们可能会认为，学习GROW模型是一件非常简单的事情。\u003c/p>\u003cp>我曾经也是这么认为的。可是，当我尝试在现实生活中运用这套方法论时，我才知道这有多么的艰难。\u003c/p>\u003cp>[Why]【不这么做的坏处】\u003c/p>\u003cp>\u003cstrong>[难点1：要压制“提建议”的冲动]\u003c/strong>\u003c/p>\u003cp>各位都知道，GROW模型主要运用的现实场景是，当别人跑来咨询你时，你要用它来教练他人。可是，在现实生活当中，当别人过来咨询你时，你的第一反应是什么？\u003c/p>\u003cp>我现在假设一个场景，帮助大家回忆一下哈。\u003c/p>\u003cp>我知道，今天能来参加拆书线下活动的小伙伴们平时都是比较爱看书的。现在，假如有一位刚进职场的小学妹跑来问你：“师兄（师姐），你认为工作后，我们应该如何保持良好的阅读习惯呢？”\u003c/p>\u003cp>请问：你的第一反应是什么？\u003c/p>\u003cp>[反例]\u003c/p>\u003cp>你心里可能会想：“呀，这个问题我很熟悉呀，我能作答！”然后，就拉着学妹的双手，语重心长地说：\u003c/p>\u003cp>职场人的时间是很宝贵的，如果你想保持阅读习惯……\u003c/p>\u003cp>\u003cu>\u003cstrong>你应该 \u003c/strong>先解决自己的学习动力问题；\u003c/u>\u003c/p>\u003cp>\u003cu>\u003cstrong>你应该 \u003c/strong>优先阅读适合自己的致用类书籍；\u003c/u>\u003c/p>\u003cp>\u003cu>\u003cstrong>你应该 \u003c/strong>在余闲时间不玩手机、不刷抖音、不煲热剧，把全部碎片时间用于读书……\u003c/u>\u003c/p>\u003cp>这是你的第一反应，它叫做“\u003cstrong>提建议\u003c/strong>”。\u003c/p>\u003cp>为什么我们喜欢提建议呢？因为自我感觉良好呀！\u003c/p>\u003cp>你看，学妹很认真地记下了你的建议，看起来你已经拯救了学妹，你预期学妹的世界将因此而得到改变。所以，你的自我感觉当然良好。\u003c/p>\u003cp>可是，你有没有想过，学妹真的会践行你的建议吗？\u003c/p>\u003cp>很遗憾，基本不会。\u003c/p>\u003cp>说实话，以上场景也是本人经常遇到的，我也是很乐意给学妹提建议的。\u003c/p>\u003cp>但，通常一两个月后当我再次碰到她，问她读书计划开展得怎么样时……学妹通常一脸尴尬，说因为出现了各种各样的突发状况，无奈暂缓了……\u003c/p>\u003cp>如果只有一个学妹出了突发状况不执行我的建议，那我可能真信了。可是，我发现，许多学妹都是用类似理由搪塞我的……我就开始反思：是不是当初我所提的建议对她其实毫无意义？因为她们根本没有去践行。\u003c/p>\u003cp>后来，我静心一想，觉得学妹们做得也没错。因为“提建议”是从我的视角出发，我认为什么是对的，就会硬塞给对方，所以对方觉得“不适用、不去用”是相当正常的。\u003c/p>\u003cp>于是，教练技术的基础要求是，当别人咨询你时，你要以“\u003cstrong>提问\u003c/strong>”的方式去启发对方主动思考，也就是说，你得压制住自己想“提建议”的冲动。这就涉及到你的底层思维模式的艰难转换，这也是你想运用GROW模型时会碰到的第一个难点。\u003c/p>\u003cp>\u003cstrong>[难点2：提问过程不可控]\u003c/strong>\u003c/p>\u003cp>好了，现在我假设你已经下定决心选择“提问题”的反应模式，这时你又会碰上第二个操作难点——\u003cstrong>提问过程的不可控因素\u003c/strong>实在太多了。\u003c/p>\u003cp>提问属于即时互动的过程。如果你记不起GROW模型各个环节的问句，请问你要如何发问？如果对方的回答老是切不到重点，请问你要如何启发他继续深入思考？……\u003c/p>\u003cp>所以，在实践中你会惊讶地发现，提问过程其实是一个“幺蛾子满天飞”的过程。\u003c/p>\u003cp>怎么解决？\u003c/p>\u003cp>作者想到的办法是，在书中为GROW模型的每一个环节都准备了详细的问题清单，每个清单大约有十几、二十条，乘以四，大约共80个条目。\u003c/p>\u003cp>可是，当碰到现实问题时，作为教练技术初学者的我们可能一个清单中的问题都无法回想起来。\u003c/p>\u003cp>[What]\u003c/p>\u003cp>于是，为了方便大家理解和记忆，今天我特意把GROW模型转化为一幅记忆图，帮助大家记住环节之间的逻辑关联，以及每个环节的基础问句。\u003c/p>\u003cp>各位请看，记忆图中的\u003cstrong>B点\u003c/strong>表示你未来想要到达的目的地，这代表着第一个环节\u003cstrong>设定总体目标（G）\u003c/strong>。\u003c/p>\u003cp>然后，图中\u003cstrong>A点\u003c/strong>表示你现在所处的位置，代表着第二个环节\u003cstrong>分析现状（R）\u003c/strong>。\u003c/p>\u003cp>接着，你可以启发对方思考\u003cstrong>如何从A点到达B点\u003c/strong>，触发对方思考第三个环节——\u003cstrong>探讨可选方案（O）\u003c/strong>。\u003c/p>\u003cp>最后，在你选定最优方案后，可以细化行动计划，确定某些小目标，明确第一步、第二步、第三步……自己应该做些什么。这就代表着模型中的第四个环节\u003cstrong>明确行动计划（W）\u003c/strong>。\u003c/p>\u003cp>根据上述逻辑，我为四个环节提炼出相应的基础问句，它们分别是：\u003c/p>\u003cp>第一句：\u003cstrong>你想要什么？\u003c/strong>（G环节）\u003c/p>\u003cp>第二句：\u003cstrong>你现在的情况是怎么样的？\u003c/strong> （R环节）\u003c/p>\u003cp>第三句：\u003cstrong>你能做些什么？\u003c/strong>（O环节）\u003c/p>\u003cp>第四句：\u003cstrong>你会怎么做？\u003c/strong>（W环节）\u003c/p>\u003cp>因此，通过“一张图和四个问句”，现在我们更加容易地把GROW模型印在自己的心中了。\u003c/p>\u003cp>与此同时，鉴于大部分咨询者一开始是不太习惯回答问题的，通常而言，我们不可能就以一个问题就能问到有用答案。所以，我们要懂得围绕各环节的基础问句稍作延伸，变成四组小问题，达成启发对方深度思考的效果。\u003c/p>\u003cp>[How]\u003c/p>\u003cp>对于设定目标的G环节，我们的延伸问题已经通过上一个拆页学习到了，包括界定问题、最终目标和绩效目标三个子问题。\u003c/p>\u003cp>接下来，我们着重提炼后三个环节ROW的问题集。事实上，它们的形态可以灵活多变，不过为了让大家加速入门，我将自己常用的问题集作为模板，供大家参考：\u003c/p>\u003cp>【\u003cstrong>ROW问题集\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>R环节（现状分析）\u003c/strong>\u003c/p>\u003cp>基础问句：你现在的情况是怎么样的？ \u003c/p>\u003cp>延伸问句：你目前遇到了什么困难吗？\u003c/p>\u003cp>能否描述一个与你现状相关的具体场景？\u003c/p>\u003cp>\u003cstrong>O环节（方案选择）\u003c/strong>\u003c/p>\u003cp>基础问句：你能做些什么？ \u003c/p>\u003cp>延伸问句：方案一、方案二、方案三分别有哪些？\u003c/p>\u003cp> 还有吗？（最大化可选方案）\u003c/p>\u003cp>\u003cstrong>W环节（行动计划）\u003c/strong>\u003c/p>\u003cp>基础问句：你会怎么做？\u003c/p>\u003cp>延伸问句：第一步、第二步、第三步分别是什么？\u003c/p>\u003cp> 你需要什么资源来支持，提高可行性？ \u003c/p>\u003cp>【案例】\u003c/p>\u003cp>接下来，我举自己的实战例子，以便大家理解如何运用“ROW问题集”。\u003c/p>\u003cp>[反例转正例]\u003c/p>\u003cp>前几天，又有一位学妹来问我与坚持读书相关的问题——\u003cu>在今年年初初她制定了一个读书计划，截至今年年底，她想要读完50本书\u003c/u>。但试运行了半年，现在她觉得好难坚持下去，于是跑来问我怎么办。\u003c/p>\u003cp>鉴于学妹的目标已经比较明确，所以我从分析现状等环节开始提问。\u003c/p>\u003cp>\u003cstrong>1、现状分析（R）\u003c/strong>\u003c/p>\u003cp>我：\u003cstrong>你现在的情况是怎么样的？\u003c/strong>是遇到什么困难了吗？\u003c/p>\u003cp>学妹：工作后，我总感觉自己的时间不够用。\u003c/p>\u003cp>我：\u003cstrong>能否描述一下你现在典型的一天是什么样子的呢？\u003c/strong>\u003c/p>\u003cp>学妹：因为公司离家远，我每天6:30起床，然后坐2小时地铁到单位；8:30-18:30是我的上班时间；然后我20:30回到家，一直忙家里的事，直到22:30才能上床睡觉。\u003c/p>\u003cp>（旁白：至此，对方的现状分析已经描述得比较清晰了，所以我就可以进入下一环节的提问。）\u003c/p>\u003cp>\u003cstrong>2、方案选择（O）\u003c/strong>\u003c/p>\u003cp>我：那么，在没有时间这个问题上，结合你的典型日程，你觉得\u003cstrong>你能做些什么呢？\u003c/strong>\u003c/p>\u003cp>学妹：在家22:00哄完孩子睡着后，其实我可以爬起来先看1小时书再睡觉。\u003c/p>\u003cp>我：恩，这个想法很好。\u003cstrong>还有吗？\u003c/strong>比如，你有什么时间有可能复用呢？\u003c/p>\u003cp>学妹：哦，坐地铁上下班时，路途中有接近4小时，也许我可以带本书在地铁里看书。\u003c/p>\u003cp>我：恩，很好。\u003cstrong>还有其他吗？\u003c/strong> \u003c/p>\u003cp>学妹：没有了，实在想不出来。\u003c/p>\u003cp>（旁白：在方案选择环节有个小技巧，我们可以多问一两次“还有吗”，尝试引导对方思考出更多可选方案。）\u003c/p>\u003cp>\u003cstrong>3、行动计划（W）\u003c/strong>\u003c/p>\u003cp>我：那么接下来，\u003cstrong>你会怎么做呢？第一步、第二步、第三步分别是什么？\u003c/strong>\u003c/p>\u003cp>学妹：第一步，我会把下半年想看的书一次性买下来；然后按照能挤出来的时间去执行——充分利用上下班坐地铁的时间，以及小孩睡下后的时间去阅读；试行一周后，我再看看还能如何优化和调整。\u003c/p>\u003cp>（旁白：现在，整套行动计划都是学妹自己一个人想出来的，大家认为，学妹后续去执行的概率会不会变得更大？肯定会。）\u003c/p>\u003cp>所以，与“提建议”形成鲜明对比的是，“提问题”是站在对方角度，请他主动思考适合自己的方案和计划，能够最大程度地启发对方，提高了对方的\u003cstrong>责任感\u003c/strong>，进而提高了她的后续执行力。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>不过，有小伙伴的心中可能还有疑虑，在实战过程中，作为提问者的我们如何突然想不到问题、卡壳了，会不会很尴尬、很奇怪？\u003c/p>\u003cp>其实，教练技术是要结合你的\u003cstrong>认真倾听\u003c/strong>才能起到作用，在提问过程中，只要你认真听取他人的表达，仔细观察对方，并按照他的兴趣、明示或暗示继续问下去，你就不会被卡住。\u003c/p>\u003cp>你还可以加上一个小技巧——用一张纸把对方所回答的\u003cstrong>关键字记录\u003c/strong>下来。一方面会让对方感觉到你很重视他的答案，进而更加认真思考你提出的问题；另一方面在记录的过程中，你也为自己腾出了思考下一个问题的时间。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】角色扮演\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>为了让大家更好的理解和运用刚刚讲述的方法。我们来做一个小游戏。\u003c/p>\u003cp>\u003cu>小明是小红的同桌同事，他今年报名参加了中级经济师的考试，考试时间在11月初。考试通过后，他就能加薪，而且有助未来的职业发展。可是，现在他感觉自己工作太忙了，抽不出太多时间复习，准备放弃考试。如果你是小红，你会怎么劝小明继续积极备考呢？\u003c/u>\u003c/p>\u003cp>现在，请大家两两为一组，一位扮演小明，另一位扮演小红，请你使用“ROW问题集”帮助小明分析现状、探索可选方案、明确行动意愿。请大家在组内演练体验5分钟。待会我会让两位分角色扮演的小伙伴上来给我们进行现场演绎和分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>70后福哥扮演小红，90后Cindy扮演小明。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>既然你这么想拿到中级经济师的证，那么你想怎么样达到这个目标呢？你每天的时间是怎么利用的？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>我一般九点半开始上班，下班是晚上八点，晚上到家忙完生活上的事情就睡觉了。所以感觉很难找到时间复习，这是我的现状。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>时间挤挤还是有的，你觉得自己有哪些时间还有可能利用起来？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>我想到，公司中午有2个小时的休息时间，我觉得利用午休时间抽出1小时复习，应该是可以的；还有我上班时间比较晚，如果我早起复习，时间还是有的。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>还有吗？晚上时间有利用的可能吗？ \u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>晚上应该很难，我干完所有事情会头疼，所以必须早睡。只有中午和早起时间了。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>今年的复习计划你打算什么时候开始呢？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>距离考试时间还剩五六个月，考试内容包括12个章节，平均每月要完成两个章节。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>你回去之后打算怎么做，第一步、第二步等等分别要做什么？\u003c/p>\u003cp>\u003cstrong>Cindy：\u003c/strong>第一步是把相关书籍买齐全；第二步平均每个月完成2个章节内容；第三步看完书籍遇到问题我还要请教小红，因为你比较有经验。\u003c/p>\u003cp>\u003cstrong>福哥：\u003c/strong>好的，没问题。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>（摘要点评）\u003c/p>\u003cp>感谢这两位小伙伴给我们带来的精彩演绎，让我们掌声送给他们。\u003c/p>\u003cp>刚才\u003cu>小红（福哥）\u003c/u>的提问基本遵循了“ROW问题集”的提问逻辑，每一个环节都有兼顾到。接着，\u003cu>小明（Cindy）\u003c/u>也很认真地作答。小明给自己梳理出来的现状是“她的工作时间很忙，大概晚上十点要睡觉”；在方案选择的时候，她给自己挑出两个时间段，一个是早起，另一个是中午时段用于复习，这时她的方案一和方案二；最后在讲到完善行动步骤时，她讲得特别好，她说“第一步要完善复习材料，第二步是按计划每月复习，第三步遇到不会就请教小红”等等，这是她的第一步、第二步、第三步。这证明大家对于这套方法论开始找到自己的感觉了。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用（第一步）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>为了帮助大家将今天所学习的“ROW问题集”运用到现实生活当中，现在请大家想象一下，在未来的一到两周内，你会不会遇到别人请教你的情境？\u003c/p>\u003cp>\u003cu>如果你是个健身达人，疫情过后，同事们纷纷关注自己的身体健康，都想来请教你“如何坚持每周至少去一次健身房”；\u003c/u>\u003c/p>\u003cp>\u003cu>如果你的厨艺很好，春节期间，你在朋友圈稍稍露了几手，现在你的朋友都来问你“如何训练自己的厨艺，以便抓住老公的胃”……\u003c/u>\u003c/p>\u003cp>现在，请大家先花2分钟时间设想一下这个情境，包括时间、地点和人物以及对方已设定的目标等概要信息。\u003c/p>\u003cp>参考模板：\u003c/p>\u003cp>情境：在\u003cu>_____\u003c/u>（何时），\u003cu>_____\u003c/u>（求助者姓名）可能会来找我咨询\u003c/p>\u003cp>\u003cu>_________________________\u003c/u>（哪件事情）。\u003c/p>\u003cp>TA的目标是：\u003cu>___________________________________。\u003c/u>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[从事保险行业的柯伟娜]\u003c/strong>\u003c/p>\u003cp>情境：在\u003cu>下周一早上\u003c/u>，\u003cu>我的团队成员小陈\u003c/u>可能会来找我咨询\u003cu>如何提高自己的介绍保险产品的能力。\u003c/u>\u003c/p>\u003cp>TA的目标是：\u003cu>他希望介绍保险产品后，能够取得客户信任，提高下单量。\u003c/u>\u003c/p>\u003cp>\u003cstrong>【A2】催化应用（第二步）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>接下来，请大家思考一下，你会如何运用“ROW问题集”向求助者提问，帮助他理清现状、寻找可选方案和明确行动计划。\u003c/p>\u003cp>请大家思考3分钟，之后我念一位小伙伴的思考结果。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[从事保险行业的柯伟娜]\u003c/strong>\u003c/p>\u003cp>我们之间的对话可能如下：\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>你现在跟客户介绍产品后情况是怎么样的？会遇到什么困难吗？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会诉说，客户听他介绍后仍然心存疑虑、迟迟不肯下单等现实困难。）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>那么，你认为你能做些什么呢？比如，在准备阶段你能多做些什么？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会说说自己可以优化产品跟潜在客户之间的匹配度）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>到了跟客户面谈时，你还能做些什么呢？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会谈及自己跟客户见面时增加一些沟通技巧等）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>所以，你的方案一是XXX，方案二是XXX……（此处稍微帮他总结一下，如果他想到的办法不够多，我适当增加1-2个可选方案供他参考。）\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>从这一周开始，在面见潜在客户之前，你会怎么做呢？第一步、第二步、第三步分别做些什么？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>（他可能会梳理出自己的具体行动步骤）\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>好的，我看见大部分小伙伴都已经写出了自己的未来规划。这个未来场景是否真正出现，其实不太重要。真正重要的是，我们今天在现场强迫自己参照新学的方法论为这个情景做过详细规划，这有利于我们的内化和理解。在未来，当大家遇到类似场景，我希望大家可以真正做到学以致用。谢谢。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>好了，以上就是今天我要带领大家学习的内容。现在我们来回顾一下。\u003c/p>\u003cp>今天我们学习了教练技术的GROW模型，在第一个拆页片段详细学习了第一环节G，通过“目标设定三步骤”可以帮助你或他人确定总体目标，\u003cstrong>提升自我觉察力\u003c/strong>。在第二个拆页片段里，我们着重学习了模型的后三步，通过“ROW问题集”，让大家理解了提问而不是提建议，会更有助于让对方明确自己的责任担当，\u003cstrong>拥有强烈的责任感\u003c/strong>。\u003c/p>\u003cp>在书中第49页，当作者给我们介绍了GROW模型后，他说到：“如果你能从本书中学到什么，最好是\u003cstrong>觉察力和责任感\u003c/strong>，它们远比GROW模型重要得多”。这也是我为大家精心挑选以上两个拆页的真正原因。\u003c/p>\u003cp>最后，我想邀请大家思考一下《高绩效教练》书名中的另一个关键词，什么才算得上是“\u003cstrong>高绩效\u003c/strong>”？\u003c/p>\u003cp>如果你只是按某人要求完成了某项任务，这算不算“高绩效”？我认为不算。只有当你以最高标准来要求自己，充分展现个人潜能，最终做成的事情超越了他人的预期——这才算得上是“高绩效”。\u003c/p>\u003cp>而，一个人要充分展现潜能达成高绩效，就需要他敢于承担自己的全部责任，并且拥有充分的自主选择权。所以，书中提到“\u003cstrong>你可以使一个人跑，但不能使他快跑\u003c/strong>”，除非你使用的是教练技术这套强有力的提问术。\u003c/p>\u003cp>非常感谢大家在这一个小时内的专注学习。现在，我要给大家留个小作业。刚才各位设想了未来一两周内别人有可能来请教你的情景，并写出了你的教练思路。我希望，当你真正遇到相似情境时，可以按照自己天的规划认真践行一遍。因为当你在现实场景中，真正运用过教练技术，你就能感受到这种方法论的独特魅力。\u003c/p>\u003cp>感谢大家的耐心聆听，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1596438832000,"updated_at":1597395981000,"ria":true},{"id":10009,"topic":"用积极倾听，提升沟通质量","learn_goal":"","remark":"倾听是沟通的基础和前提。\n学会积极倾听，可以让对方感受到尊重和接纳，帮助对方更好地表达，也能让我们更加准确地理解对方所表达的意思，建立关系的连接。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"余涛","city":"保定"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是余涛，我现在是拆书帮保定直隶分舵的组织长老，也是一名一级拆书家，很高兴能和大家在这里相聚。\u003c/p>\u003cp>我们直隶分舵的使命是：帮助每一个人用拆书链接知识和梦想。\u003c/p>\u003cp>我们的愿景是：发展成保定地区最具有影响力的成长型思维社群。\u003c/p>\u003cp>我们的价值观：成长践行、陪伴符能。\u003c/p>\u003cp>因为今天的活动中，有小组讨论环节，所以咱们先分一下组，就按座位临近来分组吧，每三个人一组。\u003c/p>\u003cp>我简单介绍一下今天的书籍：《高绩效教练》\u003c/p>\u003cp>这本书可以说非常有名，它是一本致用类型的书，里面的理念和观点都非常接地气。书中介绍的技巧方法，都是经过实践检验有效的，也是我们拿过来就能用在生活和工作中的好方法。\u003c/p>\u003cp>今天我选择的这个拆页，主要集中于解决沟通方面的问题。\u003c/p>\u003cp>我们常说，最好的沟通是倾听，那么我们如何做到积极倾听呢，作者给出了以下几个方法，请大家看拆页。\u003c/p>","ratings_count":4,"texts":[{"id":13841,"quote":"\u003cp>怎样才能做到积极倾听呢？\u003c/p>\u003cp>（1）\u003cstrong>调正心态\u003c/strong>：意识指导行为表现，在沟通中保持开放的心态做好积极倾听的准备，自然会在言行中让对方感受到尊重，产生亲密感和信任感，帮助对话顺利进行。具体可以这样做鼓励表达：比如停下手头的事情，做出愿意倾听的姿态，会让对方很快进入沟通状态；“三不原则”：在倾听的过程中做到“不评判”、“不批评”、“不依附”。关注潜能：排除偏见和先入为主的印象，努力让自己从交流中看到对方的优势和潜能。\u003c/p>\u003cp>（2）\u003cstrong>关注话外（非语言信息）\u003c/strong>：注意非语言信号可以更准确地捕捉到对方想要传达的信息，提高双方理解的一致性。比如可以关注对方说话的语速、语调、肢体语言、表情等非语言的信号，感知对方的本质需求。\u003c/p>\u003cp>（3）\u003cstrong>巧用话术\u003c/strong>：通过适当的语言表达让对方知道我们在用心倾听。具体的技巧有：重述：一般情况下，直接重述对方的原话就能达到这个效果。复述：如果对话过程较长，一直重述可能会让对方感觉你不够用心，此时可以用自己的语言复述对方的内容或意思。比如，对方说：“这本书很有意思。”你可以说：“哦，你看了一本很有意思的书啊。”简述：若是对方一口气说了很多，重述或复述就显得太刻意了，此时可以在不改变对方表达意思的基础上，简要叙述对方表达的意思。确认：若是对方表达的信息比较复杂，为确保理解一致，我们可以在简述对方意思的基础上，通过添加面部表情、身体姿势、外部情绪表现等方式，帮助对方觉察他自身言语背后的情绪，并与对方确认你的理解是否准确。\u003c/p>","explains":"\u003cp>在这个拆页中，作者提出一系列的方法，帮助我们在与他人建立连接时，可以通过积极倾听的技巧提升沟通质量。\u003c/p>\u003cp>倾听是沟通的基础和前提。学会积极倾听，可以让对方感受到尊重和接纳，帮助对方更好地表达，也能让我们更加准确地理解对方所表达的意思，建立关系的连接。\u003c/p>\u003cp>反之，如果不会倾听，彼此之间就容易出现沟通障碍，产生误解，影响人际关系和谐。\u003c/p>\u003cp>沟通中，我们可以分以下几步来做：\u003c/p>\u003cp>1、控制自己的情绪，保持开放包容心态，让对方感受到被尊重。\u003c/p>\u003cp>2、用不评判，不批评，不依附的心态，倾听对方诉求和心声。\u003c/p>\u003cp>3、沟通过程中，适时的重述对方的表达，同时用表情和动作辅助，表达对他的支持和肯定。\u003c/p>\u003cp>4、倾听语言的同时，也观察对方的表情和动作，尝试找到他的真正诉求，通过进一步沟通确定他的感受和想法。\u003c/p>\u003cp>这个技巧适用于工作生活中和别人沟通时，我们可以根据具体场景需要和个人习惯从中任选其一或者组合使用。\u003c/p>\u003cp>这个方法让我想起了最近发生在生活中的一件事：\u003c/p>\u003cp>疫情期间，可能是关在家里时间太长，孩子不能出去打篮球或和同学见面，所以最近说话总是容易急躁，常常说着说着就提高声调，有时候会嚷出来。\u003c/p>\u003cp>我感觉到他的情绪后，有时候我能提醒自己注意情绪，不要着急，能够询问他：怎么又急躁了？是不是焦虑啊？心情不好吗？但我这样问的效果并不好，反而引发孩子更多的不耐烦，一句“没有”就把我堵回来了。\u003c/p>\u003cp>更多的时候，我也会受到他情绪的感染，直接提高嗓门，对他进行指责和批评，当时心里想的就是：我是你爸爸，我说什么你就要听，轮不着你和我耍脾气！这样的结果就是孩子陷入沉默，不在与我沟通。\u003c/p>\u003cp>常常是这样发完怒之后，我就陷入自责。相信在座的家长，一定都会有和我类似的经历。\u003c/p>\u003cp>最近学习了这个拆页，我也会反思自己：我能控制自己的情绪吗？我的表现让孩子感觉到尊重了吗？我应该让自己情绪平复，然后关注孩子的表达。同时要求自己，不能用成年人标准和经验，去衡量孩子的观点和判断，其实这一点是我们最难做到的，是吧？\u003c/p>\u003cp>后来，再有类似情况，我不再反驳孩子的话，而是试着重复他说的话，很神奇，当我重复的时候，他的情绪也会慢慢的平复，我想，这是因为他感受到了被尊重，被理解。\u003c/p>","interaction":"\u003cp>[A1]激活经验提问设计：沟通是我们每天都在做的事情，家庭中、工作中我们常常会在沟通中产生问题，引发彼此的情绪，甚至引发争执。\u003c/p>\u003cp>那么，这个环节，请大家回忆一下近期是否有这些让你感觉不愉快的沟通经历，然后在你的小组当中，分享给大家。大家要记得讲故事的几个要素，时间地点人物都要有。小组讨论时间在3分钟。\u003c/p>\u003cp>小组分享后，我会请一位朋友现场给大家做一下分享。\u003c/p>\u003cp>张敏的分享：\u003c/p>\u003cp>昨天晚上为了写作业，孩子和我发生了争吵，他说：妈妈，我这个作业不会的，数学题我不会。当下我就有些情绪失控，我就质问他：你不会啊，你下午干嘛去了，就知道吃东西，你现想起来找我啦！？\u003c/p>\u003cp>现在反思自己，我应该不批评不评判，应该倾听他的诉求，小孩不会写作业了，我应该想想可以给他提供什么一些帮助呀，而不能急于批评和指责。\u003c/p>\u003cp>我可以说：你不会啊，这样咱们俩一块去读读题看一看，回放一下老师昨天的一个视频，我觉得这样沟通的话效果比较好。\u003c/p>\u003cp>另外我可以关注他的一个表情啊，语言呀，然后重塑他的一个自信心，而不是去评判他。\u003c/p>\u003cp>[A2]催化应用提问设计：好，大家刚才的分享都非常精彩，看来很多人都被沟通中的问题困扰。\u003c/p>\u003cp>如何解决这些问题呢？我们要结合今天的方法，把需要改进的地方和改进的方法写下来，这是我们学习的最终目的：学以致用。我们要用这个便签，提醒自己做出改变。\u003c/p>\u003cp>好的，大家开始写自己的便签吧，这里留给大家2分钟时间。\u003c/p>\u003cp>ivy：好的，我来分享一下我最近的和老公的一段生活经历。我们之间有时候会为了家务活儿谁干产生分歧，说白了还是大家都忙了一天工作，到了家都懒得动。有时候说着说着就吵起来了。\u003c/p>\u003cp>结合今天的学习，我想从以下几个方面进行改进。\u003c/p>\u003cp>1、我要主动意识到自己的情绪，当感觉自己要生气了，要提醒自己控制好情绪，要在态度和语气上尊长老公。\u003c/p>\u003cp>2、要学会倾听，而只是倾诉，真正感受老公的情绪和诉求。\u003c/p>\u003cp>3、用适当的回应引导老公表达情感，不打断也不争辩。\u003c/p>\u003cp>4、沟通中，观察他的表情和动作，体会他的感受，设身处地的为他着想。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1593224136000,"updated_at":1614671020000,"ria":true},{"id":9269,"topic":"教练的框架","learn_goal":"通过学习教练四问法，有效引导对方思索，直到找到解决问题的答案","remark":"一本提升团队绩效和领导力水平，激活组织的宝典！世界上最常用的教练模型——GROW模型的联合创始人惠特默爵士作品的全新版本。你的收获，会是你投入的800%。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"阅良","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好。我叫阅良，目前从事管理工作。我用三个标签来介绍一下我自己：学习者、奶爸、管理动力探索者。现在进行一个分组，今天共5位学习者，分为两组，左侧的2人一组，右侧的3人一组。今天我给大家带来的图书是《高绩效教练》，作者是英国的约翰•惠特默爵士，这是一本教练与领导领域的经典之作，已被译为30多种语言，畅销120个国家。书中最核心部分就是教练框架。当别人向我们寻求建议时，通过教练四问法，可以有效引导对方思索，从而找到答案。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":13043,"quote":"\u003cp>下面我们正式进入到拆书环节，请大家用2分钟时间，阅读一下拆页，读完举手示意一下我。\u003c/p>\u003cp>\u003cstrong>教练的框架\u003c/strong>\u003c/p>\u003cp>无论是在一个正式的教练会谈还是在一个非正式的教练对话中，我建议的提问顺序都遵循以下四个阶段。\u003c/p>\u003cp>● 目标设定（Goal），包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003c/p>\u003cp>● 现状分析（Reality），探索当前的状况。\u003c/p>\u003cp>● 方案选择（Options），可供选择的策略或行动方案。\u003c/p>\u003cp>● 该做什么（What），何时（When），谁做（Who）以及这样做的意愿（Will）。\u003c/p>\u003cp>这个顺序可以方便地形成助记符GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”：目标，现状，选择，意愿。请参见图9中每个阶段的关键问题列表。\u003c/p>\u003cp>这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。GROW模型如此有效的一个因素就是这个框架是灵活的。\u003c/p>","explains":"\u003cp>刚才大家已经阅读完了拆页，相信对内容有了一些理解。下面我来谈谈个人看法。\u003c/p>\u003cp>在我们的工作与生活中，常常会遇到别人向你寻求建议的时候，我们往往习惯于凭经验直接告诉对方建议，有意思的是，大多数建议都是不可行的；或者对方内心本有答案，只是向你寻求肯定；更有甚者会遭到对方抵触，认为你不了解具体情况。教练模型可以很好地解决这个问题。那么什么是教练模型呢？就是通过有效提问而不是直接给建议的方式，迫使对方思考，明确目标，寻找方案的过程。一般来说，教练模型需要遵循四个步骤：\u003c/p>\u003cp>1、问目标。大多数人迷失的主要原因就是目标不清晰，不清楚自己真正想要什么。通过提问，可以明确目标。在这一步骤，你可以问：你的目标是什么？这个目标是你想要的吗?\u003c/p>\u003cp>2、问现状。在设定目标后，我们需要明确自己现在的情况是什么样？通过提问，可以客观了解我们的现状。\u003c/p>\u003cp>3、问方案。面对目标与现状之间的差距，我们有哪些方案可以选择？\u003c/p>\u003cp>4、问行动。方案确定后，我们从何时何地开始？具体如何实施？ \u003c/p>\u003cp>通过以上四问法，可以迫使对方深入思考，从而自己找到答案，但步骤不是一成不变的，可以根据情况予以调整。教练模型不仅适用于工作场景，如绩效沟通；还适用于生活中朋友、家人面临困境需要帮助的情形，但它不适合闲聊或者有明显答案等情形。我在这里分享一个例子。今年上半年，我参加了秀丽老师的《时间管理》拆书课，当时她要求现场制订个人终极目标、2019年目标。\u003c/p>\u003cp>秀丽老师问我：你2019年目标是什么？（\u003cstrong>问目标\u003c/strong>）\u003c/p>\u003cp>我说：学习英语。\u003c/p>\u003cp>她又问：你英语想达到什么水平？目前你哪方面存在问题？（\u003cstrong>问现状\u003c/strong>）\u003c/p>\u003cp>我说：主要是口语方面吧。目前只是过了四六级，仍是哑巴英语。\u003c/p>\u003cp>她又问：目前你有什么方法可以到达交流的口语水平呢？（\u003cstrong>问方案\u003c/strong>）\u003c/p>\u003cp>我说：还是要多说。一是参加一个培训班，掌握方法；二是找一两个志同道合的语伴，平时微信上、QQ上用英语聊天。\u003c/p>\u003cp>她又问：那你什么时候开始参加培训班？语伴什么时候找，怎么找呢?（\u003cstrong>问行动\u003c/strong>）\u003c/p>\u003cp>我说：目前还没想好，要先去了解一下，咨询一下。\u003c/p>\u003cp>在学习英语这个问题上，我之前认为就是每天坚持，希望有一天能够突破。秀丽老师虽没有直接给我建议，但通过教练对话，让我不断反思，使我重新找到目标与行动方案。\u003c/p>","interaction":"\u003cp>A1:激活学习者经验：\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>&nbsp;&nbsp; 这样的情形在日常工作生活中还很多，比如闺蜜不知道在家专职带娃还是继续工作；家里亲戚考大学不知道选什么专业；朋友不知道是继续上班还是创业等寻求建议。请大家想一想，自己过去有没有经历过类似的经历或情景，请在组内分享，时间为2分钟，结束后，我们请一位小伙伴来分享。大家清楚吗？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者阿江分享:\u003c/p>\u003cp>在我以前做金融工作的时候，有个朋友有钱，已买了一些股票与基金，在资产配置上比较迷茫来寻求我的建议。我当时问了一些问题：\u003c/p>\u003cp>你想做什么？你有什么目标？（问目标）\u003c/p>\u003cp>你有没专业学过投资？有参加什么资产配置的培训吗？你目前配置的都是高风险的，为什么不把配置降成低风险?（问现状）\u003c/p>\u003cp>目前你投资水平较低，如何做这么高风险配置？（问方案）\u003c/p>\u003cp>通过这些问题，朋友也在反思：我没有那个专业水平，但实行了高风险的配置，只是一味听了理财经理的话。最后，朋友理清了思路，重新考虑低风险资产配置规划。\u003c/p>\u003cp>A2:催化学习者应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>谢谢阿江的分享。刚才阿江分享了一个相对成功的经历。那么未来我们可能会遇到很多这样的情形，如果发生，你如何应用这个方法呢？请大家在笔记区写一下相应场景及知识应用。注意应用场景要包括背景、达成目标截止时间、期待达成结果以及行动步骤等。请问大家清楚吗？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者阿江分享规划运用：\u003c/p>\u003cp>【目标】我现在的客户想投资智能美容院的项目，需要购置仪器寻求建议。下周，我将用教练四问，与客户沟通整店的情况，争取达成合作。\u003c/p>\u003cp>【行动】我会从四个方面进行提问：\u003c/p>\u003cp>1、问目标。你是投资一家店还是连锁店，是采取加盟形式还是开旗舰店?你的目标是什么?\u003c/p>\u003cp>2、问现状。你对投资项目有何经验？有没有亲戚朋友做过这个项目？资金情况如何?\u003c/p>\u003cp>3、问方案。你怎么做？谁跟你做？有没有成功的经验？\u003c/p>\u003cp>4、问行动。你准备什么时候加盟?什么时候购买仪器？\u003c/p>\u003cp>通过教练四问法，我可以充分了解客户项目的情况，从而让客户明确自己具体的仪器需求与目标，有利于我们销售。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1573708953000,"updated_at":1593756934000,"ria":true},{"id":9074,"topic":"Grow模型~","learn_goal":"学会运用Grow模型进行谈话，激发他人内在动力和潜能","remark":"胡萝卜加大棒的驱动模式早已被社会科学研究证明已过时，Grow模型应用一种全新的对话结构，驱动对方内在思考，激发潜能，真正实现由内而外的改变和成长。该书作者是（英）约翰.惠特默","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"田蕾","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;\u003cstrong>开场及图书介绍（1分钟）\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;大家好，我是今天的拆书家田蕾。我是一名HR、也是一位1岁男宝妈妈、更是一位终身学习爱好者。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我今天拆解的片段是出自《高绩效教练》这本书，作者是英国的约翰•惠特默，他是世界上最常用的教练模型——GROW模型的联合创始人。\r\n本书以GROW模型为逻辑，引用职场及生活中的例子，清晰阐述了教练的理念和技巧。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;Grow模型可以运用于领导与下属，教师与学生，家长与孩子，以及团队伙伴、朋友等各种关系之中。&nbsp;\u003c/p>\u003cp>好，正式开始之前，我们先确定下分组（根据现场学员人数进行划分）&nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12822,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页&nbsp;\u003c/strong>\u003c/p>\u003cp>好，现在请大家在1分钟内阅读完我现在发给你们的拆页，读完后向我举手示意，这样我们正式开始拆书环节。\u003cbr>\u003c/p>\u003cp>\u003cstrong>出自《高绩效教练》（约翰.惠默特著）（英）P85至P86页。\u003c/strong>\u003c/p>\u003cp>教练的框架\u003c/p>\u003cp>&nbsp; &nbsp; 无论是在一个正式的教练会 谈还是在一个非正式的教练对话中，我建议的\u003c/p>\u003cp>提问顺序都遵循以下四个阶段。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;1、目标设定 (Goal)，包含本次教练对话的目标，以及设定教练的短期目标和长期目标。\u003c/p>\u003cp>&nbsp; &nbsp; 2、现状分析 (Reality)，探索当前的状况。\u003c/p>\u003cp>&nbsp; &nbsp; 3、 方案选择 (Options)，可供选择的策略或行动方案。\u003c/p>\u003cp>&nbsp; &nbsp; 4、 该做什么 (What)，何时(When)，谁做(Who) 以及这样做的意愿(Wil)。\u003c/p>\u003cp>&nbsp; &nbsp;这个顺序可以方便地形成助记符 GROW，我会不断地提到它。因为选择和自我激励对成功至关重要，所以我喜欢强调在最后阶段中的意愿因素，因为在这一阶段意图转化为行动，我将其称之为“转化”: 目标，现状，选择，意愿。请参见图 9 中每个阶段的关键问题列表。\u003c/p>\u003cp>&nbsp; &nbsp;这一顺序的假设是，四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，通常情况下，教练会被用于推进之前已经讨论过或已经开始讨论的任务或流程。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>\u003cp>Grow模型如此有效的一个因素就是这个框架是灵活的。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>Goal\u003c/p>\u003cp>目标设定\u003c/p>\u003cp>你想要什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>Reality\u003c/p>\u003cp>现状分析\u003c/p>\u003cp>你现在在哪儿？\u003c/p>\u003c/td>\u003ctd>\u003cp>Options\u003c/p>\u003cp>方案选择\u003c/p>\u003cp>你能做什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>Will\u003c/p>\u003cp>行动意愿\u003c/p>\u003cp>你将要做什么？\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 图9&nbsp; GRow模型\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>（3分钟）\u003c/p>\u003cp>好的，接下来我将片段进行简单的讲解。\u003c/p>\u003cp>在工作或生活中，我们扮演着各种身份，但无论哪种身份，有时候都需要我们发挥类似教练的角色，去帮助对方完成任务或解决难题。\u003c/p>\u003cp>往往我们会有两种方式：\u003c/p>\u003cp>第一种方式：直接给予对方答案，告诉对方：“如果我是你，我会这样做”，“你就按我的想法来做”等等。\u003c/p>\u003cp>第二种方式：通过有效的倾听和提问，让对方自己“生出”属于自己的答案。我究竟想要什么？我现在在哪个阶段？我有哪些选择？我具体将如何做？\u003c/p>\u003cp>显然，第一种方式是将我们自己的想法强加于对方，这是一种不负责任的行为。第二种方式是驱动对方内在思考和对话，有助于对方由内而外的成长，我们称之为“教练方式”。那第二种方式到底如何实施呢？本书的作者提出了以下的四个步骤：\u003c/p>\u003cp>一是目标设定（Goal），要帮助对方厘清目标，或设定出一个能激励对方的目标。\u003c/p>\u003cp>二是现状分析(Reality)，帮助对方澄清目前的现状是什么样的？这个过程要保持客观。\u003c/p>\u003cp>三是你有什么选择？(Options)充分发挥创造性，创造和罗列出尽可能多的可供选择的方案。\u003c/p>\u003cp>四是你将会做什么？(Will)，什么时候开始，怎样做等，进一步将行动具象化。这里要重视对方的意愿。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>（6分钟）\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;\u003c/strong>为了让大家更好的理解，我举个自己亲身经历过的案例：\u003c/p>\u003cp>2017年7月初，我提前帮我的下属小王制订了他个人的月度绩效计划，大约过了10天左右，我与小王进行了如下对话：\u003c/p>\u003cp>我：小王，这个月“制度修订”的任务怎么还没启动？\u003c/p>\u003cp>小王：我认为这个月做制度修订并不合适。\u003c/p>\u003cp>我：这是任务，我希望你能尊重我的想法。\u003c/p>\u003cp>小王：我不知道怎么做？\u003c/p>\u003cp>我：我现在告诉你怎么做，你按我说的来做。\u003c/p>\u003cp>我说完后，小王没说话，我当作是默认了。\u003c/p>\u003cp>到了月底绩效考核时，我发现小王还是没有启动这项工作。我很气愤的给小王的绩效评了一个“差”，小王也很不高兴。\u003c/p>\u003cp>事后我想，如果我按照“Grow”操作步骤，与小王共同设定一个能激励他的绩效目标，帮他客观的分析现状及完成目标可能遇到的障碍，与他共同探讨所有可行的解决方案，最后由他自己选择解决方案及行动计划，那么最后可能小王不仅完成了任务，也增长了能力和自信。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>好了，希望以上的案例也能引发各位小伙伴关联出一些过往的经历，现在我想请各位伙伴回顾下：\u003c/p>\u003cp>您有没有在职场中或生活中遇到类似的情景呢？比如，您做为一名主管，与下属制订绩效目标或绩效面谈的情景是怎么样的？或者，您做为一名同事或朋友，当小伙伴向您抱怨完不成任务时的情景是怎么样的？或者，您做为一名家长，在暑假制定孩子的暑假学习计划的情景是怎么样的？等等\u003c/p>\u003cp>请大家先思考一下类似的情形，并在小组内进行分享，记住，要把当时事情的时间、地点、人物、起因、经过、结果都要说清楚哦，时间2分钟，现在开始！\u003c/p>\u003cp>好，时间到，现在，我想请一位伙伴来分享一下他的经历，有哪位小伙伴愿意用1分钟的时间分享一下 ？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间：\u003c/strong>7月\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>家里\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>妈妈（学习者本人）、女儿\u003c/p>\u003cp>\u003cstrong>起因：\u003c/strong>女儿制定了一份暑期计划\u003c/p>\u003cp>\u003cstrong>经过：\u003c/strong>妈妈看了之后，觉得这份暑期计划特别不实用，提出了一大堆建议\u003c/p>\u003cp>\u003cstrong>结果：\u003c/strong>女儿很生气，直接放弃了计划。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp;未来，为了促进各位伙伴更好的应用这个模型，接下来请大家用一分钟的时间在纸上写下您打算运用这个“Grow”模型的计划。\u003c/p>\u003cp>比如，您在工作或生活中，就某个事情，您打算运用这个工具来帮助对方达成目标或解决难题等等。强调一下，您的计划里，一定要有明确的期限，具体的做法，及可衡量或可观测的预期结果。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;学习者案例记录：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; \u003cstrong>时间：\u003c/strong>开学9月份\u003c/p>\u003cp>\u003cstrong>地点：\u003c/strong>家里\u003c/p>\u003cp>\u003cstrong>人物：\u003c/strong>妈妈（学习者本人）、女儿\u003c/p>\u003cp>\u003cstrong>事件：\u003c/strong>女儿制定新学期学习化学的计划\u003c/p>\u003cp>\u003cstrong>具体做法：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 目标设定环节：与女儿共同制定化学元调考试达到45分的目标（满分50分）\u003c/p>\u003cp>&nbsp; &nbsp; 现状分析环节：化学是新学期新增的科目，目前化学还没开始学，但假期已经上了18节的辅导课，女儿自己对化学比较有兴趣\u003c/p>\u003cp>&nbsp; &nbsp; 你有什么选择；经与女儿沟通，有以下三种选择：上面授课；在家上网课；每天在家巩固练习\u003c/p>\u003cp>&nbsp; &nbsp; 你将会做什么：经与女儿共同商量，最后女儿选择了“每天在家巩固练习”\u003c/p>\u003cp>&nbsp; &nbsp; \u003cstrong>可衡量或可观测的预期结果：\u003c/strong>达成目标\u003c/p>\u003cp>感谢大家今天的参与，今天的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1571276942000,"updated_at":1571285701000,"ria":true},{"id":8466,"topic":"高绩效教练","learn_goal":"了解GROW模型","remark":"你知道吗？\r\n真正的对手不是比赛中的对手，而是自己头脑中的对手！\r\n  \r\n当你的员工跑来问你“我该怎么办”的时候，你会如何指导他？\r\n当你的妻子每天念叨“我到底要继续工作还是生孩子”，你会怎么指引她？\r\n当你的孩子面临升学压力，问你“我是不是该放弃？”时，你该怎么教他坚持？\r\n\r\n你是不是也尝试过提供很多建议，甚至把实践步骤都一一教给他们，然而最终的效果并不理想，甚至像是这场沟通从未有过一样？\r\n\r\n究竟该如何走出这种指示困境？\r\n这个时候我们就要学习一种新的管理方法——“高绩效教练”法则。这个法则，是滑雪教练教出网球高手的诀窍，也是你管理工作和生活问题的起点。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"海适涛哥","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"自我介绍\r\nhello，大家好，我叫先涛，欢迎大家来到这次的线下拆书现场。\r\n首先，我目前是在樊登读书工作，因为工作的原因，就在3月份接触到了拆书法，进而就开始了自己拆书学习之路。那么什么是拆书呢\r\n什么是拆书？\r\n拆书是一种学习方法论，适用于以提升能力，解决问题为目标的成年人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验，规划具体的运用。拆书法有两种，一种是用于个人日常学习的，让人读一本书就能达到培训的效果，叫便签法；一种是用于组织学习的交RIA拆抒法，通过拆书家对书中内容的引导达到拆为己用的效果。\r\n什么是拆书帮\r\n拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵，拆书帮分舵是一个公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":12119,"quote":"\u003cp>音频链接:https://pan.baidu.com/s/1KDDU0-9a65vkSnLVJS2kXg&nbsp;提取码:i82q\u003c/p>\u003cp>GROW模型\u003cbr>因此，我建议提问的顺序遵照以下四步骤：\u003cbr>1，目标设定（goal），本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>2，现状分析（ reality），探索当前的情况。\u003c/p>\u003cp>3，方案选择（ options），可供选择的策略或行动方案。\u003c/p>\u003cp>4，该做什么（what），何时（when），谁做（who），意愿（wil）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然面，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>","explains":"\u003cp>【What】\u003cbr>本书强调了一个观点就是，放弃指导比学习教练更难，实际上我们在面对别人的询问的时候，的确会第一时间告诉别人可以怎么做，但这样的结果就是别人会觉得你站着说话不腰疼，因此在进行教练式对话的时候需要用到GROW模型。\u003cbr>【How】\u003cbr>1，目标设定，作为教练需要在谈话的过程中帮助被辅导者理清自己的目标以及想要在辅导的过程中获得什么，而不能是单纯的跟你抱怨，让你给到处理建议\u003cbr>2，现状分析，让被辅导者剖析自己所处的现状以及自己是否有做过相关努力，为什么没有取得好效果的原因是什么等等\u003cbr>3，方案选择：在知道现状和目标之后，就要引导被辅导者能通过哪些方案可以实现目标。或者有没有更多的方案可以选择。\u003c/p>\u003cp>4，具体行动：选择最优方案后该如何做呢，何时，何地，频率如何，需要什么支持，或者哪些因素会阻止我们实践\u003c/p>","interaction":"\u003cp>前段时间有个书友，看到了我写的文章，觉得我对基层管理有一定的心得，就跟我请教起了管理问题，书友目前的现状是刚刚升为主管，对于团队管理比较困惑，正好我是从这个时期过来的，就给他讲了很多自己的经验。\u003c/p>\u003cp>比如书友说很迷茫不知道如何下手，我就直接建议她多看书并给她推荐了两本书《一分钟经理人》《十人以下团队管理手册》；当书友问道团队不服从管理的时候该怎么办，我就按照自己的经验建议她“员工要么认可你的能力，要么认可你的品行，既然你的能力还没有让别人认可，那就以服务行领导为主好了”。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 但其实效果并不是很好，仔细想想就是因为自己没有遵循GROW原则，比如说，对方可能就是在跟我哭诉，或者并不清楚想要从我这里得到什么实际的操作指南，当然对于她的现状，我也没有进行引导。最后稀里糊涂的听了我的建议，回去尝试后发现不是那么回事，最后我的建议就变得无效了。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>便签\u003c/strong>\u003cstrong>【1分钟】\u003c/strong>\u003cstrong>辅导一位失恋朋友\u003c/strong>\u003c/p>\u003cp>有个朋友最近被公司辞退了，然后有面临失恋，经常在群里哭诉，我当然知道直接安慰实际上并不能起到什么作用。所以我想如果通过GROW模型进行引导，会不会有更好的想过呢。\u003c/p>\u003cp>1，沟通前先通过一些问题让他明确，沟通的目的是什么，比如我可以直接问题，你想通过跟我沟通达到什么实质性的效果吗，还是仅仅哭诉。\u003c/p>\u003cp>2，现状分析，通过问题询问他为什么会出现被辞退以及失恋的情况，是工作上哪里没有做好，为什么没有做好，跟恋爱相关还是其他\u003c/p>\u003cp>3，方案选择，打算怎么去做，如何处理接下来的事。找一份工作，什么类型的工作，打算在哪里找，想要继续爱情还是放弃等等\u003c/p>\u003cp>4，如何做，确定好方向后，什么时候开始行动，哪些因素让自己没办法行动，如果遇到困难，想要怎么解决等等\u003c/p>\u003cp>通过这一组问题的引导相信会比直接安慰或者给到建议要好，时间原因，没有办法细致展开，希望我的分享能够给大家带来一些启发，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1563787880000,"updated_at":1563787880000,"ria":true},{"id":7842,"topic":"提问的顺序","learn_goal":"能够应用grow模型赋能他人","remark":"今天给大家选择的拆页主题是提问的顺序模型Grow模型，是一种教会大家如何去推进他人行动的方法。选自约翰.惠特默的《高绩效教练》，是该书的教练原理里的一部分。这是一本关于教练能力修炼的书，教练是指通过各种提问的方式，不断的引发被提问者深入思考，探索自己的潜能。就像一面镜子一样带着被提问者了解自己，又像指南针一样引导提问者深入思考问题的本质。目前教练技术被应用的非常广泛，从企业经营管理到心理咨询领域都有其身影。","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"陈海红","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;各位伙伴大家好，很高兴大家今天再次相聚，参加我的f1-2的拆书。我是今天的分享者，陈海红。我是一个偏理性，非常喜欢学习的培训工作者。很高兴我们再次相聚，共同学习共同进步。接下来，我们进行一个分组，刚才我们进来已经找到来自己的位置，那我们坐一起就是缘分，那这边的组第一组，这边的组第二组。 &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>今天给大家拆的片段是选自约翰.惠特默的《高绩效教练》，这是一本关于教练能力修炼的书，教练是指通过各种提问的方式，不断的引发被提问者深入思考，探索自己的潜能。就像一面镜子一样带着被提问者了解自己，又像指南针一样引导提问者深入思考问题的本质。目前教练技术被应用的非常广泛，从企业经营管理到心理咨询领域都有其身影。而本书主要介绍了一种教练的提问模型，我们称之为GROW模型。\u003c/p>","ratings_count":2,"texts":[{"id":11366,"quote":"\u003cp>GROW模型\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四步骤：\u003c/p>\u003cp>˙目标设定（goal），本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>˙现状分析（reality），探索当前的情况。\u003c/p>\u003cp>˙方案选择（options），可供选择的策略或行动方案。\u003c/p>\u003cp>˙该做什么（what），何时（when），谁做（who），意愿（will）。\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>\u003cp>在现状分析之前就设定目标可能看起来有些奇怪。表面的逻辑正好相反，因为我们当然需要在我们设定目标之前了解现状，实际上并非如此，仅仅基于现状的目标容易倾向于负面，变成对问题的反应，被过去的表现所局限，因简单的推断而缺少创新，只能实现小小的增长而不是本应有的成就，甚至影响生产力。短期的固定目标甚至会让我们远离长期的目标。我在团队培训课程中目标设定的经验是团队不可避免地基于过去的所作所为来设定目标，而不是未来可以做什么。在许多情况下他们不能规划什么是可能的。\u003c/p>\u003cp>确认理想的长期解决方案后决定实现该理想的现实步骤，这种方式形成的目标通常更令人鼓舞、更有创意和更激励人。让我用一个例子来说明这一要点。如果我们试图通过分析现状，解决一个在一条战略要道上的交通拥堵问题，我们很可能会仅仅基于缓解现有交通流量来设定目标，如拓宽道路。这实际上可能会与更有远见的长期目标相矛盾，后者通过明确该地区在未来某时间的理想交通模式来设定，然后看实现该目标所需的阶段步骤。因此我的建议是，在大多数情况下，使用上述建议的四个步骤。\u003c/p>","explains":"\u003cp>What：大家已经读完原文，不知道大家是否有了自己关于这个grow模型的认识。我来分享一下我对片段的理解，GROW模型是1对1教练的提问模型，也是提问的顺序。\u003c/p>\u003cp>Why：帮助被提问者深入思考，激发被提问者的行动决策。避免总是被建议，总是无法抉择，无法采取行动并坚持。\u003c/p>\u003cp>How：\u003c/p>\u003cp>&nbsp;G-代表目标，教练提问时问的第一个问题你的目标是什么？\u003c/p>\u003cp>&nbsp;R-代表现状，了解一下目前处于的阶段。\u003c/p>\u003cp>&nbsp;O-代表方案选择，你有哪些选择的方案。\u003c/p>\u003cp>&nbsp;W-代表该做什么，接下来做什么，怎么做？\u003c/p>\u003cp>Where：那它适用于什么样的场景呢？适用于1对1沟通的场景，包适用于自我对话设定行动计划的场景。主要如目标为导向的沟通场景，做决策的场景，不知道选什么方向，困惑的时候，不知道怎么寻求帮助的时候。\u003c/p>\u003cp>案例：分享一个我应用的案例，前段时间，我的同事总是念叨想要减肥。但是又很难行动。于是，我就跟减肥的同事聊了聊。当时，\u003c/p>\u003cp>第一步：我就问她“你想减多少斤呢？想要花多久的时间呢”，然后她说3个月减6斤\u003c/p>\u003cp>第二步：我问她“那你现在多少斤？”她说:125斤。\u003c/p>\u003cp>第三步：我再问她”你目前知道的减肥的方法有哪些？”。她说:节食，运动跑步，晚上不吃饭。\u003c/p>\u003cp>第四步:我问“好，你有方法了。那你打算如何安排执行呢？你觉得需要谁来监督你吗？需不需要大家给你力量？”然后她说:节食，控制饮食，运动2次，晚饭5点半前吃好。你陪我一起吧，你监督我。”\u003c/p>\u003cp>这就是我的GROW模型的应用案例，全程我没有给予任何一个建议，都是她自己说的，要运动减肥，要饮食控制，一周要运动几次，哪些东西需要停止吃等等。两个月不到的时间，她告诉我瘦了6斤。\u003c/p>","interaction":"\u003cp>A1:那么根据我们刚才对片段的阅读和刚才我的理解的解读，好，那么接下来，大家来回忆一下，你们生活中是否也有这样的场景，对方左右摇摆，不知道如何选，或则有方法但是一直坚持不下去没有结果。给大家2分钟的时间，我们组内相互分享讨论一下，我们过去的相关经验。要求大家分享一个具体的场景哦。\u003c/p>\u003cp>学习都案例1.之前想要运动健身，但左右摇摆，师父带我加入一个绿健健身群。第一个月到第三个月，还挺有激情。后来，慢慢就退去了。\u003c/p>\u003cp>学习者案例2.也是运动锻炼，我设了100个520的跑步，参加1次半马，这是我的目标。现状:我两年前跑下半马，跑完了。这两年生孩子，有些断了。方法:加入到跑团，加了一些活动，还有社群，每天跑。然后我行动，1周2次运动，社群教练监督。\u003c/p>\u003cp>A2:那刚才我们每位伙伴都有分享了自己的相关经验，那我们说要学以致用，所以接下来我们一起来制定我们的行动计划，让我们在工作生活中把这个方法应用起来。首先我们要制定行动目标,要求明确、可衡量、能达到、符合实际、有时限。其次，行动步骤。所以我们开始吧，给大家2分钟的时间进行书写。\u003c/p>\u003cp>学习者案例记录1:针对刚才的健身在下周日前应用一次Grow 模型，设定健身方案，能够帮助自己坚持健身。\u003c/p>\u003cp>第一歩:我的目标是什么？我希望在3个月里，减脂，体脂率到20%。\u003c/p>\u003cp>第二歩:我现在的现状是什么？现在体脂率25,体重140.身高174.\u003c/p>\u003cp>第三步:我所能选择的方案是？健身房私教课，不吃脂肪类，吃饭糖类食物，多补充蛋白质，\u003c/p>\u003cp>第四步:选用一周3次私教课，不吃肉类，晚上不吃米饭，每天早上2个鸡蛋。请私教监督，设定训练规划。请妈妈监督晚饭，同事监督早，中饭。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1557232388000,"updated_at":1557413325000,"ria":true},{"id":7129,"topic":"正向引导","learn_goal":"学会正向引导","remark":"","level":"TF3-3","duration":62,"status":29,"type":0,"chaishujia":{"username":"苏红","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;开场：（3分钟）\r\n自我介绍：大家晚上好，我是苏红，接下来会与大家一起学习拆解《高绩效教练》中的2个片段，拆解前，我先介绍一下自己。我有3个标签：1、培训师2、跑步爱好者3、五维教练领导力认证讲师\r\n接下来我要介绍今天要拆解片段的《高绩效教练》这本书\r\n√图书介绍：\r\n【场景】：当朋友找你诉苦的时候，你从中打断说你不要那么挑，结果你误解了他的意思；\r\n当小朋友因为伙伴抢了他的玩具一直哭，你说 给他玩一会没事的，结果他还是噘着嘴，一直哭。\r\n【提问】：你遇到过类似因为不听对方说完或引导不当产生矛盾或没解决问题的情况吗？是不是每次我们都能处理好呢？\r\n【影响】：其实这些场景可能经常会在我们身边发生，如果处理不好，可能会产生矛盾，或者造成对方对你的信任感降低，以后有事也不想找你说。不听对方说话，又不会引导，很容易在职场、家庭教育等各方面造成负面影响。\r\n【解决】：《高绩效教练》这本书就提供了良好的思路，它通过深入而细致的探讨，教你运用沟通技巧，来处理对方的情绪，并激发自身潜能，从经历的事情中找到方法并且行动。今天我要跟大家分享这本书中关于如何用恰当的方式听对方陈述事情、并在需要时使用正向引导，用于今后的沟通场景中，让对方缓解情绪，并用积极正面的方式思考并有所行动的内容。 &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>√设定学习目标：\u003c/strong>首先我们先来学习一个基础技能，听对方说话，也是非常重要的一个点。所以，大家随我学习完本次的RIA拆书现场后，再遇到对方陈述事情的时候，可以运用问＋找＋总结的技巧，让对方可以充分说明事情的整体，让我们可以更好的理解对方要表达的意思，从而双方能够更顺畅地沟通。\u003c/p>","ratings_count":1,"texts":[{"id":10523,"quote":"\u003cp>P1\u003cstrong>【R:原文片段】\u003c/strong>选自《高绩效教练》，摘录自31页\u003c/p>\u003cp>二战时期，美军遇到一个危险的任务，司令官布莱德雷将手下召集起来，列队站好，说：“有哪位愿意担任这次任务的，请向前走两步……”\u003c/p>\u003cp>恰在此时，一位参谋请布莱德雷立马处理一份战报。等到他处理完，发现长长的队伍仍是一条直线！布莱德雷愤怒了，他大声说：“难道没有人愿意吗！”\u003c/p>\u003cp>有个将士说：“报告司令……”\u003c/p>\u003cp>布莱德雷当即打断他：“闭嘴，你这个懦夫！现在情况紧急，竟然没有一个人站出来！身为军人，你们的勇气呢？”布莱德雷生气地把所有的将士都训斥了一顿，现场的气氛十分紧张。\u003c/p>\u003cp>这时，先前说话的那个将士再次发声：“司令，请您听我把话说完！其实，我们刚才每个人都向前跨了两步，所以仍然是条直线！”布莱德雷听完这话，羞愧难当。\u003c/p>\u003cp>如果你没有听对方表达完，你就很难确认自己是否可以做到客观的判断，那么做到这件事不难。有两个关键点：1、表达出让对方陈述的动作；2、适时认同和总结。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>（互动）大家看完这一段原文，听对方把话说完容易吗？ （学习者：不太容易）为什么听对方把话说完很重要？（学习者：不然容易自己以为呗，按照自己的想法判断）对的，因为不听对方说完，就主观的评价，往往有可能误解对方的真实想法，比如上诉的片段中，司令官的做法，不听士兵说完，让对方产生逆反心理，容易被认为你是主观武断，并强势自我的人，有时候甚至会使你们之间产生矛盾摩擦，更严重的如打仗这种事，极有可能影响士气而打败仗。\u003c/p>\u003cp>所以说听对方说话，并不是那么容易而简单的，我们不仅首先要控制自己的嘴巴，还要适当的回应让对方有继续说下去的状态。\u003c/p>\u003cp>(How)接下来我们学习一下如何听对方把话说完:\u003c/p>\u003cp>1、问：“可以告诉我发生了什么？”或者其他的问句如发生了什么事？等\u003c/p>\u003cp>2、找：找关键词，重复对方描述或感受的关键词＋明白/理解，懂了？，如“你很生气，我明白了？”“她把杯子打碎了，我知道了？” 这样增加对方想要继续表达的意愿；\u003c/p>\u003cp>3、总结： 对方说完一段话后，我们可以说“所以你觉得....”等句式来简要总结下对方说话的内容，这样让对方知道我们理解了他的意思。\u003c/p>\u003cp>还是用之前我们原文的案例说，如果将军运用：问＋找＋总结的方式听士兵把话说完，是这样的： \u003c/p>\u003cp>当将军转过身发现依然是一排整齐的队列，他就问了一句：“刚才发生了什么？” 一位将士发声：“司令，我们刚才每个人都向前跨了两步！将军说：“每个人，我明白了！刚才大家都西欧昂前迈了两步，就是所有人都愿意执行这个危险的任务，是吗？我们战士们？”我想这样问完，我们不仅可以了解事情的真实情况，而且这个将军还很好的鼓舞了团队的士气！\u003c/p>\u003cp>【适用边界】当然什么方法都不可能是万能的，这个方法也有一定的适用范围，当我们时间充裕，想让对话进行下去，想让对方表达更多，就可以使用问＋找＋总结的方法。如果时间很紧张，或者情况紧急的时候，比如你要开会了，赶飞机，就可以暂时拒绝，再约你更适合的时间，来运用这个问找总结的方法。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2催化应用】（学习者剧本）\u003c/strong>\u003c/p>\u003cp>上面的讲解，是为了让大家更好的理解方法，接下来我们就来练习一下。请大家给自己设定一个未来可以用到听对方陈述事情的场景，比如：妈妈和你说她不开心的事情，如爸爸说饭不好吃；朋友和你说她面试失败的事情；同事和你发发工作上的牢骚领导怎么还不调走，都可以。请编一段小故事，一、两百字即可，设计出时间、地点、人物、背景、对话、结果，过程中用到问＋找＋总结的公式，听对方把事情说完，在纸上写出关键词即可。先进行分组，给大家五分钟时间，然后请伙伴来讲讲他的故事。\u003c/p>\u003cp>学习者剧本：琳琳面试失败了，找我来想说一下，时间下周末，就约在漫咖啡\u003c/p>\u003cp>我：（问）琳琳怎么了，说说是什么情况？\u003c/p>\u003cp>琳：还不就是我上周面试那个外资，到了第三面的时候，我没准备充分，哎也是怪我怪我，问了一个专业问题，我思路突然没了，所以估计是这个原因，周五反馈说我没有带团队的经验，所以面试没戏啦\u003c/p>\u003cp>我：（找）明白了，因为那个问题没有回答好，所以面试没通过是吗？\u003c/p>\u003cp>琳：嗯是啊，这个面试我还是有点期待，但是和你说完，也过了几天，感觉也是好多了，自己再多准备一下吧。\u003c/p>\u003cp>我：（总结）其实面试确实没通过，但是你这个想法很棒，价值比这件事还要重要。\u003c/p>\u003cp>琳：我也这么觉得，就是找你说说，你能听我说完，对我来说事情就过去了，我继续努力，我们赶紧吃饭吧\u003c/p>\u003cp>反馈总结：非常好哦，感谢我们的伙伴珊珊给我分享这样的案例，伙伴面试失利的事情，珊珊运用了我们的问找总结的方法，听朋友把事情说完，事情说完，朋友状态好多了，这件事情说自己已经过去了，这个很不错，结果也是达到了对方的需求。可见听对方说一件事情的能力，真的是基础而又重要。\u003c/p>\u003cp>\u003cstrong>【两个片段的关系】\u003c/strong>好的，听对方说一件事情，我们应该做到哪三个步骤？【互动：1、问；2、找；3、总结】好的，非常棒。\u003c/p>\u003cp>在有效沟通中，听对方陈述完事情就够了吗？显然在我们的练习当中或者是实际情况中，对方很多时候可能是带有负面情绪的，但是运用我们的问找总结，显然太基础了，因为我们发现对方的情绪还处于没有有效的缓解的状态，这时我们应该做的是正向引导。为什么呢？一件事情都是存在正反面的，情绪不好的时候，经常感受到看到的都是消极的一面，所以无论对于朋友、家人、同事还是孩子，当我们被选为倾诉对象的一方时，就需要给到他积极正向的引导。这也是我们今天这两个片段的主要逻辑关系，当听对方说完，他还处于负面情绪。那么如何做？这就是我下面要讲的内容。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":10524,"quote":"\u003cp>\u003cstrong>【R:原文片段】\u003c/strong>选自《高绩效教练》，摘录自68页;\u003c/p>\u003cp>当有某件事情没有满足人的需求，人就会产生了不好的感受，例如愤怒、沮丧、气馁、焦虑等等。负面情绪都会有持续性，而且持续时间更长，还容易让人产生各种负面的遐想，从而影响到人最终的行动。\u003c/p>\u003cp>正向引导的根本意图是把对方从关注过去的情绪中拉出来，激活点亮对方，让对方看到真实客观、进而选择自己想要的，是帮助对方开出一个新通道，走出情绪，面向未来的一个过程。\u003c/p>","explains":"\u003cp>\u003cstrong>片段2：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1量表自测题】（3分钟）\u003c/strong>在我们拆解之前，我们先来清晰的认识一下自己，接下来我们会运用一个自测题的方法，来进行测试：我是一个有正向引导力的人吗？注意题目所指的是一对一的倾诉场景，而不是聊八卦等。每道题目根据符合情况打1—6分，6表示非常符合，1表示很不符合。给大家1分钟时间。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>序号\u003c/p>\u003c/td>\u003ctd>\u003cp>题目\u003c/p>\u003c/td>\u003ctd>\u003cp>分数：6非常符合——1很不符合\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>对话时会让对方完整的阐述事情，我不打断\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>当对方阐述完后，我不会添加自己的观点评论\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>当对方描述自己情绪时，我会给予站在他角度的回复\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>听完对方事情及情绪后，我不会用批评的话语总结\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>对于对方所说，我可以联系到正面积极的一面\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>我会询问对方，从这件事得到的启发\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>7\u003c/p>\u003c/td>\u003ctd>\u003cp>我会继续询问对方，接下来的行动是什么\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>我的自测分：\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【A1量表解释】\u003c/strong>大家填写完之后，计算一下自己的总得分，我来做个统计33分及以上的小伙伴举一下手，17-32分的小伙伴举一下手，有16分以下的小伙伴么？\u003c/p>\u003cp>33分及以上的伙伴，你非常善于给对方积极正面的引导，也许在你的意识中就是充满了乐观正面的一面，你也很善于让对方发现新的方向和行为，有效的缓解情绪，让对方豁然开朗。；\u003c/p>\u003cp>17-32分的小伙伴，你有意识的想要给对方进行疏导情绪，但是有时候会喜欢给一些自己的看法，或者顺从对方的情绪让他进行发泄，而不一定做到正向的引导；\u003c/p>\u003cp>而16分及以下的朋友则是没有正向引导的意识，很容易不仔细听对方说完或宣泄完情绪，就直接告知自己的想法和建议，往往对方和你沟通完，情绪依然没有得到缓解，反而有些下次不想找你倾诉的想法存在。\u003c/p>\u003cp>如果我们分数不太高，那么今天来学习显然就是完善自己。针对于分数中高的伙伴们，今天可以理论联系实际，完善你的正面引导方法\u003c/p>\u003cp>\u003cstrong>√设定学习目标：\u003c/strong>刚好第二个片段可以告诉大家，那就是在跟随我学习完后，大家可以运用正向引导四步骤：了解事件、宣泄情绪、引导价值、激发行动的技巧，让对方从不好的情绪中走出来，联系到正面积极的一面，并吸取经验及总结行动，下次能够积极应对或解决。\u003c/p>\u003cp>给大家1分钟的时间迅速的浏览一下。\u003c/p>\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>：（6分钟）\u003c/p>\u003cp>【概念讲解】我今天要讲是正向引导，简单说就是，就是让对方从一件失败或负面情绪的事情中，找到积极正面的意义，并有接下来的行动计划。也就是从中吸取对的经验并行动。 \u003c/p>\u003cp>【举出例子】&nbsp;例如，朋友和我说他的领导，每天只负责转发邮件和差使他做事，他快烦死了，如果我们想要有正面的引导，那么就是会发现事情的另外一面，我锻炼了能力，自己尝试了很多没做过的事情，提升了我自己，所以我下次就接受任务，并尽力提升自己，做好这个任务。 \u003c/p>\u003cp>【类似概念讲解】首先，希望大家区分一下，正向和一般的引导，一般引导不会考虑到事情本身具有正反两面性，而是仅仅希望解决对方当下的情绪问题或者给出自己认为对的方法。正向引导却是发现事物两面性，先让对方发泄情绪后，引导对方找到正面积极的一面，让对方思考，并有具体的行动。\u003c/p>\u003cp>【类似概念例子】还是说上面朋友发牢骚的例子，我们一般会说，天啊，你们领导也太讨厌了吧，真的是，自己什么都不做，想要把你累死啊，你真是太惨了。这是正面引导吗？这不是正面引导，而是一般引导，只是为了缓解对方情绪的发泄，而没有从一个正面的方向进行引导，进而。我们再来一起分辨一下二者的相同点和不同点：\u003c/p>\u003cp>【区分相同点不同点】首先，当我们听对方说完事情，我们表达感受或者认同的时候，是否都是在让对方进行情绪释放的时候？【是的】对，正面引导和一般引导的相同点：都让对方进行了情绪的释放或者发泄；\u003c/p>\u003cp>我们再来寻找一下两个的不同点，发现领导让我做了很多工作中，可以自我提升，锻炼能力的这种积极正面的意义，是正面引导还是一般引导会有的？【正面引导】是的第一个不同点：正面引导需要挖掘到对方可成长的点，也就是发现事情的积极正面的价值，而一般引导是没有的。\u003c/p>\u003cp>既然多做工作可以让我得到提升和成长，如果下次领导安排了事情，我应该尽力做到充分准备，完成好这个事情，这种从事情得出行动建议的，属于正面引导还是一般引导？【正面引导】是的，通过事情的分析，总结出下次遇到情况的行动计划，显然是正面引导。\u003c/p>\u003cp>那么我们归纳一下，我们刚才分析的：\u003c/p>\u003cp>正向引导和一般引导的相同点：都可以让对方有情绪的释放\u003c/p>\u003cp>不同点：正面引导具有，而一般引导没有的两点：1、发现事情的正面价值，让对方挖掘到成长点；2、让对方从事情中总结下次遇到会做的行动计划。\u003c/p>\u003cp>（互动）大家是否能够分辨出两个概念了呢？（可以了）\u003c/p>\u003cp>\u003cstrong>&nbsp;(What)\u003c/strong>概括一下正向引导就是从事件中、要么从情绪中提炼，感受到收获和成长的逻辑思维能力，他可以表现为沟通中的对话引导。利用一些问题，引导对方获得成长的沟通技巧。每个人都有解决问题的能力，所以我们要做的就是正向引导。\u003c/p>\u003cp>\u003cstrong>(How)\u003c/strong>如何可以做到正向引导呢，首先听对方说是基础，然后你只要明确一下的四步骤： \u003c/p>\u003cp>1、了解事件：可以用问、找、总结的方法。对方说的过程是疗愈的过程。告诉大家，说得出来的痛一定不是痛，说不出来的痛，才是真的痛。\u003c/p>\u003cp>2、宣泄情绪：让对方把内心的情绪发泄出来，你可以问“你的心情如何”“你怎么想的”关键还要有运用同理心“如果换做我，我也会……”\u003c/p>\u003cp>3、引导价值：“我了解了，如果从这次事情中，我们可以得出什么启示吗？”“你可以学到什么吗？”\u003c/p>\u003cp>4、激发行动：”如果下次我们遇到了，我们要怎么做呢?”“接下来怎么做呢？”\u003c/p>\u003cp>请大家注意：1、2是用来吐槽的、疗愈的，真正解决问题进行引导的是3、4。\u003c/p>\u003cp>\u003cstrong>【举例说明】\u003c/strong>可能大家还没有完全明白给大家举个例子：\u003c/p>\u003cp>我的老师给我讲了一个他和他女儿之间，正向沟通的例子：\u003c/p>\u003cp>他的女儿在美国上小学，有一次在学校里拿到了足球中的最佳球员，这在华人中间是很难的，所以她非常开心，拿到奖杯回到家就把邻居的小伙伴请来开派对。有一个环节是把奖杯传递给每个小伙伴欣赏，结果其中一个小朋友不小心没有拿稳，咣的一声，奖杯在地上摔个粉碎。\u003c/p>\u003cp>女儿就一直不停的大哭，哭了2个多小时，妈妈一直劝她不要哭了，但是没有用，于是给我的老师打了电话，和他说了这个事情。\u003c/p>\u003cp>他马上视频连线女儿：\u003c/p>\u003cp>第一步：“女儿，告诉爸爸发生了什么？可以和爸爸说说吗”女儿就洋洋洒洒说了5分多钟，还是情绪很激动；\u003c/p>\u003cp>第二步：女儿你现在的心情如何？女儿说了很多词语描述，后悔、伤心、难过等\u003c/p>\u003cp>我明白你的心情，如果这是我的第一个奖杯，我肯定也和你一样难过\u003c/p>\u003cp>第三步：未来在遇到这样的事情，我们是不是可以总结什么经验呢？女儿说要小心，有些小朋友很小心，有些小朋友并不是这样的，尤其是人多的时候。\u003c/p>\u003cp>第四步：下次再遇到的话会如何处理？如果要给大家看，一定要叮嘱并且让小朋友双手拿稳，或者我拿着给大家看。\u003c/p>\u003cp>大家觉得这样用完后，小朋友是不是会用积极正面的心态去考虑问题了呢？\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>这个方法也不是万能的，进行正向引导的前提要基于双方的关系的，只有彼此有一定的感情基础，对方才愿意和你倾述，正向引导才有效，因此首先我们先要成为一位受人信任、会倾听的角色。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>可能有人会问：123点，说个话怎么这么麻烦？对，你可以简单点。当别人对你表达他的情绪的时候，你可以简单粗暴或者直接给建议，好....久而久之，当对方发现你不能帮助他缓解情绪等，以后可能不会再找你倾诉或者不会把你当做是贴心信任的对象。如果你不想出现这样的情况，还是建议大家用到正向引导的方法哦。\u003cbr>\u003c/p>","interaction":"\u003cp>【A3微行动学习】\u003c/p>\u003cp>好了，我们回顾正向引导的四个步骤，分别是？【互动：1、了解事件、2、宣泄情绪、3、引导价值、4、激发行动】我想问问大家：以上4点，大家有没有哪个知识点不太理解、或者觉得操作起来有难度的？当然也不仅限于这4点，关于反馈过程有疑问的都可以。\u003c/p>\u003cp>【互动】大家现在可以进行小组讨论\u003c/p>\u003cp>【提问式反馈与回应】我们今天的时间有限，不如开始投票，我们就对票数最高的那个进行分析好不好？\u003c/p>\u003cp>【互动】好的\u003c/p>\u003cp>【提问式反馈与回应】开始投票，觉得第一步骤的请举手；选择第二步骤的请举手；选择第三个的请举手，或者第四个步骤请举手。\u003c/p>\u003cp>【投票结果】大家投票结果：第三步引导价值问题比较大\u003c/p>\u003cp>【提问式反馈与回应】从刚刚大家的投票结果来看，觉得具体在引导价值有困难的小伙伴会多一些，一起来看看为什么大家会觉得引导价值有问题？难度在哪里呢？按照之间分组，由小组派出代表来分享下。\u003c/p>\u003cp>【学习者讨论】第一小组：觉得对方有固性思维，你和她说半天，比如事情又两面性啦，多想好的方面了，但是她意愿度不高啊；\u003c/p>\u003cp>第二小组：我感觉我们自己经验不够丰富，可能自己都不知道如何很快找到事情的正面价值，那么就很难还去引导对方；\u003c/p>\u003cp>第三小组：我不知道问什么才能，才能引导对方想到正面积极的价值，尤其是对象不同的时候，比如小孩什么的，她有可能听不懂。&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>【提问式反馈与回应】刚刚大家讲了几个原因，我把它们归纳为（几个）个原因：第一，对方意愿度不高；第二我很难找到事情正面的那面，第三针对不同对象如何问……大家认同吗？\u003c/p>\u003cp>【学习者确认】认同\u003c/p>\u003cp>【提问式反馈与回应】好的。由于我们现场时间的问题，我们只能解决一个问题，大家觉得这（几个）问题中，哪一个是现在现场大家目前最想要先解决的？其他问题我们可以私底下讨论再解决。\u003c/p>\u003cp>【伙伴确认】高老师：我觉得针对不同对象，如何问这个应该可以能快解决大部分人的困扰，并且也可以增加我们方法的操作性；\u003c/p>\u003cp>珊珊：我也想要把这个方法用在孩子身上，所以我希望解决的也是还能有更多的问题引导，那就更好了；\u003c/p>\u003cp>芙蓉：其他问题更多的应该是个人的积累或者是对方的状况，需要花时间和不可控因素较多，而这个方法是非常好而且实用的，我也同意是解决怎么问的问题。\u003c/p>\u003cp>【提问式反馈与回应】好的，那么我们是否已经达成一致了，在第三步引导价值很难，就是因为不知道如何通过不同的问题引导对方联系到正面积极的一面，大家认同吧？\u003c/p>\u003cp>【伙伴确认】认同 &nbsp;\u003c/p>\u003cp>【引导分组讨论问题本质】接下来，我们层层深入，更进一步接近问题的本质。我想问大家，到底为什么在引导价值中觉得提问很难呢？请大家继续分组讨论，然后写出关键词在大白纸上，之后派出代表来分享。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>第一组：因为方法中给到的问句通过这个事情可以总结什么经验呢？太单一了，比如孩子就听不懂，所以提问是很难的；\u003c/p>\u003cp>第二组：引导是关键嘛，所以更关键的就是问问题，现在就是觉得不知道如何问问题，才能做到引导到正面的一面去；\u003c/p>\u003cp>第三组：我们也是觉得引导对象很多，但是如何通过不同的人，提什么样的问题，才是最有效的，这才是问题比较难得地方。\u003c/p>\u003cp>【引导分组讨论问题本质】刚刚大家讨论得非常热烈，也提出了很多原因，我稍微整理一下大家刚才的发言，更多的是，针对各种情况，应该要如何问才能引导，是问题的关键，大家认同吗？\u003c/p>\u003cp>【互动：认同】刚大家说的，也都可以归为：多一些提问的方法，这样针对不同情况可以随意切换，才能引导出价值，大家认同吗？\u003c/p>\u003cp>【互动：认同】\u003c/p>\u003cp>【引导分组讨论解决方案】很好，那么接下来我们就聚焦到了：（还可以有几种提问的方法，是可以运用在引导价值这个地方的）？请大家根据这个问题，进入小组讨论，最后一起来分享\u003c/p>\u003cp>【讨论中】\u003c/p>\u003cp>第一小组：我们认为可以增加一个这样的问题：“除了这件事之外，还有什么收获吗”可以引出正面的一些价值，因为词也是正面的：收获；\u003c/p>\u003cp>第二小组：我们讨论的方法是：今天是自己没注意，那么我们可以怎么避免呢？\u003c/p>\u003cp>第三小组：我们有两个方法：第一个比较搞笑轻松一点的：“元芳你怎么看？”第二个如果是小朋友或者特殊情况，可以直接跳过这一步，到第四步行动上“从这件事我们以后可以怎么做？”\u003c/p>\u003cp>【拆书家反馈】谢谢大家的分享。大家给出的解决方案都很赞，我把刚刚大家讲的再归纳一下，引导价值中我们可以增加4个问句：1、除了这件事之外，还有什么收获吗，2、今天是自己没注意，那么我们可以怎么避免呢，3、“元芳你怎么看，4、“从这件事我们以后可以怎么做，大家是不是认同？\u003c/p>\u003cp>【互动】认同\u003c/p>\u003cp>【拆书家反馈】这次讨论就到这里了，刚刚也全靠大家整理出了一整套系统的办法，非常棒！今天我们的微行动学习就到这里了。\u003c/p>\u003cp>\u003cstrong>【A2布置作业】\u003c/strong>下面我要给小伙伴们布置一个方法实践的作业了。\u003c/p>\u003cp>【特定任务】在接下来的一周内，大家把今天学到的方法和自己的家人或好友分享一遍，当你可以教会别人使用的时候，说明你自己也已经掌握了这个方法，温馨提示，大家在讲方法的时候，同时别忘了举例子，这样有助于大家对于方法的理解。\u003c/p>\u003cp>欢迎本周分享到我们的爱好者群里，你是如何教会这个方法的，提交作业的小伙伴我会给她发红包哦。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>珊珊分享：我和我老公讲了一遍，也希望他平时可以对孩子进行正面引导。\u003c/p>\u003cp>当宝贝有不好的情绪产生的时候我们应该给他一些正面积极的引导，让他养成这样的一种思维的方式。我们可以这样，当小朋友因为一个事情没有达到自己期望的时候，可能就会有不好的情绪，那么我们可以用到正向引导的四步骤：1、了解事件，就这么问：告诉爸爸发生了什么事，总结一下，哦原来是这样，爸爸明白了。2、宣泄情绪，可以问那你现在心情怎么样？他说完，我还可以这么说，如果我之前经历了这个事情也一定非常伤心，来同理心一下。3、引导价值，就是引导他看到积极正面的一面，可以这么问：“我们从中可以找到什么经验吗？”或者“我们可以学到什么吗”。4、激发行动，就问下次如果遇到了，我们可以怎么做。要注意就是1、2是用来让他发泄情绪的，3、4是用来引导的，也是非常重要的核心。我就举例了一个我昨天对孩子做的正面引导的事情，给他听，还给他留了作业，下次有这样的情况，就让他来尝试使用这个方法解决一下。\u003c/p>\u003cp>【强有力的总结】\u003c/p>\u003cp>在今天将近一个小时的时间里，我们知道了，听对方陈述一件事也是需要技巧的，需要用到三个要素？【互动：1、问；2、找；3、总结】是的，只有我们听对方完整的说完，对方才更愿意表达自己，我们也可以了解真实的情况，从而沟通更加顺畅。如果对方处于一个负面情绪的时候怎么办呢？接下来我们学习了如何做一个正向引导者，大家还记得吗？【互动：了解事件、宣泄情绪、引导价值、激发行动】，还记得我们再引导价值这地地方总结的四个方法吗？引导价值中我们可以增加4个问句：1、除了这件事之外，还有什么收获吗，2、今天是自己没注意，那么我们可以怎么避免呢，3、“元芳你怎么看，4、“从这件事我们以后可以怎么做非常棒。\u003c/p>\u003cp>在听的基础上当有需要的时候，我们要做一个正向引导者，让对方在生活工作中保有积极正面的的思维模式。让每一个角落都有阳光照耀。\u003c/p>\u003cp>感谢大家，以上是我今天3-3的全部内容，谢谢大家的积极配合。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1548289377000,"updated_at":1548289850000,"ria":true},{"id":6820,"topic":"如何用GROW模型实现自我教练","learn_goal":"用GROW模型自我教练，真正解决你生活工作中面临的棘手问题","remark":"","level":"TF1-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"莫念","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"大家好，我是莫念。三个标签介绍下我自己：1.七年的连续创业者，2.自有版权谈判课程讲师，3.一名成长中的拆书家，很高兴今天能和大家一起拆书。","ratings_count":0,"texts":[{"id":10179,"quote":"\u003cp>&nbsp; &nbsp; &nbsp;GROW模型\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四个步骤：\u003c/p>\u003cp>1 目标设定（goal），本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>2 现状分析（reality），探索当前的情况。\u003c/p>\u003cp>3 方案选择（options），可供选择的策略或行动方案。\u003c/p>\u003cp>4 该做什么（what），何时（when），谁做（who），\u003c/p>\u003cp>&nbsp;&nbsp;意愿（will）。\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题时，通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个阶段开始或结束。\u003c/p>","explains":"\u003cp>“教练”的概念来自体育界。“真正的对手不是比赛中的对手，而是自己头脑的对手”。如果教练能帮助选手消除内心的障碍，他的学习与表现将释放出惊人的潜能。教练的第一步其实是自我教练，而GROW是非常流行的一个教练提问的模型。\u003c/p>\u003cp>&nbsp;GROW就四个步骤，是教练激发被教练者的四类依次递进的问题，分别是关于目标的问题（G），关于现状的问题（R），关于选择的问题（O），关于意愿的问题（W）。\u003c/p>\u003cp>这个模型来自于一个惊人的发现：作者发现一个滑雪教练居然可以培养出网球高手。\u003c/p>\u003cp>&nbsp;想象一个场景，一个滑雪教练正在指导一个网球运动员： &nbsp;网球运动员做完一个动作，滑雪教练因为不会所以在旁边问：“你觉得刚才那个球什么样（R现状）？”，“我感觉刚才那个动作力气大了一点。”“哪你觉得应该怎么调整下呢？（O选择）”，“我减下下力气再试下”。\u003c/p>\u003cp>因为他们并不会打网球，所以并没有任何指导和介入。相反，他们会询问选手的感觉，让选手自己体会自己的现状，然后做出调整。滑雪教练的询问帮助网球选手找到了自我的状态，并且自己去承担了改变的责任。\u003c/p>\u003cp>&nbsp;而如果是一个网球教练就很容易在旁边指导：你应该怎么样.......。虽然建议可能完全正确， 这个时候运动员很可能听起来像是职责，打球更没劲了。\u003c/p>\u003cp>当有人问你该怎么办的时候，你只要给他建议，对方的第一反应一定是找不能实现的理由和借口。然后说你不了解情况，对他不能感同身受。甚至认为你站着说话不腰疼，只会指手画脚。\u003c/p>\u003cp>我们对员工一遍遍地教训和指点，收效总是不大。因为他根本没觉得这是他自己应该要解决的问题。\u003c/p>\u003cp>再重复下运用GROW模型教练四个步骤：\u003c/p>\u003cp>1.Goal:你的目标是什么？\u003c/p>\u003cp>2.Reality:目前的状况怎样？\u003c/p>\u003cp>3.Options:你有哪些选择？\u003c/p>\u003cp>4.Will：下一步你怎么做？\u003c/p>","interaction":"\u003cp>A1:举个用GROW模型解决问题的例子。\u003c/p>\u003cp>今年2月份我大舅找到我：我的大侄子因为临近高三，家里给的压力太大，离家出走了，就不念了，干脆跑了。\u003c/p>\u003cp>我给大舅分享了GROW模型的四个步骤。趁着春节我也正好在大舅家做客，家人一块吃饭，家庭氛围比较好的情况下，我舅舅开口了：“儿子，这么多年，爸也没问过你，你的梦想是什么？（G）”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;侄子：“怎么想起问这么奇怪的问题？你是汪峰吗？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;舅：“说正经的，你只要跟爸说，全家人都支持你的梦想。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;侄子想了一会儿：“我的梦想是当电影明星”。这个目标还不是太具体，继续激发。最关键的是教练这个时候不能评判，有的父母：‘就你长这样，还当电影明星？’\u003c/p>\u003cp>哪一下子教练的气氛就全毁掉了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;舅：“哪你想当什么样的电影明星呢？”\u003c/p>\u003cp>&nbsp;&nbsp;侄子：“我想当黄晓明那样的，实力偶像派。”\u003c/p>\u003cp>舅：“那你怎样才能成为这样的一个明星呢？”\u003c/p>\u003cp>侄子：“我要是能考上北京电影学院的话，那这是准能成。”-- 好，终于，这是一个具体的目标了：“要考北京电影学院”。\u003c/p>\u003cp>&nbsp;舅：“哪现状是什么？”（R）\u003c/p>\u003cp>侄子：“现状就是我专业课问题不大，文化课要分也不是太高，就是我这英语差点。”\u003c/p>\u003cp>舅：“哪你有没有一些解决办法呢？”（O）\u003c/p>\u003cp>侄子：“也没什么办法，除非爸你给我找个漂亮的英语家教老师吧，没准我还有救？”\u003c/p>\u003cp>舅：“找了家教你确定你真的会好好学？”（W）\u003c/p>\u003cp>侄子：“我确定”\u003c/p>\u003cp>我大侄子通过他爸爸的教练提问，自己提出要找家教提高英语，这个是非常难能可贵的，因为这是他的梦想，教练最核心的就是相信人的潜能，真正激发对方。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>目标：晚上回去通过GROW提问模型给自己做自我教练，解决公司目前面临的现金流问题。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1.&nbsp;准备提问清单：\u003c/p>\u003cp>A：要完成的具体目标是什么？G\u003c/p>\u003cp>&nbsp;&nbsp;在11月之前让公司有50万的利润。\u003c/p>\u003cp>B：现状是什么？R\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;现状是有三笔应收帐共计30万拖了三个月了；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;课程销售这个月有10万的进账；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;微课的版权有5万的进账；\u003c/p>\u003cp>C: 现在的选择有哪些？O\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;找时间和客户沟通，在10月底前收齐应收欠款。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;周末集中和相关合作方见面，收集最近授课需求。\u003c/p>\u003cp>D：下一步马上做什么？W\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;拆书活动结束后，安排和一个近期有需求的客户见面吃饭。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545237322000,"updated_at":1545237322000,"ria":true},{"id":6763,"topic":"教练式提问，分析现状定目标，做计划","learn_goal":"找准目标分析现状，制定计划","remark":"","level":"TF2-4","duration":30,"status":29,"type":0,"chaishujia":{"username":"唐云霞","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\r\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，非常高兴能在这里与大家相遇。我是唐云霞，记住我的名字两个关键词，云朵，彩霞，合起来云霞 \r\n在这里，我的三个标签是：培训、写作、探索。欢迎跟我有相同便签的下来链接。\r\n晋级内容2-4会有两个片段，所以会有两个学习目标，他俩属于递进关系，今天跟完成本次RIA现场学习后可以： &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>学习目标1：在设立目标的时候，学习者通定方向，找价值，设时间，立标准四个步骤，设定出具体可衡量的目标。&nbsp; &nbsp; 学习目标2：在设立目标以后，学习者能够根据目标，用分析现状、选择方案、激发意愿三个步骤，通过教练式沟通，找到解决办法。\u003c/strong>&nbsp;\u003c/p>\u003cp>今天给大家来带这本书名字是（F）:《高绩效教练》这里讲的教练不是体育竞技中的教练，而是应用在商业中的辅导和沟通技术。教练不是专家、顾问，而重在创造学习和成长的环境，通过提问和对话培养个人洞察力、责任感和自信心。本书已更新到第四版，书中完善了教练部分的定义，更深入的揭示了它的心理学根源。书中详细介绍了教练是什么、可以解决什么问题、什么时候适合使用、如何有效使用等，还原教练的本来面目。（A）在教练领域的书籍中，本书算得上首屈一指的“扛鼎”之作，它浓缩了惠特默爵士在教练领域30余年的研究成果。与同类书相比，本书语言通俗易懂，而且使用类比的方式清晰说明教练技术的原理，并提炼出运用模型，让读者很容易理解和使用。（B）阅读这本书不会让你马上成为一名专业的教练，但它能帮助你更好的认识教练的价值和潜力。学会并应用书中的方法，能让你成为优秀的领导者。对于学校的教师和孩子的家长而言也十分有益，能培养出更优秀的学生和子女。 &nbsp; &nbsp; &nbsp; \r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10114,"quote":"\u003cp>\u003cstrong>片段1：设立教练目标\u003c/strong>\u003c/p>\u003cp>l&nbsp; 经过本次教练，你想得到什么?\u003c/p>\u003cp>l&nbsp; 想象一下未来一年，你理想的工作状态是什么?请具体描述你典型的工作日是什么样子。(这与目前工作也许无关，对此我并不加以批判)\u003c/p>\u003cp>l&nbsp; 此刻你最渴望的那种情景包括什么因素？谈谈下面每一项的重要性(可以使用1-10等级区分)\u003c/p>\u003cp>l&nbsp; 你工作的目标是什么？\u003c/p>\u003cp>l&nbsp; 你希望何日时达成这一目标?\u003c/p>\u003cp>l&nbsp; 在内心深处，你真正想从工作中到什么？\u003c/p>\u003cp>关于目标的描述\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>好的描述\u003c/p>\u003c/td>\u003ctd>\u003cp>不好的描述\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>为了提高市场占有率，在年底之前将客户忠诚度从40%提升到70%\u003c/p>\u003c/td>\u003ctd>\u003cp>“我们承诺将进一步深化并丰富和客户之间的关系\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>为了保持销售增长，在五年之内,推出三种销售额在1000万美元以上的新产。\u003c/p>\u003c/td>\u003ctd>\u003cp>未来希望强化产品创新，利用生物科技解决生物型资源的需求问题\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>（WHY）最近快到年底了，大家都有定目标，做计划的打算吧。但在制定目标的时候，经常容易出现的状况就是，会设立笼统的数字/概念甚至是方向来当成目标。比如原文讲到的，提高客户忠诚度，要搞创新，还要多读书，多学习，这都我们常见的目标。但因为缺乏文中讲到的关键点，所以定了目标也难以实现。\u003c/p>\u003cp>（WHAT）目标要怎么设立呢，文中有提到一些，找到目标的价值，设定完成时间，设立量化标准。\u003c/p>\u003cp>（HOW）在定目标的时候常用的方法是SMART原则，今天给大家介绍一个类似的方法，却是用自我提问的方式来达成，有以下4个步骤\u003c/p>\u003cp>1、 定方向，自我提问，你的目标是什么？或你想得到什么？\u003c/p>\u003cp>2、&nbsp; 找价值，自我提问，这个目标对你有什么价值？或请描述一下，对你有什么好处？（价值=动力））\u003c/p>\u003cp>3、&nbsp; 设时间，自我提问，你计划在什么时间完成？具体日期是什么时候？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 4、定标准，自我提问，达到什么标准？你怎么判断，怎么用数字量化呢？\u003c/p>\u003cp>【\u003cstrong>强调不那么做的坏处】\u003c/strong>在设立目标的过程中，一定要去问这些问题，只要你把这些问题都想清楚了。设的目标才更容易实现，如果直接定个方向，没有完成时间，没有标准，也没感受到价值。很可能就不了了之。 \u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>为了便于理解给大家举个例子，我今年给自己设定的目标是在拆书帮不断晋级。目标太宽泛，所以我现在还没过。那学了这本书中设立目标的方法以后，按照文中举例的方法来修改目标：1、定方向（我想成为3级拆书家）。2、找价值（提高自己的思维能力，完成后还可以加入拆研班与全国的优秀小伙伴交流）。3、设时间（今年12月31日前完成）。4、定标准（2-4和3-3最后两关通过总舵的评审，拿到3级拆书家的证书）。按照这个方法修改以后我的目标变成了：为了明年去到拆书帮全国的学习平台，在今年12月31日前，完成最后两关，2-4和3-3的拆书晋级。看了这个目标立马就非常清楚目标和方向，立马就开始思考什么时候报名晋级。\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>:那这个方法是不是所有设立目标的情况都适用呢？当然不是，它仅适用于一些特别重要，能带来价值的情况才使用。对于一些日常简单的场景，本身就是很容易达成的，那就不需要用这个方法。\u003c/p>","interaction":"\u003cp>\u003cstrong>（A1显像提问）\u003c/strong>，请各位回想一下，在过去的工作或生活中有没有遇到帮别人/自己设立目标有没有完成的情况呢。？比如说，年初给自己定的目标，要提高演讲能力、或者沟通能力，情绪管理能力，看多少本书等目标。大半年过去，发现没有完成。现在请各位小伙伴回想讨论，曾经因为设立目标太宽泛，导致目标没有完成的情况。待会请两个小伙伴起来跟我们分享一下自己，过去类似的失败经历，时间是2分钟。\u003c/p>\u003cp>\u003cstrong>现场小伙伴分享：\u003c/strong>\u003c/p>\u003cp>姗姗：18年开始的时候给自己设定的目标是在今年之内，过完3-3。成为三级拆书家，为蜀汉分舵再填拆书家。但是目标定的太宽了，以致于到现在都还有两个大关没过。\u003c/p>\u003cp>\u003cbr> \u003cstrong>（A1+经验激活）\u003c/strong>;大家设想一下，我们把时间轴放回到刚分享的情景中，如果再遇到这样的情况，如何运用今天学习的4个步骤设立目标呢？那请大家想好以后写在纸上交给我，时间是1分钟。\u003c/p>\u003cp>\u003cstrong>现场小伙伴便签：\u003c/strong>\u003c/p>\u003cp>王芳：我按照今天学习的方法重新梳理目标：1、定方向（学习好日语）2、找价值（我是在日资企业负责后勤工作，学好日语可以申请调到业务部门去，负责一些比较核心的工作，职位和工资都会增加）3、设日期（在2019年7月31日前完成）；4、定标准（通过日语三级考试，并拿到证书）\u003c/p>\u003cp>所以调整后我的目标是：为了自己的事业更上一层楼，在2019年7月31日前学完日语三级课程，并通过三级考试。\u003c/p>\u003cp>（小结）拆书家：好，谢谢大家，本次学习了设立目标，希望在以后的工作生活中，能通过定方向，找价值，设时间，立标准四个步骤，设定出具体可衡量的目标。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":10115,"quote":"\u003cp>\u003cstrong>片段二：GROW模型提问的顺序\u003c/strong>\u003c/p>\u003cp>到目前为止，我们已经建立了学习和绩效改进的觉察力与责任感的核心本质。枝叶图说明了这些非常简单却强大的概念的益处的多分支、多方面的本质。我们也已经了解了教练的背景，教练和管理之间的联系，公司的文化和变革。我们探索了教练的角色和态度，并且认为问题是教练沟通中的主要形式。我们现在必须决定问哪些问题，以及以什么样的顺序来提问。\u003c/p>\u003cp>正式或非正式\u003c/p>\u003cp>在此必须强调一点，教练过程可以进行得宽松和非正式，以至于客户不知道他们在被教练。对于每日向下属发出指令或是接受汇报的管理职能而言，没有比教练更好的方式了，但它并不应该被看作教练；它是管理。在这种情况下，教练变成管理的一种工具，成为管理人员的方式，在我看来是最有效的方式之一。在正式教练的一端，一个教练课程可以有条不紊地、有结构地进行，让它的目的和角色都是明确的。虽然大部分的教练是非正式的，但我们仍然要查验正式教练的细节，因为二者的流程是一样的，而正式教练的阶段可以更加明确地加以界定。\u003c/p>\u003cp>对一教练\u003c/p>\u003cp>为了简化和清晰，我们会关注一对一教练，虽然团队教练甚至自我教练练的形式完全一致。这两种会在后面的章节中详述。一对一的教练发生在同级之间，经理和下属之间，以往的老师和学生之间，教练和执行者之间，咨询师和求助者之间。一对一的教练甚至可能会被用于一名员工对其老板的向上管理，虽然这通常是隐蔽的。毕竟，没有人能以告知的方式很大程度地影响他的上司如何去做，因而向上教练有更高的成功率。\u003c/p>\u003cp>&nbsp;GROW模型\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四步骤\u003c/p>\u003cp>目标设定(goal)，本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>现状分析( reality)，探索当前的情况。\u003c/p>\u003cp>方案选择( options)，可供选择的策略或行动方案。\u003c/p>\u003cp>·该做什么(what)，何时(when)，谁做(who)，意愿(wil)l\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个段开始或结束。\u003c/p>","explains":"\u003cp>\u003cstrong>\u003cstrong>【学习目标】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>第一个片段中学习了设立目标，但目标设立以后，我们如何保证目标尽可能的达成呢？还需要根据现状列出具体的行动计划，才更有保障。那接下来通过本次分享，在设立目标以后，\u003cstrong>(学习目标)\u003c/strong>\u003cstrong>学习者能够根据目标，用分析现状、选择方案、激发意愿三个步骤，通过教练式沟通，帮助自己或他人自己找到解决办法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>在讲述片内容跟大家分享真实案例，在我的工作中之前，总有店长来问我说，销售不好怎么办呢？我都跟他们说，你要做好管理，排班满一点让员工少请假，结果，销售没上去人员还不稳定，店长就说，这不怪我，都是公司培训让我这么干的。领导说我闲得无聊净出馊主意，我冤枉啊，但也推不了责任，因为话是我说的。但我一想下次再碰到我怎么办，总不能每次都跟人说我不知道吧。直到我遇到了GROW模型这个教练技术，才明白别人找你征集意见就是在转移责任。拒做背锅侠，学习教练式对话。\u003c/p>\u003cp>在文中提到了GROW模型，GROW模型的第一步是设立目标，我们刚刚已经学过这里就不重复，接下来我们学习GROW模型的后三个步骤—如何分析现状列计划，促进目标的达成。\u003c/p>\u003cp>\u003cstrong>（What）\u003c/strong>:片段讲述了用教练式提问的方法，来帮助自己或对方，树立责任心促使对方或自己找到解决办法。（\u003cstrong>Why）:\u003c/strong>教练不同于顾问，老师，专家。他并不提供解决方案，他是通过对话来引导激发对方的潜能，让对方来解决这些问题。\u003cbr> （\u003cstrong>HOW）:\u003c/strong>那么我们怎么运用GROW模型的后三步，通过教练式沟通并帮助对方厘清现状，列出计划呢？有以下三个步骤: \u003cbr> 第一步:分析现状:你可以问对方，从现在的情况来看要完成这个目标最困难的问题是什么？哪些事情是现在难搞定的？除此以外还有什么？让你难以解决的原因是什么？让对方认清现状。\u003cbr> 第二步:选择方案:你可以问对方，有哪些办法来解决呢？还有其他办法吗？你有哪些选择？一组问题，帮对方找到更多的解决办法。\u003cbr> 第三步:激发意愿:你可以问对方，4W，WHAT你打算怎么做呢？WHEN什么时候开始呢？WHERE在什么地方/环境呢？WILL下一步行动是什么？一组问题把方案，转换成行动计划。\u003cbr> \u003cstrong>【预防异议】\u003c/strong>在这个过程很多人觉得，教练式提问，用起来很困难不愿意用。原因是很多人第二步选择方案的时候，问别人怎么办？如果对方回答，不知道怎么办。感觉这个对话，就没法继续了。但事实上他一定有资源/方法去解决这个问题，只是可能他自己都没有发现。这是就需要用不断提问的方法，去帮助他发现资源，找到方法。所以当对方回答不知道的时候，我们可以在上一步分析现状所列举出来的困难张，让他选择一个更容易解决的事情就可以了。\u003c/p>\u003cp>\u003cstrong>【正面案例】\u003c/strong>为了方便大家理解，我接着拿刚刚的案例举例，我学了GROW模型，学会教练沟通法以后再有店长来问我，生意不好怎么办的时候。我就会用模型来帮店长找到解决办法，\u003c/p>\u003cp>\u003cstrong>第一步分析现状，\u003c/strong>你觉得要想完成销售，最难的问题是什么？店长回答：衣服缺码。除了缺码以外呢？还有什么事是最让你烦心的？人员也不稳定，不稳定的原因是什么？工资太低了。\u003c/p>\u003cp>\u003cstrong>第二步选择方案，\u003c/strong>我问她你有什么办法可以解决吗？回答，我不知道怎么办，你觉得呢？这时候我回到她刚刚描述的现状里面去，让她选一个最容易控制且最有效果的问题。所以我接着问：缺码和工资太低，哪个问题更容易解决？回答：衣服缺码呀。问：那你怎么解决呢？回答：我可以找公司补货。我：如果公司也没货你还有其他办法吗？回答：把缺码的衣服收起来，主推尺码齐全的。\u003c/p>\u003cp>\u003cstrong>第三步激发意愿\u003c/strong>，问：下一步打算怎么做呢？答：先把衣服的尺码情况整理出来。问：计划什么时候统计完成呢？回答：今天下班前就整理完。\u003c/p>\u003cp>可以从案例中看到，店长从抱怨销售不好，不知道怎么办。到对话结束后，找到了解决办法做出了行动计划：今天先整理店铺的尺码情况，缺码的找公司补货，如果补不回来，就主推尺码齐全的产品。过程也符合我们GROW模型运用的原则，用提问来激发对方的潜能让店长自己找到了方法。他对他自己的行为承完整的责任。\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>:那是不是所有设立目标的情况都适用呢？当然不是，它仅适用于别人主动找到你，且你想通过提问的方式引导去激发对方潜能的时候，才使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>场景设计\u003c/strong>:为了让大家更好的理解和运用刚刚讲述的方法。我们来做一个小游戏，假设你是小明，你有个好朋友张三，他为了提高自己的学习能力，定的计划是明年1月份之前读完50本书。但定了目标以后，他自己感觉有点难，担心没时间，或者坚持不下去。所以他主动找到你寻求帮助，想让你跟他一起，制定一个读书的计划？\u003c/p>\u003cp>\u003cstrong>（角色扮演）\u003c/strong>:你决定用GROW模型后三步，通过分析现状，选择方案，激发意愿三个步骤，帮他制定一个具体的行动计划。\u003cbr> 然后你们展开了一场对话，请大家分角色扮演小明和张三，并讨论时间是5分钟。待会我会让两位分角色扮演的小伙伴上来给我吗分享，时间3分钟。\u003c/p>\u003cp>\u003cstrong>【\u003cstrong>现场角色扮演\u003c/strong>】\u003c/strong>\u003c/p>\u003cp>张三：我这两天定了个计划，截止2019年12月31日前，我要读完50本书，但是我回想了一下有点困难。你觉得有什么办法么？\u003c/p>\u003cp>小明：你为什么要给自己设定这个目标呢？\u003c/p>\u003cp>张三：我想要提升自己，想要进步啊\u003c/p>\u003cp>小明：你觉得你完不成的原因是什么呢？\u003c/p>\u003cp>张三：一是效率低，二是没时间\u003c/p>\u003cp>小明：还有其他困难吗？\u003c/p>\u003cp>张三：没有了，主要就是这两个原因\u003c/p>\u003cp>小明：那你觉得在效率低和没时间这个两个事情上，哪一个更好解决？\u003c/p>\u003cp>张三: 非要二选一的话，从我目前的状况来说，感觉在时间上更好解决\u003c/p>\u003cp>小明：那你准备怎么解决呢？在哪解决呢？\u003c/p>\u003cp>张三：在家，晚上孩子睡觉以后21:30—23：30，这个阶段可以有两个小时的时间。\u003c/p>\u003cp>小明：那你接下来打算怎么做呢？\u003c/p>\u003cp>小明：先把书买了，然后按计划的时间去执行。\u003c/p>\u003cp>拆书家反馈：非常感谢两位的分享，可以看大这个过程中被提问者，没有直接给出答案，而是通过提问让学习者自己找到了答案，符合我们的步骤要求。同时可以看到在对话的过程中。描述目标的时候，是不是用到了我们上一个制定目标的方法？\u003c/p>\u003cp>学习者回答：是的\u003c/p>\u003cp>拆书家反馈：非常棒的分享，掌声送给他们。\u003c/p>\u003cp>\u003cstrong>［A2催化应用］\u003c/strong>1，我们在接下来的两周之内，我们设想一个场景，比如教育子女、劝说他人、同事沟通、辅导下属等等，我们在工作和生活中的哪个情境。别人会主动找到你，为了完成某个目标但遇到了困难，他找到你寻求帮助的的情境？请大家先花2分钟时间设想一下这个情境。\u003c/p>\u003cp>【现场小伙伴场景分享】\u003c/p>\u003cp>大丫丫：到年底很多朋友向我求助如何制定年度目标\u003c/p>\u003cp>谭起龙：下周朋友找我求助怎么选择自己的职业。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp> 2、好，请大家拿出一张便签，加工出在刚刚设想的情境下，你如何通过分析现状，选择方案，激发意愿三个步骤，帮他制定一个具体的行动计划。3分钟时间。\u003cbr> 3、请小伙伴上台分享 标签内容。时间3分钟。\u003c/p>\u003cp>【现场小伙伴运用分享】\u003c/p>\u003cp>姗姗：我最近会遇到的场景是：朋友向我求助如何制定年度目标。\u003cbr>\u003c/p>\u003cp>快到年底以前朋友问我怎么做计划，我都会直接跟别人说方法，当然我说方法可能不一定有效果，今天学了&nbsp;GROW模型。我会用提问的方式激发朋友自己去思考找到解决办法。\u003c/p>\u003cp>1、（分析现状）别人问我，我首先会让她自己去分析现状：\u003c/p>\u003cp>我：“你认为你现在目标是什么呢？”\u003c/p>\u003cp>朋友：“做明年的年度计划”\u003c/p>\u003cp>我：“面对这种情况，你觉得要完成这个目标有什么困难？”\u003c/p>\u003cp>朋友：“不知道年度计划怎么做，知道自己应该努力，但是不知道努力的方向，具体怎么做。”\u003c/p>\u003cp>我：“这些困难是什么原因造成的呢？”\u003cbr>\u003c/p>\u003cp>朋友：“不知道未来应该怎么做，是面对这些问题都想找人帮忙，但是自己没有认真思考过吧”\u003c/p>\u003cp>2、（选择方案）分析完现状之后，思考解决办法：\u003c/p>\u003cp>我：“那如果这次让你自己来完成，你能想到的解决办法是什么？”\u003c/p>\u003cp>朋友：“我先把自己明年想要得到的收获写下来，然后根据收获去匹配，自己需要的什么样的技能。”\u003c/p>\u003cp>我：“知道自己想要的技能后，又怎么办呢？”\u003c/p>\u003cp>朋友：“需要什么技能就学习什么技能啊，该买书买书，该听课听课，该报班的报班，该练习旧安排时间进行练习”\u003c/p>\u003cp>我：“除此以外，你曾经还见过或者听说别人是用什么办法解决的呢？”\u003c/p>\u003cp>朋友：“在朋友圈宣誓，或者参加一些社群活动，主动分享，输出倒逼输入”\u003c/p>\u003cp>3、（激发意愿）有了解决办法以后，激发意愿督促行动。\u003c/p>\u003cp>我：“那为了完整的制定年度目标，你接下来打算第一步先干什么呢？”\u003c/p>\u003cp>朋友：“我大概有思路了，我今天先回去整理一下，把明年想要的收获定出来，然后设定时间再匹配技能和计划”\u003c/p>\u003cp>在我的提问引导下，朋友从开始的茫然，到最后找到了制定年度目标的方法，并打算采取行动。\u003c/p>\u003cp>（小结）拆书家：好的感谢分享，谢谢大家，今天第一个片段学习了设立目标，第二个片段学习GROW模型后三步，分析现状，选择方案，激发意愿三个步骤，帮他人/自己制定目标和行动计划。相信通过今天的学习，在以后的工作/生活中，只要你愿意，你一定可以用对话的方式，能帮助别人建立责任心、引导对方自己思考、找到解决办法，并心甘情愿的执行。今天内容全部结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1544769888000,"updated_at":1560006049000,"ria":true},{"id":5614,"topic":"教练式反馈","learn_goal":"应用教练式反馈，开放式提问、描述事实、回归责任3个要素","remark":"","level":"TF3-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"唐云霞","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;大家好，非常高兴能在这里与大家相遇。我是唐云霞 \r\n在这里，我的三个标签是：培训；写作；烘焙。欢迎跟我有相同标签的下来连接\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>：我们部门来了个实习生，我让她做了一个端午节的活动计划，她做好以后就发给我看，前2次检查都发现了错误，第三次她发给我检查让我反馈意见，看着那张数字都没对齐的预算表，我实在忍不住了说，你自己不检查吗，这个太粗心大意了吧。小妹妹回答说，我检查了，但是我调了好久不知道怎么对齐。我无语了说，在学校都学了啥呀，最基本的表格设置都不会，当初不是说自己办公软件熟练，能胜任这份工作吗？小妹妹不说话，然后我就开始教她如何设置格式，怎么使用公式，感觉以后可以放心了，因为教会了,以后工作会越来越顺心。但是，没多久就收到她的离职报告，意思是自己觉得能力不行，胜任不了这份工作。\u003c/p>\u003cp>\u003cstrong>【提问\u003c/strong>】：大家有没有过这种经历，你的本意是通过给别人反馈评价帮助她变得更高效，但最后结果却南辕北辙？为什么会出现这种情况呢？\u003c/p>\u003cp>【\u003cstrong>影响\u003c/strong>】：是因为我们在给别人反馈的时候，经常用的是针对个人，批判式的反馈，这些反馈对方心里是不认同的。但是迫于压力接受所以要么短时间内看起来有效，要么就是别人自尊的进一步下滑，从而产生一些不好的影响。\u003c/p>\u003cp>【\u003cstrong>解决\u003c/strong>】：由此可见，想要给到别人的反馈是长期有效的，一定要满足一个前提条件—那就是对方要发自内心的认同反馈。那我们怎么反馈，才会让别人认同昵？在约翰惠特默的《高绩效教练》一书中介绍了一种反馈/评价别人的方法，叫教练式反馈，里面提到的方法能有效解决这个问题，接下来的片段我将跟大家一块来分享这个方法。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>\u003cstrong>学习目标\u003c/strong>】：\u003c/strong>大家在跟我完成本次RIA现场学习后，在反馈别人的时候，应用教练式反馈三要素，编写（行为）出能够引导对方思考的提问（界定）从而让对方感到自身责任。\u003c/p>","ratings_count":1,"texts":[{"id":8794,"quote":"\u003cp>\u003cstrong>\u003cstrong>【A1】请大家自测量表题\u003c/strong>\u003c/strong>\u003c/p>\u003cp>我们开始今天的现场学习为了让大家了解自己的反馈水平，在讲解之前，先请大家用2分钟的时间做一下测试。仔细阅读每一句话，用自己的第一印象判断，圈出对应的得分，“1”代表很不符合实际情况，“6”代表非常符合实际情况；然后把自己的分数做个统计。\u003c/p>\u003cp>&nbsp;量表自测题\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、别人问我意见的时候，我都能用心准备。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、我从不在给人评价的时候，使用我觉得，我认为，我建议等词语。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、我总是能针对事情本身，给予反馈和评价\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、我不会觉得别人问我的问题，太过于简单\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我从不根据他人过去的表现，来评价现在\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6、在评价他人的时候，我从不使用很好、不行、还可以、太差等词语。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【I】解释自测题\u003c/strong>\u003c/p>\u003cp>这个自测题的目的是考察大家以前在评价别人的时候，是否能做到让对方持续改善的反馈。我们来做一个调查，汇总得分在30以上的小伙伴请举手，说明在对人反馈的时候，能引起他人自发的改变，平时非常注重反馈的长期效果；得分在20-30分之间的小伙伴请举手，说明在评价他人的时候，会让对方有一定的自主权选择权，还有待加强；得分在10-20分之间的小伙伴请举手，说明评价他人的时候有一定的主观意识。得分在10以下，明评价他人的时候有很强的，主观意识容易伤害到别人。通过上面的量表自测题，大家已经对自己反馈评价水平有了大致了解，对今天的拆段学习也有了一些认识。测试分数高的小伙伴，我们再接再厉；分数不高的小伙伴也请不用担心，我们今天的拆段就是帮助大家来提升的。接下来我们进一步学习，请大家阅读拆段，时间2分钟，阅读完的小伙伴请向我举手示意。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【\u003cstrong>R 原文片段\u003c/strong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>反馈与评价\u003c/strong>\u003c/p>\u003cp>最差的反馈是针对个人的，批判式的反馈；\u003c/p>\u003cp>最有效的反馈是主观性的，描述性的反馈。\u003cbr> 我们可以确认普遍使用的五级反馈，如下所示从A(效果最小的反馈)到E(效果最好而且也是五级当中唯一能够促进学习和绩的一级)。其他四级则充其量会带来微小的短期改善或会引起绩效和自尊的进一步下滑。\u003cbr> A、经理的呼喊：“你太没用了。”\u003cbr> 这是一种人格化批评，会摧毁自尊和自信，必然造成未来绩效的下下滑，不含任何有益的成分。\u003cbr> B、经理的干预：“这个报告毫无用处。”\u003c/p>\u003cp>这种针对报告而不是人的批判式评论也会摧毁执行者的自尊，尽管程度稍轻，因为它没有给予报告者任何有关如何改正的信息。\u003cbr> C、经理的干预：“你的报告内容清晰、简洁，但其编排和表述方式的日标读者太过粗糙。\u003cbr> 这样说避免了批评并且给执行者提供了关于如何改善的信息，假仍统、不具体，也没有体现任何自主权。\u003cbr> D、经理的干预：“你对报告感觉如何?\u003cbr> 执行者现在有了自主权，但可能仅仅给予无意义的回应，比如“一累”或者做出一个价值判断，比如“很棒”或“差劲”，而不是更有用的描述。\u003cbr> E、经理的干预：“你报告的主要目的是什么?”“你认为本稿多大程\u003cbr> 度上实现了这一目的?”“你是否觉得还有其他方面需要强调?”“你的目标读者是谁?”等等。\u003c/p>","explains":"\u003cp>\u003cstrong>【互动讲解】\u003c/strong>\u003c/p>\u003cp>从刚才阅读的拆段中，大家是否已经清楚的看出，作者列举了五种不同的反馈方式作对比，分别是哪五种？\u003c/p>\u003cp>学员回答： ABCDE五个不同的反馈方式。\u003c/p>\u003cp>拆书家：非常好，有小伙伴说出有五种，大家觉得哪种方式更能促进别人的进步呢？\u003c/p>\u003cp>学习者回答：第五级E\u003c/p>\u003cp>拆书家：那为什么会是第五级昵？\u003c/p>\u003cp>学员回答：让他自主去发现问题，比较尊重对方，启发性比较强。\u003c/p>\u003cp>拆书家：是的额，非常正确是第五级，因为只有它才是符合教练式反馈标准的。\u003c/p>\u003cp>\u003cstrong>Wath：\u003c/strong>我们可以看到第五级反馈有什么特点，首先被反馈人他拥有自主权可以做选择，而选择就意味着他要承担完整的责任，其次需要动用脑力去思考，在他最初回答之前必须思考并形成自己的看法， \u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>因为只有对方认同，有了自己的看法才会发自内心的接受，并长期改善。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>接下来我们看如何做好反馈，达到第五级E的效果呢），包含以下3个要素。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;第一\u003c/strong>，\u003cstrong>开放式提问\u003c/strong>，开放式提问是相对封闭式提问的，区别是开放式提问的回答有两个以上，比如最近看什么书，封闭式提问只能用是否做选择，比如最近看书了吗？\u003c/p>\u003cp>\u003cstrong>第二，描述事实，\u003c/strong>事实是相对观点，事实指眼睛可以看到的客观存在，什么是观点由事实推导出来的结论，比如说我眼睛小，鼻子塌这叫事实，说我丑，这叫观点。\u003c/p>\u003cp>\u003cstrong>第三\u003c/strong>，回归责任，主语用“你”字开始开头，把我认为，我觉得换成你认为，你觉得。把自主权坏给对方，促使他去思考让他明白事情的改进和推动在他身上。\u003c/p>\u003cp>注意这3个要素，不是步骤，你的提问中不一定按这个顺序，只要包含3个要素就可以了。\u003c/p>\u003cp>\u003cstrong>【举个例子】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>让大家再一次加深教练式反馈3个要点的理解。\u003c/p>\u003cp>同样我们让部门的小朋友，做好关于高温天气如何预防中暑的宣传文案，来找我征求意见的时候，我就决定改变以往作风，用教练式的反馈来激发她自己的责任，从而长期有效的改进。\u003c/p>\u003cp>问题1，你为什么要用红色的字体？回答：因为醒目嘛，\u003c/p>\u003cp>看3要素： 回归责任 “你”字开头，开放式提问“为什么”，描述事实“红色字体”：\u003c/p>\u003cp>问题2，你用这么多红色的字体和图片搭配，给人的感受除了醒目还有什么？回答：感觉不清爽，看起来更热。\u003c/p>\u003cp>看3要素：回归责任 “你”字开头，描述事实，“红色的字体和图片搭配”开放式提问“还有什么“\u003c/p>\u003cp>问题3，那你觉得还可以怎么改？\u003c/p>\u003cp>看3要素：回归责任 “你”字开头，描述事实“觉得”开放式提问“怎么改\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>大家想一想，教练式反馈适用于什么场合，不适合什么场合？小伙伴讨论：适用于工作场合，上下级之间。拆书家总结：小伙伴们讨论的非常正确，你希望激发对方的责任让他积极思考的时候，而如果你本身就不希望对方去思考的时候是不适用的，比如把菜刀拿过来。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>我们现在已经学了教练式反馈，接下来大家做个互动练习，以便更熟练的掌握这个方法。\u003c/p>\u003cp>先来看看将要演练场景的背景：你已经过完了3-3，自立门户有了自己的堂口，你的弟子准备下周晋级1-2，晋级之前他把准备表发给你，希望得到你的反馈和指导，你打算用教练式反馈的方法引发他的思考，对他进行反馈。\u003c/p>\u003cp>具体的场景是：下周三，晚上八点你正躺沙发上看电视，这时候你的开山弟子小王，写好了1-1的准备表发给你，顺带一句，师父多给我提提建议。\u003c/p>\u003cp>我们按开始的分组，两两一组，组长牵头，一人扮演开山弟子小王，一人扮演过了三级的师父。时间5分钟，在过程中需要提现教练式反馈的3个步骤。\u003c/p>\u003cp>5分钟后，我们邀请一组小伙伴来跟大家分享。\u003c/p>\u003cp>\u003cstrong>【现场小伙伴演练】\u003c/strong>\u003c/p>\u003cp>弟子小王：师父你看看我1-2的晋级准备表，已经准备好了，你帮我看看哪些需要补充的？\u003c/p>\u003cp>师父：我们在1-2晋级过程中，最主要的是对I部分的步骤的提炼，你觉得怎么样才能更好的出简单的学习步骤呢？\u003c/p>\u003cp>弟子小王：我觉得提炼的话，首先对段子非常了解熟悉，想到如何拆解，才能提炼出方法和步骤。\u003c/p>\u003cp>师父：你觉得除了熟悉段子外，还有哪些更好的提炼方法呢？\u003c/p>\u003cp>弟子小王：还可以把步骤列出来结合自己实际发生的事情和身边的故事进行举例说明。\u003c/p>\u003cp>【晋级者回应】\u003c/p>\u003cp>非常感谢两位小伙伴的分享，两位小伙伴在场景扮演中，都用到了教练式反馈的3个要素，“开放式提问，你字开头，描述事实”。说明大家已经掌握了这个方法。我们以热烈的掌声给到两位。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003cbr>\u003c/p>\u003cp>【特定任务】\u003c/p>\u003cp>在接下来的一周，选择你即将面对的一次教练式反馈的场景，可以是你对同事工作的反馈、可以是你生活中对朋友的评价，或者是对后来晋级者的晋级要点反馈等等，应用今天学习的教练式反馈3要素，编写一段对话，并在你选定的场合去应用，应用后在分舵的微信群里分享感受，我们大家一起复盘。\u003c/p>\u003cp>\u003cstrong>【叶静小伙伴在第二周工作中的应用分享】\u003c/strong>\u003c/p>\u003cp>今天学习了教练式反馈得的方法，刚好下周会让部门的下属交客户拜访计划，准备在这次的工作安排中运用。\u003c/p>\u003cp>下属丽丽：老大，我的拜访计划写好了，你看有什么问题？\u003c/p>\u003cp>叶静：你觉得在你的客户拜访中，最重要的客户是哪几个？\u003c/p>\u003cp>下属丽丽：是写在最前面的那个几个女士，他们都是老客户，而且买的产品价格都比较贵，所以是我们的重点客户。\u003c/p>\u003cp>我：作为你要拜访的最重要的客户，你觉得跟其客户相比在拜访上的区别是什么？\u003c/p>\u003cp>下属丽丽：第一，花的时间，肯定比普通客户多啊；第二，推荐的产品，也会是偏向更高端的，价格高，但质量好的。\u003c/p>\u003cp>叶静：非常好，但在你的拜访计划里，应该如何去体现呢？\u003c/p>\u003cp>下属丽丽：应该写清楚，去拜访的时间，还要备注去拜访时应该带的那些产品，以及这些产品的相关知识和卖点。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>以上就是我今天跟大家带来的教练式反馈，通过案例讲解大家也发现这个方法可以引发对方思考，促使持续的不断进步；请大家在接下来的工作或生活中多加应用，在应用中享受不同风格带来的乐趣，让教练式反馈成为你习惯性的思维。我是唐云霞今天3-2的就到这里，谢谢大家参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1532832491000,"updated_at":1535470113000,"ria":true},{"id":5427,"topic":"有效提问","learn_goal":"有效提问","remark":"","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"唐云霞","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，非常高兴能在这里与大家相遇。我是唐云霞 \r\n在这里，我的三个标签是：培训；写作；烘焙。欢迎跟我有相同标签的下来连接。\u003c/p>\u003cp>今天我将用15分钟给大家分享有效提问的3个技巧\u003c/p>\u003cp>\u003cstrong>场景：\u003c/strong>我们在征询别人意见的时候，都希望别人给他的回答是经过思考的。比如夏天到了，在场的女生都会去买一条裙子吧？周末的时候你和老公一起去逛商场，面对琳琅满目的商品，看得你眼花缭乱。突然眼前一亮，发现一条裙子立马试穿，从试衣间出来后，问老公，这衣服好看吗？\u003c/p>\u003cp>老公头也不抬，就回答:好看。你生气说，你看都没看就知道好看。对方回答:我看了呀。你说，明明就没有看。对方回答:我斜着眼睛的时候看了一下，好吧，就算刚才没看我现在总看了吧。最后你特别不高兴，衣服也不想买了开始相互数落。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>请大家回想一下，在工作或者生活中，有没有提出这种简单问题，别人没听你说就直接敷衍回答呢？那你以往的提问是怎么提的呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>我们本身都是希望通过，提问得到中肯的回答。但最后我们提的问题，得到的结果却变成了敷衍。甚至会可能引发相互的指责，或者是永远达不到我们预期的效果。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那这种情况怎么解决呢？我们如何提问才能让对方更认真的倾听？英国约翰惠特默，在《高绩效教练》中就提出了一个解决的办法。那就是有效提问，说我们在提问的时候，可以用一些技巧让问题更有效的。那用什么技巧？怎么做呢？那接下来的片段中，我会给大家分享方法。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>在跟随我完成本次现场分享后，学习者能复述出 “有效提问”的三大要点，并且可以运用“有效提问三大要点”编写出含有，有效提问的剧本，从而在日常工作和生活，得到更好的反馈，提高工作和生活的质量。&nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8589,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>有效提问\u003c/p>\u003cp>如果命令一个人去做他需要做的事，反而不能产出我们所需要的结果，那么什么会让我们达到目的呢?让我们尝试问一个问题。\u003c/p>\u003cp>“你在看球吗?”我们会如何回答?也许我们会辩解，也可能会撒谎，就像我们在学校的时候老师问我们是不是注意听讲一样。\u003c/p>\u003cp>“你为什么不看着球?”我们会更加辩解，或者再加上一点儿分析。“我在看球。”“我不知道。”“因为我在想我的握杆动作。”或者更诚实的，“因为你让我分神并令我紧张。”\u003c/p>\u003cp>这些问题效果都不好，但请想想如下问题的效果。\u003c/p>\u003cp>那个球朝你飞过来的时候，是朝哪一边旋转的?\u003c/p>\u003cp>当球这次过网的时候，高度是多少?\u003c/p>\u003cp>这一次，或每一次它反弹起来的时候，它会旋转得更快还是更慢?\u003c/p>\u003cp>当你第一眼看到球旋转时，它离你的对手多远?\u003c/p>\u003cp>这些问题从完全不同的角度出发，它们创造出了其他问题或是命令不能实现的四个重要的效果。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>从片段中，我们可以看出，如果能有效提问，可以让听众更聚精会神，给出思考过的答案，减少别人对我们的敷衍，从而达到我们提问的目的。首先，我们需要辨别清楚什么是有效提问，我们先来看几种场景。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>比如你的领导问你，今天打电话拜访客户了吗？你说，还没有打。领导有点生气问，你为什么没有打呢？你回答说，因为上午在写工作总结。领导说，给客户打电话是最重要还是写工作总结重要？下那这种提问算有效的提问吗？不算，因为领导使用了封闭性的提问这会逼迫对方不用太多思考直接做选择就能回答，所以这不算有效提问。（什么是封闭式提问，就是对方只能回答是或者否，比如你吃饭了吗？），有效提问是需要开放式提问的，让对方有多种回答，比如你午餐吃的什么？\u003c/p>\u003cp>又比如说你早上迟到了，领导问你说为什么早上迟到了。你回答说，因为下雨路上很堵。他问你说竟然你知道下雨，为什么不早点出门呢？你说，我睡觉也不知道下雨。闹钟都是那个时间响。领导说，你迟到了2个小时，难道你是走路过来的吗？你回答，坐车呀一个站都走了半个小时等等。那这种情况下。领导的提问算不算是有效提问？看起来像，问题都用了开放式提问。但实际也上不算，因为这个问题使用了很多的疑问词，这些疑问词是带责备的感觉，它所引发的是防卫而不是思考，什么样的词能引发思考下面我会讲。\u003c/p>\u003cp>再比如月度奖金发下来了，你发现奖金比被扣了比之前要少，你希望下个月的奖金不要再被扣掉。所以你去问领导说，领导我奖金怎么比上个月少？领导说，因为相比上个月，你的工作不是特别满意。你提问说： &nbsp; 为什么会对这个月工作不满意呢？我每天兢兢业业，晚上11点别人下班都睡觉了，我还在加班。你还有什么不满意吗？这算是有效提问吗？看起来既是开放的，对方有思考。但还是不算，因为你偏离了自己的提问目标。对方回答你以后，你被带偏了，去纠结了一个跟目标不直接相关的问题。什么是跟目标相关，比如你可以问，为了奖金不再被扣掉，我接下来的工作，有哪些是需要改进的，能告诉我具体步骤吗？\u003c/p>\u003cp>我们可以看出，有效提问，需要满足3个条件：1，开放式的问题,2，引发对方思考3，回到目标，进行反馈。所以，有效的提问是：通过开放式的提问，引发对方的思考，并对回到目标进行反馈。\u003c/p>\u003cp>明确什么是有效提问，接下来就是如何进行有效的提问，我归纳为“有效提问三步法”，简称为三步法：\u003c/p>\u003cp>1，第一步，设计开放式提问题。开放式提问是相对封闭式而言，区别在于，封闭式提问的回答只能是，是或者否，比如你吃饭了吗？开放式的提问答案是不固定的，比如你中午吃了什么？\u003c/p>\u003cp>2，第二步，替换疑问词，造画面感。为了让提问看起来是放开的，我们经常会直接用疑问词，比如为什么，如何，竟然，居然这种带有责备的口吻，不足以引发思考。所以第二步是把为什么改成，是什么原因，造成XX？为了xx，可以做哪些改进？把如何改成做这件事情的步骤是……。这里的XX是带有画面感的\u003c/p>\u003cp>3，第三步，回到目标，进行反馈。对方回答以后，不要被带偏。回想一下自己的目标，再给出反馈。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>举个我自己有效提问的例子。\u003c/p>\u003cp>每次买衣服问老公意见，基本上都是敷衍我，让我很纠结该不该买。看了这本书以后，我决定通过有效提问来改变这种状况。\u003c/p>\u003cp>1，第一步，设计开放式提问题。你觉得我穿上这衣服走出去，别人会夸我哪好看呢？老公说抬头看了一下说，说你腿好看。\u003c/p>\u003cp>2，第二步，替换疑问词，描述画面感。是什么原因显得腿好看呢？老公说，高腰的裤子，看起来腿长。或者是我穿这条裤子，配个高跟鞋走在大街上是什么感受呢？\u003c/p>\u003cp>3，第三步，回到目标进行反馈。老公说，那回头率100%哦。回答目标再反馈，立马问，那你觉得我什么时候买呢？老公说，现在就买吧。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>有效提问是不是在所有情形下都适用呢？不是。你需要对方深思熟虑认真回答你的时候，才使用。如果你本身就是随便问问，要不要去逛街，那就没必要了。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>为了加深小伙伴们对“有效提问三步法”的理解以及未来更好的应用，我们来编写个剧本，内容可以参考记叙文六要素（时间-地点-人物-起因-经过-结果）。要求剧本中的场景是小伙伴们未来的生活或工作中可能会遇到的，并且情节中有应用到“有效提问三步法”，比如问你的领导对你的工作评价、问你的师父拆书法方法或者问朋友对你的评价等等场景。\u003c/p>\u003cp>小伙伴们根据范例模板把剧本的摘要写在一张纸上，时间3分钟。3分钟后，我们请1-2位小伙伴上来分享他的剧本。\u003c/p>\u003cp>【剧本模版】\u003c/p>\u003cp>主题：\u003c/p>\u003cp>时间：\u003c/p>\u003cp>地点：\u003c/p>\u003cp>内容：（剧本的起因、经过、结果）\u003c/p>\u003cp>注：剧本情节可以加入背景、旁白等，使情节更加跌宕起伏、生动有趣。\u003c/p>\u003cp>\u003cstrong>[现场\u003c/strong>\u003cstrong>小伙伴李丹剧本分享\u003c/strong>\u003cstrong>]\u003c/strong>\u003c/p>\u003cp>主题：工作报告征求领导意见\u003c/p>\u003cp>时间：6月15日\u003c/p>\u003cp>地点：办公室\u003c/p>\u003cp>人物：我和领导\u003c/p>\u003cp>起因：写好了工作方案，想征求老板的意见\u003c/p>\u003cp>我：领导，您看这个工作方案有哪些地方是需要修改的呢?\u003c/p>\u003cp>领导：第二页需要改\u003c/p>\u003cp>我：是什么原因需要修改呢？\u003c/p>\u003cp>领导：配色和排版是有点问题\u003c/p>\u003cp>我：好的，我一会调整一下，那除此以外还有什么需要修改的呢？\u003c/p>\u003cp>领导：其他不用改\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 非常感谢李丹小伙伴的剧本分享，我们可以看出，大家对有效提问的三大要点，开放式的问题，引发对方思考，反馈答案，相信大家都能记住了。我们刚刚也运用这个方法，编写了各自的剧本。今后大家逐渐运用，以后别人就不会敷衍你回答问题。以上是我今天分享的全部内容，谢谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1530236205000,"updated_at":1530236660000,"ria":true},{"id":4811,"topic":"教练目标","learn_goal":"设置教练目标，完成教练行为","remark":"","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"唐云霞","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"大家好，非常高兴能在这里与大家相遇。我是唐云霞，您可以这样记住我的名字，飘在天上像糖果一样的云朵和彩霞，合起来唐云霞。我的三个标签是：培训、写作、烘焙。欢迎跟我有相同便签的下来链接。（F）:《高绩效教练》作者是约翰惠特墨，一名二战退役军人，开了一家运动公司，偶然一次机会，让网球教练带滑雪的学员，结果大吃一惊，效果比专业教练还好，于是，他把网球教练的一套教学方法，进行了归纳总结，形成本书即GROW模型教练的四步提问法。（A）:本书热销以后，教练一词，也开始在全球传播，教练式的对话，简单的说是自我结果导向，在双方平等的基础上进行的一种对话方式。（B）:如果你是一名培训师，一位企业管理者，在这个信息时代，面对成长中的90后，佛性青年，传统的说教完全失效的情况下，可以学习教练式对话激发对方潜能。","ratings_count":1,"texts":[{"id":7869,"quote":"\u003cp>GROW模型提问的顺序\u003c/p>\u003cp>到目前为止，我们已经建立了学习和绩效改进的觉察力与责任感的核心本质。枝叶图说明了这些非常简单却强大的概念的益处的多分支、多方面的本质。我们也已经了解了教练的背景，教练和管理之间的联系，公司的文化和变革。我们探索了教练的角色和态度，并且认为问题是教练沟通中的主要形式。我们现在必须决定问哪些问题，以及以什么样的顺序来提问。\u003c/p>\u003cp>正式或非正式\u003c/p>\u003cp>在此必须强调一点，教练过程可以进行得宽松和非正式，以至于客户不知道他们在被教练。对于每日向下属发出指令或是接受汇报的管理职能而言，没有比教练更好的方式了，但它并不应该被看作教练；它是管理。在这种情况下，教练变成管理的一种工具，成为管理人员的方式，在我看来是最有效的方式之一。在正式教练的一端，一个教练课程可以有条不紊地、有结构地进行，让它的目的和角色都是明确的。虽然大部分的教练是非正式的，但我们仍然要查验正式教练的细节，因为二者的流程是一样的，而正式教练的阶段可以更加明确地加以界定。\u003c/p>\u003cp>对一教练\u003c/p>\u003cp>为了简化和清晰，我们会关注一对一教练，虽然团队教练甚至自我教练练的形式完全一致。这两种会在后面的章节中详述。一对一的教练发生在同级之间，经理和下属之间，以往的老师和学生之间，教练和执行者之间，咨询师和求助者之间。一对一的教练甚至可能会被用于一名员工对其老板的向上管理，虽然这通常是隐蔽的。毕竟，没有人能以告知的方式很大程度地影响他的上司如何去做，因而向上教练有更高的成功率。\u003c/p>\u003cp>&nbsp;GROW模型\u003c/p>\u003cp>因此，我建议提问的顺序遵照以下四步骤\u003c/p>\u003cp>目标设定(goal)，本次教练对话的目标，以及教练的短期目标和长期目标。\u003c/p>\u003cp>现状分析( reality)，探索当前的情况。\u003c/p>\u003cp>方案选择( options)，可供选择的策略或行动方案。\u003c/p>\u003cp>·该做什么(what)，何时(when)，谁做(who)，意愿(wil)l\u003c/p>\u003cp>这一顺序的假设是四个阶段都必须进行。第一次解决一个新问题通常都是如此。然而，如果一项任务正在进行或者曾经讨论过，也可以运用教练去推进或者处理。在这种情况下，教练可以在任何一个段开始或结束。\u003c/p>","explains":"\u003cp>\u003cstrong>【反面案例】\u003c/strong>在讲述片内容跟大家分享真实案例，在我的工作中之前，总有店长来问我说，销售不好怎么办呢？我都跟他们说，你要做好管理，排班满一点让员工少请假，结果，销售没上去人员还不稳定，店长就说，这不怪我，都是公司培训让我这么干的。领导说我闲得无聊净出馊主意，我冤枉啊，但也推不了责任，因为确实也是我让她这么干的。但我一想下次再碰到我怎么办，总不能每次都跟人说我不知道吧。那有没有办法来解决类似的问题呢？我们尝试从片段中寻找答案 \u003cstrong>（What）\u003c/strong>:片段讲述了用教练式提问沟通法，来明确双方角色，帮助对方，树立责任信心促使对方自己找到解决办法。\u003cstrong>（Why）\u003c/strong>:教练不同于顾问，老师，专家。他并不提供解决方案，他是通过对话来引导激发对方的潜能，让对方来解决这些问题。\u003c/p>\u003cp>\u003cstrong>（HOW）:\u003c/strong>那么我们怎么通过GROW模型，进行教练式沟通呢？有以下四个步骤:\u003c/p>\u003cp>\u003cstrong>第一步:设定目标:\u003c/strong>问对方你目标是什么？你想把工作生活变成什么样子？帮助对方理清目标。\u003c/p>\u003cp>\u003cstrong>第二步:分析现状:\u003c/strong>你可以问对方，你的现状是什么？哪些事情是最难搞定的？让对方找到现状和目标之间的差距。\u003c/p>\u003cp>\u003cstrong>第三步:选择方案:\u003c/strong>你可以问对方，有哪些办法来解决呢？还有其他办法吗？一组问题，帮对方找到更多的解决办法。\u003c/p>\u003cp>\u003cstrong>第四步:激发意愿:\u003c/strong>你可以问对方，你打算怎么做呢？下一步行动是什么？什么时候开始呢？一组问题把方案，转换成实际行动。\u003c/p>\u003cp>\u003cstrong>【强调不那么做的坏处】\u003c/strong>进行教练沟通的时候一定是要用GROW四步提问法去沟通。如果你不这么做，直接把自己的解决方案扔给对方，那你就是背锅侠，参见开篇案例，因为你一旦怎么做，责任就发生了转移，事情没办成，跟我没有关系，都是你的错。\u003c/p>\u003cp>\u003cstrong>【正面案例】\u003c/strong>后来我学了GROW模型，学会教练沟通法以后再有店长来问我，生意不好怎么办的时候。我就会用模型来帮店长找到解决办法，第一步设定目标，你的销售目标是多少呢？店长说每天卖1万，第二步分析现状，现在每天卖多少？店长回答，七千多离目标还差两千多。什么事是最让你烦心的？衣服缺码。第三步选择方案，我问她你有什么办法可以解决吗？回答，找公司补货，如果没货你还有其他办法吗？把缺码的衣服收起来，主推尺码齐全的。第四步激发意愿，那你下一步打算怎么做呢？店长说我今天先把衣服的尺码情况整理出来，缺码的找公司补，不缺码的让导购主推。可以从案例中看到，店长从抱怨销售不好，不知道怎么办。到对话结束后，找到了解决办法：先整理店铺的尺码情况，缺码的找公司补货，如果补不回来，就主推尺码齐全的产品。过程也符合我们GROW模型运用的原则，用提问来激发对方的潜能让店长自己找到了方法。他对他自己的行为承完整的责任。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1，（显像提问），\u003c/strong>请各位回想一下，在过去的工作或生活中有没有遇到以下情况呢。你的同事说自己性格很内向，不敢当众表达，一上台的时候就紧张，大脑空白不知道说什么。她问你有没有什么方法是可以改变？或者说你的朋友，说自己男女朋友，对她不好不关心她，然后想要分手，很犹豫问你怎么办？大家回想一下，有没有遇到过类似的情况，遇到以后你都是怎么回答，回答后又成了背锅侠的情景呢。现在请各位小伙伴回想讨论，待会请两个小伙伴起来跟我们分享一下自己，过去类似的失败经历，时间是2分钟。\u003c/p>\u003cp>\u003cstrong>【现场小伙伴场景分享】\u003c/strong>\u003cbr>\u003c/p>\u003cp>小伙伴A：我妹妹跟老公已经4年没怎么在一起了，一直打冷战，也没说离婚，妹妹很烦躁找我寻求帮助。我都劝她离婚，妹妹还责怪我，她抱怨说我不理解她，离婚哪有你说得那么简单。\u003c/p>\u003cp>\u003cstrong>A1+经验激活;\u003c/strong>大家设想一下，我们把时间轴放回到刚分享的情景中，如果再遇到这样的情况，如何运用今天学习的GROW模型进行教练式沟通呢？那请大家想好以后写在纸上交给我，时间是1分钟。\u003c/p>\u003cp>\u003cstrong>【现场小伙伴便签收集】\u003c/strong>\u003c/p>\u003cp>小伙伴A：下次妹妹再找我谈离婚的话题，我会用GROW模型进行教练式的沟通，通过提问让她自己找解决办法。\u003c/p>\u003cp>设目标：&nbsp; &nbsp;通过我俩的谈论，你想得到什么？你的婚姻问题想什么时候解决？具体到哪个时间能解决？\u003c/p>\u003cp>分析现状：你现在除了长期不在一起，还有其他情况么？现在的婚姻最让你恼火的是什么？\u003c/p>\u003cp>选择方案：如果不离婚你现在的有什么办法可以解决呢？除了将就/离婚还有其他办法吗？\u003c/p>\u003cp>激发意愿：你接下来打算怎么办？\u003c/p>\u003cp>结束语：好，谢谢大家，本次学习了GROW模型，希望在以后的工作生活中，通过设立目标、分析现状、选择方案、激发意愿四个步骤，学会教练式沟通。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":7870,"quote":"\u003cp>\u003cstrong>设立教练目标\u003c/strong>\u003c/p>\u003cp>l&nbsp; 经过本次教练，你想得到什么?\u003c/p>\u003cp>l&nbsp; 想象一下未来一年，你理想的工作状态是什么?请具体描述你典型的工作日是什么样子。(这与目前工作也许无关，对此我并不加以批判)\u003c/p>\u003cp>l&nbsp; 此刻你最渴望的那种情景包括什么因素？谈谈下面每一项的重要性(可以使用1-10等级区分)\u003c/p>\u003cp>l&nbsp; 你工作的目标是什么？\u003c/p>\u003cp>l&nbsp; 你希望何日时达成这一目标?\u003c/p>\u003cp>l&nbsp; 在内心深处，你真正想从工作中到什么？\u003c/p>\u003cp>l&nbsp;&nbsp; 如果这是你目前所处的位置，那么请谈谈接下来的几步路怎走？\u003c/p>\u003cp>l&nbsp;&nbsp; 从你目前的位置，第一步最好做什么？\u003c/p>\u003cp>教练案例\u003c/p>\u003cp>描述教练四步的四章中，我从始至终通过一个虚拟的与乔教练案例的教练对话来说明每一步。乔是伦敦某广告公司的一名高级客户经他早期的快速提开脚步已经在过去两年中慢下来，与此同时中年危机及由于食物和饮料的过多摄A导致他的腰围暴长。最近他试图抑制并开如锻炼，但他的尝试酒没于无聊、失败、借口、内疚和缺少约束之中。他把他的担优和一个同事迈克分享，后者提出来要教练他。\u003c/p>\u003cp>迈克：好的，乔你希望在这半小时结束后得到什么？\u003c/p>\u003cp>乔：一个可以让我更健康的计划；\u003c/p>\u003cp>迈克：从现在持续一生，还是其他？\u003c/p>\u003cp>乔：不，那看起来太长了，另外我一旦开始行动，就会发生改变。三个月的计划会比较现实。\u003c/p>\u003cp>迈克：让我们暂时先看看长期的，变得健康对你有什么价值。\u003c/p>\u003cp>乔：我觉得自己很糟糕，而且工作很痛苦。我希望重新获得良好的感觉\u003c/p>\u003cp>迈克：好。你希望到什么时候，达到什么样的健康状态?\u003c/p>\u003cp>乔：我希望减肥15斤左右，在几个月内不仅能够跑楼梯和赶火车不喘，而且能享受跑步。\u003c/p>\u003cp>迈克：准确地说，在哪一天你希望你的体重减到多少?\u003c/p>\u003cp>乔：在夏天结束前减到190斤，大概我需要减15斤。\u003c/p>\u003cp>迈克：具体哪天?\u003c/p>\u003cp>乔:9月20日。\u003c/p>\u003cp>迈克：今天是2月19号，你还有7个月的时间。\u003c/p>\u003cp>乔：嗯！一个月2斤，也许开始时可以更快些。\u003c/p>\u003cp>迈克：到6月1日你希望减多少?\u003c/p>\u003cp>乔：到那时减掉15斤\u003c/p>\u003cp>迈克：你可以不吃饭减到那个重量，但不会更健康。我们如何来衡量健康？\u003c/p>\u003cp>乔：我从9月初开始，每周跑32公里。\u003c/p>\u003cp>迈克：跑步的速度是多少?\u003c/p>\u003cp>乔：没有界定，我只是很高兴能这么做。如果我满意的话我会知道的\u003c/p>\u003cp>适克：我不美注速度，乔，只是给你自己一个目标速度。它会是多少？\u003c/p>\u003cp>乔：好的,9分钟跑1600米。\u003c/p>\u003cp>现在，乔在教练中获得了本次教练的目标，一个长期目标，一个半途标记。他的目标是具体的、可衡量的，并可能包含了所有我们建议的品质。因为在这个案例中没有任何公司的强制，他对他自己的目标承完整的责任。\u003c/p>","explains":"\u003cp>\u003cstrong>开篇案例：\u003c/strong>在讲述片内容跟大家分享小案例，前几天，我的一个朋友跟我抱怨说，这次晋升又失败了。我很惊讶，问她为什么，她说自己在述职报告的时候，老毛病又犯了，太紧张，讲报告的时候一片空白不知所云。我非常惊讶，你去年晋升失败不就是因为当众发言太紧张吗？怎么今年又掉坑里去了，而且你去年不是说要改掉当众发言紧张的毛病吗？怎么一年过去了还这样。这让我大惑不解，这不是她的目标吗？怎么喊完口号就没下文了？这在我们生活中也是经常出现的情况。这年头 谁还没个目标啊，比如换个大点的房子，变得更漂亮，多存点钱。但到了年底回想，真正实现的目标又有多少呢？为什么会出现这种状况，我们来看今天的段子。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>（What）\u003c/strong>:我们可以看到片段讲述了通过设立教练式提问，激发对方的潜能，帮助对方设定具体的目标可衡量的目标，再找到目标背后的价值，让目标变得好执行\u003cstrong>（Why）\u003c/strong>:我们都愿意执行自己认可的目标，而不是别人强行施加的目标。而且这个目标越具体越简单，那就越容易执行。而现实生活中往往是设定了目标后，行动却很艰难，如开篇案例，设定了目标最后却不了了之。所以我们设立目标不是定个方向，而在设立目标后还需要确定量化标准，找到驱动力列出具体的行动计划\u003c/p>\u003cp>\u003cstrong>（HOW）:\u003c/strong>那在进行教练式沟通的过程中，我们怎么通过提问来具体可衡量还有计划的目标呢？经过对原文的整理，细化出来以下四个步骤，\u003c/p>\u003cp>\u003cstrong>第一步,具象化目标\u003c/strong>：你可以提问，你的最终目标是什么？你想得到什么？什么时间完成？具体是什么时间？你还剩下多少时间？（让对方说出目标并限定完成时间，判断标准，有目标，有具体时间，比如：我想考个人力二级的证书（目标考二级证），什么时间完成呢？今年上半年，具体时间是多少？6月30日前（有日期6月30日）确定目标以后我们知道了方向，但并不知道标准是什么，所以需要对目标进行量化，我们看第二步&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong> &nbsp;第二步，设立量化标准：\u003c/strong>提问，你如何来衡量XX目标呢？有没有更短期的衡量方法？还有其他更具体的衡量方法么？如案例中减肥多少斤，是个方向目标，那怎么量化呢？是节食还是运动呢？如果是节食，怎么节标准是什么，每天吃多少？运动怎么运动，跑步速度是多少？\u003c/p>\u003cp>\u003cstrong>第三步，找价值：\u003c/strong>这个目标对你有什么价值？能够具体描述一下，对你有什么好处吗？想象你拥有这个好处后的场景是什么？让对方说出价值和好处，判断标准有方向，有具体场景，比如对方说价值是可以让我能力提升（方向），那再接着问，能力提升对你有什么具体好处，可以升值加薪，那想象一下，你升值加薪后的场景？买衣服再也不用等到换季打折，才下手了（具体场景：换季买衣服）找到价值后，为了实现这个价值，获得好处。我们要设定一个行动计划\u003c/p>\u003cp>\u003cstrong>第四步，列计划：\u003c/strong>用4个W（what,where,when,who），接下来你准备做什么？什么时候开始，做这件事的频率是多少？在什么地点呢？除了你还有谁参与？如果有人参与他负责什么？&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>&nbsp;预防异议:\u003c/strong>大家听完以后是不是觉得这个过程太麻烦了，按我们之前的做法更简单，直接定个目标不就好了吗？可事实上不这么做会更麻烦，因为直接定出来的目标，没有完成时限，没有量化标准，没有到达路径。这会让对方在实施过程中，缺乏依据。参考开篇案例。结果呢，找不到方向更麻烦，还解决不了问题。那在使用这个方法的时候，具体怎么用，给大家举个例子。&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>（意译案例）:\u003c/strong>还是案例中提到的晋升朋友不敢当众发言，上台就紧张，说话说不清楚，词不达意，特别是开会作报告的时候。已经连续两次掉坑里了，特别是第二次设立了目标还是掉下去了，再次希望我能给他一些帮助。听完以后我决定用GROW模型进行教练式沟通，激发她的潜能，对于她这种只会设立方向目标的人，我决定模型中的第一步G，设立教练目标，\u003c/p>\u003cp>\u003cstrong>第一步具象化目标，\u003c/strong>我问他，你的最终目标是什么？对方回答，众发言不紧张。我问，那你希望什么时候能够实现呢？对方回答，今年上半年吧。我问，准确的说你希望什么时候？具体到哪一天完成？对方回答，6月30号以前完成。&nbsp;&nbsp;\u003cstrong>第二步，设立量化标准。\u003c/strong>我问，你如何来衡量呢？对方回答，就是发言不紧张啊。我问，那如何来衡量你不紧张呢？对方回答，拿着草稿的情况下能够通顺的发言。我问，那有没有更具体的呢，通顺发言的定义是什么?他说，一次发言0断句，重复句不超过3次。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003cstrong>第三步，找价值，\u003c/strong>我问，那你完成这个这个目标以后对你有什么价值呢？对方回答，当然有价值会让我变得更有自信。我问，你能讲一下，更有自信对你具体的好处吗？对方回答，上台不紧张，可以让我在述职报告的时候更清楚地阐述我的工作价值，让老板知道我做了哪些事情。我不但能把事情做好，而且有良好的表达能力。在未来晋升发展的时候，我的可能性更大一些。那为了实现这个价值，我们需要做什么呢？\u003cstrong>第四步，列计划。\u003c/strong>为了变得更自信，为了能晋升，你接下来准备做什么？他说，拿着稿子多练习，我问，什么时候开始，具体时间呢？回答，从今天晚上开始，那你练习的频率是多少？回答，每天练习半个小时。我问，在什么地方练呢？每天晚饭后在家练习？我问，还有更好的选择么？回答，还可以去楼下小区练习。那除了你还有谁参与呢？回答，我男朋友吧，我问，他承担什么责任呢，他每天监督我啊。\u003c/p>\u003cp>好的，我们前后对比，从最开始设立一个方向目标，当众发言不紧张，到最后通过具象化目标，立标准，找价值，列计划。设立了一个具体可衡量，有驱动力的计划。6月30日前完成当众发言不紧张，判断标准，一篇发言稿0断句，重复句不超过3个，计划：每天晚上饭后，在家/小区，练习30分钟，由男朋友进行监督。在这个过程中没有任何的强制意味，她对她己的目标承完整的责任。\u003c/p>\u003cp>\u003cstrong>适用边界:\u003c/strong>那是不是所有设立目标的情况都适用呢？当然不是，它仅适用于别人主动找到你，且你想通过引导去激发对方潜能的时候才使用。\u003c/p>","interaction":"\u003cp>A3场景设计:为了让大家更好的理解和运用刚刚讲述的方法。我们来做一个小游戏，假设你是小明，你现在还在读书，你有个室友叫小胡。眼看要毕业了，他大学英语四级没过，关系到拿毕业证的问题，然后非常苦恼，主动找到你，他问你应该怎么办？\u003c/p>\u003cp>角色扮演:假设你是小明，你决定用设立教练目标的方法，帮小胡树立一个具体可衡量的目标。然后你们展开了一场对话，请大家分角色扮演小明和小胡，并讨论时间是5分钟。待会我会让两位分角色扮演的小伙伴上来给我吗分享，时间3分钟。\u003c/p>\u003cp>【现场小伙伴场景分享】\u003c/p>\u003cp>李曼慈（扮演小胡）光东（扮演小明）展开对话：\u003c/p>\u003cp>李：我都快毕业了英语四级还没考过怎么办啊，你能帮帮我吗？\u003c/p>\u003cp>光：你的目标是什么?\u003c/p>\u003cp>李：毕业之前考过四级\u003c/p>\u003cp>光：你打算什么时候完成呢？\u003c/p>\u003cp>李：这个学年结束吧\u003c/p>\u003cp>光：具体什么时间,到哪天?\u003c/p>\u003cp>李：6月份吧，6月25号.\u003c/p>\u003cp>光：你的衡量标准是什么？\u003c/p>\u003cp>李：就是考过啊，考到425分。\u003c/p>\u003cp>光：我知道是考425分那是结果，我是问你，具体的衡量方法，有没有更短时间的衡量标准。&nbsp;\u003c/p>\u003cp>李：那就是英文作文，最多错10分，阅读理解错不能超过5个。\u003c/p>\u003cp>光：有没有更具体的衡量方法，比如你怎么做才能作文最多错10分，阅读理解错不过5个呢？\u003c/p>\u003cp>李：那要多看多听，每天背单词，阅读英文嘛\u003c/p>\u003cp>光：那有没有更具体的衡量呢？比如被多少单词，看多少文章？\u003c/p>\u003cp>李：没有背50个单词，读一篇文章。\u003c/p>\u003cp>光：你做完这些事，完成目标后对你有什么价值呢？\u003c/p>\u003cp>李：能够拿到毕业证顺利毕业；\u003c/p>\u003cp>光：有什么具体好处呢？设想一下过完四级拿到毕业后的场景？\u003c/p>\u003cp>李：拿到毕业证，就可以去国外留学，然后跟外国人聊天的时候，可以直接用英文交流，感觉很棒的的。\u003c/p>\u003cp>光：那你打算怎么做呢？什么时候开始？\u003c/p>\u003cp>李：每天背50个单词，读一篇文章，今天晚上就开始。\u003c/p>\u003cp>光：都有谁参与？\u003c/p>\u003cp>李：我们都室友参与；\u003c/p>\u003cp>光：他们承担什么职责呢：\u003c/p>\u003cp>李：室友们监督我。&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;\u003cstrong>拆书家反馈：\u003c/strong>好的，非常感谢两位的分享，大家把掌声送给他们\u003cstrong>（现场开始鼓掌）\u003c/strong>。我们可以看到在对话中使用了刚刚讲到的四个步骤，用体是怎么使用我不再赘述，简单看一下提问的思路。1：问了目标和完成时间，对方时间回答模糊的时候，又再问了一遍。2、问了量化标准，对方回答偏差的时候，跟我们原文案例一样通过反复提醒问了几次，最后对单词和阅读理解做了量化。3、找了价值，问了过四级的具体好处和场景。4、列计划，这个环节我们讲要用4个W（what,where,when,who），他用了3个，缺1个where，要是下次使用加上就更完美了。总体来说说今天刚学完就会使用，还是非常不错的，再次把掌声送给他们（现场热烈鼓掌）。\u003c/p>\u003cp>所以，在未来的运用中，我们要像光东一样，通过不断的提问，激发对方的潜能，让对方自己寻找办法。\u003c/p>\u003cp>\u003cstrong>［A2分步催化］\u003c/strong>1，在接下来的两周之内，我们设想一个场景，比如教育小孩、劝说他人、辅导下属等等，我们在工作和生活中的哪个情境。别人会主动找到你寻求帮助，在帮助中会涉及使用到设立教练目标的情境？请大家先花2分钟时间设想一下这个情境。\u003c/p>\u003cp>注意，我们还是只分享出这个场景就可以，暂时不要用刚才学到的“四步骤”对场景进行加工。\u003cbr>\u003c/p>\u003cp>【现场小伙伴场景分享】\u003c/p>\u003cp>许凯：朋友的父母爱买保健品，怎么劝都劝不住，他找到我，看有什么解决办法；\u003c/p>\u003cp>李曼慈：朋友工作不开心，老是跟领导合不来，然后她跟我诉苦求帮助。\u003c/p>\u003cp>［\u003cstrong>A2催化应用\u003c/strong>］好，请大家拿出一张便签，加工出在刚刚设想的情境下，你如何用设立教练目标的方法帮助对方制定出具体可衡量有计划的目标呢？记住4个关键步，1骤具象化目标问目标和时间，2设立量化标准有数字可衡量，3找价值问好处场景，4列计划4个W。给大家3分钟时间，写下我们怎么运用，待会请1-2位小伙伴上台分享 标签内容。\u003c/p>\u003cp>【现场小伙伴场景分享】\u003c/p>\u003cp>&nbsp; &nbsp; 李曼慈：朋友工作不开心，老是跟领导合不来，然后她跟我诉苦求帮助。\u003c/p>\u003cp>如果朋友找到我，会跟她这么说：\u003c/p>\u003cp>1、她工作不开心，那我先问她想从工作中得到什么？再问她希望在什么时候能实现。\u003c/p>\u003cp>2、然后问她衡量她目标的标准是什么？要问到具体有数字的量化标准\u003c/p>\u003cp>3、再问她，实现目标后的价值，以及对自己的好处，拥有好处后的场景；\u003c/p>\u003cp>4、最后问她接下来要做什么？什么时候开始做？在哪开始？有谁参与？参与者承担什么责任?\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>好的，感谢曼慈同学的精彩分享，拆书家带头鼓掌（现场鼓掌）。\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>好，谢谢大家，今天学习了GROW模型和设立教练目标，知道这两个知识的关键点在于：通过不断的提问，不断的追问，不断的让对方思考，然后找到解决办法。运用这种教练式的沟通技巧，可以在沟通过程中，让别人感觉你更专业，更愿意听你讲，更愿意去执行。今天内容全部结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1521252800000,"updated_at":1521252800000,"ria":true},{"id":4623,"topic":"在辅导中有效的提问","learn_goal":"学习者可以明白什么样的提问是有效的，并掌握其方法。","remark":"今天我选拆的是全球畅销50余万册的，被翻译成22国语言的，教练与领导领域首屈一指的经典书籍《高绩效教练》，这本书的作者是英国的约翰·惠特默爵士，这是最著名的一本著作。\r\n本书以GROW教练模型【G目标、R现状、O选择、W意愿】为教练逻辑，引用职场和运动场上的例子，清晰阐述了交流的理念和技巧。","level":"TF1-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"闲人","city":"长治市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"不破不能立，不拆不成器！拆书帮把知识拆成你的能力！感谢各位参加今天的拆书练习。我是80后斜杠中青年原东升，目前我是一名政府机关工作人员/全民阅读推广志愿者/两个男孩的爸爸。第一个标签让我可以是一个闲人，这个不用多说，机关单位总是可以有大把时间的，第二个标签，是我自己的事业，从自己阅读，到推广读书，这条路漫长而有意义；第三个是我最重要的角色定位，正是因为这两个可爱又淘气的小家伙，让我有了第二次成长的机会，让我再次拿起书，接触到拆书帮。\r\n拆书，并不是字面上的把书拆散，而是通过把书中的知识经过三个步骤的拆解，转化成学习者能力的一个过程。\r\n这三个步骤就是我们的RIA拆书法，R就是我们从一本书找出能解决学习者实际问题的内容，通过I就是现场拆书家现场培训式的讲解和促进，引导学习者把书中知识和工作生活实际相联系，进而转化为学习者的习惯改变或能力提升。\r\n这就是拆书法的核心——拆为己用。\r\n拆书帮就是学习爱好者自发组成的一个成人学习社群，称作拆书帮学习者俱乐部或分舵，目的是为了帮助更多的学习爱好者成为拆书家。\r\n成为拆书家，不仅可以提升自身能力，更重要的是可以帮助更多人一起学习。拆书帮，我来了。","ratings_count":1,"texts":[{"id":7662,"quote":"\u003cp>【R】阅读原文拆页\u003c/p>\u003cp>\u003cstrong>我选拆的是全球畅销50余万册的，被翻译成22国语言的，教练与领导领域首屈一指的经典书籍《高绩效教练》\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天选择的拆页来自于原书的P37-38，有效的提问。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面让我们用2分钟时间来阅读原文——\u003c/strong>\u003c/p>\u003cp>如果命令一个人去做他需要做的事,反而不能产出我们所需要的结果,那么什么会让我们达到目的呢?让我们尝试问一个问题。\u003c/p>\u003cp>•“你在看球吗?”我们会如何回答?也许我们会辩解,也可能会撒谎,就像我们在学校的时候老师问我们是不是注意听讲一样。\u003c/p>\u003cp>•“你为什么不看着球?”我们会更加辩解,或者再加上一点儿分析。“我在看球。”“我不知道。”“因为我在想我的握杆动作。”或者更诚实的,“因为你让我分神并令我紧张。”\u003c/p>\u003cp>这些问题效果都不好,但请想想如下问题的效果\u003c/p>\u003cp>•那个球朝你飞过来的时候,是朝哪一边旋转的?\u003c/p>\u003cp>•当球这次过网的时候,高度是多少?\u003c/p>\u003cp>•这一次,或每一次它反弹起来的时候,它会旋转得更快还是更慢?\u003c/p>\u003cp>•当你第一眼看到球旋转时,它离你的对手多远?\u003c/p>\u003cp>这些问题从完全不同的角度出发,它们创造出了其他问题或是命令不能实现的四个重要的效果。\u003c/p>\u003cp>•这类问题促使球员观察球,否则他们无法回答此问题。\u003c/p>\u003cp>•球员会比平常更加集中精神,才能正确回答这个问题,因此提供了更高质量的输入。\u003c/p>\u003cp>•这些答案是描述性的而不是判断性的,因此没有自我批评或是伤害自尊的风险。\u003c/p>\u003cp>•我们的教练有一个意见反馈圈,他们有能力确认球员回答的正确性,因此了解球员是否聚精会神。\u003c/p>","explains":"\u003cp>\u003cstrong>原文阅读完之后示意我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家都读完了，我来谈一下我的理解：\u003c/strong>\u003c/p>\u003cp>(what)在辅导别人时，相比较于命令的方式，通过提问的方式更能激发对方的觉察力和责任感，能让他自己找到解决问题的办法，并为自己的决定负责。\u003c/p>\u003cp>(way)原文给出了两种提问方式，“你在看球吗？”属于封闭式的问题，对方只能用“是”或“否”来作答，而不能有进一步的思考。\u003c/p>\u003cp>“你为什么不看球？”这种带有批评意味的问题容易引起对方的防御心理，甚至是抵触情绪。\u003c/p>\u003cp>(how)后面的四个问题则实现了促进对方思考和观察的效果。这一组的问题有以下三个特点：\u003c/p>\u003cp>第一，开放式而非封闭式的问题，需要描述性的答案，也就需要对方细致的观察；\u003c/p>\u003cp>第二，以寻求量化或收集事实的词语开始，比如“什么”“何时”“谁”“多少”；\u003c/p>\u003cp>第三，专注于细节，可以让对方专心致志、保持兴趣。\u003c/p>\u003cp>(适用边界)在军队，我们往往见到简单粗暴的教练方式，就是直接的命令，那是因为军队需要的是服从命令听指挥的军人。而我们今天讨论的是针对个体技能等方面的辅导和教练，需要激发个人的觉察，需要考虑个体差异。即使在军队，对于有特殊技能的人才，也会有类似这样的教练方式来激发个人的觉察。\u003c/p>","interaction":"\u003cp>分享A1便签\u003c/p>\u003cp>大儿子图图在学习吉他，老师要求每天在家练习，并把练习视频发给老师。\u003cbr>\u003c/p>\u003cp>只要有时间，我都会陪孩子一起练习，并指点一二。今天这个拆页让我想到上个月的一次练习。\u003c/p>\u003cp>图图在弹奏《龙的传人》，这个节奏我比较熟悉，自然也就能听出个一二三来，也就想着指导他一下。\u003c/p>\u003cp>弹完一遍，我听出他那个那个地方弹错了，音不准，还有节奏不在点上，就说：“你自己打节奏了吗？再来一次！”\u003c/p>\u003cp>图图有点不情愿，但还是又弹了一次，这次错的更多了。\u003c/p>\u003cp>“你能不能用点心？就这效果能给老师发吗？”\u003c/p>\u003cp>图图停在那里不弹了，眼眶也湿润了，我更是火大，“不想练就算了！”转身离开了。\u003c/p>\u003cp>反思：我使用的都是封闭式的问题，而且确实带有指责和批评的意思，甚至带有否定的意味在里面，也就难怪孩子会委屈了。\u003c/p>\u003cp>如果今天再来，我应该这样问：\u003c/p>\u003cp>“第2小节的第3拍是什么音？”\u003c/p>\u003cp>“这首曲子是什么拍子的？”\u003c/p>\u003cp>“怎样就能更熟练一点点呢？”\u003c/p>\u003cp>“怎么做可以保证整首曲子的拍子不会乱呢？”\u003c/p>\u003cp>分享A2便签\u003c/p>\u003cp>目前，大家推选我为分舵的代教育长老，我有义务带领大家一起朝着拆书家的目标迈进，要督促大家按时完成各项练习，要对小伙伴提交的预备表进行点评，我计划用以下一些问题来引导对方自己发现问题并改进。\u003c/p>\u003cp>•你本周的目标是什么？计划完成其中的哪几项内容？每天的具体计划是什么？\u003c/p>\u003cp>•目前有什么困难？要如何克服？今天的任务完成了吗？什么时间可以完成？\u003c/p>\u003cp>•你认为自己的预备表哪里还可以改进一下呢？\u003c/p>\u003cp>•你的每个环节分别需要多长时间？\u003c/p>\u003cp>•I便签的3W1H是如何体现的？前因后果和适用边界是如何考虑的？\u003c/p>\u003cp>•A1便签哪些地方对应了原文？\u003c/p>\u003cp>•A2便签是如何体现SMART原则的？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1517726257000,"updated_at":1519202454000,"ria":true},{"id":3638,"topic":"教练式沟通 激发无限可能","learn_goal":"提高觉察力，增强自信心","remark":"你是否经常为下属提供解决方案，让自己身心俱疲，结果绩效却不高？\r\n你是否在学习体育项目时，被教授各种规范动作，却很难真正掌握？\r\n你是否经常教育子女应该怎样做，结果却事与愿违？\r\n本期拆书会告诉你解决之道，学会GROW提问模型，成为高绩效教练！从此，再也不用担心员工不会工作，不用担心孩子的学习。还在等什么，赶快报名，和追逐一起来拆书吧！","level":"TF2-3","duration":22,"status":0,"type":0,"chaishujia":{"username":"追逐1","city":"合肥"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是追逐，今天我要领拆的这本书是《高绩效教练》。这里讲的教练不是体育竞技中的教练，而是应用在商业中的辅导和沟通技术。教练不是专家、顾问，而重在创造学习和成长的环境，通过提问和对话培养个人洞察力、责任感和自信心。\r\n 本书已更新到第四版，书中完善了教练部分的定义，更深入的揭示了它的心理学根源。书中详细介绍了教练是什么、可以解决什么问题、什么时候适合使用、如何有效使用等，还原教练的本来面目。\r\n 在教练领域的书籍中，本书算得上首屈一指的“扛鼎”之作，它浓缩了惠特默爵士在教练领域30余年的研究成果。与同类书相比，本书语言通俗易懂，而且使用类比的方式清晰说明教练技术的原理，让读者很容易理解和使用。\r\n 阅读这本书不会让你马上成为一名专业的教练，但它能帮助你更好的认识教练的价值和潜力。学会并应用书中的方法，能让你成为优秀的领导者。对于学校的教师和孩子的家长而言也十分有益，能培养出更优秀的学生和子女。","ratings_count":0,"texts":[{"id":6539,"quote":"\u003cp>下面我们先来阅读拆页，本片段选自原书47页，阅读时间2分钟，读完的小伙伴请抬头示意。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; I 拆书家讲解引导（细化行动步骤）：\u003c/p>\u003cp>片段里讲到了教练技术的GROW提问模型。教练不同于顾问、专家、教师，他不提供解决方案和意见，而是通过发人深省的提问和对话，激发个人天赋潜能和职业潜力。下面我来详细说明具体步骤：\u003c/p>\u003cp>第一步Goal目标设定：你可以问他：你的目标是什么？你最想实现的是什么？你希望自己的工作变成什么样子？这组问题有两个目的，一是帮助他理清目标，二是激发他明确目标。只有当目标清晰后，才能更好解决。\u003c/p>\u003cp>第二步Reality现状分析：你可以问他：现状是什么？哪些事让你心烦？你都做过哪些努力？效果如何？都有谁与此相关？这组问题是为了让对方清楚自己的现状，发现优势和不足。\u003c/p>\u003cp>第三步Options方案选择。你可以问他：那么你都有哪些选择？你都有哪些办法来解决这些问题？还有吗？这组问题是为了帮助对方尽可能想出更多方案，当他自己想出这么多方案以后，他自己都会很激动。\u003c/p>\u003cp>第四步Will意愿。你可以问他：你打算怎么做？下一步的行动是什么？还需要谁对你的帮助和支持？这一步要把方案转化为行动。教练不要把自己的想法强加给对方，而是要激发对方自己的意愿。\u003c/p>\u003cp>举一个工作的例子做说明：你是公司的销售总监，公司开发了一款新产品，但销量并不大，销售经理来问你如何来提高销售额。你可以通过这四步提问法来进行教练式沟通。\u003c/p>\u003cp>首先，通过提问让他明确目标，具体要实现的内容，比如销售额突破5000万；其次，问他现状如何，做过哪些尝试，让他发现优势和不足，相当于做了SWOT分析；再次，问他有哪些方案可以选择，启发他尽可能多的方案：比如加大广告宣传、促销等等；最后，你问他具体的行动是什么，让他把方案转为行动，激发他的意愿。\u003c/p>\u003cp>这样通过GROW模型进行提问，既培养了销售经理的洞察力、责任心和自信心，又解决了销售额的问题。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3 促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（\u003c/strong>\u003cstrong>逐字稿）：\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了GROW提问模型，那么面对具体的问题应该如何做呢？下面我为大家设计了一个典型的代表场景：你的一个朋友报名参加了一个很重要的考试，考试通过后有助于他的职业发展，升职加薪都很有可能。但是工作太繁忙，抽不出太多时间准备考试，他的压力很大，准备放弃考试。请每两人一组，先讨论应用今天的方法，然后再演练。一人扮演你的朋友，一个是你自己。用今天学习的GROW模型来进行教练式沟通，练习使用今天学习的方法。请大家注意：我们讨论和演练的主要目的是为了练习GROW提问模型，而不是在于解决你朋友的问题，请大家一定要按照这四个步骤进行演练。最后我们请一个小组现场表演。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>佳佳：你最近怎么了，听说你报名参加考试后又要放弃了。\u003c/p>\u003cp>李广：没办法，最近实在是太忙了。\u003c/p>\u003cp>佳佳：之前为什么报名参加考试呢？\u003c/p>\u003cp>李广：自己工作遇到了瓶颈，想通过考试提升自己。\u003c/p>\u003cp>佳佳：其实可以给自己定个目标。比如通过考试，达到什么水平？\u003c/p>\u003cp>李广：首先是掌握基本的理论知识，应用知识，让能力提升。\u003c/p>\u003cp>佳佳：怎么衡量自己的目标呢？\u003c/p>\u003cp>李广：首先是通过考试，其次是解决工作中的问题。\u003c/p>\u003cp>佳佳：那你觉得现在的问题是什么？\u003c/p>\u003cp>李广：主要是没有时间。\u003c/p>\u003cp>佳佳：那么除了时间紧张外，还有什么与此相关。\u003c/p>\u003cp>李广：家里都比较支持我考试，没有问题。\u003c/p>\u003cp>佳佳：针对没有时间这一块，你还可以做哪些事情？\u003c/p>\u003cp>李广：我觉得可以自己去挤一挤时间。老板布置的工作没有挑选就答应下来了，可以适当去做一些拒绝。另外做好时间管理。\u003c/p>\u003cp>佳佳：那你觉得现在下一步可以做哪些事情？\u003c/p>\u003cp>李广：可以去和老板谈一谈，哪些事情必须做，哪些事情可以交给别人做。反思自己的时间管理，去学习时间管理的知识。每天腾出两个小时去学习。\u003c/p>\u003cp>&nbsp; &nbsp; 谢谢佳佳和李广的精彩分享，应用我们学习的GROW提问模型很好的解决了问题。大家应该能够看到，这个方法是非常实用的，不管在商业还是生活中都能发挥很大作用，希望大家经常练习，熟练运用，都能成为高绩效教练，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1505044470000,"updated_at":1505046813000,"ria":true},{"id":3544,"topic":"直击事件本质，找到一次性解决方案！","learn_goal":"直击事件本质，找到一次性解决方案！","remark":"在跟随我完成本次RIA现场学习后，学习者遇到一件事可以有多种选择，但都不能让自己满意而陷入纠结时，能够按照我今天分享的3个步骤和一条注意事项（1、最大化选择；2、给观点、想法组合；3、选择最优方案；注意：选择阶段对任何观点不做任何评价）去做，找出一个执行方案。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"锅净_二毛","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"学习目标：在跟随我完成本次RIA现场学习后，学习者遇到一件事可以有多种选择，但都不能让自己满意而陷入纠结时，能够按照我今天分享的3个步骤和一条注意事项（1、最大化选择；2、给观点、想法组合；3、选择最优方案；注意：选择阶段对任何观点不做任何评价）去做，找出一个执行方案。","ratings_count":0,"texts":[{"id":6428,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>分组\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>按照上一位拆书家的分组进行分组（也可能需要调整，灵活掌握）\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>场\u003c/p>\u003cp>景\u003c/p>\u003cp>介\u003c/p>\u003cp>绍\u003c/p>\u003cp>法\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003cp>min\u003c/p>\u003cp>（2）\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>事件场景：\u003c/strong>咱们现场学习者有没有人感觉自己执行力特别强，遇到什么事情不假思索的立刻冲上去解决，马上就干，结果是按下葫芦起了瓢，又出现没想到的问题，新问题解决起来可能更棘手；又或者我们有没有遇到过公司客户的一些个人行为或要求在不违法的情况下可能和公司制度有冲突，之后老板一直强调教育你说制度是死的人是活的而不愿意调整制度，你为此感觉很为难。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>回想一下，遇到类似问题你当时是怎么解决的呢？当时的处理效果怎么样？是不是没想到还有一整套系统的方法解决这类问题呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实当我们遇到这类问题总是不能一次性解决，而需要反复返工，或者得罪客户影响自己和公司业绩时，可能会使老板怀疑你的能力甚至影响到你的升职和加薪。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>这本书就从教练的原理、教练的实践、高绩效教练领导力和超个人教练实现转型这4部分，教会我们引导他人或者自我引导成长的教练技术。进而不断提高我们思考和解决事情的能力，他能够产生的作用效果会比你想象中的要更好。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>阅读\u003c/strong>\u003c/p>\u003cp>\u003cstrong>原文\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>2min\u003c/p>\u003cp>（4）\u003c/p>\u003c/td>\u003ctd>\u003cp>那怎么做才能更好呢？今天我就和大家分享一下“教练技术中的最优选择”，这个知识点\u003c/p>\u003cp>咱们先看片段，我的拆页选自这本书的第72页。\u003c/p>\u003cp>下面给大家2分钟的时间阅读一下，阅读完请抬头示意我一下，谢谢！\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>I\u003c/strong>\u003c/p>\u003cp>\u003cstrong>引导讲解\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003cp>min\u003c/p>\u003cp>（8）\u003c/p>\u003c/td>\u003ctd>\u003cp>原文片段告诉我们，一件事情在选择阶段，要尽最大数量列出问题的解决方案，方案数量要比质量重要；绞尽脑汁的想，哪怕是再异想天开的想法都要记录下来。然后从广泛的方案中挑选出具体的行动计划，搜集方案过程中不要对任何方案抱有负面看法和评价。那具体怎么做到呢？这让我想起我做户外工作时，晚上10几个人的集体帐篷有人打呼噜打扰别人休息的事，我们怎么解决的呢？\u003c/p>\u003cp>\u003cstrong>第一步，最大化选择。\u003c/strong>\u003c/p>\u003cp>遇到问题时候找两（几）个人做头脑风暴，要让所有参与者无所顾忌的表达出所有想法和观点，想到啥说啥，直到想不出为止，并且全部记录下来。\u003c/p>\u003cp>我们当时是召开现场执行人员会议，说给打呼噜人发小帐篷的、给他们在远处搭建一个大帐篷让他们都住过去的，让他们睡在救援车上的、半夜起风会刮跑的等等，说什么的都有。\u003c/p>\u003cp>\u003cstrong>第二步，给观点、想法组合。\u003c/strong>\u003c/p>\u003cp>将所有的可选观点和想法按照可做的行为和可能产生的结果分类，将行为和结果一一搭配组合，将两个或两个以上的想法不断结合起来。\u003c/p>\u003cp>当时我们排列了简单的几个组合，发小帐篷可能半夜被吹走；都住远处呼噜帐篷里，他们可能会互相呼噜打扰；睡救援车上，人多车不够。\u003c/p>\u003cp>\u003cstrong>第三步，选择最优方案\u003c/strong>\u003c/p>\u003cp>当选择方案在列表里排成一列时，人会在潜意识中按顺序划分等级，为避开这一点，我们把组合结果很随意的誊抄到另一张纸上，不排版、不排序，然后一条一条的认真审查这些方案的利弊。\u003c/p>\u003cp>我们通过一一对比分析后还是找不到解决方案，貌似陷入僵局了，再回到第二步，进行更多的想法排列组合，最后，睡救援车上→人多车不够→发小帐篷→还会吵到别人→远离营地→被风吹跑怎么办？→锚到车上。\u003c/p>\u003cp>最后，当我们觉察到所有的选择而且非常清楚它们的利弊后，决策自然就做出来了。\u003cstrong>（疑议：你的方法就能直接找到最好的答案吗？）\u003c/strong>虽然我们最后做出的选择不一定是最好的、最完美的，但一定是最适合我们当下的。\u003c/p>\u003cp>但需要注意的是，一定要做到原文中说的那样，全过程三步骤中不要对任何想法、观点、组合产生个人偏好、审查、挖苦等任何评价、假设，因为它会抑制你的发散性思维，会使你的选择范围变小。\u003c/p>\u003cp>\u003cstrong>（适用范围）\u003c/strong>这个方法不适用于写总结、报告、方案等本身就需要不断反复修改的这种事情。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>催化应用\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>9 min\u003c/p>\u003cp>（17）\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>春节后3月底，北京樱花盛开的季节，你们公司的潜在最大的客户\u003cstrong>（\u003c/strong>一旦成交，将会使你们公司主营业务收入在现有基础上提高45%\u003cstrong>）\u003c/strong>要到你们位于亚运村的公司总部进行考察，他乘一夜10小时火车卧铺，于当天上午8点到达北京西站，老板将接站任务交给你了，但这个客户是出了名的“烟枪”就因为不让吸烟，所以不坐飞机和高铁。同时你们公司又有规定，公司所有范围内，包括车上都不允许吸烟，如果谁接待客户时候，任何人在办公室或者车内吸烟了，要罚这个接待员1000元人民币。这时候你犯难了，这个客户单签下来又不一定算我的，但车上抽烟了肯定罚我钱，如果是你，你会怎么办？\u003c/p>\u003cp>请运用我今天分享的三个步骤和一条特别注意事项小组内讨论出接站到公司的方案，你会怎么做，会怎么样和这个客户说，最后你的故事结局会是怎样的？\u003c/p>\u003cp>给大家5分钟，请在下面写出你的小剧本（摘要形式即可）5分钟后请出一名小伙伴分享一下：\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>学习者案例记录：【（设计剧本：5~6分钟）（分享剧本2~3分钟）】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>回应\u003c/strong>\u003c/p>\u003cp>\u003cstrong>与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>反馈\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>2 min\u003c/p>\u003cp>（19）\u003c/p>\u003c/td>\u003ctd>\u003cp>追问确认\u003cstrong>/\u003c/strong>好奇反问\u003cstrong>/\u003c/strong>坦诚无知\u003cstrong>/\u003c/strong>组织讨论\u003cstrong>/\u003c/strong>故事启发\u003cstrong>/\u003c/strong>\u003c/p>\u003cp>简短重述\u003cstrong>/\u003c/strong>摘要点评\u003cstrong>/\u003c/strong>真诚赞美\u003cstrong>/\u003c/strong>号召故障\u003cstrong>/\u003c/strong>超越拔高\u003cstrong>/\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（对分享者的A2做出回应，可能用到上述的任何一种或几种）\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>强有力\u003c/strong>\u003c/p>\u003cp>\u003cstrong>的结尾\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>1min\u003c/p>\u003cp>（20）\u003c/p>\u003c/td>\u003ctd>\u003cp>如此，通过大家齐心协力，我们也就把貌似僵局的不可能变成了可能。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504252249000,"updated_at":1504252443000,"ria":true},{"id":1127,"topic":"《高绩效教练》拆书","learn_goal":"学完后，能够制定符合SMART原则的目标","remark":"事件场景：在亲子教育和员工培育中，当子女或新员工来问你问题，我们都习惯性给予热心细致的指导，说这件事情就我的经验应该这样…这样….，前几次指导完后心中还有微微的得意，当多次来问几乎同类型的问题时，就会愈发不耐烦，有时还会想：他怎么这么笨呢，自己怎么都不动脑筋想的！\r\n提问：大家觉得这仅仅是子女或新员工的问题么？怎样做能引发子女或新员工的思考，提升他们的能力呢？\r\n影响：我们长期采用这种指导的方式来进行亲子教育和员工培育，常常无法发展他们的能力，对方也没有解决问题的主动性，也缺乏解决问题的信心。\r\n解决：这本出中提出的思路，运用GROW教练模型（目标goal，现状reality，选择option,意愿","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"张然","city":"苏州市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家张然，很高兴认识大家。我们进行报数分组。今天我们学习目标是：学完后，能够制定符合SMART原则的目标。\r\n我今天给大家带来的这本书名叫《高绩效教练》（场景法介绍图书）\r\n事件场景：在亲子教育和员工培育中，当子女或新员工来问你问题，我们都习惯性给予热心细致的指导，说这件事情就我的经验应该这样…这样….，前几次指导完后心中还有微微的得意，当多次来问几乎同类型的问题时，就会愈发不耐烦，有时还会想：他怎么这么笨呢，自己怎么都不动脑筋想的！\r\n提问：大家觉得这仅仅是子女或新员工的问题么？怎样做能引发子女或新员工的思考，提升他们的能力呢？\r\n影响：我们长期采用这种指导的方式来进行亲子教育和员工培育，常常无法发展他们的能力，对方也没有解决问题的主动性，也缺乏解决问题的信心。\r\n解决：这本出中提出的思路，运用GROW教练模型（目标goal，现状reality，选择option,意愿will）可以帮你解决，它能培养对方的察觉力、责任感和自信心，激发对方的潜能，而你却根本就不需是对方的领域专家，是不是很神奇呢！","ratings_count":0,"texts":[{"id":3343,"quote":"\u003cp>音频地址：\u003ca href=\"http://note.youdao.com/noteshare\">http://note.youdao.com/noteshare?id=b2c5f48fb4ea40bce06c2d356a3fdb6a \u003c/p>\u003cp>好目标的品质最终目标不在你的控制之中，但绩效目标可以，绩效目标不仅仅要遵守SMART原则：\u003c/p>\u003cp>●具体(specific)&nbsp;\u003cbr> ●可衡量（measurable）\u003cbr> ●一致同意（agreed）\u003cbr> ●可实现的(realistic)&nbsp;\u003cbr> ●阶段性的(time phased）\u003c/p>","explains":"\u003cp>我现在开始进行I\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在这个拆页里，看到了目标要满足的一些原则，其中最常用的就是SMART原则，遵循原用意，调整如下，\u003cbr>&gt;Specific(具体的)：你的目标是什么?\u003cbr>&gt;Measurable(可衡量的)：如何知道/衡量达成了目标？如果10分是你最满意的状态，你想要几分？如果目标实现了，你会看到什么，听到什么，感觉到什么？\u003cbr>&gt;Achievable(可达成的)：你可控/可以达成的是什么呢？\u003cbr>&gt;Results(结果/价值导向的)：实现这个目标的价值/意义是什么？还有呢？你认为对你更重要的是什么呢？还有呢？你真正需要的是什么呢？\u003cbr>&gt;Time Bound(有时限的)：在什么时间内完成？\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 也就是说满足这几点的目标才是高品质的目标，才能触发和指引对方行动，而运用问问题的方法来确认目标是一个非常有效的方法，问完上面的问题后，最后问：你的目标是***是么？来进行确认，最后就能得到符合SMART原则的目标。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 常用问句顺序：S—&gt;M—&gt;R—&gt;S—&gt;A，如下：\u003cbr>1. 问S：你的目标是什么?\u003cbr>2. 问M：如果目标实现了，你会看到什么，听到什么，感觉到什么？\u003cbr>3. 问R：实现这个目标的价值/意义是什么\u003cbr>4. 问S：你的目标具体是什么呢?\u003cbr>5. 问A：你可控/可以达成的是什么呢？你觉的你的目标可达成的把握度是多少呢，如果10分是你最有把握的，你是几分呢？\u003cbr>6. 问T：在什么时间内完成？ \u003cbr>7. 进行确认：你的目标是***（SMART目标）是么？ \u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我曾经就运用在帮助朋友明确英语学习的目标上，我的朋友在外企工作，经常要用到英语口语，而他这部分还需提高。\u003cbr>\u003cstrong>我：你的英语学习目标是什么?\u003cbr>朋友：我要提高英语口语？\u003cbr>我：假如目标实现了，你会看到什么，听到什么，感觉到什么？\u003cbr>朋友：我会看到我在商务中流利的和美国客户介绍我们的Projector产品，自由的和她们交谈，我感到非常自信。\u003cbr>我：学习英语口语对你有什么意义和价值？\u003cbr>朋友：英语口语是目前工作必须的能力，能让我在目前职场上走的更好？\u003cbr>我：那你的英语学习目标具体是什么呢？\u003cbr>朋友：我目前日常用语没有问题，我的具体目标练习关于Projector产品的口语\u003cbr>我：你觉的你的目标可达成的把握度是多少呢，如果10分是你最有把握的，你是几分呢？\u003cbr>朋友：公司有一个关于Projector的英文介绍教材，能熟练说出里面内容就可以了，达成度10分。\u003cbr>我：在什么时间内完成？\u003cbr>朋友：在三个月内完成\u003cbr>我：所以你的目标是在三个月内熟练说出公司的Projector的英文介绍教材内容，是么？\u003cbr>朋友：是的。\u003c/strong>\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;可以看到之前目标是：提高英语口语？经过问话后目标为：在三个月内熟练说出公司的Projector的英文介绍教材内容？已符合SMART原则，是不是很好用啊。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这种方法要运用在对方有意愿来明确目标的时候，若对方没有意愿或对这个目标不感兴趣，是怎么也问不出结果的。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003cbr>我现在进行A2\u003cbr>你目前有什么工作、学习或者生活上的目标么？请想一个近期迫切想达成的目标，编一段小故事，假设有一位A，A是位你非诚信赖的大师，你们相遇，在什么环境下你获得他的帮助，设计出人物、情节变化（包括：起因、经过、结果）和你们的对话、动作等，其中A的问话使用上面的方法。时间5分钟，5分钟后我请人站起来讲讲他的剧本。\u003c/p>\u003cp>学习者案例记录：\u003cbr>拆书家：我看各位都已写完了，我们请第一组来做下分享。\u003c/p>\u003cp>\u003cbr>第一组：首先场景是这样的：\u003cbr>----------------------------------------------------------------------------------------------------\u003cbr>\u003cstrong>在一个细雨蒙蒙的早晨，我又一次走在了十字路口，正在思考着，我要走哪一条路呢？突然路的对面来了一个长者，他看到我眉头紧锁的样子，开始跟我细聊并对我提了一些问题，他开始问我：\u003cbr>老者：你的目标是什么?\u003cbr>我：我的目标是想提升我在团队中的影响力。\u003cbr>老者：如果你的目标目实现了，你会看到什么，听到什么，感觉到什么？\u003cbr>我：我会看到我团队中每个成员都积极上进，都交出很棒的工作结果，其他的同事和上司看到我的团队很棒，我会感到很开心。\u003cbr>老者：实现这个目标的价值/意义是什么\u003cbr>我：说明我是有管理才能的，有能力胜任此职位并且有能力胜任更高的职位\u003cbr>老者：你的目标具体是什么呢?\u003cbr>我：我的具体目标是激发每位团队成员的内在驱动力、学习能力和工作技能，比如解决问题能力、表达能力、沟通能力等\u003cbr>老者：你可控或可以达成的是什么呢？\u003cbr>我：我可控的是接下来集中准备对他们进行解决问题能力、表达能力、沟通能力的培训课程\u003cbr>老者：你觉的你的目标可达成的把握度是多少呢，如果10分是你最有把握的，你是几分呢？\u003cbr>我：我有8分的把握\u003cbr>老者：在什么时间内完成？ \u003cbr>我：6个月内\u003cbr>老者：你的目标是6个月内分阶段培养团队成员的解决问题能力、表达能力和沟通能力，并且培养一个团队接班人吗？\u003cbr>我：是的。 \u003cbr>聊到这里，我很清楚自己要走那条路，我非常感谢这位老者对我的帮忙，我对他说了声谢谢。我信心满满的走向公司。\u003c/strong>\u003cbr>----------------------------------------------------------------------------------------------------\u003cbr>拆书家：很棒。这里提一点，刚听到你说你的完成有8分把握，这说明你还有一些疑惑或障碍，可以继续往下问，若能将信心往上提1分，你觉的还要做些什么或什么样的协助呢？继续往下探索，或许将信心提升到10分。这些就是我今天的拆书内容，如果没有问题，今天就要这边，谢谢大家。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3344,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1476960447000,"updated_at":1476984798000,"ria":true},{"id":632,"topic":"简单几招，提高工作中简单小事情的绩效","learn_goal":"教你提升工作中简单小事情的绩效","remark":"工作或生活中你是否也会将一些看似简单的小事情搞砸？结果是不是也往往和自己的预期相去甚远？或者按下葫芦起来瓢，又出现这样那样的新问题？到底应该怎么做呢？来拆书帮紫禁之巅分舵吧，二毛给你支个招……","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"锅净_二毛","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"自我介绍 1min\r\n 大家好，我是二毛，刚刚在最强推荐环节我说我是一个减肥达人，超级马拉松跑者。是因为我以前一直很胖，2012年的时候突然心血来潮想减个肥玩玩吧，就从228斤一路减到现在的162斤，整整66斤（对减肥这个话题感兴趣的小伙伴儿一会儿活动结束后咱们再交流哈），正是因为减肥从而迷恋上了跑步，也是因为跑步，在一场超级马拉松中认识了小武，他当时是分舵的组织长老也是一名马拉松狂热份子，当时他给我介绍的拆书帮完全不是那么回事，但还是很感谢小武在去年大概这个时候组织我们参加一场高强度的徒步活动拉练，在拉练过程中认识了王小桃，正是小桃给我重新介绍了一下拆书帮才把我吸引到这里来的，把我发展成了拆书帮的铁杆粉，这期间我也成功的把她名字发展到我们家户口本上了。是的，在这里我收获了我们的爱情，并已经组成家庭～我们小两口相约相守一百年和大家一起拆书一百年！","ratings_count":0,"texts":[{"id":1867,"quote":"\u003cp>好，每个人手上都有片段了吧？今天的片段选自《高绩效教练》这本书的第139页，给大家两分钟的时间读一下这个片段，读完后，请抬头示意我一下。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>拆书帮介绍\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>2min\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>我俩在一起后，经常有身边的同事、亲朋问我，你娶到媳妇的那个读书会是什么组织啊？由于当初小武给我介绍的拆书帮完全没有勾起我想来的兴趣，所以能跟别人清楚的介绍出拆书帮是很重要的一件事，那好什么是拆书和拆书帮呢？ &nbsp; 我一般是这么告诉他们的：1） “拆书”是一种学习方法论，强调以学习者为中心而不是以知识为中心，提倡读书不一定要把一本书从头到尾读完，最重要的是能够将书中的知识“拆为己用”真正做到知行合一，通过这个方法来帮助我们提升能力、解决问题。拆书的方法可以是个人学习，也可以是组织学习。个人学习就是便签读书法，就像我一会要做的那样。组织学习就是一位拆书家拿一本书准备一场现场的拆书，就像今天我和另外两位拆书家这样，引导大家把知识拆为己用。只要你是一位想要解决问题、认真的小伙伴，那从学习者的学习效果来衡量的话，一位拆书家创造的价值就不亚于一位培训师；2）既然一次拆书的价值不亚于培训师，那拆书家是不是在要拆的这个主题上是专家呢？不是的。“最好的学习是教会别人”拆书帮提倡的就是这个，你不用一定要在这方面非常牛X了，才来拆书，拆书家也是学习者，而通过准备一场拆书，拆书家收获的会比单纯的作为学习者收获的更多，这也是我要来拆书的原因。3）拆书帮就是这样一群爱学习的小伙伴聚集的公益自组织，他现在在全国各地已经有很多分舵，一些还没有分舵的城市也都在陆续组建中，目前咱们帝都有三家，而今天大家到来的西二旗紫禁之巅分舵是全国第一家分舵呦！\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>书籍&nbsp; &nbsp; 介绍\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>1min\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>《高绩效教练》是以GROW教练模型 （目标 goal， 现状 reality， 选择 option， 意愿 will）为教练逻辑，引用职场及运动场上的例子，清晰阐述了教练的理念和技巧。对于促进企业界开始运用的“教练型领导”，这本书将是最佳的范例，听起来这是一本领导力的书籍，但是不能简单的把它归为领导力的书，里面所提到的方法用它来教孩子也同样是有效的，它还是一本改善我们和他人沟通，激发他人梦想的一个里程碑式的著作。通过这本书封面上写的原书第4版，大家就应该知道它的畅销程度了。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【R】\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>2min\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>好，每个人手上都有片段了吧？今天的片段选自《高绩效教练》这本书的第139页，给大家两分钟的时间读一下这个片段，读完后，请抬头示意我一下。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>&nbsp;【I】\u003c/td>\u003ctd>\u003cstrong>&nbsp;2min\u003c/strong>\u003c/td>\u003ctd>\u003cp>我看大家都读完了。看过报名贴的小伙伴还记得我今天的拆书主题和什么有关吗？是提高一些工作中看似非常简单的小事情的绩效。原文片段是说我们在工作过程中有些事情从表面上看很简单，不需要怎么动脑筋，凭感觉可能就能做的很完美了，如果想做的更精更细致却又不知道如何着手进一步改进的情况下，遵循作者的GROW教练模型，按照教练一步步的引导来思考问题，考虑问题，就会有更多的完美的新的想法产生，教练也只需按照GROW模型的四步稍作变化简单的一一引导着问下去即可，四步就是GROW教练模型的目标（goal），现状（reality）,选择（option）,意愿（will）,最后很肯定的告诉大家，运用完这四个步骤后，你会很快得到一个超出预期的更好的结果。&nbsp; 原文片段中右侧虚线小方框内特别标注了外在障碍是有一个内在成份的。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>4min\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>我们公司的产品是打造企业家、社会高净值人群户外社交平台的，表现形式是4天3夜徒步108公里，全程都在戈壁滩的无人区里，连手机信号都没有，白天徒步夜晚露营，不分男女，晚上10~15人一顶大帐篷“混账”共住，今年5月份在敦煌的一场活动中，第一晚过去后，有几个客户跟我反映说他们帐篷里有打呼噜特别厉害的，吵得他们一晚上都没有睡好，强烈要求把打呼噜的人隔离开，否则休息不好的话剩下的3天2夜81公里是肯定没精力走完的，我一想这确实是个事，但解决起来也简单呀，打呼噜吵到别人嘛，给他们每人分配一顶小帐篷出去睡就好啦。结果，大家可以想像一下发生了什么？……第二天晚上所有打呼噜厉害的人集体把小帐篷紧挨着扎在了下风口浙江台州队大帐篷的旁边，呼噜声此起彼伏，整个台州队近20名客户一夜都没睡好，天一亮就早早起来跟我们提意见抗议。在这里我就犯了GROW教练模型第一步的错误，没弄清目标，以为的目标就是打呼噜的人吵到同帐篷的人了，出去就好啦，实质上目标应该是任何人都不要被呼噜吵到。因为考虑到小帐篷在戈壁滩里的抗风能力，怕晚上客户睡着睡着被吹跑，所以在第三天晚上我们远离宿营区搭建并加固了一顶10~15人的大帐篷，还美美得意的给取了个名字叫“听雷轩”，用KT板做了一个特别漂亮醒目的门牌挂上去，由于这些打呼噜的人作息时间并不一致，有早睡的有晚睡的，还有半夜需要起来的，就不断打着呼噜循环的互相影响着彼此休息，这一帐篷打呼噜的人又都没睡好。这里是犯的是GROW教练模型第二步没有详细分析清楚（现状）的这个错误，当时只是顺着客户的提议考虑了戈壁中最常见的大风而没有细致的分析出我们现场还有好多越野车停在一边可以用来给小帐篷加固这个条件，再加之第一步目标不正确，从而导致GROW教练模型的第三步（选择）这一项直接被略过，因为感觉没有什么可选了嘛。一场活动一共三晚上，三个晚都没能让客户休息好，非常影响客户体验，服务行业嘛，客户体验是重中之重，所以我们老大私底下和我们沟通时候半真半开玩笑说我们做事效率不行要扣我们绩效。其实在这场活动中出现的类似看似小的问题但很影响客户体验的事情并不少，这只是其中的一个典型事件，原来解决问题的时候总是头痛医头脚痛医脚，每天忙的焦头烂额还不出效率，心里也是挺着急的，但就是不得要领。结合片段的知识要点，仔细思考认真总结后觉得，在这个工作过程中GROW教练模型最重要的第四步压根就没有做，那就是（意愿），就是原文片段右侧虚线方框内特别强调的内在成份，也就是没有从根本上重视起这个事情。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>2min\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>当我们从根本上有了这个意愿之后，再认真利用GROW教练模型对当时的现状分析和可选择分析得出①不理会客户诉求肯定不行，②每人一顶小帐篷随便搭建的话，他们会不会搭建到影响到其他别的人休息的地方？③搭建大帐篷共住，打呼噜吵到别人，别人肯定也包括另外打呼噜的人，这也肯定不行，④剩下的就是其它可能了。首先我们要远离大帐篷宿营区（这时候大帐篷小帐篷都可以选），其次让他们打呼噜的之间还不能互相影响（这时候似乎只有小帐篷可选了），那最后要解决的就是小帐篷会被风吹跑的问题。让小帐篷与小帐篷间保持一定的距离，把小帐篷锚在越野车上，固定好就OK了。在之后我们的活动中都是这么做的包括很多别的小事情也都是利用这个模型解决了，再也没有发生别的什么小插曲，完美解决问题的方法看似很简单，但经过了一场活动三个晚上的摸索才解决好，效率真的不是很高，好在已经找到解决这种问题的方法了。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>总结\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>1min\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>以上就是我今天的拆书分享，回顾一下，工作中这些看似不起眼的小事情往往会导致我们效率低下，利用好GROW教练模型，在行动前只需简单分析一下可能就会一劳永逸的解决问题了。利用GROW教练模型之后，工作效率提升，不会再被琐事缠身，能够按时下班，就会有更多的时间去读书、去拆书、去学习。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1469151015000,"updated_at":1492063772000,"ria":true},{"id":486,"topic":"封闭式提问与开放式提问","learn_goal":"工作沟通中，为了使任务得到更多的重视，培养开放式提问的习惯","remark":"本书不仅讲解教练的原理，还会引导学习者从9个不同方面展开教练实践，通过实践激发潜能、提升巩固教练必备的素质和技能，从而实现绩效的提升。","level":"TF1-2","duration":13,"status":0,"type":0,"chaishujia":{"username":"dova","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"伙伴们好！我是Dova皮卫华。很高兴由我给大家做TF1-2的拆书分享。\r\n我选择的书是惠特默的《高绩效教练》。本书不仅讲解教练的原理，还会引导学习者从9个不同方面展开教练实践，通过实践激发潜能、提升巩固教练必备的素质和技能，从而实现绩效的提升。\r\n这本书将伴随我升级打怪的全程。","ratings_count":0,"texts":[{"id":1141,"quote":"请大家用2分钟时间，阅读手中的片段。有读完的朋友，可向我举手示意。","explains":"提出封闭式的问题，对方往往是不需要思考的，答案更多是辩解或者撒谎，体现的是提问者更在意自己说了什么而非说话的效果，没有考虑是否奏效。\r\n相反，提出开放式的问题，将引发对方的思考、或者说他不得不思考。开放式问题回避了引发自我批评的风险，但提高了对方的注意力集中度，且答案更有助于我们进行评估。\r\n当你希望得到下属某个订单的进展时，你可以采用以下2种策略：\r\n封闭式问题：你有在做这个订单吗？为什么找不到合适的人？\r\n开放式问题：你有几个候选人接近这个订单要求？他们可以推荐的理由有哪些？不符合的方面呢？还有哪些方法我们没有使用到吗？","interaction":"【A1】激活经验 6分钟 拆书家提问设计（逐字稿）：请大家回忆一下，就在上周，当你向同事询问某件事情进度或结果时，你使用的是封闭式还是开放式问题？你提了哪几个问题？结果是怎样的？\r\n给小组4分钟时间讨论一下，并把你们的想法写在便签纸上。每组请一位伙伴来给大家分享一下。（1分钟）\r\n 学习者案例记录：\r\n人事部助理入职后做了一次沟通，问了：目前工作中满意地方有哪些？困惑的地方有哪些？下一步你会做哪些调整？还需要哪些资源的支持？\r\n【A2】催化应用 2分钟 拆书家提问设计（逐字稿）：类似需要提问的情况，下周你会遇到吗？你会怎样提问呢？\r\n请大家花1分钟时间将你的提问写在便签纸上。完成后请举手示意。将有请1位伙伴分享一下。\r\n 学习者案例记录：\r\n下一个礼拜会和领导沟通几个候选人评估情况，我会先问他：目前哪些候选人是比较满意的？满意的地方是哪些方面？其他不满意的候选人又是哪些？不满意的方面有哪些？最后确定的候选人有哪几位？","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1465791872000,"updated_at":1465791872000,"ria":true},{"id":477,"topic":"真正负责的感觉随选择而来","learn_goal":"能够引导团队人员自己做出选择、承担责任","remark":"本书不仅讲解教练的原理，还会引导学习者从9个不同方面展开教练实践，通过实践激发潜能、提升巩固教练必备的素质和技能，从而实现绩效的提升","level":"TF1-1","duration":11,"status":0,"type":0,"chaishujia":{"username":"dova","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"伙伴们好！我是Dova皮卫华，来自南京。\r\n我给自己加了三个标签。\r\n做一个积极的人。不回避问题，在解决问题中积累厚度，但要注意解决问题的时机和策略。\r\n积累hr专业度。对hr各方面的知识、技能掌握的越深入，才越能成为客户选才的顾问和人才职业发展的顾问，而不单单是凭经验。\r\n成长为一名教练。培养出更多专业的下属、与下属保持良好的合作关系，才能有真正属于自己的事业。","ratings_count":0,"texts":[{"id":1113,"quote":"请大家用2分钟时间，阅读手中的片段。有读完的朋友，可向我举手示意。","explains":"真正负责的感觉随选择而来。被强加的责任感在遇到困难时容易演化为挫败感；\r\n而自我选择的责任感提醒他为自己着想，遇到困难自己找办法，提升绩效、创造奇迹。","interaction":"A1：去年12月上旬，为冲年度业绩，我分别和2个顾问谈话，要求他们在接下来的2周专攻几个客户要求很急的临床职位，并且要求他们多想想不同方法、务必搞定。接下来我发现他们二人情绪比较低落，没有成果出来，第一时间我还是在鼓励他们，当其他同事有成单时，他们开始抱怨，抱怨其他人可以选择能成的订单、他们却只能按照我的要求做成不了的订单，虽然他们也知道没有人能预测到底哪个订单能成。\r\n我忽视了选择对他们责任感提升的正向作用，现实中更多的看到了不是自主选择时他们躲避困难和受挫时消极的表现，在他们受损的同时，整个团队的业绩也是受损的。\r\nA2：昨天周会刚刚统一了行动方向，6月份是完成年度任务过半的关键月份，目前18个未关闭的大职位就是6月份的突破点。\r\n运用“真正负责的感觉随选择而来”及本文的方法，下周一早会时引导大家做出选择：\r\n团队希望能完成半年指标，你愿意为团队目标达成做出贡献吗？你的主做订单是哪几个？\r\n大家选择之后，在完成订单中遇到具体困难而无法自我突破时，我将给予引导和协助。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1465727523000,"updated_at":1465727523000,"ria":true}]};